insert into public.lessons (id, level, category_id, sort, title, title_ru, summary, content, line_count, vocab_count) values
  ('a1-01', 'A1', 'greetings', 1, 'Hello!', 'Привет!', 'Say hello and goodbye, ask how someone is, and meet ты and вы.', '{"intro":"Russian has two ways to say \"you\". Ты is for friends, family and children; вы is for strangers, older people, colleagues and groups. Greetings change with it.","sections":[{"type":"lines","kind":"dialogue","title":"Two friends meet","lines":[{"ru":"Привет!","en":"Hi!","words":[{"ru":"Привет!","en":"hi"}],"speaker":"Анна"},{"ru":"Привет! Как дела?","en":"Hi! How are you?","words":[{"ru":"Привет!","en":"hi"},{"ru":"Как","en":"how"},{"ru":"дела?","en":"(are) things"}],"speaker":"Максим"},{"ru":"Хорошо, спасибо. А у тебя?","en":"Fine, thanks. And you?","words":[{"ru":"Хорошо,","en":"well"},{"ru":"спасибо.","en":"thanks"},{"ru":"А","en":"and"},{"ru":"у","en":"by"},{"ru":"тебя?","en":"you"}],"speaker":"Анна","note":"А у тебя? is the natural way to return the question to a friend."},{"ru":"Тоже хорошо.","en":"Good too.","words":[{"ru":"Тоже","en":"also"},{"ru":"хорошо.","en":"well"}],"speaker":"Максим"}]},{"type":"lines","kind":"phrases","title":"Formal and everyday greetings","lines":[{"ru":"Здравствуйте!","en":"Hello! (formal)","words":[{"ru":"Здравствуйте!","en":"hello"}],"tag":"formal","note":"The first в is silent: [здра́ствуйте] → [здра́стуйте]."},{"ru":"Как у вас дела?","en":"How are you? (formal)","words":[{"ru":"Как","en":"how"},{"ru":"у","en":"by"},{"ru":"вас","en":"you"},{"ru":"дела?","en":"things"}],"tag":"formal"},{"ru":"Доброе утро!","en":"Good morning!","words":[{"ru":"Доброе","en":"good"},{"ru":"утро!","en":"morning"}]},{"ru":"Добрый день!","en":"Good afternoon!","words":[{"ru":"Добрый","en":"good"},{"ru":"день!","en":"day"}]},{"ru":"Добрый вечер!","en":"Good evening!","words":[{"ru":"Добрый","en":"good"},{"ru":"вечер!","en":"evening"}]},{"ru":"Нормально.","en":"Not bad. / Okay.","words":[{"ru":"Нормально.","en":"okay"}]},{"ru":"Отлично!","en":"Great!","words":[{"ru":"Отлично!","en":"excellent"}]},{"ru":"Пока!","en":"Bye!","words":[{"ru":"Пока!","en":"bye"}],"tag":"informal"},{"ru":"До свидания!","en":"Goodbye!","words":[{"ru":"До","en":"until"},{"ru":"свидания!","en":"meeting"}],"tag":"formal"}]},{"type":"grammar","title":"Ты or вы?","paragraphs":["Use **ты** with one person you know well: a friend, a family member, a child. Use **вы** with someone you don''t know, someone older or senior, and with any group of people.","The words around \"you\" change too: у тебя → у вас, твой → ваш. When in doubt, start with вы. A Russian speaker who wants to switch will say «Давай на ты» — \"let''s use ты\"."],"examples":[{"ru":"Как у тебя дела?","en":"How are you? (to a friend)"},{"ru":"Как у вас дела?","en":"How are you? (formal, or to several people)"},{"ru":"Давай на ты!","en":"Let''s use \"ты\" with each other!"}]}],"drills":[{"q":"Здравствуйте! Как у ___ дела?","answer":"вас","options":["вас","ты","тебя","вы"],"en":"Hello! How are you? (formal)","why":{"тебя":"У тебя is the informal ты version. Здравствуйте is formal, so match it with у вас.","ты":"After у you need the genitive: у вас (formal) or у тебя — never у ты.","вы":"After у you need the genitive: у вас, not у вы."}},{"q":"Привет! Как ___?","answer":"дела","options":["делать","дело","день","дела"],"en":"Hi! How are you?","why":{"дело":"Дело is singular (\"a matter\"). The greeting uses the plural: Как дела?","делать":"Делать means \"to do\". \"How are you?\" is the set phrase Как дела?","день":"День means \"day\". The everyday greeting is Как дела? — literally \"how are things\"."}},{"q":"Доброе ___!","answer":"утро","options":["вечер","ночь","день","утро"],"en":"Good morning!","why":{"вечер":"Вечер is masculine, so it''s Добрый вечер. Доброе needs a neuter word: утро.","день":"День is masculine: Добрый день. Доброе goes with утро.","ночь":"Ночь is feminine and isn''t a greeting (good night is Спокойной ночи). Доброе goes with утро."}},{"q":"До ___!","answer":"свидания","options":["свидания","привет","пока","свидание"],"en":"Goodbye!","why":{"свидание":"До takes the genitive: до свидания. On its own, свидание means \"a date\".","пока":"Пока already means \"bye\" by itself — no до in front.","привет":"Привет means \"hi\", not \"goodbye\". The phrase is До свидания!"}}]}'::jsonb, 13, 14),
  ('a1-02', 'A1', 'meeting', 2, 'Nice to meet you', 'Знакомство', 'Introduce yourself, ask someone''s name, and say where you''re from.', '{"intro":"Russians don''t say \"my name is\". They say «Меня зовут…» — literally \"they call me…\". You''ll also learn to say where you''re from with из.","sections":[{"type":"lines","kind":"dialogue","title":"Meeting at a chess club","lines":[{"ru":"Как тебя зовут?","en":"What''s your name?","words":[{"ru":"Как","en":"what"},{"ru":"тебя","en":"you"},{"ru":"зовут?","en":"(they) call"}],"speaker":"Анна"},{"ru":"Меня зовут Максим. А тебя?","en":"My name is Maksim. And yours?","words":[{"ru":"Меня","en":"me"},{"ru":"зовут","en":"(they) call"},{"ru":"Максим.","en":"Maksim"},{"ru":"А","en":"and"},{"ru":"тебя?","en":"you"}],"speaker":"Максим"},{"ru":"Меня зовут Анна. Очень приятно!","en":"I''m Anna. Nice to meet you!","words":[{"ru":"Меня","en":"me"},{"ru":"зовут","en":"(they) call"},{"ru":"Анна.","en":"Anna"},{"ru":"Очень","en":"very"},{"ru":"приятно!","en":"pleasant"}],"speaker":"Анна"},{"ru":"Мне тоже. Откуда ты?","en":"Likewise. Where are you from?","words":[{"ru":"Мне","en":"to me"},{"ru":"тоже.","en":"too"},{"ru":"Откуда","en":"where from"},{"ru":"ты?","en":"you"}],"speaker":"Максим"},{"ru":"Я из Америки. А ты?","en":"I''m from America. And you?","words":[{"ru":"Я","en":"I"},{"ru":"из","en":"from"},{"ru":"Америки.","en":"America"},{"ru":"А","en":"and"},{"ru":"ты?","en":"you"}],"speaker":"Анна"},{"ru":"Я из Москвы.","en":"I''m from Moscow.","words":[{"ru":"Я","en":"I"},{"ru":"из","en":"from"},{"ru":"Москвы.","en":"Moscow"}],"speaker":"Максим"}]},{"type":"lines","kind":"phrases","title":"More about you","lines":[{"ru":"Как вас зовут?","en":"What''s your name? (formal)","words":[{"ru":"Как","en":"what"},{"ru":"вас","en":"you"},{"ru":"зовут?","en":"(they) call"}],"tag":"formal"},{"ru":"Откуда вы?","en":"Where are you from? (formal)","words":[{"ru":"Откуда","en":"where from"},{"ru":"вы?","en":"you"}],"tag":"formal"},{"ru":"Я живу в Нью-Йорке.","en":"I live in New York.","words":[{"ru":"Я","en":"I"},{"ru":"живу","en":"live"},{"ru":"в","en":"in"},{"ru":"Нью-Йорке.","en":"New York"}]},{"ru":"Кто ты по профессии?","en":"What do you do for a living?","words":[{"ru":"Кто","en":"who"},{"ru":"ты","en":"you"},{"ru":"по","en":"by"},{"ru":"профессии?","en":"profession"}]},{"ru":"Я программист.","en":"I''m a programmer.","words":[{"ru":"Я","en":"I"},{"ru":"программист.","en":"programmer"}],"note":"Russian drops \"am / is / are\" in the present tense: literally \"I programmer\"."},{"ru":"Я студент.","en":"I''m a student.","words":[{"ru":"Я","en":"I"},{"ru":"студент.","f":"студентка.","en":"student"}],"ruF":"Я студентка.","note":"Many job and status words have a feminine form: студент → студентка."}]},{"type":"grammar","title":"\"From\" takes the genitive","paragraphs":["After **из** (\"from\"), the place name changes its ending. Feminine names in -а become -ы (or -и after к, г, х, ж, ш, ч, щ); names in -я become -и; masculine names add -а."],"examples":[{"ru":"Москва → Я из Москвы.","en":"I''m from Moscow."},{"ru":"Америка → Я из Америки.","en":"I''m from America."},{"ru":"Россия → Я из России.","en":"I''m from Russia."},{"ru":"Лондон → Я из Лондона.","en":"I''m from London."}]}],"drills":[{"q":"Меня ___ Анна.","answer":"зовут","options":["зовут","звать","зову","зовёт"],"en":"My name is Anna.","why":{"зовёт":"Зовёт is \"he/she calls\". The set phrase uses \"they call (me)\": меня зовут.","звать":"Звать is the infinitive \"to call\". The phrase needs the conjugated form: меня зовут.","зову":"Зову is \"I call\", which clashes with меня (\"me\"). The phrase is меня зовут."}},{"q":"Я из ___. (Москва)","answer":"Москвы","options":["Москву","Москва","Москвы","Москве"],"en":"I''m from Moscow.","why":{"Москва":"Из takes the genitive: из Москвы. Москва is the dictionary form.","Москве":"Москве is the prepositional (в Москве, \"in Moscow\"). Из needs the genitive: Москвы.","Москву":"Москву is the accusative (в Москву, \"to Moscow\"). Из needs Москвы."}},{"q":"Очень ___!","answer":"приятно","options":["приятный","приятная","приятно","хорошо"],"en":"Nice to meet you!","why":{"приятный":"Приятный is an adjective (\"a pleasant …\"). The set phrase uses the adverb: Очень приятно!","приятная":"Приятная is a feminine adjective. The phrase uses приятно: Очень приятно!","хорошо":"Очень хорошо means \"very good\". \"Nice to meet you\" is Очень приятно."}},{"q":"___ вы? — Я из Канады.","answer":"Откуда","options":["Куда","Как","Откуда","Где"],"en":"Where are you from? — I''m from Canada.","why":{"Где":"Где asks where something is. The answer \"из Канады\" means \"from\", so ask Откуда — \"where from\".","Куда":"Куда is \"where to\". Asking where someone is from is Откуда.","Как":"Как is \"how\". To get the answer \"Я из…\", ask Откуда вы?"}}]}'::jsonb, 12, 12),
  ('a1-03', 'A1', 'essentials', 3, 'I don''t understand', 'Я не понимаю', 'The phrases that keep a conversation going when you''re lost.', '{"intro":"You''ll use these every day while you learn. Notice how the ты form becomes the вы form by adding -те.","sections":[{"type":"lines","kind":"phrases","title":"Survival phrases","lines":[{"ru":"Я не понимаю.","en":"I don''t understand.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"понимаю.","en":"understand"}]},{"ru":"Повтори, пожалуйста.","en":"Repeat, please.","words":[{"ru":"Повтори,","en":"repeat"},{"ru":"пожалуйста.","en":"please"}]},{"ru":"Повторите, пожалуйста.","en":"Could you repeat that, please?","words":[{"ru":"Повторите,","en":"repeat"},{"ru":"пожалуйста.","en":"please"}],"tag":"formal"},{"ru":"Говори немного медленнее.","en":"Speak a little slower.","words":[{"ru":"Говори","en":"speak"},{"ru":"немного","en":"a little"},{"ru":"медленнее.","en":"more slowly"}]},{"ru":"Говорите медленнее, пожалуйста.","en":"Please speak more slowly.","words":[{"ru":"Говорите","en":"speak"},{"ru":"медленнее,","en":"more slowly"},{"ru":"пожалуйста.","en":"please"}],"tag":"formal"},{"ru":"Как сказать «checkmate» по-русски?","en":"How do you say \"checkmate\" in Russian?","words":[{"ru":"Как","en":"how"},{"ru":"сказать","en":"to say"},{"ru":"«checkmate»","en":"checkmate"},{"ru":"по-русски?","en":"in Russian"}]},{"ru":"«Мат».","en":"\"Мат.\"","words":[{"ru":"«Мат».","en":"checkmate"}]},{"ru":"Что это значит?","en":"What does this mean?","words":[{"ru":"Что","en":"what"},{"ru":"это","en":"this"},{"ru":"значит?","en":"means"}]},{"ru":"Я немного говорю по-русски.","en":"I speak a little Russian.","words":[{"ru":"Я","en":"I"},{"ru":"немного","en":"a little"},{"ru":"говорю","en":"speak"},{"ru":"по-русски.","en":"in Russian"}]},{"ru":"Ты говоришь по-английски?","en":"Do you speak English?","words":[{"ru":"Ты","en":"you"},{"ru":"говоришь","en":"speak"},{"ru":"по-английски?","en":"in English"}]},{"ru":"Извините, я не знаю.","en":"Sorry, I don''t know.","words":[{"ru":"Извините,","en":"excuse me"},{"ru":"я","en":"I"},{"ru":"не","en":"not"},{"ru":"знаю.","en":"know"}],"tag":"formal"}]},{"type":"grammar","title":"Asking politely","paragraphs":["To ask someone to do something, Russian uses the imperative. For **ты**, it often ends in -и; for **вы**, add **-те**. Add пожалуйста to be polite.","**Не** goes directly before the verb it negates: я не понимаю, я не знаю."],"examples":[{"ru":"Повтори! → Повторите!","en":"Repeat!"},{"ru":"Говори медленнее! → Говорите медленнее!","en":"Speak more slowly!"}]}],"drills":[{"q":"Я не ___.","answer":"понимаю","options":["понимаю","понимает","понимаешь","понимать"],"en":"I don''t understand.","why":{"понимаешь":"Понимаешь is the ты form. With я use понимаю.","понимает":"Понимает is the он/она form. With я use понимаю.","понимать":"Понимать is the infinitive. With я you need the я form: понимаю."}},{"q":"Говорите медленнее, ___.","answer":"пожалуйста","options":["пожалуйста","привет","спасибо","извините"],"en":"Please speak more slowly.","why":{"спасибо":"Спасибо is \"thank you\". A request takes пожалуйста — \"please\".","привет":"Привет is \"hi\". A polite request ends with пожалуйста.","извините":"Извините means \"excuse me\" and usually starts a request. At the end, say пожалуйста."}},{"q":"Как сказать «queen» ___?","answer":"по-русски","options":["по-русски","Россия","русская","русский"],"en":"How do you say \"queen\" in Russian?","why":{"русский":"Русский is an adjective (or \"the Russian language\"). \"In Russian\", for saying something, is по-русски.","Россия":"Россия is the country. \"In Russian\" is по-русски.","русская":"Русская is a feminine adjective (\"a Russian woman\"). \"In Russian\" is по-русски."}},{"q":"Ты ___ по-английски?","answer":"говоришь","options":["говорить","говорю","говорит","говоришь"],"en":"Do you speak English?","why":{"говорю":"Говорю is the я form. With ты use говоришь.","говорит":"Говорит is the он/она form. With ты use говоришь.","говорить":"Говорить is the infinitive. With ты use говоришь."}}]}'::jsonb, 11, 11),
  ('a1-04', 'A1', 'routines', 4, 'What are you doing?', 'Что ты делаешь?', 'Talk about what you''re doing now, and say you''re hungry or thirsty.', '{"intro":"Most Russian verbs you''ll meet first follow one pattern. Learn it with работать and играть, and you can use dozens of verbs.","sections":[{"type":"lines","kind":"dialogue","title":"A phone call","lines":[{"ru":"Что ты делаешь?","en":"What are you doing?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делаешь?","en":"are doing"}],"speaker":"Максим"},{"ru":"Я работаю. А ты?","en":"I''m working. And you?","words":[{"ru":"Я","en":"I"},{"ru":"работаю.","en":"am working"},{"ru":"А","en":"and"},{"ru":"ты?","en":"you"}],"speaker":"Анна"},{"ru":"Я учусь.","en":"I''m studying.","words":[{"ru":"Я","en":"I"},{"ru":"учусь.","en":"am studying"}],"speaker":"Максим"},{"ru":"Что ты учишь?","en":"What are you learning?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"учишь?","en":"are learning"}],"speaker":"Анна"},{"ru":"Я учу русский язык.","en":"I''m learning Russian.","words":[{"ru":"Я","en":"I"},{"ru":"учу","en":"am learning"},{"ru":"русский","en":"Russian"},{"ru":"язык.","en":"language"}],"speaker":"Максим"}]},{"type":"lines","kind":"phrases","title":"My day","lines":[{"ru":"Сейчас я отдыхаю.","en":"I''m relaxing right now.","words":[{"ru":"Сейчас","en":"now"},{"ru":"я","en":"I"},{"ru":"отдыхаю.","en":"am resting"}]},{"ru":"Я читаю книгу.","en":"I''m reading a book.","words":[{"ru":"Я","en":"I"},{"ru":"читаю","en":"am reading"},{"ru":"книгу.","en":"book"}]},{"ru":"Утром я пью кофе.","en":"In the morning I drink coffee.","words":[{"ru":"Утром","en":"in the morning"},{"ru":"я","en":"I"},{"ru":"пью","en":"drink"},{"ru":"кофе.","en":"coffee"}]},{"ru":"Вечером мы играем в шахматы.","en":"In the evening we play chess.","words":[{"ru":"Вечером","en":"in the evening"},{"ru":"мы","en":"we"},{"ru":"играем","en":"play"},{"ru":"в","en":"(in)"},{"ru":"шахматы.","en":"chess"}]},{"ru":"Я хочу есть.","en":"I''m hungry.","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"есть.","en":"to eat"}],"note":"Literally \"I want to eat\"."},{"ru":"Я хочу пить.","en":"I''m thirsty.","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"пить.","en":"to drink"}]},{"ru":"Я хочу спать.","en":"I''m sleepy.","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"спать.","en":"to sleep"}]}]},{"type":"grammar","title":"The -ю / -ешь pattern","paragraphs":["Verbs like **работать, делать, играть, читать** drop -ть and add these endings:","я работа**ю**, ты работа**ешь**, он / она работа**ет**, мы работа**ем**, вы работа**ете**, они работа**ют**.","**Учиться** means \"to be studying / to be a student\"; **учить** means \"to learn something\": учу русский язык."],"examples":[{"ru":"Она работает дома.","en":"She works from home."},{"ru":"Вы играете в шахматы?","en":"Do you play chess?"}]}],"drills":[{"q":"Что ты ___?","answer":"делаешь","options":["делаешь","делаю","делаем","делает"],"en":"What are you doing?","why":{"делаю":"Делаю is the я form. With ты use делаешь.","делает":"Делает is the он/она form. With ты use делаешь.","делаем":"Делаем is the мы form. With ты use делаешь."}},{"q":"Мы ___ в шахматы.","answer":"играем","options":["играешь","играем","играю","играют"],"en":"We play chess.","why":{"играю":"Играю is the я form. With мы use играем.","играешь":"Играешь is the ты form. With мы use играем.","играют":"Играют is the они form. With мы use играем."}},{"q":"Она ___ дома.","answer":"работает","options":["работают","работает","работаешь","работаю"],"en":"She works from home.","why":{"работаю":"Работаю is the я form. With она use работает.","работаешь":"Работаешь is the ты form. With она use работает.","работают":"Работают is the они form. With она use работает."}},{"q":"Я хочу ___. (I''m thirsty)","answer":"пить","options":["есть","пить","читать","спать"],"en":"I''m thirsty.","why":{"есть":"Есть means \"to eat\" — that''s hunger. Thirsty is хочу пить, \"I want to drink\".","спать":"Спать is \"to sleep\" — that''s being tired. Thirsty is хочу пить.","читать":"Читать is \"to read\". Thirsty is хочу пить."}}]}'::jsonb, 12, 15),
  ('a1-05', 'A1', 'restaurants', 5, 'At the café', 'В кафе', 'Order a drink, ask for milk or sugar, and ask how much it costs.', '{"intro":"Two little words do a lot of work at a café: с (\"with\") and без (\"without\"). Each changes the noun after it.","sections":[{"type":"lines","kind":"dialogue","title":"Ordering","lines":[{"ru":"Здравствуйте! Что будете заказывать?","en":"Hello! What would you like to order?","words":[{"ru":"Здравствуйте!","en":"hello"},{"ru":"Что","en":"what"},{"ru":"будете","en":"(you) will"},{"ru":"заказывать?","en":"order"}],"speaker":"Официант"},{"ru":"Кофе, пожалуйста.","en":"A coffee, please.","words":[{"ru":"Кофе,","en":"coffee"},{"ru":"пожалуйста.","en":"please"}],"speaker":"Анна"},{"ru":"С молоком?","en":"With milk?","words":[{"ru":"С","en":"with"},{"ru":"молоком?","en":"milk"}],"speaker":"Официант"},{"ru":"Нет, без молока. И ещё воду, пожалуйста.","en":"No, without milk. And some water, please.","words":[{"ru":"Нет,","en":"no"},{"ru":"без","en":"without"},{"ru":"молока.","en":"milk"},{"ru":"И","en":"and"},{"ru":"ещё","en":"also"},{"ru":"воду,","en":"water"},{"ru":"пожалуйста.","en":"please"}],"speaker":"Анна","note":"вода → воду: the thing you ask for takes the accusative."},{"ru":"А мне чай с лимоном.","en":"And tea with lemon for me.","words":[{"ru":"А","en":"and"},{"ru":"мне","en":"for me"},{"ru":"чай","en":"tea"},{"ru":"с","en":"with"},{"ru":"лимоном.","en":"lemon"}],"speaker":"Максим"},{"ru":"Что-нибудь ещё?","en":"Anything else?","words":[{"ru":"Что-нибудь","en":"anything"},{"ru":"ещё?","en":"else"}],"speaker":"Официант"},{"ru":"Нет, спасибо. Сколько это стоит?","en":"No, thanks. How much is it?","words":[{"ru":"Нет,","en":"no"},{"ru":"спасибо.","en":"thanks"},{"ru":"Сколько","en":"how much"},{"ru":"это","en":"this"},{"ru":"стоит?","en":"costs"}],"speaker":"Максим"},{"ru":"Триста рублей.","en":"Three hundred rubles.","words":[{"ru":"Триста","en":"three hundred"},{"ru":"рублей.","en":"rubles"}],"speaker":"Официант"}]},{"type":"grammar","title":"С and без","paragraphs":["**С** (\"with\") takes the instrumental: молоко → с молок**ом**, лимон → с лимон**ом**, сахар → с сахар**ом**.","**Без** (\"without\") takes the genitive: молоко → без молок**а**, сахар → без сахар**а**.","Note: **кофе** is masculine even though it ends in -е: мой кофе, чёрный кофе."],"examples":[{"ru":"Чай с сахаром.","en":"Tea with sugar."},{"ru":"Кофе без сахара.","en":"Coffee without sugar."}]}],"drills":[{"q":"Кофе с ___, пожалуйста. (молоко)","answer":"молоком","options":["молока","молоке","молоком","молоко"],"en":"Coffee with milk, please.","why":{"молоко":"С meaning \"with\" takes the instrumental: с молоком.","молока":"Молока is the genitive (без молока, \"without milk\"). \"With\" needs молоком.","молоке":"Молоке is the prepositional (о молоке, \"about milk\"). \"With\" needs молоком."}},{"q":"Чай без ___. (сахар)","answer":"сахара","options":["сахаром","сахар","сахаре","сахара"],"en":"Tea without sugar.","why":{"сахар":"Без takes the genitive: без сахара.","сахаром":"Сахаром is the instrumental — с сахаром, \"with sugar\". Без needs сахара.","сахаре":"Сахаре is the prepositional. Без needs the genitive: сахара."}},{"q":"___ это стоит?","answer":"Сколько","options":["Что","Как","Сколько","Где"],"en":"How much is it?","why":{"Что":"Что is \"what\". Price questions use Сколько — \"how much\".","Как":"Как is \"how\" (in what way). \"How much\" is Сколько.","Где":"Где is \"where\". \"How much is it?\" is Сколько это стоит?"}},{"q":"Что-нибудь ___?","answer":"ещё","options":["тоже","очень","ещё","уже"],"en":"Anything else?","why":{"уже":"Уже means \"already\". \"Anything else?\" is Что-нибудь ещё?","тоже":"Тоже means \"also, too\" (я тоже — me too). \"Else\" here is ещё.","очень":"Очень means \"very\" and needs a word to describe. \"Else\" is ещё."}}]}'::jsonb, 8, 14),
  ('a1-06', 'A1', 'family', 6, 'My family', 'Моя семья', 'Introduce your family and say what you have with «у меня есть».', '{"intro":"Russian has no verb \"to have\" in everyday speech. Instead you say «у меня есть» — \"by me there is\".","sections":[{"type":"lines","kind":"phrases","title":"Family photos","lines":[{"ru":"Это моя семья.","en":"This is my family.","words":[{"ru":"Это","en":"this is"},{"ru":"моя","en":"my"},{"ru":"семья.","en":"family"}]},{"ru":"Это моя мама, а это мой папа.","en":"This is my mom, and this is my dad.","words":[{"ru":"Это","en":"this is"},{"ru":"моя","en":"my"},{"ru":"мама,","en":"mom"},{"ru":"а","en":"and"},{"ru":"это","en":"this is"},{"ru":"мой","en":"my"},{"ru":"папа.","en":"dad"}]},{"ru":"У меня есть брат и сестра.","en":"I have a brother and a sister.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"есть","en":"there is"},{"ru":"брат","en":"brother"},{"ru":"и","en":"and"},{"ru":"сестра.","en":"sister"}]},{"ru":"Как его зовут?","en":"What''s his name?","words":[{"ru":"Как","en":"what"},{"ru":"его","en":"him"},{"ru":"зовут?","en":"(they) call"}]},{"ru":"Его зовут Иван.","en":"His name is Ivan.","words":[{"ru":"Его","en":"him"},{"ru":"зовут","en":"(they) call"},{"ru":"Иван.","en":"Ivan"}]},{"ru":"Как её зовут?","en":"What''s her name?","words":[{"ru":"Как","en":"what"},{"ru":"её","en":"her"},{"ru":"зовут?","en":"(they) call"}]},{"ru":"Её зовут Ольга. Она врач.","en":"Her name is Olga. She''s a doctor.","words":[{"ru":"Её","en":"her"},{"ru":"зовут","en":"(they) call"},{"ru":"Ольга.","en":"Olga"},{"ru":"Она","en":"she"},{"ru":"врач.","en":"doctor"}]},{"ru":"У тебя есть дети?","en":"Do you have children?","words":[{"ru":"У","en":"by"},{"ru":"тебя","en":"you"},{"ru":"есть","en":"there is"},{"ru":"дети?","en":"children"}]},{"ru":"Да, у меня есть сын.","en":"Yes, I have a son.","words":[{"ru":"Да,","en":"yes"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"есть","en":"there is"},{"ru":"сын.","en":"son"}]},{"ru":"Нет, у меня нет детей.","en":"No, I don''t have children.","words":[{"ru":"Нет,","en":"no"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"нет","en":"there is no"},{"ru":"детей.","en":"children"}],"note":"For \"I don''t have\", use нет and put the thing in the genitive: дети → детей."}]},{"type":"grammar","title":"Мой, моя, моё, мои","paragraphs":["\"My\" agrees with the noun it describes. Masculine nouns usually end in a consonant, feminine nouns in -а / -я, neuter nouns in -о / -е.","мой брат, **моя** сестра, **моё** фото, **мои** родители. **Папа** is masculine (he''s a man), so it''s мой папа."],"examples":[{"ru":"Это мой брат.","en":"This is my brother."},{"ru":"Это моя сестра.","en":"This is my sister."},{"ru":"Это мои родители.","en":"These are my parents."}]}],"drills":[{"q":"Это ___ сестра.","answer":"моя","options":["моё","моя","мой","мои"],"en":"This is my sister.","why":{"мой":"Мой is masculine. Сестра is feminine, so моя.","моё":"Моё is neuter. Сестра is feminine, so моя.","мои":"Мои is plural. One sister: моя."}},{"q":"Это ___ папа.","answer":"мой","options":["мои","моя","моё","мой"],"en":"This is my dad.","why":{"моя":"Папа ends in -а but means a man, so it''s masculine: мой папа.","моё":"Моё is neuter. Папа is masculine: мой.","мои":"Мои is plural. One dad: мой."}},{"q":"У меня ___ брат.","answer":"есть","options":["был","есть","нет","это"],"en":"I have a brother.","why":{"нет":"Нет means \"there isn''t\" (and would need брата). \"I have\" is у меня есть.","был":"Был is past (\"I had\"). The sentence is present: есть.","это":"Это means \"this, it\". \"Have\" in у меня… is есть."}},{"q":"Как ___ зовут? (her)","answer":"её","options":["её","ей","она","его"],"en":"What''s her name?","why":{"его":"Его is \"him\". \"Her\" is её: Как её зовут?","она":"Она is \"she\" (the subject). Зовут needs \"her\" as the object: её.","ей":"Ей is \"to her\" (ей нравится). With зовут use её."}}]}'::jsonb, 10, 12),
  ('a1-07', 'A1', 'numbers', 7, 'Numbers and time', 'Числа и время', 'Count to twenty, tell the time, and say your age.', '{"intro":"After a number, Russian nouns change form: one form after 1, another after 2–4, and a third after 5–20.","sections":[{"type":"lines","kind":"phrases","title":"Counting and time","lines":[{"ru":"Один, два, три, четыре, пять.","en":"One, two, three, four, five.","words":[{"ru":"Один,","en":"one"},{"ru":"два,","en":"two"},{"ru":"три,","en":"three"},{"ru":"четыре,","en":"four"},{"ru":"пять.","en":"five"}]},{"ru":"Шесть, семь, восемь, девять, десять.","en":"Six, seven, eight, nine, ten.","words":[{"ru":"Шесть,","en":"six"},{"ru":"семь,","en":"seven"},{"ru":"восемь,","en":"eight"},{"ru":"девять,","en":"nine"},{"ru":"десять.","en":"ten"}]},{"ru":"Сколько сейчас времени?","en":"What time is it?","words":[{"ru":"Сколько","en":"how much"},{"ru":"сейчас","en":"now"},{"ru":"времени?","en":"time"}]},{"ru":"Сейчас три часа.","en":"It''s three o''clock.","words":[{"ru":"Сейчас","en":"now"},{"ru":"три","en":"three"},{"ru":"часа.","en":"hours"}],"note":"After 2, 3 and 4 the word is часа; after 5–20 it''s часов."},{"ru":"Сейчас пять часов.","en":"It''s five o''clock.","words":[{"ru":"Сейчас","en":"now"},{"ru":"пять","en":"five"},{"ru":"часов.","en":"hours"}]},{"ru":"У меня пять минут.","en":"I have five minutes.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"пять","en":"five"},{"ru":"минут.","en":"minutes"}]},{"ru":"Партия на десять минут.","en":"A ten-minute game.","words":[{"ru":"Партия","en":"game"},{"ru":"на","en":"for"},{"ru":"десять","en":"ten"},{"ru":"минут.","en":"minutes"}]},{"ru":"Мне двадцать лет.","en":"I''m twenty years old.","words":[{"ru":"Мне","en":"to me"},{"ru":"двадцать","en":"twenty"},{"ru":"лет.","en":"years"}],"note":"Age uses the dative: мне, тебе, ему, ей + the number of years."},{"ru":"Какой сегодня день?","en":"What day is it today?","words":[{"ru":"Какой","en":"what"},{"ru":"сегодня","en":"today"},{"ru":"день?","en":"day"}]},{"ru":"Сегодня понедельник.","en":"Today is Monday.","words":[{"ru":"Сегодня","en":"today"},{"ru":"понедельник.","en":"Monday"}]}]},{"type":"grammar","title":"1, 2–4, 5+","paragraphs":["Nouns after numbers follow a pattern:","**1** час, минута, год · **2–4** часа, минуты, года · **5–20** часов, минут, лет.","Numbers that end in 1 (21, 31) behave like 1; numbers ending in 2–4 (22, 33) like 2–4."],"examples":[{"ru":"одна минута, две минуты, пять минут","en":"one minute, two minutes, five minutes"},{"ru":"Мне двадцать один год.","en":"I''m twenty-one."}]}],"drills":[{"q":"Сейчас два ___.","answer":"часа","options":["часа","часов","час","часы"],"en":"It''s two o''clock.","why":{"час":"Час goes with один or alone (Сейчас час). After 2, 3, 4 use часа.","часов":"Часов follows 5 and up (пять часов). After два use часа.","часы":"Часы means \"a clock, a watch\". After два use часа."}},{"q":"У меня десять ___.","answer":"минут","options":["минута","минуту","минут","минуты"],"en":"I have ten minutes.","why":{"минута":"Минута goes with одна. From 5 up, use the genitive plural: десять минут.","минуты":"Минуты follows 2, 3, 4 (две минуты). After десять: минут.","минуту":"Минуту is the accusative singular (через минуту). After десять: минут."}},{"q":"Мне тридцать ___.","answer":"лет","options":["годы","лет","года","год"],"en":"I''m thirty years old.","why":{"год":"Год follows numbers ending in 1 (двадцать один год). After тридцать: лет.","года":"Года follows 2–4 (два года). After тридцать: лет.","годы":"Годы means \"years\" as in an era (90-е годы). Ages from 5 up use лет."}},{"q":"___ сейчас времени?","answer":"Сколько","options":["Где","Сколько","Какой","Что"],"en":"What time is it?","why":{"Какой":"Какой is \"which\". The time question is Сколько времени? — literally \"how much time\".","Что":"Что is \"what\". To ask the time, say Сколько сейчас времени?","Где":"Где is \"where\". To ask the time: Сколько времени?"}}]}'::jsonb, 10, 16),
  ('a1-08', 'A1', 'weather', 8, 'What''s the weather like?', 'Какая погода?', 'Describe the weather and the seasons, and say you''re hot or cold.', '{"intro":"Russian weather sentences have no \"it\": just «Холодно» — \"(it''s) cold\". Rain and snow \"go\": идёт дождь.","sections":[{"type":"lines","kind":"phrases","title":"Weather talk","lines":[{"ru":"Какая сегодня погода?","en":"What''s the weather like today?","words":[{"ru":"Какая","en":"what kind of"},{"ru":"сегодня","en":"today"},{"ru":"погода?","en":"weather"}]},{"ru":"Сегодня холодно.","en":"It''s cold today.","words":[{"ru":"Сегодня","en":"today"},{"ru":"холодно.","en":"cold"}]},{"ru":"Сегодня тепло и солнечно.","en":"It''s warm and sunny today.","words":[{"ru":"Сегодня","en":"today"},{"ru":"тепло","en":"warm"},{"ru":"и","en":"and"},{"ru":"солнечно.","en":"sunny"}]},{"ru":"Идёт дождь.","en":"It''s raining.","words":[{"ru":"Идёт","en":"goes"},{"ru":"дождь.","en":"rain"}]},{"ru":"Идёт снег.","en":"It''s snowing.","words":[{"ru":"Идёт","en":"goes"},{"ru":"снег.","en":"snow"}]},{"ru":"На улице минус десять.","en":"It''s minus ten outside.","words":[{"ru":"На","en":"on"},{"ru":"улице","en":"street"},{"ru":"минус","en":"minus"},{"ru":"десять.","en":"ten"}]},{"ru":"Мне холодно.","en":"I''m cold.","words":[{"ru":"Мне","en":"to me"},{"ru":"холодно.","en":"cold"}],"note":"The person who feels cold is in the dative: мне, тебе, ему, ей холодно."},{"ru":"Мне жарко.","en":"I''m hot.","words":[{"ru":"Мне","en":"to me"},{"ru":"жарко.","en":"hot"}]},{"ru":"Я люблю лето.","en":"I love summer.","words":[{"ru":"Я","en":"I"},{"ru":"люблю","en":"love"},{"ru":"лето.","en":"summer"}]},{"ru":"Зимой в Москве очень холодно.","en":"In winter it''s very cold in Moscow.","words":[{"ru":"Зимой","en":"in winter"},{"ru":"в","en":"in"},{"ru":"Москве","en":"Moscow"},{"ru":"очень","en":"very"},{"ru":"холодно.","en":"cold"}]}]},{"type":"grammar","title":"Seasons and \"I''m cold\"","paragraphs":["\"In winter / spring / summer / autumn\" is one word in Russian: **зимой, весной, летом, осенью**.","To say how *you* feel, use the dative: **мне** холодно, **тебе** жарко? Without мне, it describes the weather."],"examples":[{"ru":"Летом жарко.","en":"It''s hot in summer."},{"ru":"Тебе не холодно?","en":"Aren''t you cold?"}]}],"drills":[{"q":"___ снег.","answer":"Идёт","options":["Идут","Идёт","Иду","Идёшь"],"en":"It''s snowing.","why":{"Иду":"Иду is \"I go\". Snow is \"it\", so Идёт снег.","Идёшь":"Идёшь is the ты form. Снег takes the он form: идёт.","Идут":"Идут is plural (\"they go\"). Снег is singular: идёт."}},{"q":"Мне ___. (I''m cold)","answer":"холодно","options":["холодно","холодный","холодная","холод"],"en":"I''m cold.","why":{"холодный":"Холодный is an adjective (\"a cold …\"). Feelings with мне use the -о form: мне холодно.","холодная":"Холодная is a feminine adjective. With мне use холодно.","холод":"Холод is the noun \"the cold\". \"I''m cold\" is Мне холодно."}},{"q":"___ очень жарко. (in summer)","answer":"Летом","options":["Лета","Летом","Лето","Лете"],"en":"It''s very hot in summer.","why":{"Лето":"Лето is the noun \"summer\". \"In summer\" is one word: летом.","Лета":"Лета is the genitive. \"In summer\" is летом, with no preposition.","Лете":"Лете is the prepositional (о лете, \"about summer\"). \"In summer\" is летом."}},{"q":"Какая сегодня ___?","answer":"погода","options":["погоды","погоду","погода","погоде"],"en":"What''s the weather like today?","why":{"погоду":"Погоду is the accusative (an object). Here погода is the subject: Какая погода?","погоды":"Погоды is the genitive. The subject stays in the plain form: погода.","погоде":"Погоде is the prepositional (о погоде, \"about the weather\"). The subject is погода."}}]}'::jsonb, 10, 12),
  ('a1-09', 'A1', 'shopping', 9, 'At the store', 'В магазине', 'Find things in a shop, ask the price and pay.', '{"intro":"«Мне нужен…» means \"I need…\". Like мой, the word нужен agrees with the thing you need.","sections":[{"type":"lines","kind":"phrases","title":"Shopping","lines":[{"ru":"Извините, где хлеб?","en":"Excuse me, where is the bread?","words":[{"ru":"Извините,","en":"excuse me"},{"ru":"где","en":"where"},{"ru":"хлеб?","en":"bread"}]},{"ru":"Хлеб там, справа.","en":"The bread is over there, on the right.","words":[{"ru":"Хлеб","en":"bread"},{"ru":"там,","en":"there"},{"ru":"справа.","en":"on the right"}]},{"ru":"Дайте, пожалуйста, бутылку воды.","en":"A bottle of water, please.","words":[{"ru":"Дайте,","en":"give"},{"ru":"пожалуйста,","en":"please"},{"ru":"бутылку","en":"bottle"},{"ru":"воды.","en":"of water"}],"note":"бутылка → бутылку (the thing you ask for); вода → воды (\"of water\")."},{"ru":"Сколько стоит эта футболка?","en":"How much is this T-shirt?","words":[{"ru":"Сколько","en":"how much"},{"ru":"стоит","en":"costs"},{"ru":"эта","en":"this"},{"ru":"футболка?","en":"T-shirt"}]},{"ru":"Тысяча рублей.","en":"A thousand rubles.","words":[{"ru":"Тысяча","en":"thousand"},{"ru":"рублей.","en":"rubles"}]},{"ru":"Это дорого.","en":"That''s expensive.","words":[{"ru":"Это","en":"this"},{"ru":"дорого.","en":"expensive"}]},{"ru":"Это недорого.","en":"That''s not expensive.","words":[{"ru":"Это","en":"this"},{"ru":"недорого.","en":"inexpensive"}]},{"ru":"Можно заплатить картой?","en":"Can I pay by card?","words":[{"ru":"Можно","en":"may I"},{"ru":"заплатить","en":"pay"},{"ru":"картой?","en":"by card"}]},{"ru":"Да, конечно.","en":"Yes, of course.","words":[{"ru":"Да,","en":"yes"},{"ru":"конечно.","en":"of course"}],"note":"конечно is pronounced [коне́шно]."},{"ru":"Мне нужен пакет.","en":"I need a bag.","words":[{"ru":"Мне","en":"to me"},{"ru":"нужен","en":"needed"},{"ru":"пакет.","en":"bag"}]}]},{"type":"grammar","title":"Нужен, нужна, нужно","paragraphs":["**Нужен** agrees with what''s needed: мне нужен пакет (m), мне нужн**а** сумка (f), мне нужн**о** молоко (n), мне нужн**ы** ключи (pl).","With a verb, always use нужно: мне нужно идти — \"I need to go\"."],"examples":[{"ru":"Мне нужна вода.","en":"I need water."},{"ru":"Мне нужно работать.","en":"I need to work."}]}],"drills":[{"q":"Мне ___ пакет.","answer":"нужен","options":["нужны","нужна","нужен","нужно"],"en":"I need a bag.","why":{"нужна":"Нужна is for feminine nouns (нужна вода). Пакет is masculine: нужен.","нужно":"Нужно is for neuter nouns or before a verb (нужно идти). Пакет takes нужен.","нужны":"Нужны is plural. One пакет: нужен."}},{"q":"Мне ___ вода.","answer":"нужна","options":["нужно","нужны","нужна","нужен"],"en":"I need water.","why":{"нужен":"Нужен is for masculine nouns (нужен пакет). Вода is feminine: нужна.","нужно":"Нужно is for neuter nouns or before a verb. Вода takes нужна.","нужны":"Нужны is plural. Вода is singular: нужна."}},{"q":"Можно заплатить ___? (by card)","answer":"картой","options":["карта","картой","карту","карты"],"en":"Can I pay by card?","why":{"карта":"\"By means of\" uses the instrumental, with no preposition: картой.","карту":"Карту is the accusative (дайте карту, \"give me the card\"). \"By card\" is картой.","карты":"Карты is the genitive or plural. \"By card\" is картой."}},{"q":"Это ___. Слишком дорого!","answer":"дорого","options":["дорого","хорошо","далеко","дёшево"],"en":"That''s expensive. Too expensive!","why":{"дёшево":"Дёшево means \"cheap\" — the opposite of слишком дорого.","далеко":"Далеко means \"far\". The next sentence is about price: дорого.","хорошо":"Хорошо means \"good\". \"Too expensive!\" calls for дорого."}}]}'::jsonb, 10, 14),
  ('a1-10', 'A1', 'directions', 10, 'Where is the metro?', 'Где метро?', 'Ask for directions and understand the answer.', '{"intro":"Listen for налево (\"to the left\") and направо (\"to the right\"). Compare them with слева and справа (\"on the left / right\").","sections":[{"type":"lines","kind":"phrases","title":"On the street","lines":[{"ru":"Извините, где метро?","en":"Excuse me, where''s the metro?","words":[{"ru":"Извините,","en":"excuse me"},{"ru":"где","en":"where"},{"ru":"метро?","en":"metro"}],"tag":"formal"},{"ru":"Идите прямо, потом налево.","en":"Go straight, then left.","words":[{"ru":"Идите","en":"go"},{"ru":"прямо,","en":"straight"},{"ru":"потом","en":"then"},{"ru":"налево.","en":"to the left"}],"tag":"formal"},{"ru":"Это далеко?","en":"Is it far?","words":[{"ru":"Это","en":"this"},{"ru":"далеко?","en":"far"}]},{"ru":"Нет, это близко.","en":"No, it''s close.","words":[{"ru":"Нет,","en":"no"},{"ru":"это","en":"this"},{"ru":"близко.","en":"close"}]},{"ru":"Пять минут пешком.","en":"Five minutes on foot.","words":[{"ru":"Пять","en":"five"},{"ru":"минут","en":"minutes"},{"ru":"пешком.","en":"on foot"}]},{"ru":"Где здесь туалет?","en":"Where''s the restroom here?","words":[{"ru":"Где","en":"where"},{"ru":"здесь","en":"here"},{"ru":"туалет?","en":"restroom"}]},{"ru":"Поверните направо.","en":"Turn right.","words":[{"ru":"Поверните","en":"turn"},{"ru":"направо.","en":"to the right"}],"tag":"formal"},{"ru":"Музей рядом с парком.","en":"The museum is next to the park.","words":[{"ru":"Музей","en":"museum"},{"ru":"рядом","en":"next"},{"ru":"с","en":"to"},{"ru":"парком.","en":"park"}]},{"ru":"Я не знаю, где это.","en":"I don''t know where that is.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"знаю,","en":"know"},{"ru":"где","en":"where"},{"ru":"это.","en":"this"}]},{"ru":"Покажите на карте, пожалуйста.","en":"Please show me on the map.","words":[{"ru":"Покажите","en":"show"},{"ru":"на","en":"on"},{"ru":"карте,","en":"map"},{"ru":"пожалуйста.","en":"please"}],"tag":"formal"}]},{"type":"grammar","title":"Where to vs where","paragraphs":["**Налево / направо** answer \"which way?\": поверните налево. **Слева / справа** answer \"where?\": магазин слева.","Formal requests end in **-ите**: идите, поверните, покажите."],"examples":[{"ru":"Аптека справа.","en":"The pharmacy is on the right."},{"ru":"Поверните налево.","en":"Turn left."}]}],"drills":[{"q":"Идите ___, потом направо. (straight)","answer":"прямо","options":["прямо","правая","право","прямой"],"en":"Go straight, then right.","why":{"право":"Право means \"a right\" (legal). \"Straight ahead\" is прямо.","правая":"Правая is \"right-hand\", an adjective. \"Straight\" is прямо.","прямой":"Прямой is an adjective (\"a straight line\"). With идите you need the adverb: прямо."}},{"q":"Это ___? Нет, близко.","answer":"далеко","options":["долго","дорого","далеко","далёкий"],"en":"Is it far? No, it''s close.","why":{"долго":"Долго is \"for a long time\". The answer близко (close) shows the question was about distance: далеко.","дорого":"Дорого is \"expensive\". Близко answers далеко, \"far\".","далёкий":"Далёкий is an adjective (\"a distant …\"). After это use the adverb: далеко."}},{"q":"Музей рядом с ___.","answer":"парком","options":["парк","парком","парке","парка"],"en":"The museum is next to the park.","why":{"парк":"Рядом с takes the instrumental: рядом с парком.","парка":"Парка is the genitive. Рядом с needs парком.","парке":"Парке is the prepositional (в парке, \"in the park\"). Рядом с needs парком."}},{"q":"Поверните ___. (to the left)","answer":"налево","options":["слева","лево","налево","левый"],"en":"Turn left.","why":{"слева":"Слева means \"on the left\" (where something is). A direction to turn is налево.","левый":"Левый is an adjective (\"left-hand\"). The direction is налево.","лево":"Лево isn''t used on its own. \"To the left\" is налево."}}]}'::jsonb, 10, 13),
  ('a1-11', 'A1', 'chess_vocab', 11, 'The pieces', 'Фигуры на доске', 'Name every chess piece and the board in Russian.', '{"intro":"Some Russian piece names are surprising: the knight is a \"horse\", the bishop is an \"elephant\", and the queen is ферзь, a word that came from Persian.","sections":[{"type":"lines","kind":"phrases","title":"Around the board","lines":[{"ru":"Это шахматная доска.","en":"This is a chessboard.","words":[{"ru":"Это","en":"this is"},{"ru":"шахматная","en":"chess"},{"ru":"доска.","en":"board"}]},{"ru":"Это пешка.","en":"This is a pawn.","words":[{"ru":"Это","en":"this is"},{"ru":"пешка.","en":"pawn"}]},{"ru":"Это конь, а это слон.","en":"This is a knight, and this is a bishop.","words":[{"ru":"Это","en":"this is"},{"ru":"конь,","en":"knight"},{"ru":"а","en":"and"},{"ru":"это","en":"this is"},{"ru":"слон.","en":"bishop"}],"note":"Конь literally means \"horse\" and слон means \"elephant\"."},{"ru":"Ладья стоит в углу.","en":"The rook stands in the corner.","words":[{"ru":"Ладья","en":"rook"},{"ru":"стоит","en":"stands"},{"ru":"в","en":"in"},{"ru":"углу.","en":"corner"}]},{"ru":"Ферзь — сильная фигура.","en":"The queen is a strong piece.","words":[{"ru":"Ферзь","en":"queen"},{"ru":"—","en":"(is)"},{"ru":"сильная","en":"strong"},{"ru":"фигура.","en":"piece"}]},{"ru":"Где король?","en":"Where''s the king?","words":[{"ru":"Где","en":"where"},{"ru":"король?","en":"king"}]},{"ru":"Король здесь.","en":"The king is here.","words":[{"ru":"Король","en":"king"},{"ru":"здесь.","en":"here"}]},{"ru":"Белые фигуры и чёрные фигуры.","en":"White pieces and black pieces.","words":[{"ru":"Белые","en":"white"},{"ru":"фигуры","en":"pieces"},{"ru":"и","en":"and"},{"ru":"чёрные","en":"black"},{"ru":"фигуры.","en":"pieces"}]},{"ru":"У меня белые.","en":"I have white.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"белые.","en":"white"}]},{"ru":"Сколько пешек? Восемь.","en":"How many pawns? Eight.","words":[{"ru":"Сколько","en":"how many"},{"ru":"пешек?","en":"pawns"},{"ru":"Восемь.","en":"eight"}]}]},{"type":"grammar","title":"Pieces have gender","paragraphs":["**Пешка** and **ладья** are feminine; **конь, слон, ферзь, король** are masculine. Adjectives agree: сильн**ая** пешка, сильн**ый** конь.","**Фигура** (\"piece\") is feminine, so: Ферзь — сильная фигура. Chess players never call the queen королева; it''s always **ферзь**."],"examples":[{"ru":"Это мой конь.","en":"This is my knight."},{"ru":"Это моя ладья.","en":"This is my rook."}]}],"drills":[{"q":"Ферзь — ___ фигура.","answer":"сильная","options":["сильная","сильные","сильный","сильное"],"en":"The queen is a strong piece.","why":{"сильный":"Сильный is masculine. The adjective agrees with фигура (feminine), not ферзь: сильная.","сильное":"Сильное is neuter. Фигура is feminine: сильная.","сильные":"Сильные is plural. One фигура: сильная."}},{"q":"Это мой ___. (knight)","answer":"конь","options":["конь","ладья","доска","пешка"],"en":"This is my knight.","why":{"пешка":"Пешка is a pawn (and feminine — it would be моя). Knight is конь.","ладья":"Ладья is a rook. Knight is конь.","доска":"Доска is the board. Knight is конь."}},{"q":"У меня восемь ___. (pawns)","answer":"пешек","options":["пешки","пешек","пешку","пешка"],"en":"I have eight pawns.","why":{"пешка":"Пешка goes with одна. From 5 up, use the genitive plural: восемь пешек.","пешки":"Пешки follows 2–4 (три пешки). After восемь: пешек.","пешку":"Пешку is the accusative singular (беру пешку). After восемь: пешек."}},{"q":"Это моя ___. (rook)","answer":"ладья","options":["король","конь","ладья","слон"],"en":"This is my rook.","why":{"конь":"Конь is a knight (and masculine — it would be мой). Rook is ладья.","слон":"Слон is a bishop. Rook is ладья.","король":"Король is the king. Rook is ладья."}}]}'::jsonb, 10, 13),
  ('a1-12', 'A1', 'chess_talk', 12, 'Let''s play!', 'Давай сыграем!', 'Start a game, choose colours and talk about whose move it is.', '{"intro":"In Russian you play \"with white\": играть белыми. That form — the instrumental — also appears in «хожу конём», \"I move my knight\".","sections":[{"type":"lines","kind":"dialogue","title":"A friendly game","lines":[{"ru":"Давай сыграем в шахматы!","en":"Let''s play chess!","words":[{"ru":"Давай","en":"let''s"},{"ru":"сыграем","en":"play"},{"ru":"в","en":"(at)"},{"ru":"шахматы!","en":"chess"}],"speaker":"Максим"},{"ru":"Давай! Ты играешь белыми или чёрными?","en":"Sure! Are you playing white or black?","words":[{"ru":"Давай!","en":"let''s"},{"ru":"Ты","en":"you"},{"ru":"играешь","en":"play"},{"ru":"белыми","en":"(with) white"},{"ru":"или","en":"or"},{"ru":"чёрными?","en":"(with) black"}],"speaker":"Анна"},{"ru":"Белыми.","en":"White.","words":[{"ru":"Белыми.","en":"(with) white"}],"speaker":"Максим"},{"ru":"Хорошо. Твой ход.","en":"Okay. Your move.","words":[{"ru":"Хорошо.","en":"good"},{"ru":"Твой","en":"your"},{"ru":"ход.","en":"move"}],"speaker":"Анна"},{"ru":"Я хожу пешкой.","en":"I''m moving a pawn.","words":[{"ru":"Я","en":"I"},{"ru":"хожу","en":"move"},{"ru":"пешкой.","en":"(with) a pawn"}],"speaker":"Максим"},{"ru":"Теперь мой ход.","en":"Now it''s my move.","words":[{"ru":"Теперь","en":"now"},{"ru":"мой","en":"my"},{"ru":"ход.","en":"move"}],"speaker":"Анна"},{"ru":"Шах!","en":"Check!","words":[{"ru":"Шах!","en":"check"}],"speaker":"Максим"},{"ru":"Ой! Хороший ход!","en":"Oh! Good move!","words":[{"ru":"Ой!","en":"oh"},{"ru":"Хороший","en":"good"},{"ru":"ход!","en":"move"}],"speaker":"Анна"}]},{"type":"lines","kind":"phrases","title":"At the end","lines":[{"ru":"Ваш ход.","en":"Your move. (formal)","words":[{"ru":"Ваш","en":"your"},{"ru":"ход.","en":"move"}],"tag":"formal"},{"ru":"Хорошая партия!","en":"Good game!","words":[{"ru":"Хорошая","en":"good"},{"ru":"партия!","en":"game"}]},{"ru":"Спасибо за игру!","en":"Thanks for the game!","words":[{"ru":"Спасибо","en":"thanks"},{"ru":"за","en":"for"},{"ru":"игру!","en":"the game"}]},{"ru":"Сыграем ещё?","en":"Shall we play again?","words":[{"ru":"Сыграем","en":"(shall we) play"},{"ru":"ещё?","en":"again"}]}]},{"type":"grammar","title":"Playing \"with\" a piece","paragraphs":["After **играть** (colours) and **ходить** (pieces), Russian uses the instrumental case:","играть бел**ыми** / чёрн**ыми** · ходить пешк**ой**, кон**ём**, слон**ом**, ладь**ёй**, ферз**ём**, корол**ём**."],"examples":[{"ru":"Я играю чёрными.","en":"I''m playing black."},{"ru":"Я хожу конём.","en":"I''m moving my knight."}]}],"drills":[{"q":"Ты играешь ___? (white)","answer":"белыми","options":["белая","белые","белый","белыми"],"en":"Are you playing white?","why":{"белые":"Белые is \"White\" as a subject (белые выиграли). Playing a colour uses the instrumental: играть белыми.","белый":"Белый is the masculine adjective \"white\". Playing a colour: белыми.","белая":"Белая is the feminine adjective. Playing a colour: белыми."}},{"q":"Твой ___.","answer":"ход","options":["ходить","ход","ходы","хожу"],"en":"Your move.","why":{"ходить":"Ходить is the verb \"to move, to walk\". \"Your move\" needs the noun: ход.","хожу":"Хожу is \"I move\". The noun is ход: Твой ход.","ходы":"Ходы is plural (\"moves\") and would need твои. One move: ход."}},{"q":"Я хожу ___. (конь)","answer":"конём","options":["конём","коня","коню","конь"],"en":"I''m moving my knight.","why":{"конь":"Moving a piece uses the instrumental: ходить конём.","коня":"Коня is the accusative (беру коня, \"I take the knight\"). Moving it: конём.","коню":"Коню is the dative (\"to the knight\"). Moving it: конём."}},{"q":"Спасибо за ___!","answer":"игру","options":["игра","игры","игре","игру"],"en":"Thanks for the game!","why":{"игра":"За meaning \"for\" takes the accusative: спасибо за игру.","игры":"Игры is the genitive or plural. За needs игру.","игре":"Игре is the prepositional (об игре). За needs игру."}}]}'::jsonb, 12, 12),
  ('a1-13', 'A1', 'hobbies', 13, 'Hobbies', 'Хобби', 'Say what you like doing — and learn the difference between играть в and играть на.', '{"intro":"Two common ways to say \"I like\": я люблю (I love, I like doing) and мне нравится (it pleases me).","sections":[{"type":"lines","kind":"phrases","title":"Free time","lines":[{"ru":"Что ты любишь делать?","en":"What do you like to do?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"любишь","en":"like"},{"ru":"делать?","en":"to do"}]},{"ru":"Я люблю музыку и спорт.","en":"I love music and sports.","words":[{"ru":"Я","en":"I"},{"ru":"люблю","en":"like"},{"ru":"музыку","en":"music"},{"ru":"и","en":"and"},{"ru":"спорт.","en":"sport"}]},{"ru":"Я играю в шахматы и в футбол.","en":"I play chess and soccer.","words":[{"ru":"Я","en":"I"},{"ru":"играю","en":"play"},{"ru":"в","en":"(at)"},{"ru":"шахматы","en":"chess"},{"ru":"и","en":"and"},{"ru":"в","en":"(at)"},{"ru":"футбол.","en":"football"}],"note":"Games and sports: играть в + the game."},{"ru":"Я играю на гитаре.","en":"I play the guitar.","words":[{"ru":"Я","en":"I"},{"ru":"играю","en":"play"},{"ru":"на","en":"on"},{"ru":"гитаре.","en":"guitar"}],"note":"Instruments: играть на + the instrument."},{"ru":"Мне нравится читать.","en":"I like reading.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравится","en":"is pleasing"},{"ru":"читать.","en":"to read"}]},{"ru":"Мне нравятся фильмы.","en":"I like movies.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравятся","en":"are pleasing"},{"ru":"фильмы.","en":"films"}],"note":"нравится for one thing or an activity; нравятся for several things."},{"ru":"Ты любишь готовить?","en":"Do you like cooking?","words":[{"ru":"Ты","en":"you"},{"ru":"любишь","en":"like"},{"ru":"готовить?","en":"to cook"}]},{"ru":"Не очень.","en":"Not really.","words":[{"ru":"Не","en":"not"},{"ru":"очень.","en":"very"}]},{"ru":"По выходным я гуляю в парке.","en":"On weekends I go for walks in the park.","words":[{"ru":"По","en":"on"},{"ru":"выходным","en":"weekends"},{"ru":"я","en":"I"},{"ru":"гуляю","en":"stroll"},{"ru":"в","en":"in"},{"ru":"парке.","en":"park"}]}]},{"type":"grammar","title":"В or на?","paragraphs":["**Играть в** + game or sport: в шахматы, в футбол, в теннис.","**Играть на** + musical instrument: на гитаре, на пианино.","**Мне нравится** + one thing or a verb; **мне нравятся** + several things."],"examples":[{"ru":"Мне нравится этот город.","en":"I like this city."},{"ru":"Мне нравятся эти книги.","en":"I like these books."}]}],"drills":[{"q":"Я играю ___ шахматы.","answer":"в","options":["с","на","в","о"],"en":"I play chess.","why":{"на":"Играть на is for musical instruments (на гитаре). Games take в: играть в шахматы.","с":"С means \"with\". Games take в: играть в шахматы.","о":"О means \"about\". Games take в: играть в шахматы."}},{"q":"Я играю ___ пианино.","answer":"на","options":["на","о","с","в"],"en":"I play the piano.","why":{"в":"Играть в is for games and sports (в шахматы). Instruments take на: играть на пианино.","с":"С means \"with\". Instruments take на: играть на пианино.","о":"О means \"about\". Instruments take на: играть на пианино."}},{"q":"Мне ___ фильмы.","answer":"нравятся","options":["нравишься","нравятся","нравится","нравлюсь"],"en":"I like movies.","why":{"нравится":"Нравится is for one thing. Фильмы is plural: нравятся.","нравлюсь":"Нравлюсь means \"I am liked\" (я нравлюсь). The films are what''s liked: нравятся.","нравишься":"Нравишься is \"you are liked\" (ты мне нравишься — I like you). Films take нравятся."}},{"q":"Что ты ___ делать?","answer":"любишь","options":["любить","люблю","любишь","любит"],"en":"What do you like to do?","why":{"люблю":"Люблю is the я form. With ты use любишь.","любит":"Любит is the он/она form. With ты use любишь.","любить":"Любить is the infinitive. With ты use любишь."}}]}'::jsonb, 9, 10),
  ('a1-14', 'A1', 'grammar', 14, 'He, she, it: gender', 'Он, она, оно', 'Every Russian noun has a gender. Learn to spot it and use the right pronoun.', '{"intro":"Things are \"he\", \"she\" or \"it\" in Russian depending on the word''s ending, not on what they are.","sections":[{"type":"lines","kind":"phrases","title":"Who and what","lines":[{"ru":"Я играю, ты играешь.","en":"I play, you play.","words":[{"ru":"Я","en":"I"},{"ru":"играю,","en":"play"},{"ru":"ты","en":"you"},{"ru":"играешь.","en":"play"}]},{"ru":"Он играет, она играет.","en":"He plays, she plays.","words":[{"ru":"Он","en":"he"},{"ru":"играет,","en":"plays"},{"ru":"она","en":"she"},{"ru":"играет.","en":"plays"}]},{"ru":"Мы играем, вы играете, они играют.","en":"We play, you play, they play.","words":[{"ru":"Мы","en":"we"},{"ru":"играем,","en":"play"},{"ru":"вы","en":"you"},{"ru":"играете,","en":"play"},{"ru":"они","en":"they"},{"ru":"играют.","en":"play"}]},{"ru":"Это мой стол.","en":"This is my table.","words":[{"ru":"Это","en":"this is"},{"ru":"мой","en":"my"},{"ru":"стол.","en":"table"}]},{"ru":"Это моя книга.","en":"This is my book.","words":[{"ru":"Это","en":"this is"},{"ru":"моя","en":"my"},{"ru":"книга.","en":"book"}]},{"ru":"Это моё окно.","en":"This is my window.","words":[{"ru":"Это","en":"this is"},{"ru":"моё","en":"my"},{"ru":"окно.","en":"window"}]},{"ru":"Это мои друзья.","en":"These are my friends.","words":[{"ru":"Это","en":"this is"},{"ru":"мои","en":"my"},{"ru":"друзья.","en":"friends"}]},{"ru":"Где телефон? Вот он.","en":"Where''s the phone? Here it is.","words":[{"ru":"Где","en":"where"},{"ru":"телефон?","en":"phone"},{"ru":"Вот","en":"here is"},{"ru":"он.","en":"it"}],"note":"Телефон is masculine, so \"it\" is он."},{"ru":"Где книга? Вот она.","en":"Where''s the book? Here it is.","words":[{"ru":"Где","en":"where"},{"ru":"книга?","en":"book"},{"ru":"Вот","en":"here is"},{"ru":"она.","en":"it"}]}]},{"type":"grammar","title":"Three genders","paragraphs":["**Masculine:** ends in a consonant or -й (стол, музей), sometimes -ь (конь). **Feminine:** ends in -а / -я (книга, неделя), sometimes -ь (ночь, дверь). **Neuter:** ends in -о / -е (окно, море).","For a word ending in -ь, check the dictionary. The pronoun matches the noun: стол → он, книга → она, окно → оно."],"examples":[{"ru":"Где окно? Вот оно.","en":"Where''s the window? Here it is."},{"ru":"Где мой конь? Вот он.","en":"Where''s my knight? Here it is."}]}],"drills":[{"q":"Где окно? Вот ___.","answer":"оно","options":["он","оно","они","она"],"en":"Where''s the window? Here it is.","why":{"он":"Он replaces masculine nouns. Окно is neuter (ends in -о): оно.","она":"Она replaces feminine nouns. Окно is neuter: оно.","они":"Они is plural. One окно: оно."}},{"q":"Где книга? Вот ___.","answer":"она","options":["она","оно","они","он"],"en":"Where''s the book? Here it is.","why":{"он":"Он replaces masculine nouns. Книга is feminine (ends in -а): она.","оно":"Оно replaces neuter nouns. Книга is feminine: она.","они":"Они is plural. One книга: она."}},{"q":"Они ___ в шахматы.","answer":"играют","options":["играют","играешь","играем","играет"],"en":"They play chess.","why":{"играет":"Играет is the он/она form. With они use играют.","играем":"Играем is the мы form. With они use играют.","играешь":"Играешь is the ты form. With они use играют."}},{"q":"Это ___ друзья.","answer":"мои","options":["моё","мой","моя","мои"],"en":"These are my friends.","why":{"мой":"Мой is masculine singular. Друзья is plural: мои.","моя":"Моя is feminine singular. Друзья is plural: мои.","моё":"Моё is neuter singular. Друзья is plural: мои."}}]}'::jsonb, 9, 13),
  ('a1-15', 'A1', 'meeting', 15, 'Where do you live?', 'Где ты живёшь?', 'Say where you live, when you moved, who you live with and what''s near your home.', '{"intro":"A conversation lesson: every answer leads to the next question. Listen to each question and answer separately, say the answers out loud, and look at the follow-up questions under each answer — they show where the conversation could go next.","sections":[{"type":"lines","kind":"conversation","title":"A new neighbour","lines":[{"ru":"Где ты живёшь?","en":"Where do you live?","words":[{"ru":"Где","en":"where"},{"ru":"ты","en":"you"},{"ru":"живёшь?","en":"live"}],"speaker":"Аня","role":"q","x":"a1-15:1"},{"ru":"Я живу во Флориде. Здесь всегда тепло!","en":"I live in Florida. It''s always warm here!","words":[{"ru":"Я","en":"I"},{"ru":"живу","en":"live"},{"ru":"во","en":"in"},{"ru":"Флориде.","en":"Florida"},{"ru":"Здесь","en":"here"},{"ru":"всегда","en":"always"},{"ru":"тепло!","en":"warm"}],"speaker":"Алекс","note":"Флорида → во Флориде: after в (in), a place takes the prepositional case, usually -е. В becomes во before в or ф plus a consonant.","follow":[{"ru":"Тебе нравится жара?","en":"Do you like the heat?"},{"ru":"Тебе нравится твой район?","en":"Do you like your neighbourhood?","link":"a1-15:6","linkTopic":"Where do you live?","linkLevel":"A1"}],"role":"a","x":"a1-15:1"},{"ru":"Ты давно во Флориде?","en":"Have you been in Florida long?","words":[{"ru":"Ты","en":"you"},{"ru":"давно","en":"long"},{"ru":"во","en":"in"},{"ru":"Флориде?","en":"Florida"}],"speaker":"Аня","role":"q","x":"a1-15:2"},{"ru":"Нет, я переехал недавно.","en":"No, I moved here recently.","words":[{"ru":"Нет,","en":"no"},{"ru":"я","en":"I"},{"ru":"переехал","f":"переехала","en":"moved"},{"ru":"недавно.","en":"recently"}],"ruF":"Нет, я переехала недавно.","speaker":"Алекс","note":"Переехал (a woman says переехала) is the past of переехать — to move to a new home or city. Давно = for a long time, недавно = recently.","follow":[{"ru":"Где ты жил раньше?","en":"Where did you live before?","ruF":"Где ты жила раньше?"},{"ru":"Тебе здесь нравится?","en":"Do you like it here?"}],"role":"a","x":"a1-15:2"},{"ru":"Почему ты переехал во Флориду?","en":"Why did you move to Florida?","words":[{"ru":"Почему","en":"why"},{"ru":"ты","en":"you"},{"ru":"переехал","f":"переехала","en":"moved"},{"ru":"во","en":"to"},{"ru":"Флориду?","en":"Florida"}],"ruF":"Почему ты переехала во Флориду?","speaker":"Аня","role":"q","x":"a1-15:3"},{"ru":"Потому что здесь есть работа и тепло.","en":"Because there''s work here, and it''s warm.","words":[{"ru":"Потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"здесь","en":"here"},{"ru":"есть","en":"there is"},{"ru":"работа","en":"work"},{"ru":"и","en":"and"},{"ru":"тепло.","en":"warmth"}],"speaker":"Алекс","note":"Почему? — Потому что… is the standard why/because pair. Motion to a place takes the accusative: во Флориду. Being there takes the prepositional: во Флориде.","follow":[{"ru":"Чем ты занимаешься?","en":"What do you do?","link":"a1-16:1","linkTopic":"What do you do?","linkLevel":"A1"},{"ru":"Ты скучаешь по дому?","en":"Do you miss home?"}],"role":"a","x":"a1-15:3"},{"ru":"С кем ты живёшь?","en":"Who do you live with?","words":[{"ru":"С","en":"with"},{"ru":"кем","en":"whom"},{"ru":"ты","en":"you"},{"ru":"живёшь?","en":"live"}],"speaker":"Аня","role":"q","x":"a1-15:4"},{"ru":"С другом. Мы вместе снимаем квартиру.","en":"With a friend. We rent an apartment together.","words":[{"ru":"С","en":"with"},{"ru":"другом.","en":"friend"},{"ru":"Мы","en":"we"},{"ru":"вместе","en":"together"},{"ru":"снимаем","en":"rent"},{"ru":"квартиру.","en":"apartment"}],"speaker":"Алекс","note":"С (with) takes the instrumental case: друг → с другом, подруга → с подругой. Снимать квартиру = to rent an apartment.","follow":[{"ru":"Где живёт твоя семья?","en":"Where does your family live?","link":"a1-22:1","linkTopic":"The people close to you","linkLevel":"A1"},{"ru":"Вы давно знакомы?","en":"Have you known each other long?"}],"role":"a","x":"a1-15:4"},{"ru":"У вас большая квартира?","en":"Is your apartment big?","words":[{"ru":"У","en":"by"},{"ru":"вас","en":"you"},{"ru":"большая","en":"big"},{"ru":"квартира?","en":"apartment"}],"speaker":"Аня","role":"q","x":"a1-15:5"},{"ru":"Нет, небольшая, но удобная.","en":"No, it''s smallish, but comfortable.","words":[{"ru":"Нет,","en":"no"},{"ru":"небольшая,","en":"smallish"},{"ru":"но","en":"but"},{"ru":"удобная.","en":"comfortable"}],"speaker":"Алекс","note":"Квартира is feminine, so its adjectives end in -ая: большая, небольшая, удобная. Небольшая is a softer \"not big\".","follow":[{"ru":"Сколько у вас комнат?","en":"How many rooms do you have?"},{"ru":"У вас есть балкон?","en":"Do you have a balcony?"}],"role":"a","x":"a1-15:5"},{"ru":"Тебе нравится твой район?","en":"Do you like your neighbourhood?","words":[{"ru":"Тебе","en":"to you"},{"ru":"нравится","en":"pleases"},{"ru":"твой","en":"your"},{"ru":"район?","en":"neighbourhood"}],"speaker":"Аня","role":"q","x":"a1-15:6"},{"ru":"Да, очень. Здесь тихо, и рядом есть парк.","en":"Yes, very much. It''s quiet here, and there''s a park nearby.","words":[{"ru":"Да,","en":"yes"},{"ru":"очень.","en":"very much"},{"ru":"Здесь","en":"here"},{"ru":"тихо,","en":"quiet"},{"ru":"и","en":"and"},{"ru":"рядом","en":"nearby"},{"ru":"есть","en":"there is"},{"ru":"парк.","en":"park"}],"speaker":"Алекс","note":"Тебе нравится…? is literally \"does it please you?\": the thing you like is the subject. Мне нравится район = I like the neighbourhood.","follow":[{"ru":"Ты часто гуляешь в парке?","en":"Do you often walk in the park?"},{"ru":"Как ты отдыхаешь?","en":"How do you relax?","link":"a1-19:2","linkTopic":"Getting to know you","linkLevel":"A1"}],"role":"a","x":"a1-15:6"},{"ru":"А что ещё есть рядом с домом?","en":"And what else is near your home?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"ещё","en":"else"},{"ru":"есть","en":"there is"},{"ru":"рядом","en":"near"},{"ru":"с","en":"with"},{"ru":"домом?","en":"home"}],"speaker":"Аня","role":"q","x":"a1-15:7"},{"ru":"Магазин, кафе и спортзал. Например, в спортзал я хожу пешком.","en":"A shop, a café and a gym. For example, I walk to the gym.","words":[{"ru":"Магазин,","en":"shop"},{"ru":"кафе","en":"café"},{"ru":"и","en":"and"},{"ru":"спортзал.","en":"gym"},{"ru":"Например,","en":"for example"},{"ru":"в","en":"to"},{"ru":"спортзал","en":"gym"},{"ru":"я","en":"I"},{"ru":"хожу","en":"go"},{"ru":"пешком.","en":"on foot"}],"speaker":"Алекс","note":"Рядом с домом = near the house (с + instrumental). Например (for example) adds a detail — and gives the other person something to ask about.","follow":[{"ru":"Что ты делаешь после работы?","en":"What do you do after work?","link":"a1-17:5","linkTopic":"From morning to evening","linkLevel":"A1"},{"ru":"Ты часто ходишь в спортзал?","en":"Do you often go to the gym?"}],"role":"a","x":"a1-15:7"}]},{"type":"grammar","title":"Where? — the prepositional case","paragraphs":["To say where something is, use **в** or **на** + the prepositional case. Most nouns change their ending to **-е**: Москва → в Москве, город → в городе, парк → в парке. Words ending in -ия take **-ии**: Россия → в России.","**Во** replaces в before в or ф plus a consonant: во Флориде, во Франции. Movement \"to\" a place uses the accusative instead: Я переехал во Флориду."],"examples":[{"ru":"Я живу в Москве.","en":"I live in Moscow."},{"ru":"Мы гуляем в парке.","en":"We walk in the park."},{"ru":"Я переехал во Флориду.","en":"I moved to Florida."}]},{"type":"grammar","title":"Linking words: потому что, например","paragraphs":["**Потому что** (because) answers почему (why): Почему ты переехал? — Потому что здесь есть работа.","**Например** (for example) adds a concrete example. Put a comma after it. Short answers sound more natural with one more sentence that starts with a linking word."],"examples":[{"ru":"Мне нравится район, потому что здесь тихо.","en":"I like the area because it''s quiet."},{"ru":"Здесь всё рядом. Например, магазин и кафе.","en":"Everything''s close. For example, the shop and the café."}]}],"drills":[{"q":"Я живу ___ Флориде.","answer":"во","options":["во","в","на","из"],"en":"I live in Florida.","why":{"в":"Before в or ф plus a consonant, в becomes во: во Флориде.","на":"На is for open spaces and events (на работе, на улице). States and cities take в/во.","из":"Из means \"from\" and takes the genitive: из Флориды. To say \"in\", use во."}},{"q":"Почему ты переехал? — ___ здесь есть работа.","answer":"Потому что","options":["Поэтому","Например","Потому что","Почему"],"en":"Why did you move? — Because there''s work here.","why":{"Поэтому":"Поэтому means \"that''s why\" and comes after the reason. To answer почему, start with потому что.","Например":"Например means \"for example\". The answer to почему begins with потому что.","Почему":"Почему is the question word \"why\". The answer starts with потому что."}},{"q":"Я живу с ___.","answer":"другом","options":["другом","друга","другу","друг"],"en":"I live with a friend.","why":{"друг":"After с (with) the noun takes the instrumental case: с другом.","друга":"Друга is the accusative or genitive. С (with) needs the instrumental: с другом.","другу":"Другу is the dative (\"to a friend\"). С (with) needs the instrumental: с другом."}}]}'::jsonb, 14, 12),
  ('a1-16', 'A1', 'work', 16, 'What do you do?', 'Чем ты занимаешься?', 'Talk about your job: what you do, where it is, how you get there and when you''re free.', '{"intro":"Russians rarely ask \"What''s your job?\" directly. They ask Чем ты занимаешься? — \"What do you occupy yourself with?\" Watch how each answer about work leads naturally to the next question.","sections":[{"type":"lines","kind":"conversation","title":"At a party","lines":[{"ru":"Чем ты занимаешься?","en":"What do you do?","words":[{"ru":"Чем","en":"(with) what"},{"ru":"ты","en":"you"},{"ru":"занимаешься?","en":"occupy yourself"}],"speaker":"Дима","role":"q","x":"a1-16:1"},{"ru":"Я работаю в мебельном магазине.","en":"I work at a furniture store.","words":[{"ru":"Я","en":"I"},{"ru":"работаю","en":"work"},{"ru":"в","en":"in"},{"ru":"мебельном","en":"furniture"},{"ru":"магазине.","en":"store"}],"speaker":"Алекс","note":"Чем ты занимаешься? asks about your job or studies. В магазине — \"in a store\": the prepositional case. Мебельный (furniture) is the adjective from мебель.","follow":[{"ru":"Тебе нравится твоя работа?","en":"Do you like your job?","link":"a2-21:1","linkTopic":"Talking about work","linkLevel":"A2"},{"ru":"Это далеко от дома?","en":"Is it far from home?"}],"role":"a","x":"a1-16:1"},{"ru":"А что ты там делаешь?","en":"And what do you do there?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"там","en":"there"},{"ru":"делаешь?","en":"do"}],"speaker":"Дима","role":"q","x":"a1-16:2"},{"ru":"Я работаю продавцом. Я помогаю людям выбирать мебель.","en":"I work as a salesperson. I help people choose furniture.","words":[{"ru":"Я","en":"I"},{"ru":"работаю","en":"work"},{"ru":"продавцом.","en":"salesperson"},{"ru":"Я","en":"I"},{"ru":"помогаю","en":"help"},{"ru":"людям","en":"people"},{"ru":"выбирать","en":"choose"},{"ru":"мебель.","en":"furniture"}],"speaker":"Алекс","note":"Работать кем? — the job takes the instrumental case: продавец → продавцом, водитель → водителем. Помогать takes the dative: помогаю людям.","follow":[{"ru":"Тебе нравится общаться с людьми?","en":"Do you like talking to people?"},{"ru":"Что самое сложное в твоей работе?","en":"What''s the hardest thing about your job?","link":"a2-21:2","linkTopic":"Talking about work","linkLevel":"A2"}],"role":"a","x":"a1-16:2"},{"ru":"Где находится твой магазин?","en":"Where is your store?","words":[{"ru":"Где","en":"where"},{"ru":"находится","en":"is located"},{"ru":"твой","en":"your"},{"ru":"магазин?","en":"store"}],"speaker":"Дима","role":"q","x":"a1-16:3"},{"ru":"В центре города, недалеко от моего дома.","en":"In the city centre, not far from my home.","words":[{"ru":"В","en":"in"},{"ru":"центре","en":"centre"},{"ru":"города,","en":"of the city"},{"ru":"недалеко","en":"not far"},{"ru":"от","en":"from"},{"ru":"моего","en":"my"},{"ru":"дома.","en":"home"}],"speaker":"Алекс","note":"Находиться = to be located. Недалеко от + genitive: от дома, от работы, от центра.","follow":[{"ru":"Это удобно?","en":"Is that convenient?"},{"ru":"А что ещё есть рядом с домом?","en":"And what else is near your home?","link":"a1-15:7","linkTopic":"Where do you live?","linkLevel":"A1"}],"role":"a","x":"a1-16:3"},{"ru":"Как ты ездишь на работу?","en":"How do you get to work?","words":[{"ru":"Как","en":"how"},{"ru":"ты","en":"you"},{"ru":"ездишь","en":"travel"},{"ru":"на","en":"to"},{"ru":"работу?","en":"work"}],"speaker":"Дима","role":"q","x":"a1-16:4"},{"ru":"Обычно на машине, но иногда на автобусе.","en":"Usually by car, but sometimes by bus.","words":[{"ru":"Обычно","en":"usually"},{"ru":"на","en":"by"},{"ru":"машине,","en":"car"},{"ru":"но","en":"but"},{"ru":"иногда","en":"sometimes"},{"ru":"на","en":"by"},{"ru":"автобусе.","en":"bus"}],"speaker":"Алекс","note":"Ездить на + prepositional = to travel by: на машине, на автобусе, на метро. On foot is пешком.","follow":[{"ru":"Сколько времени ты едешь на работу?","en":"How long does it take you to get to work?"},{"ru":"У тебя есть машина?","en":"Do you have a car?"}],"role":"a","x":"a1-16:4"},{"ru":"Во сколько ты начинаешь работать?","en":"What time do you start work?","words":[{"ru":"Во","en":"at"},{"ru":"сколько","en":"what time"},{"ru":"ты","en":"you"},{"ru":"начинаешь","en":"start"},{"ru":"работать?","en":"to work"}],"speaker":"Дима","role":"q","x":"a1-16:5"},{"ru":"В девять утра, поэтому я встаю в семь.","en":"At nine in the morning, so I get up at seven.","words":[{"ru":"В","en":"at"},{"ru":"девять","en":"nine"},{"ru":"утра,","en":"in the morning"},{"ru":"поэтому","en":"so"},{"ru":"я","en":"I"},{"ru":"встаю","en":"get up"},{"ru":"в","en":"at"},{"ru":"семь.","en":"seven"}],"speaker":"Алекс","note":"Во сколько? = at what time? Поэтому (so, that''s why) comes after the reason and before the result.","follow":[{"ru":"Во сколько ты обычно просыпаешься?","en":"What time do you usually wake up?","link":"a1-17:1","linkTopic":"From morning to evening","linkLevel":"A1"},{"ru":"Во сколько ты заканчиваешь?","en":"What time do you finish?"}],"role":"a","x":"a1-16:5"},{"ru":"Ты работаешь по субботам?","en":"Do you work on Saturdays?","words":[{"ru":"Ты","en":"you"},{"ru":"работаешь","en":"work"},{"ru":"по","en":"on"},{"ru":"субботам?","en":"Saturdays"}],"speaker":"Дима","role":"q","x":"a1-16:6"},{"ru":"Да, по субботам у нас много клиентов.","en":"Yes, on Saturdays we have a lot of customers.","words":[{"ru":"Да,","en":"yes"},{"ru":"по","en":"on"},{"ru":"субботам","en":"Saturdays"},{"ru":"у","en":"by"},{"ru":"нас","en":"us"},{"ru":"много","en":"many"},{"ru":"клиентов.","en":"customers"}],"speaker":"Алекс","note":"По субботам = on Saturdays, every Saturday (по + dative plural). Много + genitive plural: много клиентов, много людей.","follow":[{"ru":"Ты устаёшь после работы?","en":"Do you get tired after work?","link":"a2-17:6","linkTopic":"What''s new?","linkLevel":"A2"},{"ru":"Тебе нравится работать по выходным?","en":"Do you like working weekends?"}],"role":"a","x":"a1-16:6"},{"ru":"А когда у тебя выходной?","en":"And when''s your day off?","words":[{"ru":"А","en":"and"},{"ru":"когда","en":"when"},{"ru":"у","en":"by"},{"ru":"тебя","en":"you"},{"ru":"выходной?","en":"day off"}],"speaker":"Дима","role":"q","x":"a1-16:7"},{"ru":"В понедельник и вторник. Кстати, ты свободен в понедельник?","en":"Monday and Tuesday. By the way, are you free on Monday?","words":[{"ru":"В","en":"on"},{"ru":"понедельник","en":"Monday"},{"ru":"и","en":"and"},{"ru":"вторник.","en":"Tuesday"},{"ru":"Кстати,","en":"by the way"},{"ru":"ты","en":"you"},{"ru":"свободен","en":"free"},{"ru":"в","en":"on"},{"ru":"понедельник?","en":"Monday"}],"speaker":"Алекс","note":"В понедельник = on Monday (в + accusative). Кстати (by the way) moves the conversation somewhere new — here, it turns the question back to Dima.","follow":[{"ru":"Какие у тебя планы на выходные?","en":"What are your plans for the weekend?","link":"a2-19:1","linkTopic":"Plans and dreams","linkLevel":"A2"},{"ru":"Хочешь сыграть со мной?","en":"Do you want to play with me?","link":"a1-19:7","linkTopic":"Getting to know you","linkLevel":"A1"}],"role":"a","x":"a1-16:7"}]},{"type":"grammar","title":"Jobs: кем and чем","paragraphs":["Questions about jobs use the instrumental case. **Чем ты занимаешься?** — what do you do? **Кем ты работаешь?** — what do you work as? The answer takes the same case: Я работаю **продавцом**, **водителем**, **врачом**.","Masculine nouns add **-ом** (or **-ем** after a soft consonant); feminine nouns change -а to **-ой**: продавщица → продавщицей."],"examples":[{"ru":"Я работаю менеджером.","en":"I work as a manager."},{"ru":"Она работает учительницей.","en":"She works as a teacher."}]},{"type":"grammar","title":"Linking words: поэтому, кстати","paragraphs":["**Поэтому** means \"so, that''s why\". It follows the reason: Я начинаю в девять, **поэтому** встаю в семь.","**Кстати** means \"by the way\". Use it to change the topic or ask something back: Кстати, ты свободен в понедельник?"],"examples":[{"ru":"Магазин недалеко, поэтому я хожу пешком.","en":"The store is close, so I walk."},{"ru":"Кстати, где ты работаешь?","en":"By the way, where do you work?"}]}],"drills":[{"q":"Я работаю ___.","answer":"продавцом","options":["продавцом","продавцу","продавца","продавец"],"en":"I work as a salesperson.","why":{"продавец":"After работать (as a job) use the instrumental: продавцом.","продавца":"Продавца is the accusative or genitive. A job after работать takes the instrumental: продавцом.","продавцу":"Продавцу is the dative (\"to the salesperson\"). Use the instrumental: продавцом."}},{"q":"Обычно я езжу на работу на ___.","answer":"машине","options":["машине","машина","машину","машиной"],"en":"I usually drive to work.","why":{"машина":"After на (by) the vehicle takes the prepositional: на машине.","машину":"Машину is the accusative (\"buy a car\"). Travelling by car is на машине.","машиной":"Машиной is the instrumental. \"By car\" in Russian is на машине."}},{"q":"Я начинаю в девять, ___ встаю в семь.","answer":"поэтому","options":["поэтому","кстати","например","потому что"],"en":"I start at nine, so I get up at seven.","why":{"потому что":"Потому что introduces a reason. The second part here is the result, so use поэтому.","например":"Например introduces an example, not a result. Use поэтому (so).","кстати":"Кстати (by the way) changes the topic. The result of starting at nine needs поэтому."}}]}'::jsonb, 14, 18),
  ('a1-17', 'A1', 'routines', 17, 'From morning to evening', 'С утра до вечера', 'Describe your day in order — first, then, after that — from waking up to going to bed.', '{"intro":"In this conversation you walk a colleague through your day. Notice how сначала, потом and после этого turn a list of actions into a little story.","sections":[{"type":"lines","kind":"conversation","title":"On a coffee break","lines":[{"ru":"Во сколько ты обычно просыпаешься?","en":"What time do you usually wake up?","words":[{"ru":"Во","en":"at"},{"ru":"сколько","en":"what time"},{"ru":"ты","en":"you"},{"ru":"обычно","en":"usually"},{"ru":"просыпаешься?","en":"wake up"}],"speaker":"Лена","role":"q","x":"a1-17:1"},{"ru":"Обычно я просыпаюсь в семь утра.","en":"I usually wake up at seven in the morning.","words":[{"ru":"Обычно","en":"usually"},{"ru":"я","en":"I"},{"ru":"просыпаюсь","en":"wake up"},{"ru":"в","en":"at"},{"ru":"семь","en":"seven"},{"ru":"утра.","en":"in the morning"}],"speaker":"Алекс","note":"Просыпаться = to wake up; вставать = to get up (out of bed). The -ся ending stays in every form: я просыпаюсь, ты просыпаешься.","follow":[{"ru":"Тебе легко вставать утром?","en":"Is it easy for you to get up in the morning?"},{"ru":"Ты жаворонок или сова?","en":"Are you a morning person or a night owl?"}],"role":"a","x":"a1-17:1"},{"ru":"А что ты делаешь сначала?","en":"And what do you do first?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делаешь","en":"do"},{"ru":"сначала?","en":"first"}],"speaker":"Лена","role":"q","x":"a1-17:2"},{"ru":"Сначала я пью кофе, потом принимаю душ.","en":"First I have coffee, then I take a shower.","words":[{"ru":"Сначала","en":"first"},{"ru":"я","en":"I"},{"ru":"пью","en":"drink"},{"ru":"кофе,","en":"coffee"},{"ru":"потом","en":"then"},{"ru":"принимаю","en":"take"},{"ru":"душ.","en":"shower"}],"speaker":"Алекс","note":"Сначала… потом… = first… then… Принимать душ = to take a shower.","follow":[{"ru":"Что ты пьёшь утром, чай или кофе?","en":"What do you drink in the morning, tea or coffee?","link":"a1-18:4","linkTopic":"Food you love","linkLevel":"A1"},{"ru":"Ты делаешь зарядку?","en":"Do you do morning exercises?"}],"role":"a","x":"a1-17:2"},{"ru":"Что ты обычно ешь на завтрак?","en":"What do you usually eat for breakfast?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"обычно","en":"usually"},{"ru":"ешь","en":"eat"},{"ru":"на","en":"for"},{"ru":"завтрак?","en":"breakfast"}],"speaker":"Лена","role":"q","x":"a1-17:3"},{"ru":"Обычно я ем яйца и тосты.","en":"I usually eat eggs and toast.","words":[{"ru":"Обычно","en":"usually"},{"ru":"я","en":"I"},{"ru":"ем","en":"eat"},{"ru":"яйца","en":"eggs"},{"ru":"и","en":"and"},{"ru":"тосты.","en":"toast"}],"speaker":"Алекс","note":"Есть (to eat) is irregular: я ем, ты ешь, он ест. На завтрак = for breakfast; на обед, на ужин.","follow":[{"ru":"Ты часто готовишь дома?","en":"Do you often cook at home?","link":"a1-18:1","linkTopic":"Food you love","linkLevel":"A1"},{"ru":"Какое твоё любимое блюдо?","en":"What''s your favourite dish?","link":"a1-18:2","linkTopic":"Food you love","linkLevel":"A1"}],"role":"a","x":"a1-17:3"},{"ru":"Ты обедаешь на работе?","en":"Do you have lunch at work?","words":[{"ru":"Ты","en":"you"},{"ru":"обедаешь","en":"have lunch"},{"ru":"на","en":"at"},{"ru":"работе?","en":"work"}],"speaker":"Лена","role":"q","x":"a1-17:4"},{"ru":"Да, я беру обед с собой.","en":"Yes, I bring my lunch with me.","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"беру","en":"take"},{"ru":"обед","en":"lunch"},{"ru":"с","en":"with"},{"ru":"собой.","en":"myself"}],"speaker":"Алекс","note":"Брать с собой = to take with you: я беру, ты берёшь. Обедать = to have lunch; обед = lunch.","follow":[{"ru":"Где ты обычно покупаешь продукты?","en":"Where do you usually buy groceries?","link":"a1-18:6","linkTopic":"Food you love","linkLevel":"A1"},{"ru":"Сколько у тебя времени на обед?","en":"How much time do you have for lunch?"}],"role":"a","x":"a1-17:4"},{"ru":"Что ты делаешь после работы?","en":"What do you do after work?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делаешь","en":"do"},{"ru":"после","en":"after"},{"ru":"работы?","en":"work"}],"speaker":"Лена","role":"q","x":"a1-17:5"},{"ru":"Обычно я иду в спортзал. После этого я готовлю ужин.","en":"I usually go to the gym. After that I cook dinner.","words":[{"ru":"Обычно","en":"usually"},{"ru":"я","en":"I"},{"ru":"иду","en":"go"},{"ru":"в","en":"to"},{"ru":"спортзал.","en":"gym"},{"ru":"После","en":"after"},{"ru":"этого","en":"that"},{"ru":"я","en":"I"},{"ru":"готовлю","en":"cook"},{"ru":"ужин.","en":"dinner"}],"speaker":"Алекс","note":"После + genitive: после работы, после ужина. После этого (after that) links two actions in order.","follow":[{"ru":"Ты часто ходишь в спортзал?","en":"Do you often go to the gym?"},{"ru":"Как ты отдыхаешь?","en":"How do you relax?","link":"a1-19:2","linkTopic":"Getting to know you","linkLevel":"A1"}],"role":"a","x":"a1-17:5"},{"ru":"Ты поздно ложишься спать?","en":"Do you go to bed late?","words":[{"ru":"Ты","en":"you"},{"ru":"поздно","en":"late"},{"ru":"ложишься","en":"lie down"},{"ru":"спать?","en":"to sleep"}],"speaker":"Лена","role":"q","x":"a1-17:6"},{"ru":"Нет, обычно в одиннадцать, потому что я рано встаю.","en":"No, usually at eleven, because I get up early.","words":[{"ru":"Нет,","en":"no"},{"ru":"обычно","en":"usually"},{"ru":"в","en":"at"},{"ru":"одиннадцать,","en":"eleven"},{"ru":"потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"я","en":"I"},{"ru":"рано","en":"early"},{"ru":"встаю.","en":"get up"}],"speaker":"Алекс","note":"Ложиться спать = to go to bed. Поздно = late, рано = early.","follow":[{"ru":"Сколько часов ты спишь?","en":"How many hours do you sleep?"},{"ru":"Ты смотришь что-нибудь перед сном?","en":"Do you watch anything before bed?"}],"role":"a","x":"a1-17:6"},{"ru":"Ты сегодня занят?","en":"Are you busy today?","words":[{"ru":"Ты","en":"you"},{"ru":"сегодня","en":"today"},{"ru":"занят?","f":"занята?","en":"busy"}],"ruF":"Ты сегодня занята?","speaker":"Лена","role":"q","x":"a1-17:7"},{"ru":"Нет, сегодня у меня свободный вечер.","en":"No, I have a free evening today.","words":[{"ru":"Нет,","en":"no"},{"ru":"сегодня","en":"today"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"свободный","en":"free"},{"ru":"вечер.","en":"evening"}],"speaker":"Алекс","note":"Занят (to a woman: занята) is a short adjective. У меня свободный вечер = I have a free evening.","follow":[{"ru":"Хочешь сыграть со мной?","en":"Do you want to play with me?","link":"a1-19:7","linkTopic":"Getting to know you","linkLevel":"A1"},{"ru":"Что ты будешь делать вечером?","en":"What will you do this evening?"}],"role":"a","x":"a1-17:7"}]},{"type":"grammar","title":"Verbs ending in -ся","paragraphs":["Many everyday verbs end in **-ся**: просыпаться (to wake up), заниматься (to do, to practise), ложиться (to lie down). Conjugate the verb as usual, then add **-сь** after a vowel or **-ся** after a consonant: я просыпаю**сь**, ты просыпаешь**ся**, мы просыпаем**ся**."],"examples":[{"ru":"Я просыпаюсь в семь.","en":"I wake up at seven."},{"ru":"Во сколько ты ложишься спать?","en":"What time do you go to bed?"}]},{"type":"grammar","title":"Telling a story: сначала, потом, после этого","paragraphs":["**Сначала** (first), **потом** (then) and **после этого** (after that) put actions in order. They make a list sound like a story."],"examples":[{"ru":"Сначала я завтракаю, потом иду на работу.","en":"First I have breakfast, then I go to work."},{"ru":"После этого я отдыхаю.","en":"After that I rest."}]}],"drills":[{"q":"Обычно я ___ в семь утра.","answer":"просыпаюсь","options":["просыпается","просыпаться","просыпаюсь","просыпаешься"],"en":"I usually wake up at seven.","why":{"просыпается":"Просыпается is the он/она form. With я use просыпаюсь.","просыпаешься":"Просыпаешься is the ты form. With я use просыпаюсь.","просыпаться":"Просыпаться is the infinitive. After я you need the conjugated form: просыпаюсь."}},{"q":"На завтрак я ___ яйца.","answer":"ем","options":["ест","ем","ешь","есть"],"en":"I eat eggs for breakfast.","why":{"ест":"Ест is the он/она form. With я use ем.","ешь":"Ешь is the ты form. With я use ем.","есть":"Есть is the infinitive (\"to eat\"). With я use ем."}},{"q":"Сначала я пью кофе, ___ принимаю душ.","answer":"потом","options":["потом","поэтому","потому что","после"],"en":"First I drink coffee, then I take a shower.","why":{"после":"После needs a noun after it (после работы). On its own, \"then\" is потом.","поэтому":"Поэтому means \"so, that''s why\" — a result, not the next step. Use потом.","потому что":"Потому что gives a reason. The next step in order is потом."}}]}'::jsonb, 14, 13),
  ('a1-18', 'A1', 'cooking', 18, 'Food you love', 'Любимая еда', 'Talk about cooking, your favourite food, Russian dishes and where you shop.', '{"intro":"Food is one of the easiest ways to keep a conversation going. Here every answer gives your friend something new to ask about.","sections":[{"type":"lines","kind":"conversation","title":"Talking about food","lines":[{"ru":"Ты часто готовишь дома?","en":"Do you often cook at home?","words":[{"ru":"Ты","en":"you"},{"ru":"часто","en":"often"},{"ru":"готовишь","en":"cook"},{"ru":"дома?","en":"at home"}],"speaker":"Оля","role":"q","x":"a1-18:1"},{"ru":"Да, почти каждый день. Особенно я люблю готовить мясо и рис.","en":"Yes, almost every day. I especially love cooking meat and rice.","words":[{"ru":"Да,","en":"yes"},{"ru":"почти","en":"almost"},{"ru":"каждый","en":"every"},{"ru":"день.","en":"day"},{"ru":"Особенно","en":"especially"},{"ru":"я","en":"I"},{"ru":"люблю","en":"love"},{"ru":"готовить","en":"to cook"},{"ru":"мясо","en":"meat"},{"ru":"и","en":"and"},{"ru":"рис.","en":"rice"}],"speaker":"Алекс","note":"Любить + infinitive = to love doing something: люблю готовить. Особенно = especially.","follow":[{"ru":"Кто тебя научил готовить?","en":"Who taught you to cook?"},{"ru":"Что ты готовишь чаще всего?","en":"What do you cook most often?"}],"role":"a","x":"a1-18:1"},{"ru":"Какое твоё любимое блюдо?","en":"What''s your favourite dish?","words":[{"ru":"Какое","en":"which"},{"ru":"твоё","en":"your"},{"ru":"любимое","en":"favourite"},{"ru":"блюдо?","en":"dish"}],"speaker":"Оля","role":"q","x":"a1-18:2"},{"ru":"Мне очень нравится паста с курицей.","en":"I really like pasta with chicken.","words":[{"ru":"Мне","en":"to me"},{"ru":"очень","en":"very"},{"ru":"нравится","en":"pleases"},{"ru":"паста","en":"pasta"},{"ru":"с","en":"with"},{"ru":"курицей.","en":"chicken"}],"speaker":"Алекс","note":"Блюдо is neuter, so the question uses какое, твоё, любимое. С + instrumental: с курицей, с сыром, с молоком.","follow":[{"ru":"Ты умеешь готовить пасту?","en":"Can you make pasta?"},{"ru":"Какая еда тебе не нравится?","en":"What food don''t you like?"}],"role":"a","x":"a1-18:2"},{"ru":"Ты пробовал русскую кухню?","en":"Have you tried Russian food?","words":[{"ru":"Ты","en":"you"},{"ru":"пробовал","f":"пробовала","en":"tried"},{"ru":"русскую","en":"Russian"},{"ru":"кухню?","en":"cuisine"}],"ruF":"Ты пробовала русскую кухню?","speaker":"Оля","role":"q","x":"a1-18:3"},{"ru":"Да, я пробовал борщ и блины. Было очень вкусно!","en":"Yes, I''ve tried borscht and blini. It was delicious!","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"пробовал","f":"пробовала","en":"tried"},{"ru":"борщ","en":"borscht"},{"ru":"и","en":"and"},{"ru":"блины.","en":"pancakes"},{"ru":"Было","en":"it was"},{"ru":"очень","en":"very"},{"ru":"вкусно!","en":"tasty"}],"ruF":"Да, я пробовала борщ и блины. Было очень вкусно!","speaker":"Алекс","note":"Пробовал (a woman: пробовала) is the past of пробовать, \"to try (food)\". Было вкусно = it was tasty — the impersonal past uses было.","follow":[{"ru":"Хочешь попробовать пельмени?","en":"Do you want to try pelmeni?"},{"ru":"Где ты их пробовал?","en":"Where did you try them?","ruF":"Где ты их пробовала?"}],"role":"a","x":"a1-18:3"},{"ru":"Что ты пьёшь утром, чай или кофе?","en":"What do you drink in the morning, tea or coffee?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"пьёшь","en":"drink"},{"ru":"утром,","en":"in the morning"},{"ru":"чай","en":"tea"},{"ru":"или","en":"or"},{"ru":"кофе?","en":"coffee"}],"speaker":"Оля","role":"q","x":"a1-18:4"},{"ru":"Кофе, конечно! Без кофе я не могу проснуться.","en":"Coffee, of course! I can''t wake up without coffee.","words":[{"ru":"Кофе,","en":"coffee"},{"ru":"конечно!","en":"of course"},{"ru":"Без","en":"without"},{"ru":"кофе","en":"coffee"},{"ru":"я","en":"I"},{"ru":"не","en":"not"},{"ru":"могу","en":"can"},{"ru":"проснуться.","en":"wake up"}],"speaker":"Алекс","note":"Без + genitive = without: без молока, без сахара. Кофе never changes its ending — and it''s masculine: чёрный кофе.","follow":[{"ru":"Ты пьёшь кофе с молоком?","en":"Do you take your coffee with milk?"},{"ru":"Сколько чашек кофе ты пьёшь в день?","en":"How many cups of coffee do you drink a day?"}],"role":"a","x":"a1-18:4"},{"ru":"Ты любишь сладкое?","en":"Do you like sweets?","words":[{"ru":"Ты","en":"you"},{"ru":"любишь","en":"love"},{"ru":"сладкое?","en":"sweet things"}],"speaker":"Оля","role":"q","x":"a1-18:5"},{"ru":"Не очень. Но иногда я ем мороженое.","en":"Not really. But sometimes I have ice cream.","words":[{"ru":"Не","en":"not"},{"ru":"очень.","en":"very"},{"ru":"Но","en":"but"},{"ru":"иногда","en":"sometimes"},{"ru":"я","en":"I"},{"ru":"ем","en":"eat"},{"ru":"мороженое.","en":"ice cream"}],"speaker":"Алекс","note":"Сладкое = sweet things (an adjective used as a noun). Мороженое (ice cream) works the same way. Не очень = not really.","follow":[{"ru":"Какое мороженое ты любишь?","en":"What ice cream do you like?"},{"ru":"Ты умеешь печь торты?","en":"Can you bake cakes?"}],"role":"a","x":"a1-18:5"},{"ru":"Где ты обычно покупаешь продукты?","en":"Where do you usually buy groceries?","words":[{"ru":"Где","en":"where"},{"ru":"ты","en":"you"},{"ru":"обычно","en":"usually"},{"ru":"покупаешь","en":"buy"},{"ru":"продукты?","en":"groceries"}],"speaker":"Оля","role":"q","x":"a1-18:6"},{"ru":"В супермаркете рядом с домом. Там есть всё.","en":"At the supermarket near my home. They have everything there.","words":[{"ru":"В","en":"in"},{"ru":"супермаркете","en":"supermarket"},{"ru":"рядом","en":"near"},{"ru":"с","en":"with"},{"ru":"домом.","en":"home"},{"ru":"Там","en":"there"},{"ru":"есть","en":"there is"},{"ru":"всё.","en":"everything"}],"speaker":"Алекс","note":"Продукты means groceries, not \"products\". Там есть всё = there''s everything there.","follow":[{"ru":"Сколько ты тратишь на продукты?","en":"How much do you spend on groceries?"},{"ru":"На что ты обычно тратишь деньги?","en":"What do you usually spend money on?","link":"a2-22:1","linkTopic":"Talking about money","linkLevel":"A2"}],"role":"a","x":"a1-18:6"},{"ru":"Хочешь научиться готовить блины?","en":"Do you want to learn to make blini?","words":[{"ru":"Хочешь","en":"want"},{"ru":"научиться","en":"to learn"},{"ru":"готовить","en":"to cook"},{"ru":"блины?","en":"pancakes"}],"speaker":"Оля","role":"q","x":"a1-18:7"},{"ru":"Да, очень! Ты можешь меня научить?","en":"Yes, I''d love to! Can you teach me?","words":[{"ru":"Да,","en":"yes"},{"ru":"очень!","en":"very much"},{"ru":"Ты","en":"you"},{"ru":"можешь","en":"can"},{"ru":"меня","en":"me"},{"ru":"научить?","en":"teach"}],"speaker":"Алекс","note":"Научиться = to learn (a skill); научить = to teach. Меня научить = to teach me (accusative).","follow":[{"ru":"Когда тебе удобно?","en":"When is good for you?"},{"ru":"Что нужно купить для блинов?","en":"What do we need to buy for blini?"}],"role":"a","x":"a1-18:7"}]},{"type":"grammar","title":"Liking things: люблю and мне нравится","paragraphs":["**Я люблю** + a noun or an infinitive says what you love in general: Я люблю мясо. Я люблю готовить.","**Мне нравится** is softer — \"I like\". The thing you like is the subject, so with plural things the verb is plural: Мне нравятся блины."],"examples":[{"ru":"Я люблю готовить.","en":"I love cooking."},{"ru":"Мне нравятся блины.","en":"I like blini."}]},{"type":"grammar","title":"С and без","paragraphs":["**С** (with) takes the instrumental: с курицей, с молоком. **Без** (without) takes the genitive: без молока, без сахара."],"examples":[{"ru":"Кофе с молоком, пожалуйста.","en":"Coffee with milk, please."},{"ru":"Чай без сахара.","en":"Tea without sugar."}]}],"drills":[{"q":"Мне очень ___ блины.","answer":"нравятся","options":["любит","нравятся","люблю","нравится"],"en":"I really like blini.","why":{"нравится":"Блины is plural, so the verb is plural too: нравятся.","люблю":"Люблю needs я, not мне: Я люблю блины. With мне use нравятся.","любит":"Любит is the он/она form and doesn''t go with мне. Use нравятся."}},{"q":"Чай без ___, пожалуйста.","answer":"сахара","options":["сахаром","сахару","сахар","сахара"],"en":"Tea without sugar, please.","why":{"сахар":"Без (without) takes the genitive: без сахара.","сахаром":"Сахаром is the instrumental — it goes with с: с сахаром. Без needs сахара.","сахару":"Сахару is the dative. Без (without) takes the genitive: сахара."}},{"q":"Паста с ___.","answer":"курицей","options":["курицы","курицей","курица","курицу"],"en":"Pasta with chicken.","why":{"курица":"After с (with) use the instrumental: с курицей.","курицу":"Курицу is the accusative (\"I''m buying chicken\"). After с (with) use курицей.","курицы":"Курицы is the genitive — it goes with без: без курицы. With с use курицей."}}]}'::jsonb, 14, 15),
  ('a1-19', 'A1', 'hobbies', 19, 'Getting to know you', 'Давай познакомимся поближе', 'Ask about someone''s day, free time, music, films and travel — and keep the conversation going.', '{"intro":"When you''re getting to know someone, the best questions come from their last answer. Each answer here contains a \"hook\" for the next question.","sections":[{"type":"lines","kind":"conversation","title":"Getting to know each other","lines":[{"ru":"Как прошёл твой день?","en":"How was your day?","words":[{"ru":"Как","en":"how"},{"ru":"прошёл","en":"went"},{"ru":"твой","en":"your"},{"ru":"день?","en":"day"}],"speaker":"Катя","role":"q","x":"a1-19:1"},{"ru":"Хорошо, но я немного устал.","en":"Good, but I''m a little tired.","words":[{"ru":"Хорошо,","en":"well"},{"ru":"но","en":"but"},{"ru":"я","en":"I"},{"ru":"немного","en":"a little"},{"ru":"устал.","f":"устала.","en":"tired"}],"ruF":"Хорошо, но я немного устала.","speaker":"Алекс","note":"Как прошёл день? is literally \"how did the day pass?\" Устал (a woman: устала) is past tense but means \"I''m tired\" right now.","follow":[{"ru":"Что ты делал сегодня?","en":"What did you do today?","ruF":"Что ты делала сегодня?"},{"ru":"Ты много работал?","en":"Did you work a lot?","ruF":"Ты много работала?"}],"role":"a","x":"a1-19:1"},{"ru":"Как ты отдыхаешь?","en":"How do you relax?","words":[{"ru":"Как","en":"how"},{"ru":"ты","en":"you"},{"ru":"отдыхаешь?","en":"relax"}],"speaker":"Катя","role":"q","x":"a1-19:2"},{"ru":"Мне нравится гулять, заниматься спортом и смотреть фильмы.","en":"I like walking, doing sport and watching films.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравится","en":"pleases"},{"ru":"гулять,","en":"to walk"},{"ru":"заниматься","en":"to do"},{"ru":"спортом","en":"sport"},{"ru":"и","en":"and"},{"ru":"смотреть","en":"to watch"},{"ru":"фильмы.","en":"films"}],"speaker":"Алекс","note":"Мне нравится + infinitive = I like doing: мне нравится гулять. Заниматься takes the instrumental: заниматься спортом.","follow":[{"ru":"Где ты любишь гулять?","en":"Where do you like to walk?"},{"ru":"Каким спортом ты занимаешься?","en":"What sport do you do?"}],"role":"a","x":"a1-19:2"},{"ru":"Какую музыку ты слушаешь?","en":"What kind of music do you listen to?","words":[{"ru":"Какую","en":"what kind of"},{"ru":"музыку","en":"music"},{"ru":"ты","en":"you"},{"ru":"слушаешь?","en":"listen to"}],"speaker":"Катя","role":"q","x":"a1-19:3"},{"ru":"Разную. Например, рок и хип-хоп.","en":"All kinds. For example, rock and hip-hop.","words":[{"ru":"Разную.","en":"different"},{"ru":"Например,","en":"for example"},{"ru":"рок","en":"rock"},{"ru":"и","en":"and"},{"ru":"хип-хоп.","en":"hip-hop"}],"speaker":"Алекс","note":"Слушать takes the accusative: музыка → какую музыку. Разную (музыку) = various kinds.","follow":[{"ru":"У тебя есть любимая группа?","en":"Do you have a favourite band?"},{"ru":"Ты играешь на гитаре?","en":"Do you play the guitar?"}],"role":"a","x":"a1-19:3"},{"ru":"Какой твой любимый фильм?","en":"What''s your favourite film?","words":[{"ru":"Какой","en":"which"},{"ru":"твой","en":"your"},{"ru":"любимый","en":"favourite"},{"ru":"фильм?","en":"film"}],"speaker":"Катя","role":"q","x":"a1-19:4"},{"ru":"Мне нравятся научно-фантастические фильмы.","en":"I like science fiction films.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравятся","en":"please"},{"ru":"научно-фантастические","en":"science-fiction"},{"ru":"фильмы.","en":"films"}],"speaker":"Алекс","note":"Фильмы is plural, so нравятся is plural too. Научно-фантастический = science fiction; the whole genre is фантастика.","follow":[{"ru":"Ты часто ходишь в кино?","en":"Do you go to the cinema often?"},{"ru":"Какой фильм ты смотрел последним?","en":"What''s the last film you saw?","ruF":"Какой фильм ты смотрела последним?"}],"role":"a","x":"a1-19:4"},{"ru":"Ты любишь путешествовать?","en":"Do you like travelling?","words":[{"ru":"Ты","en":"you"},{"ru":"любишь","en":"love"},{"ru":"путешествовать?","en":"to travel"}],"speaker":"Катя","role":"q","x":"a1-19:5"},{"ru":"Да, я люблю открывать новые места.","en":"Yes, I love discovering new places.","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"люблю","en":"love"},{"ru":"открывать","en":"to discover"},{"ru":"новые","en":"new"},{"ru":"места.","en":"places"}],"speaker":"Алекс","note":"Место (place) is neuter: plural места, новые места. Путешествовать: я путешествую, ты путешествуешь.","follow":[{"ru":"Ты когда-нибудь был в Европе?","en":"Have you ever been to Europe?","ruF":"Ты когда-нибудь была в Европе?","link":"a2-16:1","linkTopic":"Travel stories","linkLevel":"A2"},{"ru":"Куда ты хочешь поехать?","en":"Where do you want to go?"}],"role":"a","x":"a1-19:5"},{"ru":"Ты давно играешь в шахматы?","en":"Have you been playing chess long?","words":[{"ru":"Ты","en":"you"},{"ru":"давно","en":"long"},{"ru":"играешь","en":"play"},{"ru":"в","en":"(at)"},{"ru":"шахматы?","en":"chess"}],"speaker":"Катя","role":"q","x":"a1-19:6"},{"ru":"Нет, я начал недавно. Но я играю каждый день!","en":"No, I started recently. But I play every day!","words":[{"ru":"Нет,","en":"no"},{"ru":"я","en":"I"},{"ru":"начал","f":"начала","en":"started"},{"ru":"недавно.","en":"recently"},{"ru":"Но","en":"but"},{"ru":"я","en":"I"},{"ru":"играю","en":"play"},{"ru":"каждый","en":"every"},{"ru":"день!","en":"day"}],"ruF":"Нет, я начала недавно. Но я играю каждый день!","speaker":"Алекс","note":"Games take играть в + accusative: в шахматы, в футбол. Instruments take играть на: на гитаре. Давно + present tense = \"have been … for a long time\".","follow":[{"ru":"Где ты играешь?","en":"Where do you play?"},{"ru":"Ты играешь онлайн?","en":"Do you play online?"}],"role":"a","x":"a1-19:6"},{"ru":"Хочешь сыграть со мной?","en":"Do you want to play with me?","words":[{"ru":"Хочешь","en":"want"},{"ru":"сыграть","en":"to play"},{"ru":"со","en":"with"},{"ru":"мной?","en":"me"}],"speaker":"Катя","role":"q","x":"a1-19:7"},{"ru":"Конечно! Только я ещё плохо играю.","en":"Sure! Only I don''t play very well yet.","words":[{"ru":"Конечно!","en":"of course"},{"ru":"Только","en":"only"},{"ru":"я","en":"I"},{"ru":"ещё","en":"still"},{"ru":"плохо","en":"badly"},{"ru":"играю.","en":"play"}],"speaker":"Алекс","note":"Сыграть = to play (one game) — the completed form of играть. Со мной = with me: с becomes со before мной.","follow":[{"ru":"Ты хочешь играть белыми?","en":"Do you want to play white?"},{"ru":"Когда тебе удобно?","en":"When is good for you?"}],"role":"a","x":"a1-19:7"}]},{"type":"grammar","title":"Asking \"which?\" — какой","paragraphs":["**Какой** agrees with its noun like an adjective: какой фильм (m.), какая музыка (f.), какое блюдо (n.), какие фильмы (pl.). After a verb like слушать or смотреть, use the accusative: Какую музыку ты слушаешь?"],"examples":[{"ru":"Какой твой любимый фильм?","en":"What''s your favourite film?"},{"ru":"Какую музыку ты любишь?","en":"What music do you like?"}]},{"type":"grammar","title":"Играть в or играть на?","paragraphs":["Games and sports take **в** + accusative: играть в шахматы, в футбол, в теннис. Musical instruments take **на** + prepositional: играть на гитаре, на пианино."],"examples":[{"ru":"Я играю в шахматы.","en":"I play chess."},{"ru":"Он играет на гитаре.","en":"He plays the guitar."}]}],"drills":[{"q":"Какую ___ ты слушаешь?","answer":"музыку","options":["музыкой","музыку","музыка","музыки"],"en":"What music do you listen to?","why":{"музыка":"After слушать the noun takes the accusative: какую музыку.","музыки":"Музыки is the genitive. Слушать takes the accusative: музыку.","музыкой":"Музыкой is the instrumental. Слушать takes the accusative: музыку."}},{"q":"Я играю ___ шахматы.","answer":"в","options":["в","на","о","с"],"en":"I play chess.","why":{"на":"На is for instruments (на гитаре). Games take в: в шахматы.","с":"С means \"with\": я играю с другом. For the game itself use в.","о":"О means \"about\". The game you play takes в: в шахматы."}},{"q":"Хочешь сыграть ___ мной?","answer":"со","options":["на","у","с","со"],"en":"Do you want to play with me?","why":{"с":"Before мной, с becomes со so it''s easier to say: со мной.","у":"У means \"by, at\" (у меня). \"With me\" is со мной.","на":"На means \"on, at\". \"With me\" is со мной."}}]}'::jsonb, 14, 10),
  ('a1-20', 'A1', 'shopping', 20, 'At a clothes shop', 'В магазине одежды', 'Answer a shop assistant''s questions, try something on, ask for another size and pay.', '{"intro":"In a shop the assistant asks most of the questions. Your answers can include small questions of your own — Можно посмотреть? У вас есть другой размер? — so you stay in control.","sections":[{"type":"lines","kind":"conversation","title":"Buying a jacket","lines":[{"ru":"Вам помочь?","en":"Can I help you?","words":[{"ru":"Вам","en":"to you"},{"ru":"помочь?","en":"help"}],"speaker":"Продавец","role":"q","x":"a1-20:1"},{"ru":"Да, спасибо. Я ищу куртку.","en":"Yes, thanks. I''m looking for a jacket.","words":[{"ru":"Да,","en":"yes"},{"ru":"спасибо.","en":"thanks"},{"ru":"Я","en":"I"},{"ru":"ищу","en":"look for"},{"ru":"куртку.","en":"jacket"}],"speaker":"Алекс","note":"Помочь takes the dative: вам помочь. Искать: я ищу, ты ищешь. Куртка → куртку (accusative).","follow":[{"ru":"Для себя или в подарок?","en":"For yourself or as a gift?"},{"ru":"Какой цвет вы хотите?","en":"What colour would you like?"}],"role":"a","x":"a1-20:1"},{"ru":"Какой у вас размер?","en":"What size are you?","words":[{"ru":"Какой","en":"what"},{"ru":"у","en":"by"},{"ru":"вас","en":"you"},{"ru":"размер?","en":"size"}],"speaker":"Продавец","role":"q","x":"a1-20:2"},{"ru":"Сорок восьмой. Можно посмотреть вот эту?","en":"Forty-eight. Can I look at this one?","words":[{"ru":"Сорок","en":"forty"},{"ru":"восьмой.","en":"eighth"},{"ru":"Можно","en":"may I"},{"ru":"посмотреть","en":"look at"},{"ru":"вот","en":"here"},{"ru":"эту?","en":"this one"}],"speaker":"Алекс","note":"Russian clothing sizes are numbers: 46 ≈ S, 48 ≈ M, 50 ≈ L. Можно + infinitive = may I…? Эту (куртку) is accusative.","follow":[{"ru":"Вам нравится этот цвет?","en":"Do you like this colour?"},{"ru":"Хотите посмотреть другие модели?","en":"Would you like to see other styles?"}],"role":"a","x":"a1-20:2"},{"ru":"Хотите примерить?","en":"Would you like to try it on?","words":[{"ru":"Хотите","en":"want"},{"ru":"примерить?","en":"to try on"}],"speaker":"Продавец","role":"q","x":"a1-20:3"},{"ru":"Да, спасибо. Где у вас примерочная?","en":"Yes, thanks. Where''s the fitting room?","words":[{"ru":"Да,","en":"yes"},{"ru":"спасибо.","en":"thanks"},{"ru":"Где","en":"where"},{"ru":"у","en":"by"},{"ru":"вас","en":"you"},{"ru":"примерочная?","en":"fitting room"}],"speaker":"Алекс","note":"Примерить = to try on (clothes); примерочная = fitting room. Где у вас…? is a polite way to ask where something is in a shop.","follow":[{"ru":"Вам принести другой размер?","en":"Shall I bring you another size?"},{"ru":"Хотите примерить что-нибудь ещё?","en":"Would you like to try anything else on?"}],"role":"a","x":"a1-20:3"},{"ru":"Ну как? Подходит?","en":"Well? Does it fit?","words":[{"ru":"Ну","en":"well"},{"ru":"как?","en":"how"},{"ru":"Подходит?","en":"fits"}],"speaker":"Продавец","role":"q","x":"a1-20:4"},{"ru":"Немного маленькая. У вас есть другой размер?","en":"It''s a bit small. Do you have another size?","words":[{"ru":"Немного","en":"a little"},{"ru":"маленькая.","en":"small"},{"ru":"У","en":"by"},{"ru":"вас","en":"you"},{"ru":"есть","en":"is there"},{"ru":"другой","en":"another"},{"ru":"размер?","en":"size"}],"speaker":"Алекс","note":"Подходить = to fit, to suit. Куртка is feminine: маленькая, большая. У вас есть…? = do you have…?","follow":[{"ru":"Вам принести пятидесятый?","en":"Shall I bring you a fifty?"},{"ru":"Может, другую модель?","en":"Maybe a different style?"}],"role":"a","x":"a1-20:4"},{"ru":"Вот пятидесятый. Так лучше?","en":"Here''s a fifty. Is that better?","words":[{"ru":"Вот","en":"here is"},{"ru":"пятидесятый.","en":"fiftieth"},{"ru":"Так","en":"this way"},{"ru":"лучше?","en":"better"}],"speaker":"Продавец","role":"q","x":"a1-20:5"},{"ru":"Да, намного лучше! Сколько она стоит?","en":"Yes, much better! How much is it?","words":[{"ru":"Да,","en":"yes"},{"ru":"намного","en":"much"},{"ru":"лучше!","en":"better"},{"ru":"Сколько","en":"how much"},{"ru":"она","en":"it"},{"ru":"стоит?","en":"costs"}],"speaker":"Алекс","note":"Намного лучше = much better. Она = куртка (feminine): Сколько она стоит?","follow":[{"ru":"Будете брать?","en":"Will you take it?"},{"ru":"Хотите посмотреть что-нибудь ещё?","en":"Would you like to see anything else?"}],"role":"a","x":"a1-20:5"},{"ru":"Сто долларов. Как будете платить?","en":"A hundred dollars. How would you like to pay?","words":[{"ru":"Сто","en":"hundred"},{"ru":"долларов.","en":"dollars"},{"ru":"Как","en":"how"},{"ru":"будете","en":"will"},{"ru":"платить?","en":"pay"}],"speaker":"Продавец","role":"q","x":"a1-20:6"},{"ru":"Картой, если можно.","en":"By card, if that''s OK.","words":[{"ru":"Картой,","en":"by card"},{"ru":"если","en":"if"},{"ru":"можно.","en":"possible"}],"speaker":"Алекс","note":"Платить картой = to pay by card (instrumental). Если можно = if possible — a polite softener for any request.","follow":[{"ru":"У вас есть карта скидок?","en":"Do you have a discount card?"},{"ru":"Вам нужен чек?","en":"Do you need the receipt?"}],"role":"a","x":"a1-20:6"},{"ru":"Пакет нужен?","en":"Do you need a bag?","words":[{"ru":"Пакет","en":"bag"},{"ru":"нужен?","en":"needed"}],"speaker":"Продавец","role":"q","x":"a1-20:7"},{"ru":"Нет, спасибо, не нужно. До свидания!","en":"No thanks, I don''t need one. Goodbye!","words":[{"ru":"Нет,","en":"no"},{"ru":"спасибо,","en":"thanks"},{"ru":"не","en":"not"},{"ru":"нужно.","en":"necessary"},{"ru":"До","en":"until"},{"ru":"свидания!","en":"meeting"}],"speaker":"Алекс","note":"Нужен (m.), нужна (f.), нужно (n.), нужны (pl.) agree with the thing that''s needed: пакет нужен. Не нужно = there''s no need.","follow":[{"ru":"Вы у нас первый раз?","en":"Is this your first time here?"},{"ru":"Хотите оставить отзыв?","en":"Would you like to leave a review?"}],"role":"a","x":"a1-20:7"}]},{"type":"grammar","title":"Polite questions: можно…? and у вас есть…?","paragraphs":["**Можно** + infinitive asks permission: Можно посмотреть? Можно примерить? Можно оплатить картой? On its own, Можно? means \"May I?\".","**У вас есть…?** asks whether a shop has something: У вас есть другой размер? Answers: Да, есть. / Нет, к сожалению, нет."],"examples":[{"ru":"Можно примерить?","en":"Can I try it on?"},{"ru":"У вас есть другой цвет?","en":"Do you have another colour?"}]},{"type":"grammar","title":"Linking words: если","paragraphs":["**Если** means \"if\". In everyday speech **если можно** (if possible) softens any request: Картой, если можно."],"examples":[{"ru":"Если можно, я примерю.","en":"If I may, I''ll try it on."},{"ru":"Если есть, дайте пятидесятый.","en":"If you have one, give me a fifty."}]}],"drills":[{"q":"Я ищу ___.","answer":"куртку","options":["куртки","куртку","курткой","куртка"],"en":"I''m looking for a jacket.","why":{"куртка":"Искать takes the accusative: -а becomes -у, куртку.","куртки":"Куртки is the genitive or the plural. \"I''m looking for a jacket\" is ищу куртку.","курткой":"Курткой is the instrumental. Искать takes the accusative: куртку."}},{"q":"___ примерить?","answer":"Можно","options":["Можно","Хотите","Надо","Нужно"],"en":"May I try it on?","why":{"Нужно":"Нужно means \"it''s necessary\". To ask permission, use можно.","Надо":"Надо also means \"need to\". \"May I…?\" is Можно…?","Хотите":"Хотите примерить? is what the assistant asks (\"Would you like to…?\"). To ask permission yourself: Можно примерить?"}},{"q":"Пакет ___?","answer":"нужен","options":["нужны","нужен","нужно","нужна"],"en":"Do you need a bag?","why":{"нужна":"Нужна goes with feminine nouns (нужна сумка). Пакет is masculine: нужен.","нужно":"Нужно goes with neuter nouns or with a verb. Пакет is masculine: нужен.","нужны":"Нужны goes with plurals (нужны пакеты). One пакет: нужен."}}]}'::jsonb, 14, 13),
  ('a1-21', 'A1', 'essentials', 21, 'Can you help me?', 'Ты можешь мне помочь?', 'Ask for help, ask the way, ask someone to slow down and say thank you.', '{"intro":"When you''re lost or don''t understand, a few short questions solve almost everything. A friendly local helps you here — and your answers contain the questions you''ll need most.","sections":[{"type":"lines","kind":"conversation","title":"Lost in town","lines":[{"ru":"Ты что-то ищешь?","en":"Are you looking for something?","words":[{"ru":"Ты","en":"you"},{"ru":"что-то","en":"something"},{"ru":"ищешь?","en":"look for"}],"speaker":"Саша","role":"q","x":"a1-21:1"},{"ru":"Да, я ищу аптеку. Ты можешь мне помочь?","en":"Yes, I''m looking for a pharmacy. Can you help me?","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"ищу","en":"look for"},{"ru":"аптеку.","en":"pharmacy"},{"ru":"Ты","en":"you"},{"ru":"можешь","en":"can"},{"ru":"мне","en":"me"},{"ru":"помочь?","en":"help"}],"speaker":"Алекс","note":"Помочь takes the dative: мне помочь. With a stranger who is older, use вы: Вы можете мне помочь?","follow":[{"ru":"Что случилось?","en":"What happened?"},{"ru":"Тебе плохо?","en":"Are you feeling unwell?"}],"role":"a","x":"a1-21:1"},{"ru":"Конечно! Ты знаешь адрес?","en":"Sure! Do you know the address?","words":[{"ru":"Конечно!","en":"of course"},{"ru":"Ты","en":"you"},{"ru":"знаешь","en":"know"},{"ru":"адрес?","en":"address"}],"speaker":"Саша","role":"q","x":"a1-21:2"},{"ru":"Нет, не знаю. Как мне туда добраться?","en":"No, I don''t. How do I get there?","words":[{"ru":"Нет,","en":"no"},{"ru":"не","en":"not"},{"ru":"знаю.","en":"know"},{"ru":"Как","en":"how"},{"ru":"мне","en":"me"},{"ru":"туда","en":"there"},{"ru":"добраться?","en":"to get"}],"speaker":"Алекс","note":"Как мне туда добраться? is literally \"how to me to get there?\" Туда = (to) there, with movement; там = there, no movement.","follow":[{"ru":"Ты на машине?","en":"Are you by car?"},{"ru":"Тебе нужна ближайшая аптека?","en":"Do you need the nearest pharmacy?"}],"role":"a","x":"a1-21:2"},{"ru":"Иди прямо, потом направо. Понятно?","en":"Go straight, then turn right. Got it?","words":[{"ru":"Иди","en":"go"},{"ru":"прямо,","en":"straight"},{"ru":"потом","en":"then"},{"ru":"направо.","en":"right"},{"ru":"Понятно?","en":"clear"}],"speaker":"Саша","role":"q","x":"a1-21:3"},{"ru":"Не совсем. Говори, пожалуйста, медленнее.","en":"Not quite. Please speak more slowly.","words":[{"ru":"Не","en":"not"},{"ru":"совсем.","en":"quite"},{"ru":"Говори,","en":"speak"},{"ru":"пожалуйста,","en":"please"},{"ru":"медленнее.","en":"more slowly"}],"speaker":"Алекс","note":"Медленнее = more slowly (from медленно). Говори is the ты command; to a stranger say Говорите, пожалуйста, медленнее.","follow":[{"ru":"Ты меня понимаешь?","en":"Do you understand me?"},{"ru":"Повторить?","en":"Shall I say it again?"}],"role":"a","x":"a1-21:3"},{"ru":"Прямо, а потом направо. Теперь понятно?","en":"Straight, and then right. Clear now?","words":[{"ru":"Прямо,","en":"straight"},{"ru":"а","en":"and"},{"ru":"потом","en":"then"},{"ru":"направо.","en":"right"},{"ru":"Теперь","en":"now"},{"ru":"понятно?","en":"clear"}],"speaker":"Саша","role":"q","x":"a1-21:4"},{"ru":"Да, теперь понятно. Это далеко?","en":"Yes, I''ve got it now. Is it far?","words":[{"ru":"Да,","en":"yes"},{"ru":"теперь","en":"now"},{"ru":"понятно.","en":"clear"},{"ru":"Это","en":"it"},{"ru":"далеко?","en":"far"}],"speaker":"Алекс","note":"Понятно (\"it''s clear\") is the most common way to say \"I understand\" or \"got it\". Далеко = far, близко = near.","follow":[{"ru":"Показать тебе на карте?","en":"Shall I show you on the map?"},{"ru":"Ты пешком?","en":"Are you on foot?"}],"role":"a","x":"a1-21:4"},{"ru":"Нет, пять минут пешком. Ты не местный?","en":"No, five minutes on foot. You''re not from around here?","words":[{"ru":"Нет,","en":"no"},{"ru":"пять","en":"five"},{"ru":"минут","en":"minutes"},{"ru":"пешком.","en":"on foot"},{"ru":"Ты","en":"you"},{"ru":"не","en":"not"},{"ru":"местный?","f":"местная?","en":"local"}],"ruF":"Нет, пять минут пешком. Ты не местная?","speaker":"Саша","role":"q","x":"a1-21:5"},{"ru":"Нет, я здесь первый раз. Я плохо знаю город.","en":"No, it''s my first time here. I don''t know the city well.","words":[{"ru":"Нет,","en":"no"},{"ru":"я","en":"I"},{"ru":"здесь","en":"here"},{"ru":"первый","en":"first"},{"ru":"раз.","en":"time"},{"ru":"Я","en":"I"},{"ru":"плохо","en":"badly"},{"ru":"знаю","en":"know"},{"ru":"город.","en":"city"}],"speaker":"Алекс","note":"Первый раз = the first time. Плохо знаю (\"know badly\") is how Russians say \"don''t know well\".","follow":[{"ru":"Откуда ты приехал?","en":"Where have you come from?","ruF":"Откуда ты приехала?"},{"ru":"Тебе нравится наш город?","en":"Do you like our city?"}],"role":"a","x":"a1-21:5"},{"ru":"Но ты хорошо говоришь по-русски! Ты учишь русский?","en":"But you speak Russian well! Are you learning Russian?","words":[{"ru":"Но","en":"but"},{"ru":"ты","en":"you"},{"ru":"хорошо","en":"well"},{"ru":"говоришь","en":"speak"},{"ru":"по-русски!","en":"in Russian"},{"ru":"Ты","en":"you"},{"ru":"учишь","en":"learn"},{"ru":"русский?","en":"Russian"}],"speaker":"Саша","role":"q","x":"a1-21:6"},{"ru":"Спасибо! Да, учу, но пока говорю медленно.","en":"Thanks! Yes, I am, but for now I speak slowly.","words":[{"ru":"Спасибо!","en":"thanks"},{"ru":"Да,","en":"yes"},{"ru":"учу,","en":"learn"},{"ru":"но","en":"but"},{"ru":"пока","en":"for now"},{"ru":"говорю","en":"speak"},{"ru":"медленно.","en":"slowly"}],"speaker":"Алекс","note":"Учить русский = to learn Russian (the language); говорить по-русски = to speak Russian. Пока = for now, so far.","follow":[{"ru":"Почему ты учишь русский?","en":"Why are you learning Russian?"},{"ru":"Ты давно учишь русский?","en":"Have you been learning Russian long?"}],"role":"a","x":"a1-21:6"},{"ru":"Что ещё тебе нужно?","en":"What else do you need?","words":[{"ru":"Что","en":"what"},{"ru":"ещё","en":"else"},{"ru":"тебе","en":"to you"},{"ru":"нужно?","en":"needed"}],"speaker":"Саша","role":"q","x":"a1-21:7"},{"ru":"Больше ничего, спасибо! Ты мне очень помог.","en":"Nothing else, thanks! You''ve been a big help.","words":[{"ru":"Больше","en":"more"},{"ru":"ничего,","en":"nothing"},{"ru":"спасибо!","en":"thanks"},{"ru":"Ты","en":"you"},{"ru":"мне","en":"me"},{"ru":"очень","en":"very much"},{"ru":"помог.","en":"helped"}],"speaker":"Алекс","note":"Ты мне очень помог — to a woman, помогла. Больше ничего = nothing more. Russian happily uses double negatives: мне ничего не нужно.","follow":[{"ru":"Хочешь, я тебя провожу?","en":"Want me to walk you there?"},{"ru":"Может, выпьем кофе?","en":"Shall we grab a coffee?"}],"role":"a","x":"a1-21:7"}]},{"type":"grammar","title":"Asking for help","paragraphs":["Three questions that rescue any conversation:","**Ты можешь мне помочь?** / **Вы можете мне помочь?** — Can you help me?","**Говори медленнее, пожалуйста.** — Please speak more slowly. **Повтори, пожалуйста.** — Please say it again.","**Как это называется по-русски?** — What''s this called in Russian?"],"examples":[{"ru":"Вы можете мне помочь?","en":"Can you help me? (formal)"},{"ru":"Как это называется по-русски?","en":"What''s this called in Russian?"},{"ru":"Повторите, пожалуйста.","en":"Please say it again. (formal)"}]},{"type":"grammar","title":"Там or туда? Где or куда?","paragraphs":["Russian separates location from direction. **Где?** (where?) → **там** (there), **здесь** (here). **Куда?** (where to?) → **туда** (to there), **сюда** (to here)."],"examples":[{"ru":"Аптека там.","en":"The pharmacy is there."},{"ru":"Как мне туда добраться?","en":"How do I get there?"}]}],"drills":[{"q":"Ты можешь ___ помочь?","answer":"мне","options":["меня","мной","я","мне"],"en":"Can you help me?","why":{"меня":"Помочь takes the dative: мне, тебе, вам. Меня is the accusative.","я":"Я is the subject form. \"Help me\" is помочь мне (dative).","мной":"Мной is the instrumental (со мной). Помочь takes the dative: мне."}},{"q":"Как мне ___ добраться?","answer":"туда","options":["где","там","туда","тут"],"en":"How do I get there?","why":{"там":"Там means \"there\" with no movement. Getting somewhere is movement: туда.","где":"Где is the question word \"where?\". Here you need \"(to) there\": туда.","тут":"Тут means \"here\". To get \"there\", use туда."}},{"q":"Говори, пожалуйста, ___.","answer":"медленнее","options":["медленнее","медленный","медленно","медленная"],"en":"Please speak more slowly.","why":{"медленно":"Медленно means \"slowly\". To ask for \"more slowly\", use медленнее.","медленный":"Медленный is an adjective (a slow train). After a verb you need an adverb: медленнее.","медленная":"Медленная is a feminine adjective. After говори you need the adverb медленнее."}}]}'::jsonb, 14, 10),
  ('a1-22', 'A1', 'family', 22, 'The people close to you', 'Мои близкие', 'Talk about where your family lives, brothers and sisters, your parents'' jobs and staying in touch.', '{"intro":"Family comes up in almost every friendly conversation with Russians. Notice how each answer gives a detail the other person can ask about next.","sections":[{"type":"lines","kind":"conversation","title":"Family and home","lines":[{"ru":"Где живёт твоя семья?","en":"Where does your family live?","words":[{"ru":"Где","en":"where"},{"ru":"живёт","en":"lives"},{"ru":"твоя","en":"your"},{"ru":"семья?","en":"family"}],"speaker":"Миша","role":"q","x":"a1-22:1"},{"ru":"Мои родители живут в другом штате, далеко отсюда.","en":"My parents live in another state, far from here.","words":[{"ru":"Мои","en":"my"},{"ru":"родители","en":"parents"},{"ru":"живут","en":"live"},{"ru":"в","en":"in"},{"ru":"другом","en":"another"},{"ru":"штате,","en":"state"},{"ru":"далеко","en":"far"},{"ru":"отсюда.","en":"from here"}],"speaker":"Алекс","note":"Другой (another) → в другом штате: the prepositional case. Отсюда = from here.","follow":[{"ru":"В каком штате?","en":"Which state?"},{"ru":"Ты родился там?","en":"Were you born there?","ruF":"Ты родилась там?"}],"role":"a","x":"a1-22:1"},{"ru":"Ты часто их видишь?","en":"Do you see them often?","words":[{"ru":"Ты","en":"you"},{"ru":"часто","en":"often"},{"ru":"их","en":"them"},{"ru":"видишь?","en":"see"}],"speaker":"Миша","role":"q","x":"a1-22:2"},{"ru":"Не очень часто, поэтому я звоню им каждую неделю.","en":"Not very often, so I call them every week.","words":[{"ru":"Не","en":"not"},{"ru":"очень","en":"very"},{"ru":"часто,","en":"often"},{"ru":"поэтому","en":"so"},{"ru":"я","en":"I"},{"ru":"звоню","en":"call"},{"ru":"им","en":"them"},{"ru":"каждую","en":"every"},{"ru":"неделю.","en":"week"}],"speaker":"Алекс","note":"Звонить takes the dative: звоню им, звоню маме. Каждую неделю = every week (time takes the accusative).","follow":[{"ru":"Ты скучаешь по ним?","en":"Do you miss them?","link":"a1-22:7","linkTopic":"The people close to you","linkLevel":"A1"},{"ru":"Когда ты их видел в последний раз?","en":"When did you last see them?","ruF":"Когда ты их видела в последний раз?"}],"role":"a","x":"a1-22:2"},{"ru":"У тебя есть братья или сёстры?","en":"Do you have any brothers or sisters?","words":[{"ru":"У","en":"by"},{"ru":"тебя","en":"you"},{"ru":"есть","en":"are there"},{"ru":"братья","en":"brothers"},{"ru":"или","en":"or"},{"ru":"сёстры?","en":"sisters"}],"speaker":"Миша","role":"q","x":"a1-22:3"},{"ru":"Да, у меня есть младший брат.","en":"Yes, I have a younger brother.","words":[{"ru":"Да,","en":"yes"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"есть","en":"there is"},{"ru":"младший","en":"younger"},{"ru":"брат.","en":"brother"}],"speaker":"Алекс","note":"У меня есть = I have. Младший = younger, старший = older: старшая сестра, младший брат.","follow":[{"ru":"Как его зовут?","en":"What''s his name?"},{"ru":"Вы дружите?","en":"Do you get along?"}],"role":"a","x":"a1-22:3"},{"ru":"Сколько ему лет?","en":"How old is he?","words":[{"ru":"Сколько","en":"how many"},{"ru":"ему","en":"to him"},{"ru":"лет?","en":"years"}],"speaker":"Миша","role":"q","x":"a1-22:4"},{"ru":"Ему пятнадцать лет. Он ещё учится в школе.","en":"He''s fifteen. He''s still at school.","words":[{"ru":"Ему","en":"to him"},{"ru":"пятнадцать","en":"fifteen"},{"ru":"лет.","en":"years"},{"ru":"Он","en":"he"},{"ru":"ещё","en":"still"},{"ru":"учится","en":"studies"},{"ru":"в","en":"at"},{"ru":"школе.","en":"school"}],"speaker":"Алекс","note":"Age uses the dative: ему пятнадцать лет — \"to him fifteen years\". Год (1) → года (2–4) → лет (5 and up).","follow":[{"ru":"Он хорошо учится?","en":"Does he do well at school?"},{"ru":"Чем он увлекается?","en":"What''s he into?"}],"role":"a","x":"a1-22:4"},{"ru":"Вы похожи?","en":"Are you alike?","words":[{"ru":"Вы","en":"you"},{"ru":"похожи?","en":"alike"}],"speaker":"Миша","role":"q","x":"a1-22:5"},{"ru":"Немного. Например, мы оба любим спорт.","en":"A little. For example, we both love sport.","words":[{"ru":"Немного.","en":"a little"},{"ru":"Например,","en":"for example"},{"ru":"мы","en":"we"},{"ru":"оба","en":"both"},{"ru":"любим","en":"love"},{"ru":"спорт.","en":"sport"}],"speaker":"Алекс","note":"Похожи = alike (a short adjective in the plural). Оба = both (men or mixed); обе for two women.","follow":[{"ru":"Вы вместе играете в шахматы?","en":"Do you play chess together?"},{"ru":"Вы часто ссоритесь?","en":"Do you argue often?"}],"role":"a","x":"a1-22:5"},{"ru":"Чем занимаются твои родители?","en":"What do your parents do?","words":[{"ru":"Чем","en":"(with) what"},{"ru":"занимаются","en":"are busy with"},{"ru":"твои","en":"your"},{"ru":"родители?","en":"parents"}],"speaker":"Миша","role":"q","x":"a1-22:6"},{"ru":"Мама работает в больнице, а папа — водитель.","en":"Mum works at a hospital, and Dad is a driver.","words":[{"ru":"Мама","en":"mum"},{"ru":"работает","en":"works"},{"ru":"в","en":"at"},{"ru":"больнице,","en":"hospital"},{"ru":"а","en":"and"},{"ru":"папа","en":"dad"},{"ru":"—","en":""},{"ru":"водитель.","en":"driver"}],"speaker":"Алекс","note":"The dash stands in for \"is\" between two nouns: папа — водитель. А (and, while) sets two people side by side.","follow":[{"ru":"Им нравится их работа?","en":"Do they like their jobs?"},{"ru":"Твоя мама врач?","en":"Is your mum a doctor?"}],"role":"a","x":"a1-22:6"},{"ru":"Ты скучаешь по ним?","en":"Do you miss them?","words":[{"ru":"Ты","en":"you"},{"ru":"скучаешь","en":"miss"},{"ru":"по","en":"(for)"},{"ru":"ним?","en":"them"}],"speaker":"Миша","role":"q","x":"a1-22:7"},{"ru":"Да, конечно. Но мы часто говорим по видео.","en":"Yes, of course. But we often talk on video.","words":[{"ru":"Да,","en":"yes"},{"ru":"конечно.","en":"of course"},{"ru":"Но","en":"but"},{"ru":"мы","en":"we"},{"ru":"часто","en":"often"},{"ru":"говорим","en":"talk"},{"ru":"по","en":"by"},{"ru":"видео.","en":"video"}],"speaker":"Алекс","note":"Скучать по + dative = to miss someone: скучаю по маме, по ним. По видео = on a video call.","follow":[{"ru":"Когда ты к ним поедешь?","en":"When are you going to see them?"},{"ru":"Они приедут к тебе в гости?","en":"Will they come and visit you?"}],"role":"a","x":"a1-22:7"}]},{"type":"grammar","title":"Saying someone''s age","paragraphs":["Age uses the **dative**: мне двадцать лет (I''m 20), ему пятнадцать лет, ей тридцать лет. The word for \"years\" changes with the number: 1 → **год** (двадцать один год), 2–4 → **года** (два года), 5–20 → **лет** (пять лет)."],"examples":[{"ru":"Сколько тебе лет?","en":"How old are you?"},{"ru":"Мне двадцать пять лет.","en":"I''m twenty-five."},{"ru":"Ему три года.","en":"He''s three."}]},{"type":"grammar","title":"А or и?","paragraphs":["**И** joins similar things: мама и папа. **А** sets two things side by side or contrasts them: Мама работает в больнице, **а** папа — водитель. It''s also how you turn a question back: А ты?"],"examples":[{"ru":"Я живу здесь, а они живут далеко.","en":"I live here, and they live far away."},{"ru":"А у тебя есть сестра?","en":"And do you have a sister?"}]}],"drills":[{"q":"Я звоню ___ каждую неделю.","answer":"им","options":["ими","им","они","их"],"en":"I call them every week.","why":{"их":"Их is the accusative. Звонить takes the dative: им.","они":"Они is the subject form. Звонить (to call) takes the dative: им.","ими":"Ими is the instrumental (с ними). Звонить takes the dative: им."}},{"q":"Ему пятнадцать ___.","answer":"лет","options":["года","годы","лет","год"],"en":"He''s fifteen.","why":{"год":"Год goes with 1 (and 21, 31…). After 5–20 use лет.","года":"Года goes with 2, 3, 4. After пятнадцать use лет.","годы":"Годы means \"years\" as a period (the nineties), not age. Use лет."}},{"q":"Я скучаю по ___.","answer":"маме","options":["мама","маму","мамой","маме"],"en":"I miss my mum.","why":{"мама":"After скучать по the noun takes the dative: по маме.","маму":"Маму is the accusative. Скучать по takes the dative: маме.","мамой":"Мамой is the instrumental. Скучать по takes the dative: маме."}}]}'::jsonb, 14, 11),
  ('a2-01', 'A2', 'routines', 1, 'My day', 'Мой день', 'Describe your daily routine, what you did yesterday and what you''ll do after work.', '{"intro":"Now your sentences get longer. You''ll connect them with time words: обычно, потом, после работы, вчера.","sections":[{"type":"lines","kind":"phrases","title":"A normal day","lines":[{"ru":"Обычно я встаю в семь часов.","en":"I usually get up at seven.","words":[{"ru":"Обычно","en":"usually"},{"ru":"я","en":"I"},{"ru":"встаю","en":"get up"},{"ru":"в","en":"at"},{"ru":"семь","en":"seven"},{"ru":"часов.","en":"o''clock"}]},{"ru":"Утром я завтракаю дома.","en":"I have breakfast at home in the morning.","words":[{"ru":"Утром","en":"in the morning"},{"ru":"я","en":"I"},{"ru":"завтракаю","en":"have breakfast"},{"ru":"дома.","en":"at home"}]},{"ru":"Потом я еду на работу.","en":"Then I go to work.","words":[{"ru":"Потом","en":"then"},{"ru":"я","en":"I"},{"ru":"еду","en":"go"},{"ru":"на","en":"to"},{"ru":"работу.","en":"work"}]},{"ru":"Сегодня я работаю до вечера.","en":"Today I''m working until the evening.","words":[{"ru":"Сегодня","en":"today"},{"ru":"я","en":"I"},{"ru":"работаю","en":"work"},{"ru":"до","en":"until"},{"ru":"вечера.","en":"evening"}]},{"ru":"После работы я пойду домой.","en":"After work, I''ll go home.","words":[{"ru":"После","en":"after"},{"ru":"работы","en":"work"},{"ru":"я","en":"I"},{"ru":"пойду","en":"will go"},{"ru":"домой.","en":"home"}]},{"ru":"Вечером я смотрю сериалы.","en":"In the evening I watch TV series.","words":[{"ru":"Вечером","en":"in the evening"},{"ru":"я","en":"I"},{"ru":"смотрю","en":"watch"},{"ru":"сериалы.","en":"series"}]},{"ru":"Я ложусь спать в одиннадцать.","en":"I go to bed at eleven.","words":[{"ru":"Я","en":"I"},{"ru":"ложусь","en":"go to bed"},{"ru":"спать","en":"sleep"},{"ru":"в","en":"at"},{"ru":"одиннадцать.","en":"eleven"}]},{"ru":"Что ты обычно делаешь по выходным?","en":"What do you usually do on weekends?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"обычно","en":"usually"},{"ru":"делаешь","en":"do"},{"ru":"по","en":"on"},{"ru":"выходным?","en":"weekends"}]},{"ru":"Вчера я ходил в магазин.","en":"Yesterday I went to the store.","words":[{"ru":"Вчера","en":"yesterday"},{"ru":"я","en":"I"},{"ru":"ходил","f":"ходила","en":"went"},{"ru":"в","en":"to"},{"ru":"магазин.","en":"store"}],"ruF":"Вчера я ходила в магазин.","note":"Past tense agrees with the speaker: a man says ходил, a woman says ходила."}]},{"type":"grammar","title":"Time expressions","paragraphs":["**В** + time: в семь часов, в одиннадцать. **До** + genitive (\"until\"): до вечера, до обеда. **После** + genitive (\"after\"): после работы, после обеда.","**По** + dative plural means \"on (every)…\": по выходным, по утрам, по вечерам."],"examples":[{"ru":"По утрам я бегаю.","en":"I run in the mornings."},{"ru":"После обеда я работаю до шести.","en":"After lunch I work until six."}]}],"drills":[{"q":"После ___ я пойду домой.","answer":"работы","options":["работой","работу","работы","работа"],"en":"After work I''ll go home.","why":{"работа":"После takes the genitive: после работы.","работу":"Работу is the accusative (иду на работу). После needs работы.","работой":"Работой is the instrumental (с работой). После needs работы."}},{"q":"Что ты обычно делаешь по ___?","answer":"выходным","options":["выходные","выходных","выходным","выходными"],"en":"What do you usually do on weekends?","why":{"выходные":"По meaning \"on (regularly)\" takes the dative: по выходным.","выходных":"Выходных is the genitive (после выходных). По needs выходным.","выходными":"Выходными is the instrumental (перед выходными). По needs выходным."}},{"q":"Вчера я ___ в магазин. (I went — a man)","answer":"ходил","options":["пойду","хожу","ходил","ходила"],"en":"Yesterday I went to the store.","why":{"хожу":"Хожу is present (\"I go\"). Вчера needs the past: ходил.","пойду":"Пойду is future (\"I''ll go\"). Вчера needs the past: ходил.","ходила":"Ходила is the past for a woman. A man says ходил."}},{"q":"Я встаю ___ семь часов.","answer":"в","options":["до","в","на","по"],"en":"I get up at seven.","why":{"на":"Clock times take в: в семь часов.","до":"До means \"until, before\". \"At seven\" is в семь.","по":"По isn''t used for clock times. \"At seven\" is в семь."}}]}'::jsonb, 9, 9),
  ('a2-02', 'A2', 'restaurants', 2, 'At a restaurant', 'В ресторане', 'Order a full meal, ask for recommendations, and say you like the food.', '{"intro":"«Я бы хотел» is the polite way to say \"I would like\". It uses the past tense, so a woman says «я бы хотела».","sections":[{"type":"lines","kind":"dialogue","title":"Dinner out","lines":[{"ru":"Добрый вечер! Вы готовы заказать?","en":"Good evening! Are you ready to order?","words":[{"ru":"Добрый","en":"good"},{"ru":"вечер!","en":"evening"},{"ru":"Вы","en":"you"},{"ru":"готовы","en":"ready"},{"ru":"заказать?","en":"to order"}],"speaker":"Официантка"},{"ru":"Что ты хочешь заказать?","en":"What do you want to order?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"хочешь","en":"want"},{"ru":"заказать?","en":"to order"}],"speaker":"Максим"},{"ru":"Я бы хотела борщ и салат.","en":"I''d like borscht and a salad.","words":[{"ru":"Я","en":"I"},{"ru":"бы","en":"would"},{"ru":"хотела","en":"like"},{"ru":"борщ","en":"borscht"},{"ru":"и","en":"and"},{"ru":"салат.","en":"salad"}],"speaker":"Анна"},{"ru":"А я буду рыбу. Что вы посоветуете?","en":"And I''ll have the fish. What do you recommend?","words":[{"ru":"А","en":"and"},{"ru":"я","en":"I"},{"ru":"буду","en":"will have"},{"ru":"рыбу.","en":"fish"},{"ru":"Что","en":"what"},{"ru":"вы","en":"you"},{"ru":"посоветуете?","en":"recommend"}],"speaker":"Максим"},{"ru":"Попробуйте пельмени. Они очень вкусные.","en":"Try the pelmeni. They''re very good.","words":[{"ru":"Попробуйте","en":"try"},{"ru":"пельмени.","en":"pelmeni"},{"ru":"Они","en":"they"},{"ru":"очень","en":"very"},{"ru":"вкусные.","en":"tasty"}],"speaker":"Официантка"}]},{"type":"lines","kind":"phrases","title":"Useful at the table","lines":[{"ru":"Я бы хотел кофе без сахара.","en":"I''d like coffee without sugar.","words":[{"ru":"Я","en":"I"},{"ru":"бы","en":"would"},{"ru":"хотел","f":"хотела","en":"like"},{"ru":"кофе","en":"coffee"},{"ru":"без","en":"without"},{"ru":"сахара.","en":"sugar"}],"ruF":"Я бы хотела кофе без сахара."},{"ru":"Можно меню?","en":"May I see the menu?","words":[{"ru":"Можно","en":"may I"},{"ru":"меню?","en":"menu"}]},{"ru":"Сколько это стоит?","en":"How much does this cost?","words":[{"ru":"Сколько","en":"how much"},{"ru":"это","en":"this"},{"ru":"стоит?","en":"costs"}]},{"ru":"Мне очень нравится эта еда.","en":"I really like this food.","words":[{"ru":"Мне","en":"to me"},{"ru":"очень","en":"really"},{"ru":"нравится","en":"is pleasing"},{"ru":"эта","en":"this"},{"ru":"еда.","en":"food"}]},{"ru":"Это было очень вкусно!","en":"That was delicious!","words":[{"ru":"Это","en":"this"},{"ru":"было","en":"was"},{"ru":"очень","en":"very"},{"ru":"вкусно!","en":"tasty"}]},{"ru":"Счёт, пожалуйста.","en":"The bill, please.","words":[{"ru":"Счёт,","en":"the bill"},{"ru":"пожалуйста.","en":"please"}]}]},{"type":"grammar","title":"Polite ordering","paragraphs":["**Я бы хотел / хотела** + noun or verb = \"I would like\". **Бы** makes the sentence conditional and polite.","**Я буду** + noun (accusative) = \"I''ll have…\": я буду суп, я буду рыбу."],"examples":[{"ru":"Я бы хотел заказать.","en":"I''d like to order."},{"ru":"Я буду чай с лимоном.","en":"I''ll have tea with lemon."}]}],"drills":[{"q":"Я ___ хотела салат.","answer":"бы","options":["бы","буду","быть","был"],"en":"I''d like a salad.","why":{"буду":"Буду makes the future. A polite \"I''d like\" is я бы хотела.","был":"Был is the past \"was\". The polite \"would\" is бы.","быть":"Быть is the infinitive \"to be\". The polite \"would\" is бы."}},{"q":"Я буду ___. (рыба)","answer":"рыбу","options":["рыбы","рыба","рыбой","рыбу"],"en":"I''ll have the fish.","why":{"рыба":"When ordering, the dish is the object (accusative): Я буду рыбу.","рыбы":"Рыбы is the genitive (нет рыбы). Ordering it: рыбу.","рыбой":"Рыбой is the instrumental (с рыбой, \"with fish\"). Ordering it: рыбу."}},{"q":"Мне очень ___ эта еда.","answer":"нравится","options":["нравлюсь","люблю","нравятся","нравится"],"en":"I really like this food.","why":{"нравятся":"Нравятся is plural. Еда is one thing: нравится.","люблю":"Люблю needs я as the subject (я люблю эту еду). With мне use нравится.","нравлюсь":"Нравлюсь means \"I am liked\". The food is what''s liked: нравится."}},{"q":"___, пожалуйста. (the bill)","answer":"Счёт","options":["Счёта","Счётом","Счета","Счёт"],"en":"The bill, please.","why":{"Счёта":"Счёта is the genitive. Asking for something like this uses the plain form: Счёт, пожалуйста.","Счета":"Счета is plural (\"bills, accounts\"). One bill: Счёт.","Счётом":"Счётом is the instrumental. Use the plain form: Счёт."}}]}'::jsonb, 11, 10),
  ('a2-03', 'A2', 'cooking', 3, 'Groceries and cooking', 'Продукты и готовка', 'Write a shopping list, ask about prices by the kilo, and cook together.', '{"intro":"Quantities use the genitive: a kilo *of* apples, a bottle *of* milk, a little *(of)* salt.","sections":[{"type":"lines","kind":"phrases","title":"In the kitchen","lines":[{"ru":"Нам нужно купить молоко и яйца.","en":"We need to buy milk and eggs.","words":[{"ru":"Нам","en":"to us"},{"ru":"нужно","en":"need"},{"ru":"купить","en":"to buy"},{"ru":"молоко","en":"milk"},{"ru":"и","en":"and"},{"ru":"яйца.","en":"eggs"}]},{"ru":"Что у нас есть в холодильнике?","en":"What do we have in the fridge?","words":[{"ru":"Что","en":"what"},{"ru":"у","en":"by"},{"ru":"нас","en":"us"},{"ru":"есть","en":"there is"},{"ru":"в","en":"in"},{"ru":"холодильнике?","en":"fridge"}]},{"ru":"У нас нет хлеба.","en":"We''re out of bread.","words":[{"ru":"У","en":"by"},{"ru":"нас","en":"us"},{"ru":"нет","en":"no"},{"ru":"хлеба.","en":"bread"}]},{"ru":"Сколько стоит килограмм яблок?","en":"How much is a kilo of apples?","words":[{"ru":"Сколько","en":"how much"},{"ru":"стоит","en":"costs"},{"ru":"килограмм","en":"kilo"},{"ru":"яблок?","en":"of apples"}]},{"ru":"Я готовлю ужин.","en":"I''m making dinner.","words":[{"ru":"Я","en":"I"},{"ru":"готовлю","en":"am making"},{"ru":"ужин.","en":"dinner"}]},{"ru":"Порежь, пожалуйста, лук.","en":"Chop the onion, please.","words":[{"ru":"Порежь,","en":"chop"},{"ru":"пожалуйста,","en":"please"},{"ru":"лук.","en":"onion"}]},{"ru":"Добавь немного соли.","en":"Add a little salt.","words":[{"ru":"Добавь","en":"add"},{"ru":"немного","en":"a little"},{"ru":"соли.","en":"salt"}]},{"ru":"Суп готов!","en":"The soup is ready!","words":[{"ru":"Суп","en":"soup"},{"ru":"готов!","en":"ready"}]},{"ru":"Ты умеешь готовить пельмени?","en":"Do you know how to make pelmeni?","words":[{"ru":"Ты","en":"you"},{"ru":"умеешь","en":"know how"},{"ru":"готовить","en":"to make"},{"ru":"пельмени?","en":"pelmeni"}]},{"ru":"Меня научила бабушка.","en":"My grandma taught me.","words":[{"ru":"Меня","en":"me"},{"ru":"научила","en":"taught"},{"ru":"бабушка.","en":"grandma"}]}]},{"type":"grammar","title":"Genitive of quantity","paragraphs":["Words of amount take the genitive: килограмм **яблок**, бутылка **молока**, немного **соли**, много **воды**.","**Нет** + genitive = \"there isn''t any\": нет хлеба, нет сахара.","**Уметь** = \"to know how to\": я умею готовить."],"examples":[{"ru":"Купи, пожалуйста, литр молока.","en":"Please buy a liter of milk."},{"ru":"У нас нет сахара.","en":"We''re out of sugar."}]}],"drills":[{"q":"Килограмм ___, пожалуйста. (яблоки)","answer":"яблок","options":["яблоки","яблоками","яблок","яблоко"],"en":"A kilo of apples, please.","why":{"яблоки":"Amounts take the genitive: килограмм яблок (genitive plural).","яблоко":"Яблоко is one apple. \"A kilo of apples\" is килограмм яблок.","яблоками":"Яблоками is the instrumental. After килограмм use яблок."}},{"q":"У нас нет ___. (хлеб)","answer":"хлеба","options":["хлебом","хлеб","хлебу","хлеба"],"en":"We''re out of bread.","why":{"хлеб":"Нет (\"there''s no\") takes the genitive: нет хлеба.","хлебу":"Хлебу is the dative. Нет needs хлеба.","хлебом":"Хлебом is the instrumental. Нет needs хлеба."}},{"q":"Добавь немного ___. (соль)","answer":"соли","options":["соли","соле","солью","соль"],"en":"Add a little salt.","why":{"соль":"Немного (\"a little\") takes the genitive: немного соли.","солью":"Солью is the instrumental (с солью). Немного needs соли.","соле":"Соле isn''t a real form. Соль is feminine, so its genitive is соли."}},{"q":"Ты ___ готовить?","answer":"умеешь","options":["умеешь","умеет","уметь","умею"],"en":"Do you know how to cook?","why":{"умею":"Умею is the я form. With ты use умеешь.","умеет":"Умеет is the он/она form. With ты use умеешь.","уметь":"Уметь is the infinitive. With ты use умеешь."}}]}'::jsonb, 10, 10),
  ('a2-04', 'A2', 'plans', 4, 'Making plans', 'Планы на выходные', 'Suggest a meeting, agree on a time and place, or politely say no.', '{"intro":"Days of the week take в + accusative: в субботу, в воскресенье. «Тебе подходит?» — \"Does that suit you?\" — is the key planning question.","sections":[{"type":"lines","kind":"dialogue","title":"Weekend plans","lines":[{"ru":"Что ты делаешь в субботу?","en":"What are you doing on Saturday?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делаешь","en":"are doing"},{"ru":"в","en":"on"},{"ru":"субботу?","en":"Saturday"}],"speaker":"Максим"},{"ru":"Пока не знаю. А что?","en":"I don''t know yet. Why?","words":[{"ru":"Пока","en":"yet"},{"ru":"не","en":"not"},{"ru":"знаю.","en":"know"},{"ru":"А","en":"and"},{"ru":"что?","en":"what"}],"speaker":"Анна"},{"ru":"Давай встретимся и сходим в кино.","en":"Let''s meet up and go to the movies.","words":[{"ru":"Давай","en":"let''s"},{"ru":"встретимся","en":"meet"},{"ru":"и","en":"and"},{"ru":"сходим","en":"go"},{"ru":"в","en":"to"},{"ru":"кино.","en":"the movies"}],"speaker":"Максим"},{"ru":"С удовольствием! Во сколько?","en":"I''d love to! What time?","words":[{"ru":"С","en":"with"},{"ru":"удовольствием!","en":"pleasure"},{"ru":"Во","en":"at"},{"ru":"сколько?","en":"what time"}],"speaker":"Анна"},{"ru":"В семь вечера. Тебе подходит?","en":"At seven in the evening. Does that work for you?","words":[{"ru":"В","en":"at"},{"ru":"семь","en":"seven"},{"ru":"вечера.","en":"in the evening"},{"ru":"Тебе","en":"to you"},{"ru":"подходит?","en":"suits"}],"speaker":"Максим"},{"ru":"Да, подходит. Где встретимся?","en":"Yes, that works. Where shall we meet?","words":[{"ru":"Да,","en":"yes"},{"ru":"подходит.","en":"suits"},{"ru":"Где","en":"where"},{"ru":"встретимся?","en":"(shall we) meet"}],"speaker":"Анна"},{"ru":"У входа в кинотеатр.","en":"At the cinema entrance.","words":[{"ru":"У","en":"at"},{"ru":"входа","en":"the entrance"},{"ru":"в","en":"to"},{"ru":"кинотеатр.","en":"cinema"}],"speaker":"Максим"}]},{"type":"lines","kind":"phrases","title":"Saying yes or no","lines":[{"ru":"Извини, я не могу, у меня дела.","en":"Sorry, I can''t, I have things to do.","words":[{"ru":"Извини,","en":"sorry"},{"ru":"я","en":"I"},{"ru":"не","en":"not"},{"ru":"могу,","en":"can"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"дела.","en":"things to do"}]},{"ru":"Может быть, в воскресенье?","en":"Maybe on Sunday?","words":[{"ru":"Может","en":"maybe"},{"ru":"быть,","en":"be"},{"ru":"в","en":"on"},{"ru":"воскресенье?","en":"Sunday"}]},{"ru":"Договорились!","en":"It''s a deal!","words":[{"ru":"Договорились!","en":"agreed"}]},{"ru":"До встречи!","en":"See you then!","words":[{"ru":"До","en":"until"},{"ru":"встречи!","en":"meeting"}]}]},{"type":"grammar","title":"Days and times","paragraphs":["Days: в понедельник, во вторник, в среду, в четверг, в пятницу, в субботу, в воскресенье.","Times: в семь утра, в три часа дня, в восемь вечера. **Во сколько?** = \"At what time?\""],"examples":[{"ru":"Давай встретимся в пятницу.","en":"Let''s meet on Friday."},{"ru":"Фильм начинается в восемь вечера.","en":"The film starts at 8 p.m."}]}],"drills":[{"q":"Что ты делаешь в ___? (Saturday)","answer":"субботу","options":["субботу","суббота","субботы","субботе"],"en":"What are you doing on Saturday?","why":{"суббота":"\"On (a day)\" is в + accusative: в субботу.","субботы":"Субботы is the genitive (до субботы). \"On Saturday\" is в субботу.","субботе":"Субботе is the prepositional (о субботе). \"On Saturday\" is в субботу."}},{"q":"___ сколько?","answer":"Во","options":["До","В","На","Во"],"en":"At what time?","why":{"В":"Before сколько, в becomes во to be easier to say: Во сколько?","На":"На isn''t used for times. \"At what time?\" is Во сколько?","До":"До means \"until\" (до скольки — until what time). \"At what time?\" is Во сколько?"}},{"q":"Тебе ___? — Да, отлично.","answer":"подходит","options":["подходит","подходишь","подойти","подходят"],"en":"Does that work for you? — Yes, great.","why":{"подходишь":"Подходишь is \"you suit\". It''s the plan or time that suits you: подходит.","подходят":"Подходят is plural. One plan or time: подходит.","подойти":"Подойти is the infinitive. The sentence needs the он/оно form: подходит."}},{"q":"Извини, я не ___.","answer":"могу","options":["мочь","можешь","может","могу"],"en":"Sorry, I can''t.","why":{"может":"Может is the он/она form. With я use могу.","можешь":"Можешь is the ты form. With я use могу.","мочь":"Мочь is the infinitive. With я use могу."}}]}'::jsonb, 11, 10),
  ('a2-05', 'A2', 'friends', 5, 'Making friends', 'Новые друзья', 'Get to know someone new, find common interests and swap contacts.', '{"intro":"«Чем ты увлекаешься?» — \"What are you into?\" — opens up any friendly conversation. The answer takes the instrumental: увлекаюсь фотографией.","sections":[{"type":"lines","kind":"phrases","title":"New friends","lines":[{"ru":"Ты давно живёшь здесь?","en":"Have you lived here long?","words":[{"ru":"Ты","en":"you"},{"ru":"давно","en":"long"},{"ru":"живёшь","en":"live"},{"ru":"здесь?","en":"here"}]},{"ru":"Нет, я переехал недавно.","en":"No, I moved recently.","words":[{"ru":"Нет,","en":"no"},{"ru":"я","en":"I"},{"ru":"переехал","f":"переехала","en":"moved"},{"ru":"недавно.","en":"recently"}],"ruF":"Нет, я переехала недавно.","note":"Russian uses the present tense for \"have been doing\": давно живёшь = \"have lived for a long time\"."},{"ru":"Хочешь пойти с нами в бар?","en":"Want to come to a bar with us?","words":[{"ru":"Хочешь","en":"want"},{"ru":"пойти","en":"to go"},{"ru":"с","en":"with"},{"ru":"нами","en":"us"},{"ru":"в","en":"to"},{"ru":"бар?","en":"bar"}]},{"ru":"Конечно, с радостью!","en":"Sure, gladly!","words":[{"ru":"Конечно,","en":"of course"},{"ru":"с","en":"with"},{"ru":"радостью!","en":"joy"}]},{"ru":"Чем ты увлекаешься?","en":"What are you into?","words":[{"ru":"Чем","en":"with what"},{"ru":"ты","en":"you"},{"ru":"увлекаешься?","en":"are into"}]},{"ru":"Я увлекаюсь фотографией.","en":"I''m into photography.","words":[{"ru":"Я","en":"I"},{"ru":"увлекаюсь","en":"am into"},{"ru":"фотографией.","en":"photography"}]},{"ru":"У нас много общего!","en":"We have a lot in common!","words":[{"ru":"У","en":"by"},{"ru":"нас","en":"us"},{"ru":"много","en":"much"},{"ru":"общего!","en":"in common"}]},{"ru":"Давай обменяемся номерами.","en":"Let''s swap numbers.","words":[{"ru":"Давай","en":"let''s"},{"ru":"обменяемся","en":"exchange"},{"ru":"номерами.","en":"numbers"}]},{"ru":"Напиши мне в Телеграм.","en":"Message me on Telegram.","words":[{"ru":"Напиши","en":"write"},{"ru":"мне","en":"to me"},{"ru":"в","en":"in"},{"ru":"Телеграм.","en":"Telegram"}]},{"ru":"Было приятно познакомиться!","en":"It was nice to meet you!","words":[{"ru":"Было","en":"it was"},{"ru":"приятно","en":"nice"},{"ru":"познакомиться!","en":"to meet"}]}]},{"type":"grammar","title":"Увлекаться + instrumental","paragraphs":["Verbs ending in **-ся** often mean \"to be into / to be busy with\". **Увлекаться** and **заниматься** both take the instrumental:","увлекаюсь музык**ой**, фотографи**ей**, шахмат**ами** · занимаюсь спорт**ом**."],"examples":[{"ru":"Он увлекается историей.","en":"He''s into history."},{"ru":"Я увлекаюсь шахматами с детства.","en":"I''ve loved chess since childhood."}]}],"drills":[{"q":"Чем ты ___?","answer":"увлекаешься","options":["увлекаюсь","увлекаться","увлекается","увлекаешься"],"en":"What are you into?","why":{"увлекаюсь":"Увлекаюсь is the я form. With ты use увлекаешься.","увлекается":"Увлекается is the он/она form. With ты use увлекаешься.","увлекаться":"Увлекаться is the infinitive. With ты use увлекаешься."}},{"q":"Я увлекаюсь ___. (фотография)","answer":"фотографией","options":["фотографии","фотографию","фотографией","фотография"],"en":"I''m into photography.","why":{"фотография":"Увлекаться takes the instrumental: увлекаюсь фотографией.","фотографию":"Фотографию is the accusative. Увлекаться needs фотографией.","фотографии":"Фотографии is the genitive or prepositional. Увлекаться needs фотографией."}},{"q":"Нет, я переехала ___.","answer":"недавно","options":["недавно","скоро","долго","давно"],"en":"No, I moved recently.","why":{"давно":"Давно means \"long ago\". \"Recently\" is недавно.","долго":"Долго means \"for a long time\". \"Recently\" is недавно.","скоро":"Скоро means \"soon\" (future). With a past verb, \"recently\" is недавно."}},{"q":"Было приятно ___!","answer":"познакомиться","options":["знакомый","знаю","знакомство","познакомиться"],"en":"Nice to meet you!","why":{"знакомый":"Знакомый means \"an acquaintance\". After приятно use a verb: познакомиться.","знакомство":"Знакомство is a noun (\"getting to know\"). After приятно use the verb: познакомиться.","знаю":"Знаю is \"I know\". \"Nice to meet you\" is Приятно познакомиться."}}]}'::jsonb, 10, 7),
  ('a2-06', 'A2', 'travel', 6, 'Getting around', 'Транспорт', 'Buy tickets, find the right bus or train, and understand announcements.', '{"intro":"Russian separates going on foot (идти) from going by vehicle (ехать). You''ll hear «Следующая станция…» on every metro ride.","sections":[{"type":"lines","kind":"phrases","title":"On the move","lines":[{"ru":"Как доехать до вокзала?","en":"How do I get to the train station?","words":[{"ru":"Как","en":"how"},{"ru":"доехать","en":"to get"},{"ru":"до","en":"to"},{"ru":"вокзала?","en":"the station"}]},{"ru":"Садитесь на автобус номер пять.","en":"Take bus number five.","words":[{"ru":"Садитесь","en":"get"},{"ru":"на","en":"on"},{"ru":"автобус","en":"bus"},{"ru":"номер","en":"number"},{"ru":"пять.","en":"five"}],"tag":"formal"},{"ru":"Где можно купить билет?","en":"Where can I buy a ticket?","words":[{"ru":"Где","en":"where"},{"ru":"можно","en":"can one"},{"ru":"купить","en":"buy"},{"ru":"билет?","en":"ticket"}]},{"ru":"Сколько стоит билет до Петербурга?","en":"How much is a ticket to St Petersburg?","words":[{"ru":"Сколько","en":"how much"},{"ru":"стоит","en":"costs"},{"ru":"билет","en":"ticket"},{"ru":"до","en":"to"},{"ru":"Петербурга?","en":"Petersburg"}]},{"ru":"Поезд отправляется в девять утра.","en":"The train leaves at 9 a.m.","words":[{"ru":"Поезд","en":"train"},{"ru":"отправляется","en":"departs"},{"ru":"в","en":"at"},{"ru":"девять","en":"nine"},{"ru":"утра.","en":"in the morning"}]},{"ru":"Нужно сделать пересадку.","en":"You need to change.","words":[{"ru":"Нужно","en":"(you) need"},{"ru":"сделать","en":"to make"},{"ru":"пересадку.","en":"transfer"}]},{"ru":"На какой станции выходить?","en":"Which station do I get off at?","words":[{"ru":"На","en":"at"},{"ru":"какой","en":"which"},{"ru":"станции","en":"station"},{"ru":"выходить?","en":"to get off"}]},{"ru":"Я еду на такси.","en":"I''m going by taxi.","words":[{"ru":"Я","en":"I"},{"ru":"еду","en":"am going"},{"ru":"на","en":"by"},{"ru":"такси.","en":"taxi"}]},{"ru":"Я опоздал на поезд.","en":"I missed my train.","words":[{"ru":"Я","en":"I"},{"ru":"опоздал","f":"опоздала","en":"was late"},{"ru":"на","en":"for"},{"ru":"поезд.","en":"train"}],"ruF":"Я опоздала на поезд."},{"ru":"Следующая станция — «Театральная».","en":"Next station: Teatralnaya.","words":[{"ru":"Следующая","en":"next"},{"ru":"станция","en":"station"},{"ru":"—","en":"(is)"},{"ru":"«Театральная».","en":"Teatralnaya"}],"note":"You''ll hear this announcement in the Moscow metro."}]},{"type":"grammar","title":"Идти or ехать?","paragraphs":["**Идти** = to go on foot; **ехать** = to go by vehicle. Transport takes **на** + prepositional: на автобусе, на поезде, на метро, на такси.","**До** + genitive = \"as far as / to\": до вокзала, до центра."],"examples":[{"ru":"Я иду на работу пешком.","en":"I walk to work."},{"ru":"Я еду на работу на метро.","en":"I take the metro to work."}]}],"drills":[{"q":"Как доехать до ___? (вокзал)","answer":"вокзала","options":["вокзале","вокзала","вокзалу","вокзал"],"en":"How do I get to the station?","why":{"вокзал":"До takes the genitive: до вокзала.","вокзалу":"Вокзалу is the dative (к вокзалу). До needs вокзала.","вокзале":"Вокзале is the prepositional (на вокзале). До needs вокзала."}},{"q":"Я ___ на такси.","answer":"еду","options":["хожу","иду","еду","ходил"],"en":"I''m going by taxi.","why":{"иду":"Иду is going on foot. By vehicle (на такси) use ехать: еду.","хожу":"Хожу is walking, regularly. In a taxi, right now: еду.","ходил":"Ходил is past and on foot. Now, by taxi: еду."}},{"q":"Нужно сделать ___.","answer":"пересадку","options":["пересадки","пересадка","пересадку","пересадкой"],"en":"You need to change.","why":{"пересадка":"Сделать takes a direct object in the accusative: пересадку.","пересадки":"Пересадки is the genitive or plural. The object of сделать is пересадку.","пересадкой":"Пересадкой is the instrumental. The object of сделать is пересадку."}},{"q":"___ станция — «Арбатская».","answer":"Следующая","options":["Следующее","Следующие","Следующий","Следующая"],"en":"Next station: Arbatskaya.","why":{"Следующий":"Следующий is masculine. Станция is feminine: Следующая.","Следующее":"Следующее is neuter. Станция is feminine: Следующая.","Следующие":"Следующие is plural. One станция: Следующая."}}]}'::jsonb, 10, 14),
  ('a2-07', 'A2', 'hotels', 7, 'At the hotel', 'В гостинице', 'Check in, ask about breakfast and report a problem with your room.', '{"intro":"Hotel Russian is formal — you''ll use вы throughout. «Номер» means both \"room\" and \"number\".","sections":[{"type":"lines","kind":"phrases","title":"Check-in and stay","lines":[{"ru":"Здравствуйте, у меня забронирован номер.","en":"Hello, I have a room booked.","words":[{"ru":"Здравствуйте,","en":"hello"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"забронирован","en":"booked"},{"ru":"номер.","en":"room"}],"tag":"formal"},{"ru":"Ваша фамилия?","en":"Your last name?","words":[{"ru":"Ваша","en":"your"},{"ru":"фамилия?","en":"surname"}],"tag":"formal"},{"ru":"На сколько ночей?","en":"For how many nights?","words":[{"ru":"На","en":"for"},{"ru":"сколько","en":"how many"},{"ru":"ночей?","en":"nights"}]},{"ru":"На три ночи.","en":"For three nights.","words":[{"ru":"На","en":"for"},{"ru":"три","en":"three"},{"ru":"ночи.","en":"nights"}]},{"ru":"Завтрак включён?","en":"Is breakfast included?","words":[{"ru":"Завтрак","en":"breakfast"},{"ru":"включён?","en":"included"}]},{"ru":"Да, завтрак с семи до десяти.","en":"Yes, breakfast is from seven to ten.","words":[{"ru":"Да,","en":"yes"},{"ru":"завтрак","en":"breakfast"},{"ru":"с","en":"from"},{"ru":"семи","en":"seven"},{"ru":"до","en":"until"},{"ru":"десяти.","en":"ten"}]},{"ru":"Вот ваш ключ.","en":"Here''s your key.","words":[{"ru":"Вот","en":"here is"},{"ru":"ваш","en":"your"},{"ru":"ключ.","en":"key"}],"tag":"formal"},{"ru":"Номер на третьем этаже.","en":"The room is on the third floor.","words":[{"ru":"Номер","en":"room"},{"ru":"на","en":"on"},{"ru":"третьем","en":"third"},{"ru":"этаже.","en":"floor"}]},{"ru":"В номере не работает кондиционер.","en":"The air conditioning in my room isn''t working.","words":[{"ru":"В","en":"in"},{"ru":"номере","en":"the room"},{"ru":"не","en":"not"},{"ru":"работает","en":"works"},{"ru":"кондиционер.","en":"air conditioner"}]},{"ru":"Во сколько нужно освободить номер?","en":"What time is check-out?","words":[{"ru":"Во","en":"at"},{"ru":"сколько","en":"what time"},{"ru":"нужно","en":"(one) must"},{"ru":"освободить","en":"vacate"},{"ru":"номер?","en":"the room"}]},{"ru":"Можно оставить вещи?","en":"Can I leave my bags?","words":[{"ru":"Можно","en":"may I"},{"ru":"оставить","en":"leave"},{"ru":"вещи?","en":"things"}]}]},{"type":"grammar","title":"On the third floor","paragraphs":["\"On the … floor\" uses **на** + prepositional of the ordinal number: на перв**ом**, втор**ом**, трет**ьем**, пят**ом** этаже.","**С … до …** + genitive gives a time range: с семи до десяти, с девяти до шести."],"examples":[{"ru":"Ресторан работает с восьми до одиннадцати.","en":"The restaurant is open from eight to eleven."},{"ru":"Мой номер на пятом этаже.","en":"My room is on the fifth floor."}]}],"drills":[{"q":"Номер на третьем ___.","answer":"этаже","options":["этаже","этаж","этажом","этажа"],"en":"The room is on the third floor.","why":{"этаж":"На for location (\"on\") takes the prepositional: на этаже.","этажа":"Этажа is the genitive. Location with на needs этаже.","этажом":"Этажом is the instrumental (под этажом). \"On the floor\" is на этаже."}},{"q":"Завтрак с семи до ___.","answer":"десяти","options":["десятью","десяти","десять","десятый"],"en":"Breakfast is from seven to ten.","why":{"десять":"До takes the genitive: до десяти.","десятью":"Десятью is the instrumental. До needs десяти.","десятый":"Десятый is \"tenth\". \"Until ten\" is до десяти."}},{"q":"На сколько ___?","answer":"ночей","options":["ночи","ночей","ночь","ночью"],"en":"For how many nights?","why":{"ночь":"After сколько use the genitive plural: сколько ночей.","ночи":"Ночи follows 2–4 (две ночи). After сколько: ночей.","ночью":"Ночью means \"at night\". After сколько: ночей."}},{"q":"У меня ___ номер.","answer":"забронирован","options":["забронирую","забронировать","забронирован","бронь"],"en":"I have a room booked.","why":{"забронировать":"Забронировать is the infinitive \"to book\". \"Is booked\" is the short form: забронирован.","бронь":"Бронь is the noun \"a booking\". \"A room is booked\" is номер забронирован.","забронирую":"Забронирую is \"I will book\". Already booked: забронирован."}}]}'::jsonb, 11, 11),
  ('a2-08', 'A2', 'fitness', 8, 'At the gym', 'В спортзале', 'Talk about exercise, your workout and how you feel afterwards.', '{"intro":"«Заниматься» + instrumental means \"to do (a sport)\". And Russians say «я устал» — \"I got tired\" — to mean \"I''m tired\".","sections":[{"type":"lines","kind":"phrases","title":"Working out","lines":[{"ru":"Я хожу в спортзал три раза в неделю.","en":"I go to the gym three times a week.","words":[{"ru":"Я","en":"I"},{"ru":"хожу","en":"go"},{"ru":"в","en":"to"},{"ru":"спортзал","en":"the gym"},{"ru":"три","en":"three"},{"ru":"раза","en":"times"},{"ru":"в","en":"a"},{"ru":"неделю.","en":"week"}]},{"ru":"Я бегаю по утрам.","en":"I run in the mornings.","words":[{"ru":"Я","en":"I"},{"ru":"бегаю","en":"run"},{"ru":"по","en":"in"},{"ru":"утрам.","en":"the mornings"}]},{"ru":"Сколько подходов?","en":"How many sets?","words":[{"ru":"Сколько","en":"how many"},{"ru":"подходов?","en":"sets"}]},{"ru":"Три по десять.","en":"Three sets of ten.","words":[{"ru":"Три","en":"three"},{"ru":"по","en":"of"},{"ru":"десять.","en":"ten"}]},{"ru":"Мне нужно размяться.","en":"I need to warm up.","words":[{"ru":"Мне","en":"to me"},{"ru":"нужно","en":"need"},{"ru":"размяться.","en":"to warm up"}]},{"ru":"У меня болят ноги после тренировки.","en":"My legs hurt after the workout.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"болят","en":"ache"},{"ru":"ноги","en":"legs"},{"ru":"после","en":"after"},{"ru":"тренировки.","en":"the workout"}]},{"ru":"Ты занимаешься спортом?","en":"Do you do any sports?","words":[{"ru":"Ты","en":"you"},{"ru":"занимаешься","en":"do"},{"ru":"спортом?","en":"sport"}]},{"ru":"Я занимаюсь йогой.","en":"I do yoga.","words":[{"ru":"Я","en":"I"},{"ru":"занимаюсь","en":"do"},{"ru":"йогой.","en":"yoga"}]},{"ru":"Давай тренироваться вместе!","en":"Let''s train together!","words":[{"ru":"Давай","en":"let''s"},{"ru":"тренироваться","en":"train"},{"ru":"вместе!","en":"together"}]},{"ru":"Я устал.","en":"I''m tired.","words":[{"ru":"Я","en":"I"},{"ru":"устал.","f":"устала.","en":"got tired"}],"ruF":"Я устала.","note":"The past tense here describes your state now."},{"ru":"Ещё один раз!","en":"One more time!","words":[{"ru":"Ещё","en":"another"},{"ru":"один","en":"one"},{"ru":"раз!","en":"time"}]}]},{"type":"grammar","title":"How often?","paragraphs":["**Раз в неделю / в месяц** = \"once a week / a month\"; два, три, четыре **раза**; пять **раз**.","**По утрам / по вечерам** = \"in the mornings / evenings\" (habitually).","**Заниматься** + instrumental: спорт**ом**, йог**ой**, плавани**ем**."],"examples":[{"ru":"Я плаваю два раза в неделю.","en":"I swim twice a week."},{"ru":"Она занимается бегом.","en":"She runs (does running)."}]}],"drills":[{"q":"Я хожу в спортзал три ___ в неделю.","answer":"раза","options":["раза","разу","раз","разом"],"en":"I go to the gym three times a week.","why":{"раз":"Раз follows 1 and 5 and up (пять раз). After три: раза.","разу":"Разу is the dative (ни разу — not once). After три: раза.","разом":"Разом means \"all at once\". After три: раза."}},{"q":"Ты занимаешься ___?","answer":"спортом","options":["спорта","спортом","спорте","спорт"],"en":"Do you do any sports?","why":{"спорт":"Заниматься takes the instrumental: заниматься спортом.","спорта":"Спорта is the genitive. Заниматься needs спортом.","спорте":"Спорте is the prepositional (о спорте). Заниматься needs спортом."}},{"q":"У меня ___ ноги.","answer":"болят","options":["болят","болеть","болела","болит"],"en":"My legs hurt.","why":{"болит":"Болит is for one thing (болит голова). Ноги is plural: болят.","болеть":"Болеть is the infinitive. A plural subject needs болят.","болела":"Болела is past and feminine singular. Present, plural: болят."}},{"q":"Я ___. (I''m tired — a woman)","answer":"устала","options":["устать","устал","устала","устаю"],"en":"I''m tired.","why":{"устал":"Устал is what a man says. A woman says устала.","устаю":"Устаю is \"I get tired\" (usually). \"I''m tired\" right now is устала.","устать":"Устать is the infinitive. A woman says устала."}}]}'::jsonb, 11, 9),
  ('a2-09', 'A2', 'health', 9, 'At the doctor''s', 'У врача', 'Make an appointment, describe symptoms and understand the doctor''s advice.', '{"intro":"Pain is something that \"hurts at you\": «у меня болит голова». The verb agrees with what hurts.","sections":[{"type":"lines","kind":"dialogue","title":"An appointment","lines":[{"ru":"Мне нужно записаться к врачу.","en":"I need to make a doctor''s appointment.","words":[{"ru":"Мне","en":"to me"},{"ru":"нужно","en":"need"},{"ru":"записаться","en":"to book"},{"ru":"к","en":"to"},{"ru":"врачу.","en":"the doctor"}],"speaker":"Анна"},{"ru":"Что вас беспокоит?","en":"What seems to be the problem?","words":[{"ru":"Что","en":"what"},{"ru":"вас","en":"you"},{"ru":"беспокоит?","en":"is bothering"}],"speaker":"Врач"},{"ru":"У меня болит голова.","en":"I have a headache.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"болит","en":"aches"},{"ru":"голова.","en":"head"}],"speaker":"Анна"},{"ru":"И ещё температура и кашель.","en":"And I have a fever and a cough.","words":[{"ru":"И","en":"and"},{"ru":"ещё","en":"also"},{"ru":"температура","en":"temperature"},{"ru":"и","en":"and"},{"ru":"кашель.","en":"cough"}],"speaker":"Анна"},{"ru":"Как давно?","en":"For how long?","words":[{"ru":"Как","en":"how"},{"ru":"давно?","en":"long"}],"speaker":"Врач"},{"ru":"Со вчерашнего дня.","en":"Since yesterday.","words":[{"ru":"Со","en":"since"},{"ru":"вчерашнего","en":"yesterday''s"},{"ru":"дня.","en":"day"}],"speaker":"Анна"},{"ru":"Принимайте это лекарство три раза в день.","en":"Take this medicine three times a day.","words":[{"ru":"Принимайте","en":"take"},{"ru":"это","en":"this"},{"ru":"лекарство","en":"medicine"},{"ru":"три","en":"three"},{"ru":"раза","en":"times"},{"ru":"в","en":"a"},{"ru":"день.","en":"day"}],"speaker":"Врач"}]},{"type":"lines","kind":"phrases","title":"Afterwards","lines":[{"ru":"Где ближайшая аптека?","en":"Where''s the nearest pharmacy?","words":[{"ru":"Где","en":"where"},{"ru":"ближайшая","en":"nearest"},{"ru":"аптека?","en":"pharmacy"}]},{"ru":"Мне уже лучше.","en":"I feel better already.","words":[{"ru":"Мне","en":"to me"},{"ru":"уже","en":"already"},{"ru":"лучше.","en":"better"}]},{"ru":"У меня болит горло.","en":"I have a sore throat.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"болит","en":"aches"},{"ru":"горло.","en":"throat"}]},{"ru":"Выздоравливай!","en":"Get well soon!","words":[{"ru":"Выздоравливай!","en":"get well"}]}]},{"type":"grammar","title":"What hurts?","paragraphs":["**У меня болит** + one thing: голова, горло, живот. **У меня болят** + several: ноги, глаза, зубы.","**Записаться к** + dative = \"to make an appointment with\": к врачу, к стоматологу."],"examples":[{"ru":"У него болит спина.","en":"His back hurts."},{"ru":"Я записалась к врачу на завтра.","en":"I''ve booked a doctor''s appointment for tomorrow."}]}],"drills":[{"q":"У меня ___ голова.","answer":"болит","options":["больно","болею","болит","болят"],"en":"I have a headache.","why":{"болят":"Болят is plural. Голова is one thing: болит.","болею":"Болею is \"I''m ill\". With голова as the subject: болит.","больно":"Больно is \"it hurts\" (мне больно). With голова as the subject: болит."}},{"q":"У меня ___ глаза.","answer":"болят","options":["болел","болеет","болят","болит"],"en":"My eyes hurt.","why":{"болит":"Болит is singular. Глаза is plural: болят.","болеет":"Болеет is \"is ill\" (about a person). Body parts hurt: болят.","болел":"Болел is past and masculine singular. Present, plural: болят."}},{"q":"Мне нужно записаться к ___.","answer":"врачу","options":["врачу","врачом","врача","врач"],"en":"I need to see a doctor.","why":{"врач":"К (\"to someone\") takes the dative: к врачу.","врача":"Врача is the genitive or accusative. К needs врачу.","врачом":"Врачом is the instrumental (с врачом). К needs врачу."}},{"q":"Мне уже ___.","answer":"лучше","options":["лучший","хорошо","лучше","хороший"],"en":"I feel better already.","why":{"хорошо":"Хорошо is \"good, fine\". Уже (\"already\") points to a change: лучше, \"better\".","лучший":"Лучший is the adjective \"the best\". With мне use the adverb: лучше.","хороший":"Хороший is an adjective. With мне use лучше."}}]}'::jsonb, 11, 9),
  ('a2-10', 'A2', 'phone', 10, 'On the phone', 'По телефону', 'Answer the phone, ask for someone, leave a message and handle a bad line.', '{"intro":"Russians answer with «Алло!». Calling someone takes the dative: звонить кому? — мне, тебе, Анне.","sections":[{"type":"lines","kind":"phrases","title":"Phone calls","lines":[{"ru":"Алло!","en":"Hello? (answering the phone)","words":[{"ru":"Алло!","en":"hello"}]},{"ru":"Здравствуйте, можно Анну?","en":"Hello, may I speak to Anna?","words":[{"ru":"Здравствуйте,","en":"hello"},{"ru":"можно","en":"may I"},{"ru":"Анну?","en":"Anna"}],"tag":"formal"},{"ru":"Её сейчас нет.","en":"She''s not in right now.","words":[{"ru":"Её","en":"her"},{"ru":"сейчас","en":"now"},{"ru":"нет.","en":"isn''t here"}]},{"ru":"Что-нибудь передать?","en":"Can I take a message?","words":[{"ru":"Что-нибудь","en":"anything"},{"ru":"передать?","en":"to pass on"}]},{"ru":"Перезвоните, пожалуйста, позже.","en":"Please call back later.","words":[{"ru":"Перезвоните,","en":"call back"},{"ru":"пожалуйста,","en":"please"},{"ru":"позже.","en":"later"}],"tag":"formal"},{"ru":"Вас плохо слышно.","en":"I can''t hear you well.","words":[{"ru":"Вас","en":"you"},{"ru":"плохо","en":"badly"},{"ru":"слышно.","en":"audible"}]},{"ru":"Я тебе перезвоню.","en":"I''ll call you back.","words":[{"ru":"Я","en":"I"},{"ru":"тебе","en":"to you"},{"ru":"перезвоню.","en":"will call back"}]},{"ru":"Кто это?","en":"Who''s this?","words":[{"ru":"Кто","en":"who"},{"ru":"это?","en":"this"}]},{"ru":"Вы ошиблись номером.","en":"You''ve got the wrong number.","words":[{"ru":"Вы","en":"you"},{"ru":"ошиблись","en":"made a mistake"},{"ru":"номером.","en":"number"}],"tag":"formal"},{"ru":"Я не могу сейчас говорить.","en":"I can''t talk right now.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"могу","en":"can"},{"ru":"сейчас","en":"now"},{"ru":"говорить.","en":"talk"}]},{"ru":"Позвони мне вечером.","en":"Call me tonight.","words":[{"ru":"Позвони","en":"call"},{"ru":"мне","en":"me"},{"ru":"вечером.","en":"in the evening"}]}]},{"type":"grammar","title":"Calling someone","paragraphs":["**Звонить / позвонить** take the dative: позвони **мне**, я позвоню **тебе**, позвоните **Анне**.","**Её нет / его нет** = \"she / he isn''t here\" (нет + genitive)."],"examples":[{"ru":"Я позвоню тебе завтра.","en":"I''ll call you tomorrow."},{"ru":"Мамы нет дома.","en":"Mom isn''t home."}]}],"drills":[{"q":"Позвони ___ вечером.","answer":"мне","options":["мной","я","мне","меня"],"en":"Call me in the evening.","why":{"меня":"Звонить takes the dative (\"to me\"): позвони мне.","я":"Я is \"I\" (the subject). \"Call me\" is позвони мне.","мной":"Мной is the instrumental (со мной). Звонить needs мне."}},{"q":"Её сейчас ___.","answer":"нет","options":["ни","нету","не","нет"],"en":"She''s not here right now.","why":{"не":"Не negates a verb or word. \"Isn''t here\" is нет: её нет.","нету":"Нету is very colloquial. Standard Russian says её нет.","ни":"Ни means \"not even, neither\". \"She isn''t here\" is её нет."}},{"q":"Вас плохо ___.","answer":"слышно","options":["слышать","слышу","слышный","слышно"],"en":"I can''t hear you well.","why":{"слышу":"Слышу needs я (я вас плохо слышу). With no subject, use слышно.","слышать":"Слышать is the infinitive. The impersonal \"can be heard\" is слышно.","слышный":"Слышный is an adjective. The impersonal form is слышно."}},{"q":"Я тебе ___.","answer":"перезвоню","options":["перезвонить","перезвонишь","перезвоню","перезвонит"],"en":"I''ll call you back.","why":{"перезвонишь":"Перезвонишь is the ты form. With я use перезвоню.","перезвонит":"Перезвонит is the он/она form. With я use перезвоню.","перезвонить":"Перезвонить is the infinitive. With я use перезвоню."}}]}'::jsonb, 11, 6),
  ('a2-11', 'A2', 'grammar', 11, 'The past tense', 'Прошедшее время', 'Talk about what happened — and choose the masculine or feminine form.', '{"intro":"The Russian past tense is simple: one form per gender. It agrees with who did the action, so a man and a woman say \"I played\" differently.","sections":[{"type":"lines","kind":"phrases","title":"What happened","lines":[{"ru":"Вчера я играл в шахматы.","en":"Yesterday I played chess.","words":[{"ru":"Вчера","en":"yesterday"},{"ru":"я","en":"I"},{"ru":"играл","f":"играла","en":"played"},{"ru":"в","en":"(at)"},{"ru":"шахматы.","en":"chess"}],"ruF":"Вчера я играла в шахматы."},{"ru":"Он выиграл, а она проиграла.","en":"He won, and she lost.","words":[{"ru":"Он","en":"he"},{"ru":"выиграл,","en":"won"},{"ru":"а","en":"and"},{"ru":"она","en":"she"},{"ru":"проиграла.","en":"lost"}]},{"ru":"Мы играли весь вечер.","en":"We played all evening.","words":[{"ru":"Мы","en":"we"},{"ru":"играли","en":"played"},{"ru":"весь","en":"the whole"},{"ru":"вечер.","en":"evening"}]},{"ru":"Где ты был?","en":"Where were you?","words":[{"ru":"Где","en":"where"},{"ru":"ты","en":"you"},{"ru":"был?","f":"была?","en":"were"}],"ruF":"Где ты была?"},{"ru":"Я был в Москве.","en":"I was in Moscow.","words":[{"ru":"Я","en":"I"},{"ru":"был","f":"была","en":"was"},{"ru":"в","en":"in"},{"ru":"Москве.","en":"Moscow"}],"ruF":"Я была в Москве."},{"ru":"Было интересно!","en":"It was interesting!","words":[{"ru":"Было","en":"it was"},{"ru":"интересно!","en":"interesting"}]},{"ru":"Партия была длинной.","en":"The game was long.","words":[{"ru":"Партия","en":"the game"},{"ru":"была","en":"was"},{"ru":"длинной.","en":"long"}]},{"ru":"Кто выиграл?","en":"Who won?","words":[{"ru":"Кто","en":"who"},{"ru":"выиграл?","en":"won"}]},{"ru":"Я не видел этот фильм.","en":"I haven''t seen this film.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"видел","f":"видела","en":"saw"},{"ru":"этот","en":"this"},{"ru":"фильм.","en":"film"}],"ruF":"Я не видела этот фильм."}]},{"type":"grammar","title":"-л, -ла, -ло, -ли","paragraphs":["Remove **-ть** and add **-л** (masculine), **-ла** (feminine), **-ло** (neuter) or **-ли** (plural). The ending shows the gender of the subject, not the person: я играл (a man), я играла (a woman), ты играла (to a woman).","\"To be\" in the past: был, была, было, были. Note the stress: была́, but бы́ло, бы́ли."],"examples":[{"ru":"Он читал. Она читала. Они читали.","en":"He read. She read. They read."},{"ru":"Ты была дома?","en":"Were you at home? (to a woman)"}]}],"drills":[{"q":"Вчера она ___ в шахматы.","answer":"играла","options":["играло","играла","играл","играли"],"en":"Yesterday she played chess.","why":{"играл":"Играл is the past for он. With она use играла.","играли":"Играли is the plural past (мы, они). With она use играла.","играло":"Играло is the neuter past (оно). With она use играла."}},{"q":"Мы ___ весь вечер.","answer":"играли","options":["играла","играл","играем","играли"],"en":"We played all evening.","why":{"играл":"Играл is the past for он. Мы takes the plural: играли.","играла":"Играла is the past for она. Мы takes the plural: играли.","играем":"Играем is present (\"we play\"). This sentence is about the past: играли."}},{"q":"Где ты ___? (to a man)","answer":"был","options":["была","было","были","был"],"en":"Where were you?","why":{"была":"Была is the past for a woman. To a man: был.","было":"Было is the neuter past (оно). To a man: был.","были":"Были is plural (or polite вы). To a man, with ты: был."}},{"q":"Это ___ интересно!","answer":"было","options":["был","были","была","было"],"en":"That was interesting!","why":{"был":"Был is masculine. Это … интересно is impersonal, so use the neuter: было.","была":"Была is feminine. The impersonal form is было.","были":"Были is plural. The impersonal form is было."}}]}'::jsonb, 9, 8),
  ('a2-12', 'A2', 'grammar', 12, 'The future', 'Будущее время', 'Say what you will do — and meet verb aspect, the heart of Russian grammar.', '{"intro":"Russian has two futures. «Я буду играть» describes the activity; «я сыграю» promises a single completed game.","sections":[{"type":"lines","kind":"phrases","title":"Plans and promises","lines":[{"ru":"Завтра я буду работать.","en":"Tomorrow I''ll be working.","words":[{"ru":"Завтра","en":"tomorrow"},{"ru":"я","en":"I"},{"ru":"буду","en":"will"},{"ru":"работать.","en":"work"}]},{"ru":"Что ты будешь делать вечером?","en":"What will you do tonight?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"будешь","en":"will"},{"ru":"делать","en":"do"},{"ru":"вечером?","en":"tonight"}]},{"ru":"Я буду смотреть фильм.","en":"I''ll watch a movie.","words":[{"ru":"Я","en":"I"},{"ru":"буду","en":"will"},{"ru":"смотреть","en":"watch"},{"ru":"фильм.","en":"a film"}]},{"ru":"Я обязательно выиграю!","en":"I''ll definitely win!","words":[{"ru":"Я","en":"I"},{"ru":"обязательно","en":"definitely"},{"ru":"выиграю!","en":"will win"}]},{"ru":"Мы сыграем завтра.","en":"We''ll play tomorrow.","words":[{"ru":"Мы","en":"we"},{"ru":"сыграем","en":"will play"},{"ru":"завтра.","en":"tomorrow"}]},{"ru":"После работы я пойду домой.","en":"After work I''ll go home.","words":[{"ru":"После","en":"after"},{"ru":"работы","en":"work"},{"ru":"я","en":"I"},{"ru":"пойду","en":"will go"},{"ru":"домой.","en":"home"}]},{"ru":"Летом мы поедем на море.","en":"In summer we''ll go to the seaside.","words":[{"ru":"Летом","en":"in summer"},{"ru":"мы","en":"we"},{"ru":"поедем","en":"will go"},{"ru":"на","en":"to the"},{"ru":"море.","en":"sea"}]},{"ru":"Я позвоню тебе завтра.","en":"I''ll call you tomorrow.","words":[{"ru":"Я","en":"I"},{"ru":"позвоню","en":"will call"},{"ru":"тебе","en":"you"},{"ru":"завтра.","en":"tomorrow"}]},{"ru":"Скоро будет дождь.","en":"It''s going to rain soon.","words":[{"ru":"Скоро","en":"soon"},{"ru":"будет","en":"will be"},{"ru":"дождь.","en":"rain"}]}]},{"type":"grammar","title":"Two futures","paragraphs":["**Imperfective** verbs (process, repetition) form the future with **буду** + infinitive: я буду играть, ты будешь читать.","**Perfective** verbs (one complete result) simply conjugate: я сыграю, я выиграю, я позвоню, я сделаю.","Most verbs come in pairs: играть / сыграть, делать / сделать, звонить / позвонить, писать / написать."],"examples":[{"ru":"Я буду писать письмо весь вечер.","en":"I''ll be writing the letter all evening."},{"ru":"Я напишу письмо и пойду спать.","en":"I''ll write the letter and go to bed."}]}],"drills":[{"q":"Завтра я ___ работать.","answer":"буду","options":["был","будешь","будет","буду"],"en":"Tomorrow I''ll be working.","why":{"будешь":"Будешь is the ты form. With я use буду.","будет":"Будет is the он/она form. With я use буду.","был":"Был is past. Завтра (tomorrow) needs the future: буду."}},{"q":"Я обязательно ___! (win)","answer":"выиграю","options":["выиграть","выиграл","выиграю","выигрываю"],"en":"I''ll definitely win!","why":{"выигрываю":"Выигрываю is present (\"I''m winning, I usually win\"). One future win is выиграю.","выиграл":"Выиграл is past (\"I won\"). \"I''ll win\" is выиграю.","выиграть":"Выиграть is the infinitive. With я use выиграю."}},{"q":"Летом мы ___ на море.","answer":"поедем","options":["ездили","поехали","едем","поедем"],"en":"In summer we''ll go to the seaside.","why":{"едем":"Едем is present (\"we''re on our way\"). \"We''ll go in summer\" is поедем.","ездили":"Ездили is past (\"we went and came back\"). For the future: поедем.","поехали":"Поехали is past (or \"let''s go!\"). For the future: поедем."}},{"q":"Я ___ тебе завтра.","answer":"позвоню","options":["звонил","позвоню","позвонил","звоню"],"en":"I''ll call you tomorrow.","why":{"звоню":"Звоню is present (\"I''m calling\"). Завтра needs the future: позвоню.","позвонил":"Позвонил is past (\"I called\"). For the future: позвоню.","звонил":"Звонил is past. For the future: позвоню."}}]}'::jsonb, 9, 9),
  ('a2-13', 'A2', 'chess_talk', 13, 'Why that move?', 'Почему ты так сыграл?', 'Ask about a move, explain your plan and react to your opponent''s ideas.', '{"intro":"In chess Russian, the pieces are treated as living things: you protect \"короля\" and attack \"ферзя\". You''ll also meet свой — \"one''s own\".","sections":[{"type":"lines","kind":"dialogue","title":"After the game","lines":[{"ru":"Почему ты сделал этот ход?","en":"Why did you make that move?","words":[{"ru":"Почему","en":"why"},{"ru":"ты","en":"you"},{"ru":"сделал","en":"made"},{"ru":"этот","en":"this"},{"ru":"ход?","en":"move"}],"speaker":"Анна"},{"ru":"Я хочу защитить своего короля.","en":"I want to protect my king.","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"защитить","en":"to protect"},{"ru":"своего","en":"my own"},{"ru":"короля.","en":"king"}],"speaker":"Максим"},{"ru":"А почему не конём?","en":"And why not with the knight?","words":[{"ru":"А","en":"and"},{"ru":"почему","en":"why"},{"ru":"не","en":"not"},{"ru":"конём?","en":"with the knight"}],"speaker":"Анна"},{"ru":"Конь нужен для атаки.","en":"I need the knight for the attack.","words":[{"ru":"Конь","en":"the knight"},{"ru":"нужен","en":"is needed"},{"ru":"для","en":"for"},{"ru":"атаки.","en":"the attack"}],"speaker":"Максим"},{"ru":"Ты хочешь напасть на мою ладью?","en":"Do you want to attack my rook?","words":[{"ru":"Ты","en":"you"},{"ru":"хочешь","en":"want"},{"ru":"напасть","en":"to attack"},{"ru":"на","en":"on"},{"ru":"мою","en":"my"},{"ru":"ладью?","en":"rook"}],"speaker":"Анна"},{"ru":"Да, а потом поставить мат!","en":"Yes, and then give checkmate!","words":[{"ru":"Да,","en":"yes"},{"ru":"а","en":"and"},{"ru":"потом","en":"then"},{"ru":"поставить","en":"to give"},{"ru":"мат!","en":"mate"}],"speaker":"Максим"},{"ru":"Посмотрим!","en":"We''ll see!","words":[{"ru":"Посмотрим!","en":"we''ll see"}],"speaker":"Анна"}]},{"type":"lines","kind":"phrases","title":"Talking strategy","lines":[{"ru":"Мне кажется, это ошибка.","en":"I think that''s a mistake.","words":[{"ru":"Мне","en":"to me"},{"ru":"кажется,","en":"it seems"},{"ru":"это","en":"this"},{"ru":"ошибка.","en":"mistake"}]},{"ru":"Какой твой план?","en":"What''s your plan?","words":[{"ru":"Какой","en":"what"},{"ru":"твой","en":"your"},{"ru":"план?","en":"plan"}]},{"ru":"Я не видел этот ход.","en":"I didn''t see that move.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"видел","f":"видела","en":"saw"},{"ru":"этот","en":"this"},{"ru":"ход.","en":"move"}],"ruF":"Я не видела этот ход."},{"ru":"Хороший ход! Я не ожидал.","en":"Good move! I didn''t expect that.","words":[{"ru":"Хороший","en":"good"},{"ru":"ход!","en":"move"},{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"ожидал.","f":"ожидала.","en":"expected"}],"ruF":"Хороший ход! Я не ожидала."}]},{"type":"grammar","title":"Свой and \"living\" pieces","paragraphs":["**Свой** (\"one''s own\") refers back to the subject: я защищаю **своего** короля, она защищает **свою** ладью.","Masculine piece names take the animate accusative (like people): король → корол**я**, конь → кон**я**, слон → слон**а**, ферзь → ферз**я**. Feminine pieces change normally: пешк**у**, ладь**ю**."],"examples":[{"ru":"Я беру твоего ферзя.","en":"I''m taking your queen."},{"ru":"Она защищает свою пешку.","en":"She''s protecting her pawn."}]}],"drills":[{"q":"Я хочу защитить своего ___.","answer":"короля","options":["королю","короля","королём","король"],"en":"I want to protect my king.","why":{"король":"Защитить takes the accusative. Король is animate, so its accusative is короля (see своего).","королю":"Королю is the dative (\"to the king\"). The object of защитить is короля.","королём":"Королём is the instrumental. The object of защитить is короля."}},{"q":"Почему ты сделал этот ___?","answer":"ход","options":["ход","ходе","ходом","хода"],"en":"Why did you make that move?","why":{"хода":"Хода is the genitive. Сделать takes the accusative, which for ход is just ход.","ходом":"Ходом is the instrumental. The object of сделать is ход.","ходе":"Ходе is the prepositional. The object of сделать is ход."}},{"q":"Я беру твоего ___. (ферзь)","answer":"ферзя","options":["ферзь","ферзя","ферзю","ферзём"],"en":"I''m taking your queen.","why":{"ферзь":"Брать takes the accusative. Pieces count as animate, so it''s ферзя (see твоего).","ферзём":"Ферзём is the instrumental (ходить ферзём). Taking it: ферзя.","ферзю":"Ферзю is the dative. Taking it: ферзя."}},{"q":"Мне ___, это ошибка.","answer":"кажется","options":["казался","кажусь","казаться","кажется"],"en":"I think that''s a mistake.","why":{"кажусь":"Кажусь is \"I seem\". \"It seems to me\" is мне кажется.","казался":"Казался is past and masculine (\"seemed\"). Present, impersonal: кажется.","казаться":"Казаться is the infinitive. The phrase is мне кажется."}}]}'::jsonb, 11, 10),
  ('a2-14', 'A2', 'chess_vocab', 14, 'Moves and captures', 'Ходы и взятия', 'Describe how pieces move and capture, including castling and en passant.', '{"intro":"Russian chess vocabulary is precise: брать and бить both mean \"to capture\", and the knight moves \"like the letter Г\".","sections":[{"type":"lines","kind":"phrases","title":"How pieces move","lines":[{"ru":"Конь ходит буквой «Г».","en":"The knight moves in an L-shape.","words":[{"ru":"Конь","en":"the knight"},{"ru":"ходит","en":"moves"},{"ru":"буквой","en":"(like the) letter"},{"ru":"«Г».","en":"G"}],"note":"Russians describe the knight''s move as the letter Г."},{"ru":"Слон ходит по диагонали.","en":"The bishop moves diagonally.","words":[{"ru":"Слон","en":"the bishop"},{"ru":"ходит","en":"moves"},{"ru":"по","en":"along"},{"ru":"диагонали.","en":"the diagonal"}]},{"ru":"Ладья ходит по вертикали и горизонтали.","en":"The rook moves along files and ranks.","words":[{"ru":"Ладья","en":"the rook"},{"ru":"ходит","en":"moves"},{"ru":"по","en":"along"},{"ru":"вертикали","en":"files"},{"ru":"и","en":"and"},{"ru":"горизонтали.","en":"ranks"}]},{"ru":"Пешка бьёт наискосок.","en":"A pawn captures diagonally.","words":[{"ru":"Пешка","en":"a pawn"},{"ru":"бьёт","en":"captures"},{"ru":"наискосок.","en":"diagonally"}]},{"ru":"Я беру твоего слона.","en":"I''m taking your bishop.","words":[{"ru":"Я","en":"I"},{"ru":"беру","en":"am taking"},{"ru":"твоего","en":"your"},{"ru":"слона.","en":"bishop"}]},{"ru":"Он взял мою пешку.","en":"He took my pawn.","words":[{"ru":"Он","en":"he"},{"ru":"взял","en":"took"},{"ru":"мою","en":"my"},{"ru":"пешку.","en":"pawn"}]},{"ru":"Я сделал рокировку.","en":"I castled.","words":[{"ru":"Я","en":"I"},{"ru":"сделал","f":"сделала","en":"made"},{"ru":"рокировку.","en":"castling"}],"ruF":"Я сделала рокировку."},{"ru":"Ты поставил мне шах.","en":"You put me in check.","words":[{"ru":"Ты","en":"you"},{"ru":"поставил","f":"поставила","en":"gave"},{"ru":"мне","en":"me"},{"ru":"шах.","en":"check"}],"ruF":"Ты поставила мне шах."},{"ru":"Король не может ходить под шах.","en":"The king can''t move into check.","words":[{"ru":"Король","en":"the king"},{"ru":"не","en":"not"},{"ru":"может","en":"can"},{"ru":"ходить","en":"move"},{"ru":"под","en":"into"},{"ru":"шах.","en":"check"}]},{"ru":"Пешка превратилась в ферзя.","en":"The pawn became a queen.","words":[{"ru":"Пешка","en":"the pawn"},{"ru":"превратилась","en":"turned"},{"ru":"в","en":"into"},{"ru":"ферзя.","en":"a queen"}]},{"ru":"Это взятие на проходе.","en":"That''s en passant.","words":[{"ru":"Это","en":"this"},{"ru":"взятие","en":"capture"},{"ru":"на","en":"in"},{"ru":"проходе.","en":"passing"}]}]},{"type":"grammar","title":"Брать, взять, бить","paragraphs":["**Брать** (to take, imperfective): я беру, ты берёшь. **Взять** (perfective): я возьму; past взял, взяла.","**Бить** describes what a piece attacks or captures: пешка бьёт наискосок, слон бьёт по диагонали."],"examples":[{"ru":"Я возьму твою ладью.","en":"I''ll take your rook."},{"ru":"Этот слон бьёт всю диагональ.","en":"This bishop controls the whole diagonal."}]}],"drills":[{"q":"Я ___ твоего слона. (am taking)","answer":"беру","options":["берёшь","взять","брал","беру"],"en":"I''m taking your bishop.","why":{"брал":"Брал is past (\"I was taking\"). Right now: беру.","взять":"Взять is an infinitive. \"I''m taking\" is беру.","берёшь":"Берёшь is the ты form. With я use беру."}},{"q":"Он ___ мою пешку. (took)","answer":"взял","options":["берёт","брать","возьму","взял"],"en":"He took my pawn.","why":{"брать":"Брать is the infinitive. \"He took\" (done) is взял.","возьму":"Возьму is \"I''ll take\" (future, я). \"He took\" is взял.","берёт":"Берёт is present (\"he takes\"). Already done: взял."}},{"q":"Слон ходит по ___.","answer":"диагонали","options":["диагоналей","диагонали","диагональ","диагональю"],"en":"The bishop moves diagonally.","why":{"диагональ":"По (\"along\") takes the dative: по диагонали.","диагональю":"Диагональю is the instrumental. По needs диагонали.","диагоналей":"Диагоналей is the genitive plural. Along one diagonal: по диагонали."}},{"q":"Я сделал ___.","answer":"рокировку","options":["рокировка","рокировку","рокировки","рокировкой"],"en":"I castled.","why":{"рокировка":"Сделать takes the accusative: сделал рокировку.","рокировки":"Рокировки is the genitive or plural. The object is рокировку.","рокировкой":"Рокировкой is the instrumental. The object is рокировку."}}]}'::jsonb, 11, 12),
  ('a2-15', 'A2', 'smalltalk', 15, 'How was your weekend?', 'Как прошли выходные?', 'Tell the story of your weekend in the past tense — what you did, where you went and what you thought of it.', '{"intro":"Monday-morning small talk is the perfect place to practise the past tense. Notice how linking words — сначала, потом, хотя, честно говоря — turn short answers into real stories.","sections":[{"type":"lines","kind":"conversation","title":"Monday morning","lines":[{"ru":"Как прошли твои выходные?","en":"How was your weekend?","words":[{"ru":"Как","en":"how"},{"ru":"прошли","en":"went"},{"ru":"твои","en":"your"},{"ru":"выходные?","en":"weekend"}],"speaker":"Ира","role":"q","x":"a2-15:1"},{"ru":"Хорошо, но слишком быстро! Честно говоря, я бы хотел ещё один выходной.","en":"Good, but too short! To be honest, I''d like one more day off.","words":[{"ru":"Хорошо,","en":"good"},{"ru":"но","en":"but"},{"ru":"слишком","en":"too"},{"ru":"быстро!","en":"fast"},{"ru":"Честно","en":"honestly"},{"ru":"говоря,","en":"speaking"},{"ru":"я","en":"I"},{"ru":"бы","en":"would"},{"ru":"хотел","f":"хотела","en":"like"},{"ru":"ещё","en":"one more"},{"ru":"один","en":"one"},{"ru":"выходной.","en":"day off"}],"ruF":"Хорошо, но слишком быстро! Честно говоря, я бы хотела ещё один выходной.","speaker":"Алекс","note":"Выходные (the weekend) is plural, so the verb is plural: прошли. Честно говоря = to be honest. Я бы хотел (a woman: хотела) = I''d like — бы makes it \"would\".","follow":[{"ru":"Ты устал?","en":"Are you tired?","ruF":"Ты устала?"},{"ru":"Что ты делал в пятницу вечером?","en":"What did you do on Friday night?","ruF":"Что ты делала в пятницу вечером?"}],"role":"a","x":"a2-15:1"},{"ru":"А что ты делал на выходных?","en":"So what did you do at the weekend?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делал","f":"делала","en":"did"},{"ru":"на","en":"at"},{"ru":"выходных?","en":"weekend"}],"ruF":"А что ты делала на выходных?","speaker":"Ира","role":"q","x":"a2-15:2"},{"ru":"В субботу я ходил в спортзал, а вечером встретился с друзьями.","en":"On Saturday I went to the gym, and in the evening I met up with friends.","words":[{"ru":"В","en":"on"},{"ru":"субботу","en":"Saturday"},{"ru":"я","en":"I"},{"ru":"ходил","f":"ходила","en":"went"},{"ru":"в","en":"to"},{"ru":"спортзал,","en":"gym"},{"ru":"а","en":"and"},{"ru":"вечером","en":"in the evening"},{"ru":"встретился","f":"встретилась","en":"met"},{"ru":"с","en":"with"},{"ru":"друзьями.","en":"friends"}],"ruF":"В субботу я ходила в спортзал, а вечером встретилась с друзьями.","speaker":"Алекс","note":"Ходил (a woman: ходила) means \"went and came back\" — a round trip. Встретиться с + instrumental = to meet up with: с друзьями.","follow":[{"ru":"Ты давно знаешь этих друзей?","en":"Have you known these friends long?"},{"ru":"Вас было много?","en":"Were there a lot of you?"}],"role":"a","x":"a2-15:2"},{"ru":"Куда вы ходили с друзьями?","en":"Where did you go with your friends?","words":[{"ru":"Куда","en":"where to"},{"ru":"вы","en":"you"},{"ru":"ходили","en":"went"},{"ru":"с","en":"with"},{"ru":"друзьями?","en":"friends"}],"speaker":"Ира","role":"q","x":"a2-15:3"},{"ru":"Сначала мы поужинали в ресторане, а потом пошли в кино.","en":"First we had dinner at a restaurant, and then we went to the cinema.","words":[{"ru":"Сначала","en":"first"},{"ru":"мы","en":"we"},{"ru":"поужинали","en":"had dinner"},{"ru":"в","en":"at"},{"ru":"ресторане,","en":"restaurant"},{"ru":"а","en":"and"},{"ru":"потом","en":"then"},{"ru":"пошли","en":"went"},{"ru":"в","en":"to"},{"ru":"кино.","en":"cinema"}],"speaker":"Алекс","note":"Поужинали and пошли are completed, one-time actions in a sequence, so they''re perfective. Сначала… а потом… sets the order.","follow":[{"ru":"В каком ресторане вы были?","en":"Which restaurant were you at?"},{"ru":"Что вы ели?","en":"What did you eat?"}],"role":"a","x":"a2-15:3"},{"ru":"Какой фильм вы смотрели?","en":"What film did you see?","words":[{"ru":"Какой","en":"which"},{"ru":"фильм","en":"film"},{"ru":"вы","en":"you"},{"ru":"смотрели?","en":"watched"}],"speaker":"Ира","role":"q","x":"a2-15:4"},{"ru":"Новый боевик. На самом деле, мне он не очень понравился.","en":"A new action film. Actually, I didn''t really like it.","words":[{"ru":"Новый","en":"new"},{"ru":"боевик.","en":"action film"},{"ru":"На","en":"on"},{"ru":"самом","en":"very"},{"ru":"деле,","en":"matter"},{"ru":"мне","en":"to me"},{"ru":"он","en":"it"},{"ru":"не","en":"not"},{"ru":"очень","en":"very"},{"ru":"понравился.","en":"pleased"}],"speaker":"Алекс","note":"На самом деле = actually, in fact — it often brings in something unexpected. Понравился agrees with фильм: фильм мне понравился, книга мне понравилась.","follow":[{"ru":"Тебе нравятся боевики?","en":"Do you like action films?"},{"ru":"А друзьям понравилось?","en":"Did your friends like it?"}],"role":"a","x":"a2-15:4"},{"ru":"Почему он тебе не понравился?","en":"Why didn''t you like it?","words":[{"ru":"Почему","en":"why"},{"ru":"он","en":"it"},{"ru":"тебе","en":"to you"},{"ru":"не","en":"not"},{"ru":"понравился?","en":"pleased"}],"speaker":"Ира","role":"q","x":"a2-15:5"},{"ru":"Потому что сюжет был скучный, хотя актёры играли хорошо.","en":"Because the plot was boring, although the actors were good.","words":[{"ru":"Потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"сюжет","en":"plot"},{"ru":"был","en":"was"},{"ru":"скучный,","en":"boring"},{"ru":"хотя","en":"although"},{"ru":"актёры","en":"actors"},{"ru":"играли","en":"played"},{"ru":"хорошо.","en":"well"}],"speaker":"Алекс","note":"Хотя = although: it adds the other side of the story. Актёры играли хорошо — actors \"play\" roles in Russian.","follow":[{"ru":"Какой твой любимый фильм?","en":"What''s your favourite film?","link":"a1-19:4","linkTopic":"Getting to know you","linkLevel":"A1"},{"ru":"Какие фильмы тебе нравятся?","en":"What kind of films do you like?"}],"role":"a","x":"a2-15:5"},{"ru":"А что ты делал в воскресенье?","en":"And what did you do on Sunday?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делал","f":"делала","en":"did"},{"ru":"в","en":"on"},{"ru":"воскресенье?","en":"Sunday"}],"ruF":"А что ты делала в воскресенье?","speaker":"Ира","role":"q","x":"a2-15:6"},{"ru":"В воскресенье я отдыхал дома: убирал квартиру, читал и рано лёг спать.","en":"On Sunday I rested at home: I cleaned the apartment, read, and went to bed early.","words":[{"ru":"В","en":"on"},{"ru":"воскресенье","en":"Sunday"},{"ru":"я","en":"I"},{"ru":"отдыхал","f":"отдыхала","en":"rested"},{"ru":"дома:","en":"at home"},{"ru":"убирал","f":"убирала","en":"cleaned"},{"ru":"квартиру,","en":"apartment"},{"ru":"читал","f":"читала","en":"read"},{"ru":"и","en":"and"},{"ru":"рано","en":"early"},{"ru":"лёг","f":"легла","en":"lay down"},{"ru":"спать.","en":"to sleep"}],"ruF":"В воскресенье я отдыхала дома: убирала квартиру, читала и рано легла спать.","speaker":"Алекс","note":"The imperfective past (отдыхал, убирал, читал) describes how the time was spent. Лёг (a woman: легла) спать = went to bed.","follow":[{"ru":"Ты любишь убирать?","en":"Do you like cleaning?"},{"ru":"Что ты сейчас читаешь?","en":"What are you reading at the moment?"}],"role":"a","x":"a2-15:6"},{"ru":"Ты хорошо отдохнул?","en":"Did you get a good rest?","words":[{"ru":"Ты","en":"you"},{"ru":"хорошо","en":"well"},{"ru":"отдохнул?","f":"отдохнула?","en":"rested"}],"ruF":"Ты хорошо отдохнула?","speaker":"Ира","role":"q","x":"a2-15:7"},{"ru":"В общем, да. Я готов к новой неделе!","en":"All in all, yes. I''m ready for a new week!","words":[{"ru":"В","en":"in"},{"ru":"общем,","en":"general"},{"ru":"да.","en":"yes"},{"ru":"Я","en":"I"},{"ru":"готов","f":"готова","en":"ready"},{"ru":"к","en":"for"},{"ru":"новой","en":"new"},{"ru":"неделе!","en":"week"}],"ruF":"В общем, да. Я готова к новой неделе!","speaker":"Алекс","note":"В общем = all in all, basically — use it to sum up. Готов (a woman: готова) к + dative = ready for: к новой неделе.","follow":[{"ru":"Какие у тебя планы на эту неделю?","en":"What are your plans for this week?"},{"ru":"Хочешь кофе?","en":"Do you want some coffee?"}],"role":"a","x":"a2-15:7"}]},{"type":"grammar","title":"Finished or not? Поужинали or ужинали","paragraphs":["Most Russian verbs come in pairs. The **perfective** (поужинать, посмотреть, пойти) is for one completed action — especially actions in a sequence: Мы поужинали, а потом пошли в кино.","The **imperfective** (ужинать, смотреть, читать) describes an activity or how time was spent, without focusing on the result: В воскресенье я отдыхал, читал, убирал квартиру."],"examples":[{"ru":"Вчера я смотрел телевизор.","en":"Yesterday I watched TV (for a while)."},{"ru":"Вчера я посмотрел новый фильм.","en":"Yesterday I watched a new film (start to finish)."}]},{"type":"grammar","title":"Linking words: на самом деле, хотя, честно говоря, в общем","paragraphs":["**На самом деле** (actually) corrects or surprises. **Хотя** (although) adds the other side. **Честно говоря** (to be honest) softens an opinion. **В общем** (all in all) sums up."],"examples":[{"ru":"На самом деле, я не люблю боевики.","en":"Actually, I don''t like action films."},{"ru":"Было скучно, хотя актёры хорошие.","en":"It was boring, although the actors are good."},{"ru":"В общем, всё было хорошо.","en":"All in all, everything was fine."}]}],"drills":[{"q":"Сначала мы ___ в ресторане, а потом пошли в кино.","answer":"поужинали","options":["поужинали","ужинаем","поужинаем","ужинать"],"en":"First we had dinner at a restaurant, then went to the cinema.","why":{"ужинаем":"Ужинаем is the present tense. The story is about Saturday: поужинали.","поужинаем":"Поужинаем is the future (\"we''ll have dinner\"). This already happened: поужинали.","ужинать":"Ужинать is the infinitive. After мы you need the past form: поужинали."}},{"q":"Сюжет был скучный, ___ актёры играли хорошо.","answer":"хотя","options":["поэтому","если","потому что","хотя"],"en":"The plot was boring, although the actors were good.","why":{"потому что":"Потому что gives a reason, but good acting isn''t why the plot was boring. The two parts contrast: хотя.","поэтому":"Поэтому means \"so, that''s why\" — a result. Here the two parts contrast: хотя.","если":"Если means \"if\". The actors really did play well, so use хотя (although)."}},{"q":"Фильм мне не ___.","answer":"понравился","options":["понравились","понравилась","понравился","понравилось"],"en":"I didn''t like the film.","why":{"понравилась":"Понравилась agrees with a feminine noun (книга). Фильм is masculine: понравился.","понравилось":"Понравилось is neuter (кино мне понравилось). Фильм is masculine: понравился.","понравились":"Понравились is plural. One фильм: понравился."}}]}'::jsonb, 14, 12),
  ('a2-16', 'A2', 'travel', 16, 'Travel stories', 'Путешествия', 'Talk about places you''ve been, your last trip, what you liked and where you dream of going.', '{"intro":"Travel stories are full of past and future: where you''ve been, and where you''ll go next. Notice кроме того, хотя and если — they make your answers longer and more natural.","sections":[{"type":"lines","kind":"conversation","title":"Travel talk","lines":[{"ru":"Ты когда-нибудь был в Европе?","en":"Have you ever been to Europe?","words":[{"ru":"Ты","en":"you"},{"ru":"когда-нибудь","en":"ever"},{"ru":"был","f":"была","en":"been"},{"ru":"в","en":"in"},{"ru":"Европе?","en":"Europe"}],"ruF":"Ты когда-нибудь была в Европе?","speaker":"Максим","role":"q","x":"a2-16:1"},{"ru":"Да, я был в Германии и хотел бы посетить ещё несколько стран.","en":"Yes, I''ve been to Germany, and I''d like to visit a few more countries.","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"был","f":"была","en":"was"},{"ru":"в","en":"in"},{"ru":"Германии","en":"Germany"},{"ru":"и","en":"and"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"посетить","en":"to visit"},{"ru":"ещё","en":"more"},{"ru":"несколько","en":"several"},{"ru":"стран.","en":"countries"}],"ruF":"Да, я была в Германии и хотела бы посетить ещё несколько стран.","speaker":"Алекс","note":"\"Have been to\" a place: был в + prepositional (в Германии). Несколько + genitive plural: несколько стран.","follow":[{"ru":"Что тебе понравилось в Германии?","en":"What did you like in Germany?"},{"ru":"В какие страны ты хочешь поехать?","en":"Which countries do you want to go to?"}],"role":"a","x":"a2-16:1"},{"ru":"Когда ты в последний раз путешествовал?","en":"When did you last travel?","words":[{"ru":"Когда","en":"when"},{"ru":"ты","en":"you"},{"ru":"в","en":"(the)"},{"ru":"последний","en":"last"},{"ru":"раз","en":"time"},{"ru":"путешествовал?","f":"путешествовала?","en":"travelled"}],"ruF":"Когда ты в последний раз путешествовала?","speaker":"Максим","role":"q","x":"a2-16:2"},{"ru":"Несколько месяцев назад, когда я ездил в другой город.","en":"A few months ago, when I went to another city.","words":[{"ru":"Несколько","en":"several"},{"ru":"месяцев","en":"months"},{"ru":"назад,","en":"ago"},{"ru":"когда","en":"when"},{"ru":"я","en":"I"},{"ru":"ездил","f":"ездила","en":"went"},{"ru":"в","en":"to"},{"ru":"другой","en":"another"},{"ru":"город.","en":"city"}],"ruF":"Несколько месяцев назад, когда я ездила в другой город.","speaker":"Алекс","note":"Назад = ago, after the time: месяц назад, несколько месяцев назад. Ездил (a woman: ездила) = went there and back by transport.","follow":[{"ru":"Ты ездил один?","en":"Did you go alone?","ruF":"Ты ездила одна?"},{"ru":"Ты летел или ехал на машине?","en":"Did you fly or drive?","ruF":"Ты летела или ехала на машине?"}],"role":"a","x":"a2-16:2"},{"ru":"В какой город?","en":"Which city?","words":[{"ru":"В","en":"to"},{"ru":"какой","en":"which"},{"ru":"город?","en":"city"}],"speaker":"Максим","role":"q","x":"a2-16:3"},{"ru":"В Нью-Йорк. Я был там в первый раз.","en":"New York. It was my first time there.","words":[{"ru":"В","en":"to"},{"ru":"Нью-Йорк.","en":"New York"},{"ru":"Я","en":"I"},{"ru":"был","f":"была","en":"was"},{"ru":"там","en":"there"},{"ru":"в","en":"for"},{"ru":"первый","en":"first"},{"ru":"раз.","en":"time"}],"ruF":"В Нью-Йорк. Я была там в первый раз.","speaker":"Алекс","note":"В первый раз = for the first time. Нью-Йорк doesn''t change after в when you''re going somewhere (the accusative looks like the dictionary form).","follow":[{"ru":"Сколько дней ты там был?","en":"How many days were you there?","ruF":"Сколько дней ты там была?"},{"ru":"Где ты жил?","en":"Where did you stay?","ruF":"Где ты жила?"}],"role":"a","x":"a2-16:3"},{"ru":"Что тебе больше всего понравилось?","en":"What did you like most?","words":[{"ru":"Что","en":"what"},{"ru":"тебе","en":"to you"},{"ru":"больше","en":"more"},{"ru":"всего","en":"of all"},{"ru":"понравилось?","en":"pleased"}],"speaker":"Максим","role":"q","x":"a2-16:4"},{"ru":"Больше всего мне понравились музеи. Кроме того, там очень вкусная еда.","en":"I liked the museums most. Besides that, the food there is really good.","words":[{"ru":"Больше","en":"more"},{"ru":"всего","en":"of all"},{"ru":"мне","en":"to me"},{"ru":"понравились","en":"pleased"},{"ru":"музеи.","en":"museums"},{"ru":"Кроме","en":"besides"},{"ru":"того,","en":"that"},{"ru":"там","en":"there"},{"ru":"очень","en":"very"},{"ru":"вкусная","en":"tasty"},{"ru":"еда.","en":"food"}],"speaker":"Алекс","note":"Больше всего = most of all. Кроме того (besides, also) adds one more point to what you''ve said.","follow":[{"ru":"В каком музее ты был?","en":"Which museum did you go to?","ruF":"В каком музее ты была?"},{"ru":"Что ты там ел?","en":"What did you eat there?","ruF":"Что ты там ела?"}],"role":"a","x":"a2-16:4"},{"ru":"Ты любишь путешествовать один?","en":"Do you like travelling alone?","words":[{"ru":"Ты","en":"you"},{"ru":"любишь","en":"like"},{"ru":"путешествовать","en":"to travel"},{"ru":"один?","f":"одна?","en":"alone"}],"ruF":"Ты любишь путешествовать одна?","speaker":"Максим","role":"q","x":"a2-16:5"},{"ru":"Не очень. Обычно я езжу с друзьями, потому что так веселее. Хотя иногда хочется побыть одному.","en":"Not really. I usually go with friends, because it''s more fun that way. Although sometimes I feel like being on my own.","words":[{"ru":"Не","en":"not"},{"ru":"очень.","en":"very"},{"ru":"Обычно","en":"usually"},{"ru":"я","en":"I"},{"ru":"езжу","en":"go"},{"ru":"с","en":"with"},{"ru":"друзьями,","en":"friends"},{"ru":"потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"так","en":"that way"},{"ru":"веселее.","en":"more fun"},{"ru":"Хотя","en":"although"},{"ru":"иногда","en":"sometimes"},{"ru":"хочется","en":"one feels like"},{"ru":"побыть","en":"to be"},{"ru":"одному.","f":"одной.","en":"alone"}],"ruF":"Не очень. Обычно я езжу с друзьями, потому что так веселее. Хотя иногда хочется побыть одной.","speaker":"Алекс","note":"Веселее = more fun (comparative of весело). Хочется + infinitive = I feel like… Одному (a woman: одной) is the dative after побыть.","follow":[{"ru":"С кем ты обычно путешествуешь?","en":"Who do you usually travel with?"},{"ru":"Ты любишь большие компании?","en":"Do you like big groups?"}],"role":"a","x":"a2-16:5"},{"ru":"Куда ты хочешь поехать в следующий раз?","en":"Where do you want to go next time?","words":[{"ru":"Куда","en":"where to"},{"ru":"ты","en":"you"},{"ru":"хочешь","en":"want"},{"ru":"поехать","en":"to go"},{"ru":"в","en":"(the)"},{"ru":"следующий","en":"next"},{"ru":"раз?","en":"time"}],"speaker":"Максим","role":"q","x":"a2-16:6"},{"ru":"Я мечтаю поехать в Россию. Если получится, поеду летом.","en":"I dream of going to Russia. If it works out, I''ll go in the summer.","words":[{"ru":"Я","en":"I"},{"ru":"мечтаю","en":"dream"},{"ru":"поехать","en":"to go"},{"ru":"в","en":"to"},{"ru":"Россию.","en":"Russia"},{"ru":"Если","en":"if"},{"ru":"получится,","en":"it works out"},{"ru":"поеду","en":"will go"},{"ru":"летом.","en":"in summer"}],"speaker":"Алекс","note":"Если получится = if it works out — a very common phrase. Поеду (I''ll go) is the perfective future. Летом = in summer.","follow":[{"ru":"Какой город ты хочешь увидеть?","en":"Which city do you want to see?"},{"ru":"Тебе нужна виза?","en":"Do you need a visa?"}],"role":"a","x":"a2-16:6"},{"ru":"Ты уже готовишься к поездке?","en":"Are you already getting ready for the trip?","words":[{"ru":"Ты","en":"you"},{"ru":"уже","en":"already"},{"ru":"готовишься","en":"prepare"},{"ru":"к","en":"for"},{"ru":"поездке?","en":"trip"}],"speaker":"Максим","role":"q","x":"a2-16:7"},{"ru":"Да, я учу русский каждый день. Кстати, это одна из причин, почему я учу язык!","en":"Yes, I study Russian every day. By the way, that''s one of the reasons I''m learning the language!","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"учу","en":"learn"},{"ru":"русский","en":"Russian"},{"ru":"каждый","en":"every"},{"ru":"день.","en":"day"},{"ru":"Кстати,","en":"by the way"},{"ru":"это","en":"this"},{"ru":"одна","en":"one"},{"ru":"из","en":"of"},{"ru":"причин,","en":"reasons"},{"ru":"почему","en":"why"},{"ru":"я","en":"I"},{"ru":"учу","en":"learn"},{"ru":"язык!","en":"language"}],"speaker":"Алекс","note":"Готовиться к + dative = to prepare for: к поездке, к экзамену. Одна из причин = one of the reasons (из + genitive plural).","follow":[{"ru":"Почему ты учишь русский?","en":"Why are you learning Russian?"},{"ru":"Что ещё тебе нужно сделать до поездки?","en":"What else do you need to do before the trip?"}],"role":"a","x":"a2-16:7"}]},{"type":"grammar","title":"Have you ever been…? — был в…, ездил в…","paragraphs":["\"Have you ever been to…?\" is simply the past of быть + в + prepositional: Ты когда-нибудь был в Европе? — Да, я был в Германии.","**Ездил / ходил** + в + accusative tells about a round trip: Я ездил в Нью-Йорк (I went to New York and came back)."],"examples":[{"ru":"Я был в Москве два раза.","en":"I''ve been to Moscow twice."},{"ru":"Летом я ездил к родителям.","en":"In the summer I went to see my parents."}]},{"type":"grammar","title":"Linking words: кроме того, хотя, если","paragraphs":["**Кроме того** (besides, also) adds another point. **Хотя** (although) adds a contrast, even at the start of a sentence in speech. **Если** (if) + the future describes a possible plan: Если получится, поеду летом."],"examples":[{"ru":"Там красиво. Кроме того, недорого.","en":"It''s beautiful there. Besides, it''s not expensive."},{"ru":"Если будет время, я тебе позвоню.","en":"If I have time, I''ll call you."}]}],"drills":[{"q":"Я был в ___.","answer":"Германии","options":["Германия","Германией","Германии","Германию"],"en":"I''ve been to Germany.","why":{"Германию":"Германию is for movement (поехать в Германию). \"Been in\" takes the prepositional: в Германии.","Германия":"After в you need a case ending. With был: в Германии.","Германией":"Германией is the instrumental. After был в use the prepositional: в Германии."}},{"q":"Я ездил в Нью-Йорк три месяца ___.","answer":"назад","options":["после","назад","потом","через"],"en":"I went to New York three months ago.","why":{"после":"После needs a noun after it (после работы). \"Ago\" is назад, after the time.","потом":"Потом means \"then, afterwards\". \"Ago\" is назад.","через":"Через means \"in\" — from now into the future: через три месяца = in three months. For the past use назад."}},{"q":"Если ___, я поеду летом.","answer":"получится","options":["получить","получилось","получается","получится"],"en":"If it works out, I''ll go in the summer.","why":{"получилось":"Получилось is the past. With a future plan (поеду), если takes the future: получится.","получается":"Получается is the present. For the summer ahead, use the future: получится.","получить":"Получить is the infinitive (\"to receive\"). \"If it works out\" is если получится."}}]}'::jsonb, 14, 15),
  ('a2-17', 'A2', 'friends', 17, 'What''s new?', 'Что нового?', 'Catch up with an old friend: a new job, a first day, yesterday evening and when to meet.', '{"intro":"Catching up means telling a lot in a little time. Weigh both sides with с одной стороны… с другой стороны, and order events with сначала and после этого.","sections":[{"type":"lines","kind":"conversation","title":"Catching up","lines":[{"ru":"Что интересного произошло на этой неделе?","en":"What interesting things happened this week?","words":[{"ru":"Что","en":"what"},{"ru":"интересного","en":"interesting"},{"ru":"произошло","en":"happened"},{"ru":"на","en":"this"},{"ru":"этой","en":"this"},{"ru":"неделе?","en":"week"}],"speaker":"Наташа","role":"q","x":"a2-17:1"},{"ru":"На этой неделе я начал новую работу и познакомился с интересными людьми.","en":"This week I started a new job and met some interesting people.","words":[{"ru":"На","en":"this"},{"ru":"этой","en":"this"},{"ru":"неделе","en":"week"},{"ru":"я","en":"I"},{"ru":"начал","f":"начала","en":"started"},{"ru":"новую","en":"new"},{"ru":"работу","en":"job"},{"ru":"и","en":"and"},{"ru":"познакомился","f":"познакомилась","en":"met"},{"ru":"с","en":"with"},{"ru":"интересными","en":"interesting"},{"ru":"людьми.","en":"people"}],"ruF":"На этой неделе я начала новую работу и познакомилась с интересными людьми.","speaker":"Алекс","note":"Что интересного? — что + an adjective in the genitive: что нового? что интересного? Познакомиться с + instrumental = to meet someone for the first time.","follow":[{"ru":"С кем ты познакомился?","en":"Who did you meet?","ruF":"С кем ты познакомилась?"},{"ru":"Как тебе коллеги?","en":"How do you like your colleagues?"}],"role":"a","x":"a2-17:1"},{"ru":"Правда? Где ты теперь работаешь?","en":"Really? Where are you working now?","words":[{"ru":"Правда?","en":"really"},{"ru":"Где","en":"where"},{"ru":"ты","en":"you"},{"ru":"теперь","en":"now"},{"ru":"работаешь?","en":"work"}],"speaker":"Наташа","role":"q","x":"a2-17:2"},{"ru":"В автосалоне. Я продаю машины.","en":"At a car dealership. I sell cars.","words":[{"ru":"В","en":"at"},{"ru":"автосалоне.","en":"car dealership"},{"ru":"Я","en":"I"},{"ru":"продаю","en":"sell"},{"ru":"машины.","en":"cars"}],"speaker":"Алекс","note":"Автосалон = car dealership: в автосалоне. Продавать: я продаю, ты продаёшь.","follow":[{"ru":"Ты разбираешься в машинах?","en":"Do you know a lot about cars?"},{"ru":"Ты ушёл из мебельного магазина?","en":"Did you leave the furniture store?","ruF":"Ты ушла из мебельного магазина?"}],"role":"a","x":"a2-17:2"},{"ru":"И как тебе там?","en":"And how do you like it there?","words":[{"ru":"И","en":"and"},{"ru":"как","en":"how"},{"ru":"тебе","en":"to you"},{"ru":"там?","en":"there"}],"speaker":"Наташа","role":"q","x":"a2-17:3"},{"ru":"Пока нравится. С одной стороны, много нового, а с другой стороны, коллеги очень помогают.","en":"I like it so far. On the one hand, there''s a lot that''s new, but on the other hand, my colleagues help a lot.","words":[{"ru":"Пока","en":"so far"},{"ru":"нравится.","en":"pleases"},{"ru":"С","en":"from"},{"ru":"одной","en":"one"},{"ru":"стороны,","en":"side"},{"ru":"много","en":"a lot"},{"ru":"нового,","en":"new"},{"ru":"а","en":"and"},{"ru":"с","en":"from"},{"ru":"другой","en":"other"},{"ru":"стороны,","en":"side"},{"ru":"коллеги","en":"colleagues"},{"ru":"очень","en":"a lot"},{"ru":"помогают.","en":"help"}],"speaker":"Алекс","note":"Как тебе…? is a short, friendly \"how do you find…?\". С одной стороны… с другой стороны… weighs up two sides.","follow":[{"ru":"Тебе нравится твой начальник?","en":"Do you like your boss?"},{"ru":"Что самое сложное в твоей работе?","en":"What''s the hardest thing about your job?","link":"a2-21:2","linkTopic":"Talking about work","linkLevel":"A2"}],"role":"a","x":"a2-17:3"},{"ru":"Тебе было трудно в первый день?","en":"Was it hard on your first day?","words":[{"ru":"Тебе","en":"to you"},{"ru":"было","en":"was"},{"ru":"трудно","en":"hard"},{"ru":"в","en":"on"},{"ru":"первый","en":"first"},{"ru":"день?","en":"day"}],"speaker":"Наташа","role":"q","x":"a2-17:4"},{"ru":"Да, немного. Сначала я ничего не понимал, но после этого стало легче.","en":"Yes, a little. At first I didn''t understand anything, but after that it got easier.","words":[{"ru":"Да,","en":"yes"},{"ru":"немного.","en":"a little"},{"ru":"Сначала","en":"at first"},{"ru":"я","en":"I"},{"ru":"ничего","en":"nothing"},{"ru":"не","en":"not"},{"ru":"понимал,","f":"понимала,","en":"understood"},{"ru":"но","en":"but"},{"ru":"после","en":"after"},{"ru":"этого","en":"that"},{"ru":"стало","en":"it became"},{"ru":"легче.","en":"easier"}],"ruF":"Да, немного. Сначала я ничего не понимала, но после этого стало легче.","speaker":"Алекс","note":"Мне было трудно = it was hard for me (dative + было). Стало легче = it got easier. Ничего не понимал — a double negative is normal in Russian.","follow":[{"ru":"Кто тебе помогал?","en":"Who helped you?"},{"ru":"Что было самым трудным?","en":"What was the hardest part?"}],"role":"a","x":"a2-17:4"},{"ru":"Что ты делал вчера после работы?","en":"What did you do yesterday after work?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"делал","f":"делала","en":"did"},{"ru":"вчера","en":"yesterday"},{"ru":"после","en":"after"},{"ru":"работы?","en":"work"}],"ruF":"Что ты делала вчера после работы?","speaker":"Наташа","role":"q","x":"a2-17:5"},{"ru":"Сначала я поужинал, потом немного погулял и посмотрел фильм.","en":"First I had dinner, then went for a short walk and watched a film.","words":[{"ru":"Сначала","en":"first"},{"ru":"я","en":"I"},{"ru":"поужинал,","f":"поужинала,","en":"had dinner"},{"ru":"потом","en":"then"},{"ru":"немного","en":"a little"},{"ru":"погулял","f":"погуляла","en":"walked"},{"ru":"и","en":"and"},{"ru":"посмотрел","f":"посмотрела","en":"watched"},{"ru":"фильм.","en":"film"}],"ruF":"Сначала я поужинала, потом немного погуляла и посмотрела фильм.","speaker":"Алекс","note":"A chain of completed actions uses the perfective past: поужинал, погулял, посмотрел. Немного погулять = to go for a short walk.","follow":[{"ru":"Какой фильм ты посмотрел?","en":"Which film did you watch?","ruF":"Какой фильм ты посмотрела?"},{"ru":"Где ты гулял?","en":"Where did you walk?","ruF":"Где ты гуляла?"}],"role":"a","x":"a2-17:5"},{"ru":"Ты устаёшь после работы?","en":"Do you get tired after work?","words":[{"ru":"Ты","en":"you"},{"ru":"устаёшь","en":"get tired"},{"ru":"после","en":"after"},{"ru":"работы?","en":"work"}],"speaker":"Наташа","role":"q","x":"a2-17:6"},{"ru":"Иногда, но я стараюсь каждый день гулять, потому что это помогает отдохнуть.","en":"Sometimes, but I try to go for a walk every day, because it helps me unwind.","words":[{"ru":"Иногда,","en":"sometimes"},{"ru":"но","en":"but"},{"ru":"я","en":"I"},{"ru":"стараюсь","en":"try"},{"ru":"каждый","en":"every"},{"ru":"день","en":"day"},{"ru":"гулять,","en":"to walk"},{"ru":"потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"это","en":"it"},{"ru":"помогает","en":"helps"},{"ru":"отдохнуть.","en":"to rest"}],"speaker":"Алекс","note":"Стараться + infinitive = to try to. Помогать + infinitive: это помогает отдохнуть.","follow":[{"ru":"Как ты отдыхаешь?","en":"How do you relax?","link":"a1-19:2","linkTopic":"Getting to know you","linkLevel":"A1"},{"ru":"Ты высыпаешься?","en":"Do you get enough sleep?"}],"role":"a","x":"a2-17:6"},{"ru":"Когда мы увидимся?","en":"When shall we meet up?","words":[{"ru":"Когда","en":"when"},{"ru":"мы","en":"we"},{"ru":"увидимся?","en":"will see each other"}],"speaker":"Наташа","role":"q","x":"a2-17:7"},{"ru":"Давай в субботу! Если ты свободна, можем вместе пообедать.","en":"Let''s do Saturday! If you''re free, we can have lunch together.","words":[{"ru":"Давай","en":"let''s"},{"ru":"в","en":"on"},{"ru":"субботу!","en":"Saturday"},{"ru":"Если","en":"if"},{"ru":"ты","en":"you"},{"ru":"свободна,","en":"free"},{"ru":"можем","en":"we can"},{"ru":"вместе","en":"together"},{"ru":"пообедать.","en":"have lunch"}],"speaker":"Алекс","note":"Увидимся (we''ll see each other) is the perfective future. Наташа is a woman, so: если ты свободна.","follow":[{"ru":"Где встретимся?","en":"Where shall we meet?"},{"ru":"Во сколько тебе удобно?","en":"What time suits you?"}],"role":"a","x":"a2-17:7"}]},{"type":"grammar","title":"Что нового? Что интересного?","paragraphs":["After **что** in questions like these, the adjective goes into the genitive (-ого): Что нового? (What''s new?) Что интересного? Что случилось плохого? The answer often starts with На этой неделе… or Ничего особенного (nothing special)."],"examples":[{"ru":"Что нового? — Ничего особенного.","en":"What''s new? — Nothing special."},{"ru":"Что интересного было на работе?","en":"Anything interesting at work?"}]},{"type":"grammar","title":"Weighing two sides","paragraphs":["**С одной стороны… а с другой стороны…** (on the one hand… on the other hand…) shows you''ve thought about both sides. **После этого** (after that) moves a story forward."],"examples":[{"ru":"С одной стороны, работа трудная, а с другой стороны, интересная.","en":"On the one hand the job is hard, but on the other hand it''s interesting."},{"ru":"Сначала было трудно, но после этого стало легче.","en":"At first it was hard, but after that it got easier."}]}],"drills":[{"q":"Что ___ произошло на этой неделе?","answer":"интересного","options":["интересное","интересный","интересно","интересного"],"en":"What interesting things happened this week?","why":{"интересное":"After что in this kind of question, the adjective goes into the genitive: что интересного.","интересный":"Интересный is the masculine dictionary form. \"Что интересного?\" uses the genitive -ого.","интересно":"Интересно is an adverb (\"it''s interesting\"). The question is что интересного?"}},{"q":"Я познакомился с интересными ___.","answer":"людьми","options":["людей","люди","людьми","людям"],"en":"I met some interesting people.","why":{"люди":"After с (with) use the instrumental: с людьми.","людей":"Людей is the genitive or accusative. С (with) takes the instrumental: людьми.","людям":"Людям is the dative. С (with) takes the instrumental: людьми."}},{"q":"С одной стороны, много нового, а с ___ стороны, коллеги помогают.","answer":"другой","options":["другого","другой","другая","другую"],"en":"On the one hand there''s a lot that''s new; on the other, my colleagues help.","why":{"другая":"The phrase is с другой стороны — с + genitive, feminine ending -ой.","другую":"Другую is the accusative. The fixed phrase is с другой стороны.","другого":"Другого is masculine. Сторона is feminine: с другой стороны."}}]}'::jsonb, 14, 11),
  ('a2-18', 'A2', 'opinions', 18, 'What do you think?', 'Что ты думаешь?', 'Give your opinion, explain why, compare big cities and small towns, and talk about what matters to you.', '{"intro":"Opinions turn small talk into a real conversation. Мне кажется, потому что and с другой стороны help you say what you think — and why.","sections":[{"type":"lines","kind":"conversation","title":"A good discussion","lines":[{"ru":"Я хочу открыть шахматный клуб. Что ты думаешь об этом?","en":"I want to open a chess club. What do you think about it?","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"открыть","en":"to open"},{"ru":"шахматный","en":"chess"},{"ru":"клуб.","en":"club"},{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"думаешь","en":"think"},{"ru":"об","en":"about"},{"ru":"этом?","en":"this"}],"speaker":"Олег","role":"q","x":"a2-18:1"},{"ru":"Мне кажется, это хорошая идея, но я хотел бы сначала всё обдумать.","en":"I think it''s a good idea, but I''d like to think it all over first.","words":[{"ru":"Мне","en":"to me"},{"ru":"кажется,","en":"seems"},{"ru":"это","en":"this"},{"ru":"хорошая","en":"good"},{"ru":"идея,","en":"idea"},{"ru":"но","en":"but"},{"ru":"я","en":"I"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"сначала","en":"first"},{"ru":"всё","en":"everything"},{"ru":"обдумать.","en":"think over"}],"ruF":"Мне кажется, это хорошая идея, но я хотела бы сначала всё обдумать.","speaker":"Алекс","note":"Мне кажется = it seems to me, I think — softer than я думаю. Об этом = about this: о becomes об before a vowel.","follow":[{"ru":"Где ты хочешь его открыть?","en":"Where do you want to open it?"},{"ru":"Тебе нужна помощь?","en":"Do you need help?"}],"role":"a","x":"a2-18:1"},{"ru":"Почему ты сомневаешься?","en":"Why are you unsure?","words":[{"ru":"Почему","en":"why"},{"ru":"ты","en":"you"},{"ru":"сомневаешься?","en":"doubt"}],"speaker":"Олег","role":"q","x":"a2-18:2"},{"ru":"Потому что это дорого. Но с другой стороны, это может быть полезно в будущем.","en":"Because it''s expensive. But on the other hand, it could be useful in the future.","words":[{"ru":"Потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"это","en":"it"},{"ru":"дорого.","en":"expensive"},{"ru":"Но","en":"but"},{"ru":"с","en":"from"},{"ru":"другой","en":"other"},{"ru":"стороны,","en":"side"},{"ru":"это","en":"it"},{"ru":"может","en":"can"},{"ru":"быть","en":"be"},{"ru":"полезно","en":"useful"},{"ru":"в","en":"in"},{"ru":"будущем.","en":"future"}],"speaker":"Алекс","note":"Сомневаться = to doubt, to be unsure. Может быть полезно = may be useful. В будущем = in the future.","follow":[{"ru":"Сколько это может стоить?","en":"How much could it cost?"},{"ru":"Ты бы ходил в такой клуб?","en":"Would you go to a club like that?","ruF":"Ты бы ходила в такой клуб?"}],"role":"a","x":"a2-18:2"},{"ru":"А ты предпочитаешь жить в большом городе или в маленьком?","en":"And do you prefer living in a big city or a small one?","words":[{"ru":"А","en":"and"},{"ru":"ты","en":"you"},{"ru":"предпочитаешь","en":"prefer"},{"ru":"жить","en":"to live"},{"ru":"в","en":"in"},{"ru":"большом","en":"big"},{"ru":"городе","en":"city"},{"ru":"или","en":"or"},{"ru":"в","en":"in"},{"ru":"маленьком?","en":"small"}],"speaker":"Олег","role":"q","x":"a2-18:3"},{"ru":"Я предпочитаю большой город, потому что там больше возможностей.","en":"I prefer a big city, because there are more opportunities.","words":[{"ru":"Я","en":"I"},{"ru":"предпочитаю","en":"prefer"},{"ru":"большой","en":"big"},{"ru":"город,","en":"city"},{"ru":"потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"там","en":"there"},{"ru":"больше","en":"more"},{"ru":"возможностей.","en":"opportunities"}],"speaker":"Алекс","note":"Предпочитать = to prefer: я предпочитаю, ты предпочитаешь. Больше + genitive plural: больше возможностей.","follow":[{"ru":"В каком городе ты хотел бы жить?","en":"Which city would you like to live in?","ruF":"В каком городе ты хотела бы жить?"},{"ru":"Ты вырос в большом городе?","en":"Did you grow up in a big city?","ruF":"Ты выросла в большом городе?"}],"role":"a","x":"a2-18:3"},{"ru":"А что тебе не нравится в больших городах?","en":"And what don''t you like about big cities?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"тебе","en":"to you"},{"ru":"не","en":"not"},{"ru":"нравится","en":"pleases"},{"ru":"в","en":"in"},{"ru":"больших","en":"big"},{"ru":"городах?","en":"cities"}],"speaker":"Олег","role":"q","x":"a2-18:4"},{"ru":"Честно говоря, там слишком много машин и шума.","en":"To be honest, there are too many cars and too much noise.","words":[{"ru":"Честно","en":"honestly"},{"ru":"говоря,","en":"speaking"},{"ru":"там","en":"there"},{"ru":"слишком","en":"too"},{"ru":"много","en":"many"},{"ru":"машин","en":"cars"},{"ru":"и","en":"and"},{"ru":"шума.","en":"noise"}],"speaker":"Алекс","note":"Слишком много + genitive = too many, too much: много машин (plural), много шума (singular).","follow":[{"ru":"Где тебе больше нравится отдыхать?","en":"Where do you prefer to relax?"},{"ru":"Ты бы хотел жить в деревне?","en":"Would you like to live in the countryside?","ruF":"Ты бы хотела жить в деревне?"}],"role":"a","x":"a2-18:4"},{"ru":"Слушай, а что для тебя важнее всего в отношениях?","en":"Listen, what matters most to you in a relationship?","words":[{"ru":"Слушай,","en":"listen"},{"ru":"а","en":"and"},{"ru":"что","en":"what"},{"ru":"для","en":"for"},{"ru":"тебя","en":"you"},{"ru":"важнее","en":"more important"},{"ru":"всего","en":"of all"},{"ru":"в","en":"in"},{"ru":"отношениях?","en":"relationships"}],"speaker":"Олег","role":"q","x":"a2-18:5"},{"ru":"Для меня важны доверие, уважение и умение разговаривать друг с другом.","en":"For me, trust, respect and being able to talk to each other are important.","words":[{"ru":"Для","en":"for"},{"ru":"меня","en":"me"},{"ru":"важны","en":"important"},{"ru":"доверие,","en":"trust"},{"ru":"уважение","en":"respect"},{"ru":"и","en":"and"},{"ru":"умение","en":"ability"},{"ru":"разговаривать","en":"to talk"},{"ru":"друг","en":"each"},{"ru":"с","en":"with"},{"ru":"другом.","en":"other"}],"speaker":"Алекс","note":"Важнее всего = most important of all. Друг с другом = with each other. Умение + infinitive = the ability to…","follow":[{"ru":"А что для тебя неприемлемо?","en":"And what''s unacceptable to you?"},{"ru":"Ты легко знакомишься с новыми людьми?","en":"Do you find it easy to meet new people?","link":"a2-20:6","linkTopic":"Let''s talk it through","linkLevel":"A2"}],"role":"a","x":"a2-18:5"},{"ru":"А в дружбе?","en":"And in friendship?","words":[{"ru":"А","en":"and"},{"ru":"в","en":"in"},{"ru":"дружбе?","en":"friendship"}],"speaker":"Олег","role":"q","x":"a2-18:6"},{"ru":"В дружбе то же самое. Кроме того, друг должен быть рядом, когда трудно.","en":"The same in friendship. Besides that, a friend should be there when things are hard.","words":[{"ru":"В","en":"in"},{"ru":"дружбе","en":"friendship"},{"ru":"то","en":"the"},{"ru":"же","en":"same"},{"ru":"самое.","en":"same thing"},{"ru":"Кроме","en":"besides"},{"ru":"того,","en":"that"},{"ru":"друг","en":"friend"},{"ru":"должен","en":"must"},{"ru":"быть","en":"be"},{"ru":"рядом,","en":"close by"},{"ru":"когда","en":"when"},{"ru":"трудно.","en":"hard"}],"speaker":"Алекс","note":"То же самое = the same thing. Должен (a woman: должна) + infinitive = must, should. Кроме того adds another point.","follow":[{"ru":"У тебя много друзей?","en":"Do you have a lot of friends?"},{"ru":"Как вы познакомились с лучшим другом?","en":"How did you meet your best friend?"}],"role":"a","x":"a2-18:6"},{"ru":"Что бы ты изменил в своей жизни?","en":"What would you change in your life?","words":[{"ru":"Что","en":"what"},{"ru":"бы","en":"would"},{"ru":"ты","en":"you"},{"ru":"изменил","f":"изменила","en":"change"},{"ru":"в","en":"in"},{"ru":"своей","en":"your"},{"ru":"жизни?","en":"life"}],"ruF":"Что бы ты изменила в своей жизни?","speaker":"Олег","role":"q","x":"a2-18:7"},{"ru":"Я бы хотел больше путешествовать и постоянно развиваться.","en":"I''d like to travel more and keep growing as a person.","words":[{"ru":"Я","en":"I"},{"ru":"бы","en":"would"},{"ru":"хотел","f":"хотела","en":"like"},{"ru":"больше","en":"more"},{"ru":"путешествовать","en":"to travel"},{"ru":"и","en":"and"},{"ru":"постоянно","en":"constantly"},{"ru":"развиваться.","en":"to grow"}],"ruF":"Я бы хотела больше путешествовать и постоянно развиваться.","speaker":"Алекс","note":"Бы + past tense = would: что бы ты изменил? я бы хотел… Развиваться = to develop, to grow as a person.","follow":[{"ru":"Что тебе мешает?","en":"What''s stopping you?"},{"ru":"Куда ты хочешь поехать в следующий раз?","en":"Where do you want to go next time?","link":"a2-16:6","linkTopic":"Travel stories","linkLevel":"A2"}],"role":"a","x":"a2-18:7"}]},{"type":"grammar","title":"Giving your opinion","paragraphs":["**Мне кажется** (it seems to me) and **по-моему** (in my opinion) are soft. **Я думаю, что…** and **я считаю, что…** are firmer. Ask for someone''s opinion with **Что ты думаешь об этом?** or **Как ты считаешь?**"],"examples":[{"ru":"По-моему, это хорошая идея.","en":"In my opinion, it''s a good idea."},{"ru":"Я считаю, что это дорого.","en":"I think it''s expensive."}]},{"type":"grammar","title":"\"Would\": бы + past tense","paragraphs":["Russian makes \"would\" with **бы** + the past tense. It works for wishes and imagined situations: **Я бы хотел** путешествовать (I''d like to travel). **Что бы ты изменил?** (What would you change?)"],"examples":[{"ru":"Я бы хотел жить у моря.","en":"I''d like to live by the sea."},{"ru":"Я бы купила эту машину.","en":"I''d buy this car. (a woman speaking)"}]}],"drills":[{"q":"Мне ___, это хорошая идея.","answer":"кажется","options":["кажешься","кажусь","кажется","казаться"],"en":"I think it''s a good idea.","why":{"кажусь":"Кажусь means \"I seem\" (я кажусь уставшим). \"It seems to me\" is мне кажется.","казаться":"Казаться is the infinitive. The fixed phrase is мне кажется.","кажешься":"Кажешься is the ты form (\"you seem\"). Use мне кажется."}},{"q":"Что бы ты ___ в своей жизни?","answer":"изменил","options":["изменишь","изменять","изменит","изменил"],"en":"What would you change in your life?","why":{"изменишь":"Изменишь is the future (\"you will change\"). With бы use the past form: изменил.","изменять":"Изменять is an infinitive. Бы needs the past form: изменил.","изменит":"Изменит is the future for он/она. With ты and бы: изменил."}},{"q":"Для меня важны доверие и ___.","answer":"уважение","options":["уважения","уважаю","уважать","уважение"],"en":"For me, trust and respect are important.","why":{"уважать":"Уважать is the verb \"to respect\". The list needs a noun like доверие: уважение.","уважаю":"Уважаю means \"I respect\" — a verb. You need the noun: уважение.","уважения":"Уважения is the genitive. In this list the noun stays in the dictionary form: уважение."}}]}'::jsonb, 14, 18),
  ('a2-19', 'A2', 'plans', 19, 'Plans and dreams', 'Планы и мечты', 'Talk about your plans for the weekend, the year and the next five years — and what you''ll do if things change.', '{"intro":"Plans need the future tense, and real plans come with conditions. Notice если (if) — in Russian it takes the future: если пойдёт дождь, я останусь дома.","sections":[{"type":"lines","kind":"conversation","title":"Over coffee","lines":[{"ru":"Какие у тебя планы на выходные?","en":"What are your plans for the weekend?","words":[{"ru":"Какие","en":"what"},{"ru":"у","en":"by"},{"ru":"тебя","en":"you"},{"ru":"планы","en":"plans"},{"ru":"на","en":"for"},{"ru":"выходные?","en":"weekend"}],"speaker":"Вика","role":"q","x":"a2-19:1"},{"ru":"Я собираюсь закончить несколько дел, а потом хочу отдохнуть.","en":"I''m going to finish a few things, and then I want to rest.","words":[{"ru":"Я","en":"I"},{"ru":"собираюсь","en":"am going"},{"ru":"закончить","en":"to finish"},{"ru":"несколько","en":"several"},{"ru":"дел,","en":"things"},{"ru":"а","en":"and"},{"ru":"потом","en":"then"},{"ru":"хочу","en":"want"},{"ru":"отдохнуть.","en":"to rest"}],"speaker":"Алекс","note":"Собираться + infinitive = to be going to, to plan to. Дело (a task) → несколько дел (genitive plural).","follow":[{"ru":"Ты будешь работать в субботу?","en":"Will you be working on Saturday?"},{"ru":"Хочешь пойти куда-нибудь вместе?","en":"Do you want to go somewhere together?"}],"role":"a","x":"a2-19:1"},{"ru":"Какие дела?","en":"What things?","words":[{"ru":"Какие","en":"what"},{"ru":"дела?","en":"things"}],"speaker":"Вика","role":"q","x":"a2-19:2"},{"ru":"Например, мне нужно постирать вещи и купить продукты.","en":"For example, I need to do the laundry and buy groceries.","words":[{"ru":"Например,","en":"for example"},{"ru":"мне","en":"to me"},{"ru":"нужно","en":"need"},{"ru":"постирать","en":"to wash"},{"ru":"вещи","en":"clothes"},{"ru":"и","en":"and"},{"ru":"купить","en":"to buy"},{"ru":"продукты.","en":"groceries"}],"speaker":"Алекс","note":"Мне нужно + infinitive = I need to. Постирать вещи = to do the laundry (вещи = things, clothes).","follow":[{"ru":"Где ты обычно покупаешь продукты?","en":"Where do you usually buy groceries?","link":"a1-18:6","linkTopic":"Food you love","linkLevel":"A1"},{"ru":"Тебе помочь?","en":"Do you want some help?"}],"role":"a","x":"a2-19:2"},{"ru":"А что ты будешь делать, если пойдёт дождь?","en":"And what will you do if it rains?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"будешь","en":"will"},{"ru":"делать,","en":"do"},{"ru":"если","en":"if"},{"ru":"пойдёт","en":"goes"},{"ru":"дождь?","en":"rain"}],"speaker":"Вика","role":"q","x":"a2-19:3"},{"ru":"Скорее всего, останусь дома и посмотрю фильм.","en":"Most likely I''ll stay home and watch a film.","words":[{"ru":"Скорее","en":"most"},{"ru":"всего,","en":"likely"},{"ru":"останусь","en":"will stay"},{"ru":"дома","en":"at home"},{"ru":"и","en":"and"},{"ru":"посмотрю","en":"will watch"},{"ru":"фильм.","en":"film"}],"speaker":"Алекс","note":"Пойдёт дождь = it will rain (literally \"rain will go\"). Скорее всего = most likely. Останусь and посмотрю are the perfective future.","follow":[{"ru":"Ты любишь дождь?","en":"Do you like rain?"},{"ru":"Какие фильмы тебе нравятся?","en":"What kind of films do you like?"}],"role":"a","x":"a2-19:3"},{"ru":"Ты планируешь куда-нибудь поехать в этом году?","en":"Are you planning to go anywhere this year?","words":[{"ru":"Ты","en":"you"},{"ru":"планируешь","en":"plan"},{"ru":"куда-нибудь","en":"somewhere"},{"ru":"поехать","en":"to go"},{"ru":"в","en":"this"},{"ru":"этом","en":"this"},{"ru":"году?","en":"year"}],"speaker":"Вика","role":"q","x":"a2-19:4"},{"ru":"Да, я хотел бы съездить в Европу. Если будут деньги, конечно.","en":"Yes, I''d like to take a trip to Europe. If I have the money, of course.","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"съездить","en":"to take a trip"},{"ru":"в","en":"to"},{"ru":"Европу.","en":"Europe"},{"ru":"Если","en":"if"},{"ru":"будут","en":"will be"},{"ru":"деньги,","en":"money"},{"ru":"конечно.","en":"of course"}],"ruF":"Да, я хотела бы съездить в Европу. Если будут деньги, конечно.","speaker":"Алекс","note":"Съездить = to make a trip there and back. Деньги is plural, so: если будут деньги.","follow":[{"ru":"Ты когда-нибудь был в Европе?","en":"Have you ever been to Europe?","ruF":"Ты когда-нибудь была в Европе?","link":"a2-16:1","linkTopic":"Travel stories","linkLevel":"A2"},{"ru":"Ты копишь на что-нибудь?","en":"Are you saving up for anything?","link":"a2-22:4","linkTopic":"Talking about money","linkLevel":"A2"}],"role":"a","x":"a2-19:4"},{"ru":"Чем ты хочешь заниматься через пять лет?","en":"What do you want to be doing in five years?","words":[{"ru":"Чем","en":"(with) what"},{"ru":"ты","en":"you"},{"ru":"хочешь","en":"want"},{"ru":"заниматься","en":"to do"},{"ru":"через","en":"in"},{"ru":"пять","en":"five"},{"ru":"лет?","en":"years"}],"speaker":"Вика","role":"q","x":"a2-19:5"},{"ru":"Я хочу иметь стабильную работу, путешествовать и создать семью.","en":"I want to have a stable job, travel and start a family.","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"иметь","en":"to have"},{"ru":"стабильную","en":"stable"},{"ru":"работу,","en":"job"},{"ru":"путешествовать","en":"to travel"},{"ru":"и","en":"and"},{"ru":"создать","en":"to create"},{"ru":"семью.","en":"family"}],"speaker":"Алекс","note":"Через + a time = in (from now): через пять лет, через неделю. Создать семью = to start a family.","follow":[{"ru":"Ты хотел бы открыть собственный бизнес?","en":"Would you like to start your own business?","ruF":"Ты хотела бы открыть собственный бизнес?","link":"a2-21:5","linkTopic":"Talking about work","linkLevel":"A2"},{"ru":"Где ты хочешь жить?","en":"Where do you want to live?"}],"role":"a","x":"a2-19:5"},{"ru":"Как ты думаешь, это реально?","en":"Do you think that''s realistic?","words":[{"ru":"Как","en":"how"},{"ru":"ты","en":"you"},{"ru":"думаешь,","en":"think"},{"ru":"это","en":"this"},{"ru":"реально?","en":"realistic"}],"speaker":"Вика","role":"q","x":"a2-19:6"},{"ru":"Думаю, да, хотя придётся много работать.","en":"I think so, although I''ll have to work a lot.","words":[{"ru":"Думаю,","en":"think"},{"ru":"да,","en":"yes"},{"ru":"хотя","en":"although"},{"ru":"придётся","en":"will have"},{"ru":"много","en":"a lot"},{"ru":"работать.","en":"to work"}],"speaker":"Алекс","note":"Придётся + infinitive = will have to: мне придётся много работать. Хотя (although) adds the \"but\".","follow":[{"ru":"Что тебе нужно для этого?","en":"What do you need for that?","link":"a2-21:7","linkTopic":"Talking about work","linkLevel":"A2"},{"ru":"Что тебе мешает?","en":"What''s stopping you?"}],"role":"a","x":"a2-19:6"},{"ru":"Ты уже решил, чем займёшься завтра?","en":"Have you decided what you''ll do tomorrow?","words":[{"ru":"Ты","en":"you"},{"ru":"уже","en":"already"},{"ru":"решил,","f":"решила,","en":"decided"},{"ru":"чем","en":"(with) what"},{"ru":"займёшься","en":"will do"},{"ru":"завтра?","en":"tomorrow"}],"ruF":"Ты уже решила, чем займёшься завтра?","speaker":"Вика","role":"q","x":"a2-19:7"},{"ru":"Пока нет, я ещё думаю. А ты?","en":"Not yet, I''m still thinking. And you?","words":[{"ru":"Пока","en":"yet"},{"ru":"нет,","en":"no"},{"ru":"я","en":"I"},{"ru":"ещё","en":"still"},{"ru":"думаю.","en":"think"},{"ru":"А","en":"and"},{"ru":"ты?","en":"you"}],"speaker":"Алекс","note":"Решить = to decide. Займёшься is the perfective future of заняться: чем займёшься? Пока нет = not yet.","follow":[{"ru":"Хочешь сходить в кино?","en":"Do you want to go to the cinema?"},{"ru":"Давай что-нибудь придумаем вместе?","en":"Shall we think of something together?"}],"role":"a","x":"a2-19:7"}]},{"type":"grammar","title":"Talking about the future","paragraphs":["**Собираться** + infinitive = to be going to: Я собираюсь отдохнуть. The **imperfective future** is буду + infinitive (Что ты будешь делать?). The **perfective future** looks like the present but means a completed future action: останусь (I''ll stay), посмотрю (I''ll watch). **Через** + time = in (from now)."],"examples":[{"ru":"Через неделю я поеду в Москву.","en":"In a week I''ll go to Moscow."},{"ru":"Что ты будешь делать завтра?","en":"What will you be doing tomorrow?"}]},{"type":"grammar","title":"If: если + future","paragraphs":["When \"if\" is about the future, Russian uses the future after **если** — English uses the present: **Если пойдёт** дождь, я **останусь** дома (If it rains, I''ll stay home)."],"examples":[{"ru":"Если будет время, я позвоню.","en":"If I have time, I''ll call."},{"ru":"Если получится, поеду летом.","en":"If it works out, I''ll go in the summer."}]}],"drills":[{"q":"Если ___ дождь, я останусь дома.","answer":"пойдёт","options":["идёт","пойдёт","идти","пошёл"],"en":"If it rains, I''ll stay home.","why":{"идёт":"Идёт is the present. Russian uses the future after если for future events: пойдёт.","пошёл":"Пошёл is the past. For a future \"if\", use the future: пойдёт.","идти":"Идти is the infinitive. After если use a full verb in the future: пойдёт."}},{"q":"Я хочу открыть свой бизнес ___ пять лет.","answer":"через","options":["назад","за","после","через"],"en":"I want to start my own business in five years.","why":{"назад":"Назад means \"ago\". For \"in five years from now\", use через.","после":"После needs a noun after it (после работы). \"In five years\" is через пять лет.","за":"За пять лет means \"within five years\" — how long something takes. \"Five years from now\" is через."}},{"q":"Я ___ закончить несколько дел.","answer":"собираюсь","options":["собираю","собирается","собираться","собираюсь"],"en":"I''m going to finish a few things.","why":{"собираю":"Собираю (without -сь) means \"I collect, I gather\". \"I''m going to\" is собираюсь.","собираться":"Собираться is the infinitive. With я use собираюсь.","собирается":"Собирается is the он/она form. With я use собираюсь."}}]}'::jsonb, 14, 15),
  ('a2-20', 'A2', 'problems', 20, 'Let''s talk it through', 'Давай поговорим', 'Apologise, explain what you meant, talk about solving problems and feelings — and make up.', '{"intro":"Clearing up a misunderstanding takes calm, clear Russian. This conversation teaches you to explain yourself, talk about feelings and finish on a good note.","sections":[{"type":"lines","kind":"conversation","title":"Clearing things up","lines":[{"ru":"Почему ты не ответил на моё сообщение?","en":"Why didn''t you answer my message?","words":[{"ru":"Почему","en":"why"},{"ru":"ты","en":"you"},{"ru":"не","en":"not"},{"ru":"ответил","f":"ответила","en":"answered"},{"ru":"на","en":"to"},{"ru":"моё","en":"my"},{"ru":"сообщение?","en":"message"}],"ruF":"Почему ты не ответила на моё сообщение?","speaker":"Лиза","role":"q","x":"a2-20:1"},{"ru":"Извини, я был занят на работе и не мог ответить.","en":"Sorry, I was busy at work and couldn''t reply.","words":[{"ru":"Извини,","en":"sorry"},{"ru":"я","en":"I"},{"ru":"был","f":"была","en":"was"},{"ru":"занят","f":"занята","en":"busy"},{"ru":"на","en":"at"},{"ru":"работе","en":"work"},{"ru":"и","en":"and"},{"ru":"не","en":"not"},{"ru":"мог","f":"могла","en":"could"},{"ru":"ответить.","en":"to answer"}],"ruF":"Извини, я была занята на работе и не могла ответить.","speaker":"Алекс","note":"Ответить на + accusative = to answer, to reply to: на сообщение, на вопрос. Мог (a woman: могла) is the past of мочь.","follow":[{"ru":"Ты всегда так занят?","en":"Are you always this busy?","ruF":"Ты всегда так занята?"},{"ru":"Ты его прочитал?","en":"Did you read it?","ruF":"Ты его прочитала?"}],"role":"a","x":"a2-20:1"},{"ru":"Ладно. Ты можешь объяснить, что ты имеешь в виду?","en":"Okay. Can you explain what you mean?","words":[{"ru":"Ладно.","en":"okay"},{"ru":"Ты","en":"you"},{"ru":"можешь","en":"can"},{"ru":"объяснить,","en":"explain"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"имеешь","en":"have"},{"ru":"в","en":"in"},{"ru":"виду?","en":"view"}],"speaker":"Лиза","role":"q","x":"a2-20:2"},{"ru":"Конечно. Я просто хотел сказать, что нам нужно всё обсудить.","en":"Of course. I just wanted to say that we need to talk everything through.","words":[{"ru":"Конечно.","en":"of course"},{"ru":"Я","en":"I"},{"ru":"просто","en":"just"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"сказать,","en":"to say"},{"ru":"что","en":"that"},{"ru":"нам","en":"to us"},{"ru":"нужно","en":"need"},{"ru":"всё","en":"everything"},{"ru":"обсудить.","en":"to discuss"}],"ruF":"Конечно. Я просто хотела сказать, что нам нужно всё обсудить.","speaker":"Алекс","note":"Иметь в виду = to mean (what you intend to say). Нам нужно = we need (dative + нужно). Обсудить = to discuss.","follow":[{"ru":"Что именно ты хочешь обсудить?","en":"What exactly do you want to discuss?"},{"ru":"Это серьёзно?","en":"Is it serious?"}],"role":"a","x":"a2-20:2"},{"ru":"Как ты обычно решаешь проблемы?","en":"How do you usually solve problems?","words":[{"ru":"Как","en":"how"},{"ru":"ты","en":"you"},{"ru":"обычно","en":"usually"},{"ru":"решаешь","en":"solve"},{"ru":"проблемы?","en":"problems"}],"speaker":"Лиза","role":"q","x":"a2-20:3"},{"ru":"Сначала я стараюсь понять ситуацию, а потом ищу решение.","en":"First I try to understand the situation, and then I look for a solution.","words":[{"ru":"Сначала","en":"first"},{"ru":"я","en":"I"},{"ru":"стараюсь","en":"try"},{"ru":"понять","en":"to understand"},{"ru":"ситуацию,","en":"situation"},{"ru":"а","en":"and"},{"ru":"потом","en":"then"},{"ru":"ищу","en":"look for"},{"ru":"решение.","en":"solution"}],"speaker":"Алекс","note":"Решать проблемы = to solve problems; решение = a solution. Стараться + infinitive = to try to.","follow":[{"ru":"Ты просишь кого-нибудь о помощи?","en":"Do you ask anyone for help?"},{"ru":"Это всегда работает?","en":"Does that always work?"}],"role":"a","x":"a2-20:3"},{"ru":"А если ты злишься?","en":"And if you''re angry?","words":[{"ru":"А","en":"and"},{"ru":"если","en":"if"},{"ru":"ты","en":"you"},{"ru":"злишься?","en":"are angry"}],"speaker":"Лиза","role":"q","x":"a2-20:4"},{"ru":"Если я злюсь, мне нужно немного времени. После этого я спокойно всё объясняю.","en":"If I''m angry, I need a little time. After that I calmly explain everything.","words":[{"ru":"Если","en":"if"},{"ru":"я","en":"I"},{"ru":"злюсь,","en":"am angry"},{"ru":"мне","en":"to me"},{"ru":"нужно","en":"need"},{"ru":"немного","en":"a little"},{"ru":"времени.","en":"time"},{"ru":"После","en":"after"},{"ru":"этого","en":"that"},{"ru":"я","en":"I"},{"ru":"спокойно","en":"calmly"},{"ru":"всё","en":"everything"},{"ru":"объясняю.","en":"explain"}],"speaker":"Алекс","note":"Злиться = to be angry: я злюсь, ты злишься. Немного + genitive: немного времени.","follow":[{"ru":"Что тебя может разозлить?","en":"What can make you angry?"},{"ru":"Ты быстро успокаиваешься?","en":"Do you calm down quickly?"}],"role":"a","x":"a2-20:4"},{"ru":"Что тебя больше всего раздражает?","en":"What annoys you most?","words":[{"ru":"Что","en":"what"},{"ru":"тебя","en":"you"},{"ru":"больше","en":"more"},{"ru":"всего","en":"of all"},{"ru":"раздражает?","en":"annoys"}],"speaker":"Лиза","role":"q","x":"a2-20:5"},{"ru":"Мне не нравится, когда люди не говорят прямо о своих чувствах.","en":"I don''t like it when people don''t say directly how they feel.","words":[{"ru":"Мне","en":"to me"},{"ru":"не","en":"not"},{"ru":"нравится,","en":"pleases"},{"ru":"когда","en":"when"},{"ru":"люди","en":"people"},{"ru":"не","en":"not"},{"ru":"говорят","en":"speak"},{"ru":"прямо","en":"directly"},{"ru":"о","en":"about"},{"ru":"своих","en":"their"},{"ru":"чувствах.","en":"feelings"}],"speaker":"Алекс","note":"Раздражать = to annoy: меня раздражает… О + prepositional: о чувствах. Свой = one''s own.","follow":[{"ru":"А тебе легко говорить о чувствах?","en":"And is it easy for you to talk about feelings?"},{"ru":"Ты всегда говоришь прямо?","en":"Do you always say things directly?"}],"role":"a","x":"a2-20:5"},{"ru":"Ты легко знакомишься с новыми людьми?","en":"Do you find it easy to meet new people?","words":[{"ru":"Ты","en":"you"},{"ru":"легко","en":"easily"},{"ru":"знакомишься","en":"get to know"},{"ru":"с","en":"with"},{"ru":"новыми","en":"new"},{"ru":"людьми?","en":"people"}],"speaker":"Лиза","role":"q","x":"a2-20:6"},{"ru":"Иногда да, но сначала я могу немного стесняться.","en":"Sometimes, but at first I can be a little shy.","words":[{"ru":"Иногда","en":"sometimes"},{"ru":"да,","en":"yes"},{"ru":"но","en":"but"},{"ru":"сначала","en":"at first"},{"ru":"я","en":"I"},{"ru":"могу","en":"can"},{"ru":"немного","en":"a little"},{"ru":"стесняться.","en":"to be shy"}],"speaker":"Алекс","note":"Знакомиться с + instrumental = to get to know, to meet. Стесняться = to be shy, to feel awkward.","follow":[{"ru":"Как ты обычно начинаешь разговор?","en":"How do you usually start a conversation?"},{"ru":"Где ты обычно знакомишься с людьми?","en":"Where do you usually meet people?"}],"role":"a","x":"a2-20:6"},{"ru":"Ну что, мир?","en":"So, are we okay?","words":[{"ru":"Ну","en":"well"},{"ru":"что,","en":"so"},{"ru":"мир?","en":"peace"}],"speaker":"Лиза","role":"q","x":"a2-20:7"},{"ru":"Конечно, мир! В общем, я рад, что мы поговорили.","en":"Of course we are! All in all, I''m glad we talked.","words":[{"ru":"Конечно,","en":"of course"},{"ru":"мир!","en":"peace"},{"ru":"В","en":"in"},{"ru":"общем,","en":"general"},{"ru":"я","en":"I"},{"ru":"рад,","f":"рада,","en":"glad"},{"ru":"что","en":"that"},{"ru":"мы","en":"we"},{"ru":"поговорили.","en":"talked"}],"ruF":"Конечно, мир! В общем, я рада, что мы поговорили.","speaker":"Алекс","note":"Мир means both \"peace\" and \"world\". Ну что, мир? is how friends make up. Рад (a woman: рада) = glad.","follow":[{"ru":"Пойдём выпьем кофе?","en":"Shall we go and get a coffee?"},{"ru":"Увидимся в выходные?","en":"See you at the weekend?"}],"role":"a","x":"a2-20:7"}]},{"type":"grammar","title":"Feelings: -ся verbs and \"it annoys me\"","paragraphs":["Many feeling verbs end in **-ся**: злиться (to be angry), стесняться (to be shy), обижаться (to take offence), волноваться (to worry). Others work like нравиться — the person is the object: **меня раздражает** шум (noise annoys me), **меня беспокоит** работа (work worries me)."],"examples":[{"ru":"Я злюсь, когда опаздывают.","en":"I get angry when people are late."},{"ru":"Меня раздражает шум.","en":"Noise annoys me."}]},{"type":"grammar","title":"Linking words: если, после этого, в общем","paragraphs":["**Если** (if) sets a condition. **После этого** (after that) moves to the next step. **В общем** (all in all) sums up at the end."],"examples":[{"ru":"Если я злюсь, я молчу.","en":"If I''m angry, I keep quiet."},{"ru":"В общем, всё хорошо.","en":"All in all, everything''s fine."}]}],"drills":[{"q":"Почему ты не ответил ___ моё сообщение?","answer":"на","options":["о","в","для","на"],"en":"Why didn''t you answer my message?","why":{"в":"Ответить takes на: ответить на сообщение, на вопрос.","о":"О means \"about\". \"Answer a message\" is ответить на сообщение.","для":"Для means \"for\". Ответить takes на."}},{"q":"Когда я ___, мне нужно время.","answer":"злюсь","options":["злиться","злишься","злится","злюсь"],"en":"When I''m angry, I need time.","why":{"злишься":"Злишься is the ты form. With я use злюсь.","злится":"Злится is the он/она form. With я use злюсь.","злиться":"Злиться is the infinitive. With я use злюсь."}},{"q":"Я рад, ___ мы поговорили.","answer":"что","options":["если","что","чтобы","потому"],"en":"I''m glad we talked.","why":{"чтобы":"Чтобы means \"in order to, so that\". After рад, use что: рад, что…","потому":"Потому on its own isn''t a linking word — it''s потому что. After рад, simply use что.","если":"Если means \"if\". You''re glad about something that happened: рад, что…"}}]}'::jsonb, 14, 16),
  ('a2-21', 'A2', 'work', 21, 'Talking about work', 'Разговор о работе', 'Say what you like about your job, what''s hard, how many hours you work and whether you''d start your own business.', '{"intro":"Work talk is full of opinions and reasons. Here you''ll weigh pros and cons and list your points with во-первых, во-вторых and поэтому.","sections":[{"type":"lines","kind":"conversation","title":"About your job","lines":[{"ru":"Тебе нравится твоя работа?","en":"Do you like your job?","words":[{"ru":"Тебе","en":"to you"},{"ru":"нравится","en":"pleases"},{"ru":"твоя","en":"your"},{"ru":"работа?","en":"job"}],"speaker":"Юля","role":"q","x":"a2-21:1"},{"ru":"Да, мне нравится общаться с людьми, но иногда работа бывает сложной.","en":"Yes, I like talking to people, but sometimes the work can be hard.","words":[{"ru":"Да,","en":"yes"},{"ru":"мне","en":"to me"},{"ru":"нравится","en":"pleases"},{"ru":"общаться","en":"to talk"},{"ru":"с","en":"with"},{"ru":"людьми,","en":"people"},{"ru":"но","en":"but"},{"ru":"иногда","en":"sometimes"},{"ru":"работа","en":"work"},{"ru":"бывает","en":"can be"},{"ru":"сложной.","en":"difficult"}],"speaker":"Алекс","note":"Бывать = to be at times: работа бывает сложной (the instrumental after бывать). Общаться с + instrumental = to talk with.","follow":[{"ru":"Сколько ты уже там работаешь?","en":"How long have you been working there?"},{"ru":"Ты устаёшь после работы?","en":"Do you get tired after work?","link":"a2-17:6","linkTopic":"What''s new?","linkLevel":"A2"}],"role":"a","x":"a2-21:1"},{"ru":"Что самое сложное в твоей работе?","en":"What''s the hardest thing about your job?","words":[{"ru":"Что","en":"what"},{"ru":"самое","en":"the most"},{"ru":"сложное","en":"difficult"},{"ru":"в","en":"in"},{"ru":"твоей","en":"your"},{"ru":"работе?","en":"job"}],"speaker":"Юля","role":"q","x":"a2-21:2"},{"ru":"Иногда трудно понять, что именно нужно клиенту.","en":"Sometimes it''s hard to understand exactly what the customer needs.","words":[{"ru":"Иногда","en":"sometimes"},{"ru":"трудно","en":"hard"},{"ru":"понять,","en":"to understand"},{"ru":"что","en":"what"},{"ru":"именно","en":"exactly"},{"ru":"нужно","en":"needs"},{"ru":"клиенту.","en":"the customer"}],"speaker":"Алекс","note":"Самое сложное = the hardest thing (самый + adjective = the most…). Нужно клиенту = the customer needs (dative).","follow":[{"ru":"Как ты это решаешь?","en":"How do you deal with that?"},{"ru":"Клиенты бывают грубыми?","en":"Are customers ever rude?"}],"role":"a","x":"a2-21:2"},{"ru":"А что тебе больше всего нравится?","en":"And what do you like most?","words":[{"ru":"А","en":"and"},{"ru":"что","en":"what"},{"ru":"тебе","en":"to you"},{"ru":"больше","en":"more"},{"ru":"всего","en":"of all"},{"ru":"нравится?","en":"pleases"}],"speaker":"Юля","role":"q","x":"a2-21:3"},{"ru":"Мне нравится помогать людям выбирать машину.","en":"I like helping people choose a car.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравится","en":"pleases"},{"ru":"помогать","en":"to help"},{"ru":"людям","en":"people"},{"ru":"выбирать","en":"choose"},{"ru":"машину.","en":"car"}],"speaker":"Алекс","note":"Помогать + dative + infinitive: помогать людям выбирать. Машина → машину (accusative).","follow":[{"ru":"Ты сам любишь машины?","en":"Do you love cars yourself?","ruF":"Ты сама любишь машины?"},{"ru":"Какая у тебя машина?","en":"What car do you have?"}],"role":"a","x":"a2-21:3"},{"ru":"Сколько часов в неделю ты работаешь?","en":"How many hours a week do you work?","words":[{"ru":"Сколько","en":"how many"},{"ru":"часов","en":"hours"},{"ru":"в","en":"a"},{"ru":"неделю","en":"week"},{"ru":"ты","en":"you"},{"ru":"работаешь?","en":"work"}],"speaker":"Юля","role":"q","x":"a2-21:4"},{"ru":"Около сорока, но иногда больше, если много клиентов.","en":"About forty, but sometimes more if there are a lot of customers.","words":[{"ru":"Около","en":"about"},{"ru":"сорока,","en":"forty"},{"ru":"но","en":"but"},{"ru":"иногда","en":"sometimes"},{"ru":"больше,","en":"more"},{"ru":"если","en":"if"},{"ru":"много","en":"many"},{"ru":"клиентов.","en":"customers"}],"speaker":"Алекс","note":"Около + genitive = about, approximately: около сорока. В неделю = a week, per week.","follow":[{"ru":"Ты работаешь по выходным?","en":"Do you work weekends?"},{"ru":"Тебе платят за переработку?","en":"Do you get paid for overtime?"}],"role":"a","x":"a2-21:4"},{"ru":"Ты хотел бы открыть собственный бизнес?","en":"Would you like to start your own business?","words":[{"ru":"Ты","en":"you"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"открыть","en":"to open"},{"ru":"собственный","en":"own"},{"ru":"бизнес?","en":"business"}],"ruF":"Ты хотела бы открыть собственный бизнес?","speaker":"Юля","role":"q","x":"a2-21:5"},{"ru":"Да, мне интересно работать на себя и развивать собственный проект.","en":"Yes, I''m interested in working for myself and building my own project.","words":[{"ru":"Да,","en":"yes"},{"ru":"мне","en":"to me"},{"ru":"интересно","en":"interesting"},{"ru":"работать","en":"to work"},{"ru":"на","en":"for"},{"ru":"себя","en":"oneself"},{"ru":"и","en":"and"},{"ru":"развивать","en":"to develop"},{"ru":"собственный","en":"own"},{"ru":"проект.","en":"project"}],"speaker":"Алекс","note":"Работать на себя = to work for yourself. Собственный = one''s own — a little more formal than свой.","follow":[{"ru":"У тебя уже есть идея?","en":"Do you already have an idea?"},{"ru":"Это не страшно?","en":"Isn''t that scary?"}],"role":"a","x":"a2-21:5"},{"ru":"Какой бизнес ты хотел бы открыть?","en":"What kind of business would you like to start?","words":[{"ru":"Какой","en":"what kind of"},{"ru":"бизнес","en":"business"},{"ru":"ты","en":"you"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"открыть?","en":"to open"}],"ruF":"Какой бизнес ты хотела бы открыть?","speaker":"Юля","role":"q","x":"a2-21:6"},{"ru":"Может быть, свой магазин. С одной стороны, это риск, а с другой стороны — свобода.","en":"Maybe my own store. On the one hand, it''s a risk, but on the other hand — freedom.","words":[{"ru":"Может","en":"maybe"},{"ru":"быть,","en":"be"},{"ru":"свой","en":"own"},{"ru":"магазин.","en":"store"},{"ru":"С","en":"from"},{"ru":"одной","en":"one"},{"ru":"стороны,","en":"side"},{"ru":"это","en":"it"},{"ru":"риск,","en":"risk"},{"ru":"а","en":"and"},{"ru":"с","en":"from"},{"ru":"другой","en":"other"},{"ru":"стороны","en":"side"},{"ru":"—","en":""},{"ru":"свобода.","en":"freedom"}],"speaker":"Алекс","note":"Может быть = maybe. Свой = one''s own. The dash stands in for \"is\": с другой стороны — свобода.","follow":[{"ru":"Что бы ты продавал?","en":"What would you sell?","ruF":"Что бы ты продавала?"},{"ru":"Ты готов рискнуть?","en":"Are you ready to take the risk?","ruF":"Ты готова рискнуть?"}],"role":"a","x":"a2-21:6"},{"ru":"Что тебе нужно для этого?","en":"What do you need for that?","words":[{"ru":"Что","en":"what"},{"ru":"тебе","en":"to you"},{"ru":"нужно","en":"needed"},{"ru":"для","en":"for"},{"ru":"этого?","en":"this"}],"speaker":"Юля","role":"q","x":"a2-21:7"},{"ru":"Во-первых, деньги, а во-вторых, опыт. Поэтому пока я коплю и учусь.","en":"First, money, and second, experience. So for now I''m saving up and learning.","words":[{"ru":"Во-первых,","en":"firstly"},{"ru":"деньги,","en":"money"},{"ru":"а","en":"and"},{"ru":"во-вторых,","en":"secondly"},{"ru":"опыт.","en":"experience"},{"ru":"Поэтому","en":"so"},{"ru":"пока","en":"for now"},{"ru":"я","en":"I"},{"ru":"коплю","en":"save"},{"ru":"и","en":"and"},{"ru":"учусь.","en":"learn"}],"speaker":"Алекс","note":"Во-первых, во-вторых = firstly, secondly. Копить = to save up: я коплю, ты копишь.","follow":[{"ru":"Сколько тебе нужно накопить?","en":"How much do you need to save?"},{"ru":"Ты копишь на что-нибудь?","en":"Are you saving up for anything?","link":"a2-22:4","linkTopic":"Talking about money","linkLevel":"A2"}],"role":"a","x":"a2-21:7"}]},{"type":"grammar","title":"The most…: самый","paragraphs":["**Самый** + adjective makes \"the most…\" and agrees with the noun: самый интересный день, самая трудная работа, самое важное решение. On its own, the neuter **самое** + adjective means \"the … thing\": самое сложное (the hardest thing), самое главное (the main thing)."],"examples":[{"ru":"Это самый лучший день!","en":"This is the best day!"},{"ru":"Самое главное — здоровье.","en":"The main thing is health."}]},{"type":"grammar","title":"Linking words: во-первых, во-вторых, поэтому","paragraphs":["List your reasons with **во-первых** (firstly) and **во-вторых** (secondly), then draw the conclusion with **поэтому** (so, that''s why)."],"examples":[{"ru":"Во-первых, это дорого, а во-вторых, далеко. Поэтому я не поеду.","en":"Firstly it''s expensive, and secondly it''s far. So I won''t go."}]}],"drills":[{"q":"Что самое ___ в твоей работе?","answer":"сложное","options":["сложная","сложно","сложное","сложный"],"en":"What''s the hardest thing about your job?","why":{"сложный":"\"The hardest thing\" is самое сложное — the neuter form, used as a noun.","сложная":"Сложная is feminine. \"The hardest thing\" is самое сложное (neuter).","сложно":"Сложно is an adverb (\"it''s hard\"). After самое you need the neuter adjective: сложное."}},{"q":"Мне нравится помогать ___ выбирать машину.","answer":"людям","options":["людей","людям","люди","людьми"],"en":"I like helping people choose a car.","why":{"люди":"Помогать takes the dative: людям.","людей":"Людей is the genitive or accusative. Помогать takes the dative: людям.","людьми":"Людьми is the instrumental (с людьми). Помогать takes the dative: людям."}},{"q":"Мне нужен опыт, ___ пока я учусь.","answer":"поэтому","options":["хотя","потому что","поэтому","кстати"],"en":"I need experience, so for now I''m learning.","why":{"потому что":"Потому что gives a reason. Learning is the result of needing experience: поэтому.","хотя":"Хотя means \"although\" — a contrast. Here it''s cause and result: поэтому.","кстати":"Кстати (by the way) changes the topic. The result here needs поэтому."}}]}'::jsonb, 14, 16),
  ('a2-22', 'A2', 'money', 22, 'Talking about money', 'Поговорим о деньгах', 'Talk about what you spend on, saving, your last purchase, shopping online and lending money.', '{"intro":"Money is a great topic for practising reasons and opinions — and for prepositions: тратить на, копить на, платить за.","sections":[{"type":"lines","kind":"conversation","title":"Money talk with a roommate","lines":[{"ru":"На что ты обычно тратишь деньги?","en":"What do you usually spend your money on?","words":[{"ru":"На","en":"on"},{"ru":"что","en":"what"},{"ru":"ты","en":"you"},{"ru":"обычно","en":"usually"},{"ru":"тратишь","en":"spend"},{"ru":"деньги?","en":"money"}],"speaker":"Паша","role":"q","x":"a2-22:1"},{"ru":"В основном на жильё, еду, машину и повседневные расходы.","en":"Mostly on housing, food, the car and everyday expenses.","words":[{"ru":"В","en":"in"},{"ru":"основном","en":"main"},{"ru":"на","en":"on"},{"ru":"жильё,","en":"housing"},{"ru":"еду,","en":"food"},{"ru":"машину","en":"car"},{"ru":"и","en":"and"},{"ru":"повседневные","en":"everyday"},{"ru":"расходы.","en":"expenses"}],"speaker":"Алекс","note":"Тратить на + accusative = to spend on: на еду, на машину. В основном = mostly, mainly.","follow":[{"ru":"Сколько ты платишь за квартиру?","en":"How much do you pay for the apartment?"},{"ru":"Ты ведёшь бюджет?","en":"Do you keep a budget?"}],"role":"a","x":"a2-22:1"},{"ru":"Ты предпочитаешь экономить или тратить деньги?","en":"Do you prefer saving money or spending it?","words":[{"ru":"Ты","en":"you"},{"ru":"предпочитаешь","en":"prefer"},{"ru":"экономить","en":"to save"},{"ru":"или","en":"or"},{"ru":"тратить","en":"to spend"},{"ru":"деньги?","en":"money"}],"speaker":"Паша","role":"q","x":"a2-22:2"},{"ru":"Я стараюсь разумно экономить, но иногда позволяю себе что-нибудь приятное.","en":"I try to save sensibly, but sometimes I treat myself to something nice.","words":[{"ru":"Я","en":"I"},{"ru":"стараюсь","en":"try"},{"ru":"разумно","en":"sensibly"},{"ru":"экономить,","en":"to save"},{"ru":"но","en":"but"},{"ru":"иногда","en":"sometimes"},{"ru":"позволяю","en":"allow"},{"ru":"себе","en":"myself"},{"ru":"что-нибудь","en":"something"},{"ru":"приятное.","en":"nice"}],"speaker":"Алекс","note":"Позволять себе = to allow yourself, to treat yourself. Что-нибудь приятное = something nice.","follow":[{"ru":"На чём ты экономишь?","en":"What do you save on?"},{"ru":"Тебе легко экономить?","en":"Is saving easy for you?"}],"role":"a","x":"a2-22:2"},{"ru":"Что ты купил себе в последний раз?","en":"What''s the last thing you bought for yourself?","words":[{"ru":"Что","en":"what"},{"ru":"ты","en":"you"},{"ru":"купил","f":"купила","en":"bought"},{"ru":"себе","en":"yourself"},{"ru":"в","en":"(the)"},{"ru":"последний","en":"last"},{"ru":"раз?","en":"time"}],"ruF":"Что ты купила себе в последний раз?","speaker":"Паша","role":"q","x":"a2-22:3"},{"ru":"Новые наушники. Честно говоря, они были дороговаты, но очень хорошие.","en":"New headphones. To be honest, they were a bit pricey, but they''re really good.","words":[{"ru":"Новые","en":"new"},{"ru":"наушники.","en":"headphones"},{"ru":"Честно","en":"honestly"},{"ru":"говоря,","en":"speaking"},{"ru":"они","en":"they"},{"ru":"были","en":"were"},{"ru":"дороговаты,","en":"a bit pricey"},{"ru":"но","en":"but"},{"ru":"очень","en":"very"},{"ru":"хорошие.","en":"good"}],"speaker":"Алекс","note":"Дороговаты = a bit too expensive: the suffix -оват- softens an adjective. Наушники (headphones) is always plural.","follow":[{"ru":"Сколько они стоили?","en":"How much did they cost?"},{"ru":"Где ты их купил?","en":"Where did you buy them?","ruF":"Где ты их купила?"}],"role":"a","x":"a2-22:3"},{"ru":"Ты копишь на что-нибудь?","en":"Are you saving up for anything?","words":[{"ru":"Ты","en":"you"},{"ru":"копишь","en":"save"},{"ru":"на","en":"for"},{"ru":"что-нибудь?","en":"anything"}],"speaker":"Паша","role":"q","x":"a2-22:4"},{"ru":"Да, я коплю на путешествие. Кроме того, я хочу купить новую машину.","en":"Yes, I''m saving up for a trip. Besides that, I want to buy a new car.","words":[{"ru":"Да,","en":"yes"},{"ru":"я","en":"I"},{"ru":"коплю","en":"save"},{"ru":"на","en":"for"},{"ru":"путешествие.","en":"trip"},{"ru":"Кроме","en":"besides"},{"ru":"того,","en":"that"},{"ru":"я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"купить","en":"to buy"},{"ru":"новую","en":"new"},{"ru":"машину.","en":"car"}],"speaker":"Алекс","note":"Копить на + accusative = to save up for: на путешествие, на машину. Кроме того adds another point.","follow":[{"ru":"Куда ты хочешь поехать в следующий раз?","en":"Where do you want to go next time?","link":"a2-16:6","linkTopic":"Travel stories","linkLevel":"A2"},{"ru":"Какую машину ты хочешь?","en":"What car do you want?"}],"role":"a","x":"a2-22:4"},{"ru":"Ты часто покупаешь что-то онлайн?","en":"Do you often buy things online?","words":[{"ru":"Ты","en":"you"},{"ru":"часто","en":"often"},{"ru":"покупаешь","en":"buy"},{"ru":"что-то","en":"something"},{"ru":"онлайн?","en":"online"}],"speaker":"Паша","role":"q","x":"a2-22:5"},{"ru":"Да, довольно часто, потому что это удобно. Но одежду я покупаю в магазине, потому что хочу её примерить.","en":"Yes, quite often, because it''s convenient. But I buy clothes in a store, because I want to try them on.","words":[{"ru":"Да,","en":"yes"},{"ru":"довольно","en":"quite"},{"ru":"часто,","en":"often"},{"ru":"потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"это","en":"it"},{"ru":"удобно.","en":"convenient"},{"ru":"Но","en":"but"},{"ru":"одежду","en":"clothes"},{"ru":"я","en":"I"},{"ru":"покупаю","en":"buy"},{"ru":"в","en":"in"},{"ru":"магазине,","en":"store"},{"ru":"потому","en":"because"},{"ru":"что","en":"(that)"},{"ru":"хочу","en":"want"},{"ru":"её","en":"it"},{"ru":"примерить.","en":"to try on"}],"speaker":"Алекс","note":"Довольно = quite, fairly. Одежда (clothes) is singular in Russian, so it''s её примерить — \"try it on\".","follow":[{"ru":"Что ты покупаешь онлайн чаще всего?","en":"What do you buy online most often?"},{"ru":"Ты когда-нибудь возвращал покупки?","en":"Have you ever returned a purchase?","ruF":"Ты когда-нибудь возвращала покупки?"}],"role":"a","x":"a2-22:5"},{"ru":"Ты даёшь деньги в долг друзьям?","en":"Do you lend money to friends?","words":[{"ru":"Ты","en":"you"},{"ru":"даёшь","en":"give"},{"ru":"деньги","en":"money"},{"ru":"в","en":"into"},{"ru":"долг","en":"debt"},{"ru":"друзьям?","en":"friends"}],"speaker":"Паша","role":"q","x":"a2-22:6"},{"ru":"Иногда даю, если это хороший друг. Но не очень большие суммы.","en":"Sometimes, if it''s a good friend. But not very large amounts.","words":[{"ru":"Иногда","en":"sometimes"},{"ru":"даю,","en":"give"},{"ru":"если","en":"if"},{"ru":"это","en":"this"},{"ru":"хороший","en":"good"},{"ru":"друг.","en":"friend"},{"ru":"Но","en":"but"},{"ru":"не","en":"not"},{"ru":"очень","en":"very"},{"ru":"большие","en":"big"},{"ru":"суммы.","en":"sums"}],"speaker":"Алекс","note":"Давать в долг = to lend (literally \"give into debt\"); брать в долг = to borrow. Давать: я даю, ты даёшь.","follow":[{"ru":"Тебе всегда возвращают деньги?","en":"Do people always pay you back?"},{"ru":"Ты когда-нибудь брал в долг?","en":"Have you ever borrowed money?","ruF":"Ты когда-нибудь брала в долг?"}],"role":"a","x":"a2-22:6"},{"ru":"Как ты думаешь, деньги приносят счастье?","en":"Do you think money brings happiness?","words":[{"ru":"Как","en":"how"},{"ru":"ты","en":"you"},{"ru":"думаешь,","en":"think"},{"ru":"деньги","en":"money"},{"ru":"приносят","en":"bring"},{"ru":"счастье?","en":"happiness"}],"speaker":"Паша","role":"q","x":"a2-22:7"},{"ru":"На самом деле, не совсем. Деньги дают свободу, но счастье — это люди рядом.","en":"Actually, not exactly. Money gives you freedom, but happiness is the people around you.","words":[{"ru":"На","en":"on"},{"ru":"самом","en":"very"},{"ru":"деле,","en":"matter"},{"ru":"не","en":"not"},{"ru":"совсем.","en":"quite"},{"ru":"Деньги","en":"money"},{"ru":"дают","en":"give"},{"ru":"свободу,","en":"freedom"},{"ru":"но","en":"but"},{"ru":"счастье","en":"happiness"},{"ru":"—","en":""},{"ru":"это","en":"that''s"},{"ru":"люди","en":"people"},{"ru":"рядом.","en":"nearby"}],"speaker":"Алекс","note":"На самом деле = actually. Деньги is always plural: деньги дают, деньги приносят. Счастье — это… = happiness is…","follow":[{"ru":"А что для тебя счастье?","en":"And what is happiness for you?"},{"ru":"Что бы ты изменил в своей жизни?","en":"What would you change in your life?","ruF":"Что бы ты изменила в своей жизни?","link":"a2-18:7","linkTopic":"What do you think?","linkLevel":"A2"}],"role":"a","x":"a2-22:7"}]},{"type":"grammar","title":"Spending, saving, lending","paragraphs":["Each money verb has its own preposition: **тратить на** + accusative (spend on), **копить на** + accusative (save up for), **платить за** + accusative (pay for). **Давать в долг** = to lend, **брать в долг** = to borrow."],"examples":[{"ru":"Я плачу за квартиру тысячу долларов.","en":"I pay a thousand dollars for the apartment."},{"ru":"Можно взять у тебя в долг?","en":"Can I borrow from you?"}]},{"type":"grammar","title":"Softening: довольно, -оват-, не совсем","paragraphs":["Russians often soften what they say. **Довольно** = quite, fairly. The suffix **-оват-** means \"a bit too\": дороговато (a bit pricey), великовата (a bit big). **Не совсем** = not exactly."],"examples":[{"ru":"Куртка мне великовата.","en":"The jacket is a bit big for me."},{"ru":"Это довольно дорого.","en":"That''s fairly expensive."}]}],"drills":[{"q":"Я трачу деньги ___ еду и жильё.","answer":"на","options":["в","за","на","для"],"en":"I spend money on food and housing.","why":{"в":"Тратить takes на: тратить на еду.","за":"За goes with платить (платить за квартиру). Тратить takes на.","для":"Для means \"for (the benefit of)\". \"Spend on\" is тратить на."}},{"q":"Я коплю на ___.","answer":"путешествие","options":["путешествия","путешествие","путешествием","путешествии"],"en":"I''m saving up for a trip.","why":{"путешествия":"Копить на takes the accusative: на путешествие (for this neuter noun it looks like the dictionary form).","путешествием":"Путешествием is the instrumental. Копить на takes the accusative: путешествие.","путешествии":"Путешествии is the prepositional (о путешествии). Копить на takes the accusative: путешествие."}},{"q":"Деньги ___ свободу.","answer":"дают","options":["даю","даёт","дают","даёшь"],"en":"Money gives you freedom.","why":{"даёт":"Даёт is singular. Деньги is always plural in Russian: дают.","даю":"Даю is the я form. Plural деньги needs дают.","даёшь":"Даёшь is the ты form. Plural деньги needs дают."}}]}'::jsonb, 14, 16),
  ('b1-01', 'B1', 'smalltalk', 1, 'How was your day?', 'Как прошёл день?', 'Keep a casual conversation flowing with natural fillers and follow-up questions.', '{"intro":"Real conversations are full of little words — слушай, кстати, ну, ладно — that give you time to think. Use them and you''ll sound much more natural.","sections":[{"type":"lines","kind":"dialogue","title":"Catching up","lines":[{"ru":"Привет! Как прошёл твой день?","en":"Hi! How was your day?","words":[{"ru":"Привет!","en":"hi"},{"ru":"Как","en":"how"},{"ru":"прошёл","en":"went"},{"ru":"твой","en":"your"},{"ru":"день?","en":"day"}],"speaker":"Анна"},{"ru":"Неплохо, но я очень устал.","en":"Not bad, but I''m really tired.","words":[{"ru":"Неплохо,","en":"not bad"},{"ru":"но","en":"but"},{"ru":"я","en":"I"},{"ru":"очень","en":"very"},{"ru":"устал.","en":"got tired"}],"speaker":"Максим"},{"ru":"Что нового?","en":"What''s new?","words":[{"ru":"Что","en":"what"},{"ru":"нового?","en":"new"}],"speaker":"Анна"},{"ru":"Да ничего особенного.","en":"Nothing special.","words":[{"ru":"Да","en":"well"},{"ru":"ничего","en":"nothing"},{"ru":"особенного.","en":"special"}],"speaker":"Максим"},{"ru":"Слушай, я давно хотел с тобой поговорить.","en":"Listen, I''ve been wanting to talk to you for a while.","words":[{"ru":"Слушай,","en":"listen"},{"ru":"я","en":"I"},{"ru":"давно","en":"for a long time"},{"ru":"хотел","en":"wanted"},{"ru":"с","en":"with"},{"ru":"тобой","en":"you"},{"ru":"поговорить.","en":"to talk"}],"speaker":"Максим"},{"ru":"О чём?","en":"About what?","words":[{"ru":"О","en":"about"},{"ru":"чём?","en":"what"}],"speaker":"Анна"}]},{"type":"lines","kind":"phrases","title":"Small talk","lines":[{"ru":"Как тебе новая работа?","en":"How''s the new job?","words":[{"ru":"Как","en":"how"},{"ru":"тебе","en":"to you"},{"ru":"новая","en":"new"},{"ru":"работа?","en":"job"}]},{"ru":"Ты слышал новость?","en":"Have you heard the news?","words":[{"ru":"Ты","en":"you"},{"ru":"слышал","f":"слышала","en":"heard"},{"ru":"новость?","en":"the news"}],"ruF":"Ты слышала новость?"},{"ru":"Кстати, ты не знаешь, где Максим?","en":"By the way, do you know where Maksim is?","words":[{"ru":"Кстати,","en":"by the way"},{"ru":"ты","en":"you"},{"ru":"не","en":"not"},{"ru":"знаешь,","en":"know"},{"ru":"где","en":"where"},{"ru":"Максим?","en":"Maksim"}]},{"ru":"Ну, ладно, мне пора.","en":"Well, okay, I''d better go.","words":[{"ru":"Ну,","en":"well"},{"ru":"ладно,","en":"all right"},{"ru":"мне","en":"to me"},{"ru":"пора.","en":"it''s time"}],"note":"Мне пора — \"it''s time for me\" — is the polite way to wrap up a chat."},{"ru":"Рад был тебя видеть!","en":"It was great to see you!","words":[{"ru":"Рад","f":"рада","en":"glad"},{"ru":"был","f":"была","en":"was"},{"ru":"тебя","en":"you"},{"ru":"видеть!","en":"to see"}],"ruF":"рада была тебя видеть!"}]},{"type":"grammar","title":"Fillers and \"How do you like…?\"","paragraphs":["**Слушай / слушайте** (\"listen\") introduces a new topic. **Кстати** = \"by the way\". **Ну** buys time. **Ладно** = \"okay, fine\".","**Как тебе** + noun? = \"How do you like…?\": Как тебе фильм? Как тебе Москва?","**Рад / рада / рады** agrees with the speaker: a man says рад, a woman says рада."],"examples":[{"ru":"Как тебе новый город?","en":"How do you like the new city?"},{"ru":"Мы рады вас видеть!","en":"We''re happy to see you!"}]}],"drills":[{"q":"Как ___ твой день?","answer":"прошёл","options":["прошло","прошла","прошёл","пройти"],"en":"How was your day?","why":{"прошла":"Прошла is feminine. День is masculine: прошёл.","прошло":"Прошло is neuter. День is masculine: прошёл.","пройти":"Пройти is the infinitive. День needs the masculine past: прошёл."}},{"q":"Что ___?","answer":"нового","options":["нового","новости","новый","новое"],"en":"What''s new?","why":{"новое":"The set phrase uses the genitive: Что нового?","новый":"Новый is the masculine adjective. The phrase is Что нового?","новости":"Новости means \"the news\". \"What''s new?\" is Что нового?"}},{"q":"Ну, ладно, мне ___.","answer":"пора","options":["время","нужно","надо","пора"],"en":"Well, okay, I''d better go.","why":{"надо":"Надо (\"need to\") needs a verb after it (мне надо идти). On its own, \"I''d better go\" is мне пора.","нужно":"Like надо, нужно needs a verb after it. On its own: мне пора.","время":"Время is the noun \"time\" — мне время isn''t idiomatic. Say мне пора."}},{"q":"Я так ___ тебя видеть! (a woman)","answer":"рада","options":["рады","рад","радость","рада"],"en":"I''m so glad to see you!","why":{"рад":"Рад is what a man says. A woman says рада.","рады":"Рады is plural (мы рады). One woman: рада.","радость":"Радость is the noun \"joy\". \"I''m glad\" is рада."}}]}'::jsonb, 11, 8),
  ('b1-02', 'B1', 'opinions', 2, 'In my opinion', 'По-моему', 'Give your opinion, agree or disagree politely, and weigh both sides.', '{"intro":"You''ll learn to say \"I think…\" in several ways, and to disagree without sounding rude: «Я не совсем согласен с тобой, но…».","sections":[{"type":"lines","kind":"phrases","title":"Saying what you think","lines":[{"ru":"Я думаю, что нам стоит попробовать что-нибудь новое.","en":"I think we should try something new.","words":[{"ru":"Я","en":"I"},{"ru":"думаю,","en":"think"},{"ru":"что","en":"that"},{"ru":"нам","en":"for us"},{"ru":"стоит","en":"it''s worth"},{"ru":"попробовать","en":"trying"},{"ru":"что-нибудь","en":"something"},{"ru":"новое.","en":"new"}]},{"ru":"По-моему, это отличная идея.","en":"In my opinion, it''s a great idea.","words":[{"ru":"По-моему,","en":"in my view"},{"ru":"это","en":"this"},{"ru":"отличная","en":"excellent"},{"ru":"идея.","en":"idea"}]},{"ru":"Я не совсем согласен с тобой, но понимаю твою точку зрения.","en":"I don''t completely agree with you, but I understand your point of view.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"совсем","en":"entirely"},{"ru":"согласен","f":"согласна","en":"agree"},{"ru":"с","en":"with"},{"ru":"тобой,","en":"you"},{"ru":"но","en":"but"},{"ru":"понимаю","en":"understand"},{"ru":"твою","en":"your"},{"ru":"точку","en":"point"},{"ru":"зрения.","en":"of view"}],"ruF":"Я не совсем согласна с тобой, но понимаю твою точку зрения."},{"ru":"С одной стороны, это дорого, с другой — удобно.","en":"On the one hand it''s expensive; on the other, it''s convenient.","words":[{"ru":"С","en":"from"},{"ru":"одной","en":"one"},{"ru":"стороны,","en":"side"},{"ru":"это","en":"it''s"},{"ru":"дорого,","en":"expensive"},{"ru":"с","en":"from"},{"ru":"другой","en":"the other"},{"ru":"—","en":"—"},{"ru":"удобно.","en":"convenient"}]},{"ru":"А как ты считаешь?","en":"And what do you think?","words":[{"ru":"А","en":"and"},{"ru":"как","en":"how"},{"ru":"ты","en":"you"},{"ru":"считаешь?","en":"think"}]},{"ru":"Я уверен, что всё получится.","en":"I''m sure everything will work out.","words":[{"ru":"Я","en":"I"},{"ru":"уверен,","f":"уверена,","en":"sure"},{"ru":"что","en":"that"},{"ru":"всё","en":"everything"},{"ru":"получится.","en":"will work out"}],"ruF":"Я уверена, что всё получится."},{"ru":"Честно говоря, я сомневаюсь.","en":"To be honest, I have my doubts.","words":[{"ru":"Честно","en":"honestly"},{"ru":"говоря,","en":"speaking"},{"ru":"я","en":"I"},{"ru":"сомневаюсь.","en":"doubt"}]},{"ru":"Ты прав.","en":"You''re right.","words":[{"ru":"Ты","en":"you"},{"ru":"прав.","f":"права.","en":"right"}],"ruF":"Ты права."},{"ru":"Это зависит от ситуации.","en":"It depends on the situation.","words":[{"ru":"Это","en":"it"},{"ru":"зависит","en":"depends"},{"ru":"от","en":"on"},{"ru":"ситуации.","en":"the situation"}]}]},{"type":"grammar","title":"Opinion frames","paragraphs":["**Я думаю / считаю, что…** · **По-моему,…** · **Мне кажется, что…** all introduce an opinion. Note the comma before **что**.","**Стоит** + infinitive = \"it''s worth / we should\": стоит попробовать.","**Согласен / согласна с** + instrumental = \"agree with\": я согласна с тобой."],"examples":[{"ru":"Мне кажется, что он прав.","en":"I think he''s right."},{"ru":"Тебе стоит отдохнуть.","en":"You should get some rest."}]}],"drills":[{"q":"Я не совсем ___ с тобой. (a man)","answer":"согласен","options":["согласиться","согласна","согласие","согласен"],"en":"I don''t completely agree with you.","why":{"согласна":"Согласна is what a woman says. A man says согласен.","согласие":"Согласие is the noun \"agreement\". \"I agree\" is я согласен.","согласиться":"Согласиться is the infinitive \"to agree\". \"I agree\" is я согласен."}},{"q":"Нам ___ попробовать что-нибудь новое.","answer":"стоит","options":["стоят","стоит","стоял","стоить"],"en":"We should try something new.","why":{"стоить":"Стоить is the infinitive. \"We should\" is нам стоит.","стоят":"Стоят is plural (\"they cost\"). The impersonal \"it''s worth\" is стоит.","стоял":"Стоял is past (\"stood\"). The phrase is нам стоит."}},{"q":"Я понимаю твою точку ___.","answer":"зрения","options":["зрением","зрения","зрению","зрение"],"en":"I understand your point of view.","why":{"зрение":"The phrase is точка зрения (\"point of view\"), with зрения in the genitive.","зрением":"Зрением is the instrumental. The fixed phrase is точка зрения.","зрению":"Зрению is the dative. The fixed phrase is точка зрения."}},{"q":"Это зависит от ___.","answer":"ситуации","options":["ситуацию","ситуация","ситуацией","ситуации"],"en":"It depends on the situation.","why":{"ситуация":"От takes the genitive: от ситуации.","ситуацию":"Ситуацию is the accusative. От needs ситуации.","ситуацией":"Ситуацией is the instrumental. От needs ситуации."}}]}'::jsonb, 9, 10),
  ('b1-03', 'B1', 'hobbies', 3, 'Honestly, I''ve never…', 'Честно говоря…', 'Talk about experiences — what you''ve done, never done and dream of doing.', '{"intro":"Russian piles negatives together: «Я никогда ничего не делал» — literally \"I never nothing didn''t do\". It''s correct, and it''s the only way to say it.","sections":[{"type":"lines","kind":"phrases","title":"Experiences","lines":[{"ru":"Ты когда-нибудь был в России?","en":"Have you ever been to Russia?","words":[{"ru":"Ты","en":"you"},{"ru":"когда-нибудь","en":"ever"},{"ru":"был","f":"была","en":"been"},{"ru":"в","en":"in"},{"ru":"России?","en":"Russia"}],"ruF":"Ты когда-нибудь была в России?"},{"ru":"Нет, ни разу.","en":"No, never.","words":[{"ru":"Нет,","en":"no"},{"ru":"ни","en":"not"},{"ru":"разу.","en":"once"}]},{"ru":"Честно говоря, я никогда раньше этого не делал.","en":"Honestly, I''ve never done this before.","words":[{"ru":"Честно","en":"honestly"},{"ru":"говоря,","en":"speaking"},{"ru":"я","en":"I"},{"ru":"никогда","en":"never"},{"ru":"раньше","en":"before"},{"ru":"этого","en":"this"},{"ru":"не","en":"not"},{"ru":"делал.","f":"делала.","en":"did"}],"ruF":"Честно говоря, я никогда раньше этого не делала.","note":"Russian requires the double negative: никогда … не."},{"ru":"Я ещё ни разу не прыгал с парашютом.","en":"I''ve never skydived yet.","words":[{"ru":"Я","en":"I"},{"ru":"ещё","en":"yet"},{"ru":"ни","en":"not"},{"ru":"разу","en":"once"},{"ru":"не","en":"not"},{"ru":"прыгал","f":"прыгала","en":"jumped"},{"ru":"с","en":"with"},{"ru":"парашютом.","en":"a parachute"}],"ruF":"Я ещё ни разу не прыгала с парашютом."},{"ru":"Это был мой первый раз.","en":"It was my first time.","words":[{"ru":"Это","en":"it"},{"ru":"был","en":"was"},{"ru":"мой","en":"my"},{"ru":"первый","en":"first"},{"ru":"раз.","en":"time"}]},{"ru":"Мне было немного страшно.","en":"I was a little scared.","words":[{"ru":"Мне","en":"to me"},{"ru":"было","en":"was"},{"ru":"немного","en":"a little"},{"ru":"страшно.","en":"scary"}]},{"ru":"Ничего страшного!","en":"It''s no big deal!","words":[{"ru":"Ничего","en":"nothing"},{"ru":"страшного!","en":"terrible"}]},{"ru":"Я давно мечтаю об этом.","en":"I''ve dreamed of this for a long time.","words":[{"ru":"Я","en":"I"},{"ru":"давно","en":"for a long time"},{"ru":"мечтаю","en":"dream"},{"ru":"об","en":"about"},{"ru":"этом.","en":"this"}]},{"ru":"Никто не знал.","en":"Nobody knew.","words":[{"ru":"Никто","en":"nobody"},{"ru":"не","en":"not"},{"ru":"знал.","en":"knew"}]},{"ru":"Я ничего не понял.","en":"I didn''t understand a thing.","words":[{"ru":"Я","en":"I"},{"ru":"ничего","en":"nothing"},{"ru":"не","en":"not"},{"ru":"понял.","f":"поняла.","en":"understood"}],"ruF":"Я ничего не поняла."}]},{"type":"grammar","title":"Double negatives","paragraphs":["Negative words — **никогда** (never), **ничего** (nothing), **никто** (nobody), **нигде** (nowhere) — always come with **не** before the verb.","**Ни разу** = \"not once\". **Когда-нибудь** = \"ever\" in questions."],"examples":[{"ru":"Я нигде не был.","en":"I haven''t been anywhere."},{"ru":"Никто ничего не сказал.","en":"Nobody said anything."}]}],"drills":[{"q":"Я никогда ___ был в России.","answer":"не","options":["нет","ни","не","нету"],"en":"I''ve never been to Russia.","why":{"ни":"Ни is for \"neither…nor\" or \"not even\". To negate the verb, use не: никогда не был.","нет":"Нет stands alone (\"no\", \"there isn''t\"). Before a verb, use не.","нету":"Нету is colloquial for \"there isn''t\". Before a verb, use не."}},{"q":"Ты когда-___ был в Москве?","answer":"нибудь","options":["ни","либо","то","нибудь"],"en":"Have you ever been to Moscow?","why":{"то":"Когда-то means \"once, at some point\". In a question, \"ever\" is когда-нибудь.","либо":"Когда-либо is formal and bookish. In conversation, \"ever\" is когда-нибудь.","ни":"Ни doesn''t attach with a hyphen. \"Ever\" is когда-нибудь."}},{"q":"___ не знал. (Nobody)","answer":"Никто","options":["Нигде","Никогда","Никто","Ничего"],"en":"Nobody knew.","why":{"Ничего":"Ничего is \"nothing\". \"Nobody\" is никто.","Никогда":"Никогда is \"never\". \"Nobody\" is никто.","Нигде":"Нигде is \"nowhere\". \"Nobody\" is никто."}},{"q":"Я ___ не понял. (anything)","answer":"ничего","options":["никогда","никто","ничего","нигде"],"en":"I didn''t understand anything.","why":{"никто":"Никто is \"nobody\". \"Anything\" in a negative sentence is ничего.","никогда":"Никогда is \"never\". \"Anything\" here is ничего.","нигде":"Нигде is \"nowhere\". \"Anything\" here is ничего."}}]}'::jsonb, 10, 8),
  ('b1-04', 'B1', 'emotions', 4, 'Feelings', 'Чувства', 'Say how you feel, ask what happened and comfort someone.', '{"intro":"Russian expresses many feelings as \"it is (sad) to me\": мне грустно. Others use verbs ending in -ся: волноваться, злиться.","sections":[{"type":"lines","kind":"phrases","title":"How do you feel?","lines":[{"ru":"Я так рад тебя видеть!","en":"I''m so happy to see you!","words":[{"ru":"Я","en":"I"},{"ru":"так","en":"so"},{"ru":"рад","f":"рада","en":"glad"},{"ru":"тебя","en":"you"},{"ru":"видеть!","en":"to see"}],"ruF":"Я так рада тебя видеть!"},{"ru":"Мне грустно.","en":"I feel sad.","words":[{"ru":"Мне","en":"to me"},{"ru":"грустно.","en":"sad"}]},{"ru":"Я волнуюсь из-за экзамена.","en":"I''m nervous about the exam.","words":[{"ru":"Я","en":"I"},{"ru":"волнуюсь","en":"am nervous"},{"ru":"из-за","en":"because of"},{"ru":"экзамена.","en":"the exam"}]},{"ru":"Не волнуйся, всё будет хорошо.","en":"Don''t worry, everything will be fine.","words":[{"ru":"Не","en":"don''t"},{"ru":"волнуйся,","en":"worry"},{"ru":"всё","en":"everything"},{"ru":"будет","en":"will be"},{"ru":"хорошо.","en":"fine"}]},{"ru":"Я злюсь на себя.","en":"I''m angry at myself.","words":[{"ru":"Я","en":"I"},{"ru":"злюсь","en":"am angry"},{"ru":"на","en":"at"},{"ru":"себя.","en":"myself"}]},{"ru":"Мне стыдно.","en":"I''m embarrassed.","words":[{"ru":"Мне","en":"to me"},{"ru":"стыдно.","en":"ashamed"}]},{"ru":"Я в восторге!","en":"I''m thrilled!","words":[{"ru":"Я","en":"I"},{"ru":"в","en":"in"},{"ru":"восторге!","en":"delight"}]},{"ru":"Что случилось?","en":"What happened?","words":[{"ru":"Что","en":"what"},{"ru":"случилось?","en":"happened"}]},{"ru":"Ты выглядишь расстроенным.","en":"You look upset.","words":[{"ru":"Ты","en":"you"},{"ru":"выглядишь","en":"look"},{"ru":"расстроенным.","f":"расстроенной.","en":"upset"}],"ruF":"Ты выглядишь расстроенной.","note":"Выглядеть takes the instrumental, so the adjective agrees: расстроенным (m), расстроенной (f)."},{"ru":"Я тебя понимаю.","en":"I understand how you feel.","words":[{"ru":"Я","en":"I"},{"ru":"тебя","en":"you"},{"ru":"понимаю.","en":"understand"}]}]},{"type":"grammar","title":"Two ways to feel","paragraphs":["**Dative + adverb** for states: мне грустно, весело, скучно, стыдно, страшно, обидно.","**Reflexive verbs** for emotions you experience: я волнуюсь, я злюсь, я радуюсь.","**Из-за** + genitive gives a (usually negative) cause: из-за экзамена, из-за погоды."],"examples":[{"ru":"Мне скучно.","en":"I''m bored."},{"ru":"Не злись на меня!","en":"Don''t be angry with me!"}]}],"drills":[{"q":"Мне ___. (I''m bored)","answer":"скучно","options":["скука","скучать","скучно","скучный"],"en":"I''m bored.","why":{"скучный":"Скучный is an adjective (\"a boring film\"). Feelings with мне use the -о form: мне скучно.","скучать":"Скучать is a verb (я скучаю — I miss, I''m bored). With мне use скучно.","скука":"Скука is the noun \"boredom\". \"I''m bored\" is мне скучно."}},{"q":"Я волнуюсь из-за ___.","answer":"экзамена","options":["экзамену","экзаменом","экзамена","экзамен"],"en":"I''m nervous about the exam.","why":{"экзамен":"Из-за takes the genitive: из-за экзамена.","экзаменом":"Экзаменом is the instrumental (перед экзаменом). Из-за needs экзамена.","экзамену":"Экзамену is the dative. Из-за needs экзамена."}},{"q":"Не ___, всё будет хорошо.","answer":"волнуйся","options":["волнуется","волнуюсь","волноваться","волнуйся"],"en":"Don''t worry, everything will be fine.","why":{"волнуюсь":"Волнуюсь is \"I worry\". A command to ты is волнуйся.","волнуется":"Волнуется is \"he/she worries\". A command to ты is волнуйся.","волноваться":"Волноваться is the infinitive. A command to ты is волнуйся."}},{"q":"Что ___?","answer":"случилось","options":["случай","случился","случилось","случаться"],"en":"What happened?","why":{"случился":"Случился is masculine. With что, use the neuter: случилось.","случай":"Случай is the noun \"case, incident\". \"What happened?\" is Что случилось?","случаться":"Случаться is the infinitive. \"What happened?\" is Что случилось?"}}]}'::jsonb, 10, 11),
  ('b1-05', 'B1', 'work', 5, 'Work and careers', 'Работа и карьера', 'Talk about your job, meetings, deadlines and career plans.', '{"intro":"To say what you do for a living, use работать + instrumental: работаю менеджером, учителем, врачом.","sections":[{"type":"lines","kind":"phrases","title":"At work","lines":[{"ru":"Кем ты работаешь?","en":"What do you do for a living?","words":[{"ru":"Кем","en":"as what"},{"ru":"ты","en":"you"},{"ru":"работаешь?","en":"work"}]},{"ru":"Я работаю менеджером в крупной компании.","en":"I work as a manager at a large company.","words":[{"ru":"Я","en":"I"},{"ru":"работаю","en":"work"},{"ru":"менеджером","en":"as a manager"},{"ru":"в","en":"in"},{"ru":"крупной","en":"large"},{"ru":"компании.","en":"company"}]},{"ru":"Мне предложили новую должность.","en":"I''ve been offered a new position.","words":[{"ru":"Мне","en":"to me"},{"ru":"предложили","en":"(they) offered"},{"ru":"новую","en":"new"},{"ru":"должность.","en":"position"}]},{"ru":"У меня завтра собеседование.","en":"I have a job interview tomorrow.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"завтра","en":"tomorrow"},{"ru":"собеседование.","en":"interview"}]},{"ru":"У нас совещание в десять.","en":"We have a meeting at ten.","words":[{"ru":"У","en":"by"},{"ru":"нас","en":"us"},{"ru":"совещание","en":"meeting"},{"ru":"в","en":"at"},{"ru":"десять.","en":"ten"}]},{"ru":"Мне нужно закончить проект до пятницы.","en":"I need to finish the project by Friday.","words":[{"ru":"Мне","en":"to me"},{"ru":"нужно","en":"need"},{"ru":"закончить","en":"to finish"},{"ru":"проект","en":"the project"},{"ru":"до","en":"by"},{"ru":"пятницы.","en":"Friday"}]},{"ru":"Мой начальник очень строгий.","en":"My boss is very strict.","words":[{"ru":"Мой","en":"my"},{"ru":"начальник","en":"boss"},{"ru":"очень","en":"very"},{"ru":"строгий.","en":"strict"}]},{"ru":"Мне нравится моя работа, но я много работаю.","en":"I like my job, but I work a lot.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравится","en":"like"},{"ru":"моя","en":"my"},{"ru":"работа,","en":"job"},{"ru":"но","en":"but"},{"ru":"я","en":"I"},{"ru":"много","en":"a lot"},{"ru":"работаю.","en":"work"}]},{"ru":"Я хочу сменить работу.","en":"I want to change jobs.","words":[{"ru":"Я","en":"I"},{"ru":"хочу","en":"want"},{"ru":"сменить","en":"to change"},{"ru":"работу.","en":"jobs"}]},{"ru":"Я работаю удалённо.","en":"I work remotely.","words":[{"ru":"Я","en":"I"},{"ru":"работаю","en":"work"},{"ru":"удалённо.","en":"remotely"}]},{"ru":"Коллеги мне помогают.","en":"My colleagues help me.","words":[{"ru":"Коллеги","en":"colleagues"},{"ru":"мне","en":"me"},{"ru":"помогают.","en":"help"}]}]},{"type":"grammar","title":"Профессия and \"they\"","paragraphs":["**Работать** + instrumental: работать программист**ом**, учител**ем**, медсестр**ой**. The question is **Кем ты работаешь?**","Russian often uses an unnamed \"they\" instead of the passive: **мне предложили** = \"I was offered\", **мне сказали** = \"I was told\"."],"examples":[{"ru":"Она работает врачом.","en":"She works as a doctor."},{"ru":"Нам сказали, что совещание перенесли.","en":"We were told the meeting was moved."}]}],"drills":[{"q":"___ ты работаешь?","answer":"Кем","options":["Как","Кем","Кто","Где"],"en":"What do you do for a living?","why":{"Кто":"A job after работать is in the instrumental (работать кем?), so the question is Кем.","Как":"Как is \"how\". To ask about someone''s job: Кем ты работаешь?","Где":"Где is \"where\" — the answer would be a place. For a job title: Кем."}},{"q":"Я работаю ___. (менеджер)","answer":"менеджером","options":["менеджера","менеджером","менеджеру","менеджер"],"en":"I work as a manager.","why":{"менеджер":"Работать (as a job) takes the instrumental: работаю менеджером.","менеджера":"Менеджера is the genitive or accusative. Работать needs менеджером.","менеджеру":"Менеджеру is the dative. Работать needs менеджером."}},{"q":"Мне ___ новую должность.","answer":"предложили","options":["предложил","предлагаю","предложить","предложили"],"en":"I''ve been offered a new position.","why":{"предложил":"Предложил is \"he offered\" and needs a subject. With no subject (\"they offered\", meaning \"I was offered\"): предложили.","предлагаю":"Предлагаю is \"I offer\" (present). \"I was offered\" is мне предложили.","предложить":"Предложить is the infinitive. \"I was offered\" is мне предложили."}},{"q":"Мне нужно закончить проект до ___.","answer":"пятницы","options":["пятницей","пятница","пятницу","пятницы"],"en":"I need to finish the project by Friday.","why":{"пятница":"До takes the genitive: до пятницы.","пятницу":"Пятницу is the accusative (в пятницу, \"on Friday\"). До needs пятницы.","пятницей":"Пятницей is the instrumental (перед пятницей). До needs пятницы."}}]}'::jsonb, 11, 12),
  ('b1-06', 'B1', 'dating', 6, 'Dating and communication', 'Свидания и общение', 'Invite someone out, say you like them and keep the conversation warm.', '{"intro":"«Ты мне нравишься» — \"you are pleasing to me\" — is how Russians say \"I like you\" romantically. The roles are reversed compared with English.","sections":[{"type":"lines","kind":"phrases","title":"Getting closer","lines":[{"ru":"Можно пригласить тебя на ужин?","en":"May I take you out to dinner?","words":[{"ru":"Можно","en":"may I"},{"ru":"пригласить","en":"invite"},{"ru":"тебя","en":"you"},{"ru":"на","en":"to"},{"ru":"ужин?","en":"dinner"}]},{"ru":"С удовольствием. Когда тебе удобно?","en":"I''d love to. When works for you?","words":[{"ru":"С","en":"with"},{"ru":"удовольствием.","en":"pleasure"},{"ru":"Когда","en":"when"},{"ru":"тебе","en":"for you"},{"ru":"удобно?","en":"convenient"}]},{"ru":"Мне с тобой интересно.","en":"I really enjoy talking with you.","words":[{"ru":"Мне","en":"to me"},{"ru":"с","en":"with"},{"ru":"тобой","en":"you"},{"ru":"интересно.","en":"interesting"}]},{"ru":"Ты мне нравишься.","en":"I like you.","words":[{"ru":"Ты","en":"you"},{"ru":"мне","en":"to me"},{"ru":"нравишься.","en":"are pleasing"}],"note":"Literally \"you are pleasing to me\"."},{"ru":"Я тебе нравлюсь?","en":"Do you like me?","words":[{"ru":"Я","en":"I"},{"ru":"тебе","en":"to you"},{"ru":"нравлюсь?","en":"am pleasing"}]},{"ru":"Давай ещё встретимся.","en":"Let''s see each other again.","words":[{"ru":"Давай","en":"let''s"},{"ru":"ещё","en":"again"},{"ru":"встретимся.","en":"meet"}]},{"ru":"Мне кажется, нам нужно поговорить.","en":"I think we need to talk.","words":[{"ru":"Мне","en":"to me"},{"ru":"кажется,","en":"it seems"},{"ru":"нам","en":"we"},{"ru":"нужно","en":"need"},{"ru":"поговорить.","en":"to talk"}]},{"ru":"Я скучаю по тебе.","en":"I miss you.","words":[{"ru":"Я","en":"I"},{"ru":"скучаю","en":"miss"},{"ru":"по","en":"—"},{"ru":"тебе.","en":"you"}],"note":"Скучать по + dative: скучаю по тебе, по дому."},{"ru":"Спасибо за чудесный вечер!","en":"Thank you for a wonderful evening!","words":[{"ru":"Спасибо","en":"thanks"},{"ru":"за","en":"for"},{"ru":"чудесный","en":"wonderful"},{"ru":"вечер!","en":"evening"}]},{"ru":"Напиши, когда доедешь.","en":"Text me when you get home.","words":[{"ru":"Напиши,","en":"text me"},{"ru":"когда","en":"when"},{"ru":"доедешь.","en":"you get home"}],"note":"A caring Russian goodbye: let me know you got there safely."}]},{"type":"grammar","title":"Who likes whom","paragraphs":["With **нравиться**, the person who likes is in the dative and the person liked is the subject:","**ты** мне нравишься (I like you) · **я** тебе нравлюсь? (do you like me?) · **она** ему нравится (he likes her).","**Пригласить** + accusative + **на** + accusative: пригласить тебя на ужин, на свидание."],"examples":[{"ru":"Он мне очень нравится.","en":"I really like him."},{"ru":"Я скучаю по родителям.","en":"I miss my parents."}]}],"drills":[{"q":"Ты мне ___.","answer":"нравишься","options":["нравишься","нравятся","нравлюсь","нравится"],"en":"I like you.","why":{"нравлюсь":"Нравлюсь is \"I am liked\" and goes with я (я тебе нравлюсь). With ты: нравишься.","нравится":"Нравится is the он/она/оно form. With ты: нравишься.","нравятся":"Нравятся is plural. With ты: нравишься."}},{"q":"Я скучаю по ___.","answer":"тебе","options":["тебе","тобой","тебя","ты"],"en":"I miss you.","why":{"тебя":"Тебя is the genitive or accusative. Скучать по takes the dative: по тебе.","ты":"Ты is the subject form. Скучать по needs тебе.","тобой":"Тобой is the instrumental (с тобой). Скучать по needs тебе."}},{"q":"Можно пригласить тебя на ___?","answer":"ужин","options":["ужина","ужин","ужине","ужином"],"en":"May I invite you to dinner?","why":{"ужина":"Ужина is the genitive. Inviting to an event is на + accusative: на ужин.","ужине":"На ужине means \"at dinner\". Inviting someone to dinner is на ужин.","ужином":"Ужином is the instrumental (за ужином, \"over dinner\"). Inviting is на ужин."}},{"q":"Спасибо за ___ вечер!","answer":"чудесный","options":["чудесная","чудесного","чудесным","чудесный"],"en":"Thank you for a wonderful evening!","why":{"чудесного":"Чудесного is genitive (or for living things). Вечер isn''t alive, so after за it keeps the plain form: чудесный.","чудесным":"Чудесным is the instrumental. За (\"for\") takes the accusative: чудесный.","чудесная":"Чудесная is feminine. Вечер is masculine: чудесный."}}]}'::jsonb, 10, 6),
  ('b1-07', 'B1', 'movies', 7, 'Movies and entertainment', 'Кино и развлечения', 'Discuss films and series — genres, plot, actors and what you thought.', '{"intro":"In the past tense, понравиться agrees with the thing you liked: мне понравился фильм, мне понравилась книга.","sections":[{"type":"lines","kind":"phrases","title":"Talking about films","lines":[{"ru":"Какие фильмы тебе нравятся?","en":"What kind of movies do you like?","words":[{"ru":"Какие","en":"what kind of"},{"ru":"фильмы","en":"films"},{"ru":"тебе","en":"to you"},{"ru":"нравятся?","en":"appeal"}]},{"ru":"Мне нравятся комедии и детективы.","en":"I like comedies and crime dramas.","words":[{"ru":"Мне","en":"to me"},{"ru":"нравятся","en":"appeal"},{"ru":"комедии","en":"comedies"},{"ru":"и","en":"and"},{"ru":"детективы.","en":"crime dramas"}]},{"ru":"Этот фильм основан на реальных событиях.","en":"This film is based on true events.","words":[{"ru":"Этот","en":"this"},{"ru":"фильм","en":"film"},{"ru":"основан","en":"is based"},{"ru":"на","en":"on"},{"ru":"реальных","en":"real"},{"ru":"событиях.","en":"events"}]},{"ru":"Кто играет главную роль?","en":"Who plays the lead?","words":[{"ru":"Кто","en":"who"},{"ru":"играет","en":"plays"},{"ru":"главную","en":"the lead"},{"ru":"роль?","en":"role"}]},{"ru":"Сюжет очень захватывающий.","en":"The plot is really gripping.","words":[{"ru":"Сюжет","en":"the plot"},{"ru":"очень","en":"very"},{"ru":"захватывающий.","en":"gripping"}]},{"ru":"Мне не понравился конец.","en":"I didn''t like the ending.","words":[{"ru":"Мне","en":"to me"},{"ru":"не","en":"not"},{"ru":"понравился","en":"appealed"},{"ru":"конец.","en":"the ending"}]},{"ru":"Давай посмотрим что-нибудь на выходных.","en":"Let''s watch something this weekend.","words":[{"ru":"Давай","en":"let''s"},{"ru":"посмотрим","en":"watch"},{"ru":"что-нибудь","en":"something"},{"ru":"на","en":"on"},{"ru":"выходных.","en":"the weekend"}]},{"ru":"Ты смотрел этот сериал?","en":"Have you watched this series?","words":[{"ru":"Ты","en":"you"},{"ru":"смотрел","f":"смотрела","en":"watched"},{"ru":"этот","en":"this"},{"ru":"сериал?","en":"series"}],"ruF":"Ты смотрела этот сериал?"},{"ru":"Не рассказывай, я ещё не досмотрел!","en":"Don''t tell me — I haven''t finished it yet!","words":[{"ru":"Не","en":"don''t"},{"ru":"рассказывай,","en":"tell"},{"ru":"я","en":"I"},{"ru":"ещё","en":"still"},{"ru":"не","en":"not"},{"ru":"досмотрел!","f":"досмотрела!","en":"finished watching"}],"ruF":"Не рассказывай, я ещё не досмотрела!"}]},{"type":"grammar","title":"Понравился, понравилась…","paragraphs":["The past tense of **(по)нравиться** agrees with the thing liked, not with you:","мне понравил**ся** фильм · мне понравил**ась** книга · мне понравил**ось** кино · мне понравил**ись** актёры."],"examples":[{"ru":"Тебе понравилась музыка?","en":"Did you like the music?"},{"ru":"Нам очень понравился спектакль.","en":"We really enjoyed the play."}]}],"drills":[{"q":"Мне не ___ конец.","answer":"понравился","options":["понравились","понравился","понравилась","понравилось"],"en":"I didn''t like the ending.","why":{"понравилась":"Понравилась is feminine. Конец is masculine: понравился.","понравилось":"Понравилось is neuter. Конец is masculine: понравился.","понравились":"Понравились is plural. One конец: понравился."}},{"q":"Тебе ___ книга?","answer":"понравилась","options":["понравились","понравилась","понравился","понравилось"],"en":"Did you like the book?","why":{"понравился":"Понравился is masculine. Книга is feminine: понравилась.","понравилось":"Понравилось is neuter. Книга is feminine: понравилась.","понравились":"Понравились is plural. One книга: понравилась."}},{"q":"Фильм основан на реальных ___.","answer":"событиях","options":["событий","событиях","события","событиями"],"en":"The film is based on true events.","why":{"события":"Основан на takes the prepositional: на реальных событиях.","событий":"Событий is the genitive plural. Основан на needs событиях.","событиями":"Событиями is the instrumental. Основан на needs событиях."}},{"q":"Кто играет главную ___?","answer":"роль","options":["роли","ролей","роль","ролью"],"en":"Who plays the lead?","why":{"роли":"Роли is the genitive or plural. Играть takes the accusative, which for роль is just роль.","ролью":"Ролью is the instrumental. The object of играть is роль.","ролей":"Ролей is the genitive plural. One role: роль."}}]}'::jsonb, 9, 11),
  ('b1-08', 'B1', 'money', 8, 'Money', 'Деньги', 'Pay, borrow, save and talk about prices without awkwardness.', '{"intro":"Russian has a lovely idiom for \"I can''t afford it\": «Это мне не по карману» — \"it doesn''t fit my pocket\".","sections":[{"type":"lines","kind":"phrases","title":"Money talk","lines":[{"ru":"Я коплю на отпуск.","en":"I''m saving up for a vacation.","words":[{"ru":"Я","en":"I"},{"ru":"коплю","en":"am saving"},{"ru":"на","en":"for"},{"ru":"отпуск.","en":"a vacation"}]},{"ru":"Это мне не по карману.","en":"I can''t afford it.","words":[{"ru":"Это","en":"this"},{"ru":"мне","en":"to me"},{"ru":"не","en":"not"},{"ru":"по","en":"within"},{"ru":"карману.","en":"pocket"}]},{"ru":"Можно заплатить наличными?","en":"Can I pay in cash?","words":[{"ru":"Можно","en":"may I"},{"ru":"заплатить","en":"pay"},{"ru":"наличными?","en":"in cash"}]},{"ru":"Сколько с меня?","en":"How much do I owe?","words":[{"ru":"Сколько","en":"how much"},{"ru":"с","en":"from"},{"ru":"меня?","en":"me"}]},{"ru":"Я забыл кошелёк дома.","en":"I left my wallet at home.","words":[{"ru":"Я","en":"I"},{"ru":"забыл","f":"забыла","en":"forgot"},{"ru":"кошелёк","en":"wallet"},{"ru":"дома.","en":"at home"}],"ruF":"Я забыла кошелёк дома."},{"ru":"Одолжи мне, пожалуйста, тысячу рублей.","en":"Could you lend me a thousand rubles?","words":[{"ru":"Одолжи","en":"lend"},{"ru":"мне,","en":"me"},{"ru":"пожалуйста,","en":"please"},{"ru":"тысячу","en":"a thousand"},{"ru":"рублей.","en":"rubles"}]},{"ru":"Я верну завтра.","en":"I''ll pay you back tomorrow.","words":[{"ru":"Я","en":"I"},{"ru":"верну","en":"will return"},{"ru":"завтра.","en":"tomorrow"}]},{"ru":"Цены выросли.","en":"Prices have gone up.","words":[{"ru":"Цены","en":"prices"},{"ru":"выросли.","en":"have risen"}]},{"ru":"Здесь есть банкомат?","en":"Is there an ATM here?","words":[{"ru":"Здесь","en":"here"},{"ru":"есть","en":"is there"},{"ru":"банкомат?","en":"an ATM"}]},{"ru":"Я слежу за своими расходами.","en":"I keep track of my spending.","words":[{"ru":"Я","en":"I"},{"ru":"слежу","en":"keep track"},{"ru":"за","en":"of"},{"ru":"своими","en":"my own"},{"ru":"расходами.","en":"expenses"}]}]},{"type":"grammar","title":"Useful money verbs","paragraphs":["**Копить на** + accusative = \"save up for\": копить на машину. **Платить / заплатить** + instrumental for the means: картой, наличными.","**Следить за** + instrumental = \"keep an eye on\": следить за расходами, за ценами."],"examples":[{"ru":"Мы копим на квартиру.","en":"We''re saving up for an apartment."},{"ru":"Я заплачу картой.","en":"I''ll pay by card."}]}],"drills":[{"q":"Я коплю на ___.","answer":"отпуск","options":["отпуск","отпуска","отпуске","отпуском"],"en":"I''m saving for a vacation.","why":{"отпуска":"Отпуска is the genitive. Saving for something is копить на + accusative: на отпуск.","отпуском":"Отпуском is the instrumental. Saving for it: на отпуск.","отпуске":"В отпуске means \"on vacation\". Saving for one is копить на отпуск."}},{"q":"Это мне не по ___.","answer":"карману","options":["кармана","карман","карманом","карману"],"en":"I can''t afford it.","why":{"карман":"The idiom is не по карману (\"not for my pocket\"), with по + dative.","кармана":"Кармана is the genitive. The idiom is не по карману.","карманом":"Карманом is the instrumental. The idiom is не по карману."}},{"q":"Можно заплатить ___? (in cash)","answer":"наличными","options":["наличными","наличных","наличные","наличным"],"en":"Can I pay in cash?","why":{"наличные":"Paying with something uses the instrumental: платить наличными.","наличных":"Наличных is the genitive. Paying with it: наличными.","наличным":"Наличным is the dative. Paying with it: наличными."}},{"q":"Я слежу за своими ___.","answer":"расходами","options":["расходам","расходы","расходов","расходами"],"en":"I keep track of my spending.","why":{"расходы":"Следить за takes the instrumental: за своими расходами.","расходов":"Расходов is the genitive. Следить за needs расходами.","расходам":"Расходам is the dative. Следить за needs расходами."}}]}'::jsonb, 10, 10),
  ('b1-09', 'B1', 'problems', 9, 'Problems and disagreements', 'Проблемы и споры', 'Disagree, apologise, clear up a misunderstanding and make peace.', '{"intro":"Arguments happen in every language. Here you''ll learn to defend your view, admit a mistake and move on gracefully.","sections":[{"type":"lines","kind":"phrases","title":"Working it out","lines":[{"ru":"Мне кажется, ты не прав.","en":"I think you''re wrong.","words":[{"ru":"Мне","en":"to me"},{"ru":"кажется,","en":"it seems"},{"ru":"ты","en":"you"},{"ru":"не","en":"not"},{"ru":"прав.","f":"права.","en":"right"}],"ruF":"Мне кажется, ты не права."},{"ru":"Давай не будем ссориться.","en":"Let''s not argue.","words":[{"ru":"Давай","en":"let''s"},{"ru":"не","en":"not"},{"ru":"будем","en":"—"},{"ru":"ссориться.","en":"quarrel"}]},{"ru":"Извини, я не хотел тебя обидеть.","en":"Sorry, I didn''t mean to offend you.","words":[{"ru":"Извини,","en":"sorry"},{"ru":"я","en":"I"},{"ru":"не","en":"not"},{"ru":"хотел","f":"хотела","en":"meant"},{"ru":"тебя","en":"you"},{"ru":"обидеть.","en":"to offend"}],"ruF":"Извини, я не хотела тебя обидеть."},{"ru":"Ты меня не так понял.","en":"You''ve misunderstood me.","words":[{"ru":"Ты","en":"you"},{"ru":"меня","en":"me"},{"ru":"не","en":"not"},{"ru":"так","en":"right"},{"ru":"понял.","f":"поняла.","en":"understood"}],"ruF":"Ты меня не так поняла."},{"ru":"Я имел в виду другое.","en":"I meant something else.","words":[{"ru":"Я","en":"I"},{"ru":"имел","f":"имела","en":"had"},{"ru":"в","en":"in"},{"ru":"виду","en":"view"},{"ru":"другое.","en":"something else"}],"ruF":"Я имела в виду другое."},{"ru":"Это не моя вина.","en":"It''s not my fault.","words":[{"ru":"Это","en":"it''s"},{"ru":"не","en":"not"},{"ru":"моя","en":"my"},{"ru":"вина.","en":"fault"}]},{"ru":"Давай найдём компромисс.","en":"Let''s find a compromise.","words":[{"ru":"Давай","en":"let''s"},{"ru":"найдём","en":"find"},{"ru":"компромисс.","en":"a compromise"}]},{"ru":"Меня это раздражает.","en":"That annoys me.","words":[{"ru":"Меня","en":"me"},{"ru":"это","en":"this"},{"ru":"раздражает.","en":"irritates"}]},{"ru":"Я готов обсудить это спокойно.","en":"I''m ready to talk about it calmly.","words":[{"ru":"Я","en":"I"},{"ru":"готов","f":"готова","en":"ready"},{"ru":"обсудить","en":"to discuss"},{"ru":"это","en":"it"},{"ru":"спокойно.","en":"calmly"}],"ruF":"Я готова обсудить это спокойно."},{"ru":"Ладно, проехали.","en":"Okay, let''s drop it.","words":[{"ru":"Ладно,","en":"okay"},{"ru":"проехали.","en":"moving on"}],"note":"Проехали — colloquial \"let''s move on\", literally \"we''ve driven past\"."}]},{"type":"grammar","title":"Clearing things up","paragraphs":["**Иметь в виду** = \"to mean\": я имел в виду другое. **Не так понять** = \"to misunderstand\".","**Давай не будем** + imperfective infinitive = \"let''s not…\": давай не будем спорить."],"examples":[{"ru":"Что ты имеешь в виду?","en":"What do you mean?"},{"ru":"Давай не будем об этом.","en":"Let''s not talk about that."}]}],"drills":[{"q":"Давай не будем ___.","answer":"ссориться","options":["ссорились","ссориться","ссора","поссоримся"],"en":"Let''s not argue.","why":{"поссоримся":"Поссоримся is \"we''ll fall out\". After не будем, use an infinitive: ссориться.","ссорились":"Ссорились is past. After не будем, use an infinitive: ссориться.","ссора":"Ссора is the noun \"a quarrel\". After не будем, use the verb: ссориться."}},{"q":"Я имел в ___ другое.","answer":"виду","options":["видом","виду","вид","виде"],"en":"I meant something else.","why":{"вид":"The fixed phrase is иметь в виду (\"to mean\").","виде":"В виде means \"in the form of\". \"I meant\" is имел в виду.","видом":"Видом is the instrumental. The fixed phrase is иметь в виду."}},{"q":"Это не моя ___.","answer":"вина","options":["вины","вина","вину","виной"],"en":"It''s not my fault.","why":{"вину":"Вину is the accusative (an object). Here вина is the subject: моя вина.","вины":"Вины is the genitive. As the subject: вина.","виной":"Виной is the instrumental. With моя, use вина."}},{"q":"Ты меня не так ___.","answer":"понял","options":["понял","понять","понимаю","понятно"],"en":"You misunderstood me.","why":{"понимаю":"Понимаю is \"I understand\" (я, present). \"You understood\" to a man is понял.","понять":"Понять is the infinitive. \"You understood\" is ты понял.","понятно":"Понятно means \"it''s clear\". \"You understood\" is ты понял."}}]}'::jsonb, 10, 5),
  ('b1-10', 'B1', 'grammar', 10, 'If…', 'Если бы…', 'Make real and hypothetical conditions — in life and at the board.', '{"intro":"Russian uses one simple pattern for \"if I had…\" and \"if I had had…\": если бы + past tense, then бы + past tense.","sections":[{"type":"lines","kind":"phrases","title":"Conditions","lines":[{"ru":"Если ты пойдёшь конём, я возьму ладью.","en":"If you move your knight, I''ll take the rook.","words":[{"ru":"Если","en":"if"},{"ru":"ты","en":"you"},{"ru":"пойдёшь","en":"go"},{"ru":"конём,","en":"with the knight"},{"ru":"я","en":"I"},{"ru":"возьму","en":"will take"},{"ru":"ладью.","en":"the rook"}]},{"ru":"Если будет дождь, мы останемся дома.","en":"If it rains, we''ll stay home.","words":[{"ru":"Если","en":"if"},{"ru":"будет","en":"it will be"},{"ru":"дождь,","en":"rain"},{"ru":"мы","en":"we"},{"ru":"останемся","en":"will stay"},{"ru":"дома.","en":"at home"}]},{"ru":"Если бы у меня было время, я бы поехал в Россию.","en":"If I had time, I''d go to Russia.","words":[{"ru":"Если","en":"if"},{"ru":"бы","en":"—"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"было","en":"was"},{"ru":"время,","en":"time"},{"ru":"я","en":"I"},{"ru":"бы","en":"would"},{"ru":"поехал","f":"поехала","en":"go"},{"ru":"в","en":"to"},{"ru":"Россию.","en":"Russia"}],"ruF":"Если бы у меня было время, я бы поехала в Россию."},{"ru":"Если бы ты взял пешку, ты бы выиграл.","en":"If you''d taken the pawn, you would have won.","words":[{"ru":"Если","en":"if"},{"ru":"бы","en":"—"},{"ru":"ты","en":"you"},{"ru":"взял","f":"взяла","en":"took"},{"ru":"пешку,","en":"the pawn"},{"ru":"ты","en":"you"},{"ru":"бы","en":"would"},{"ru":"выиграл.","f":"выиграла.","en":"have won"}],"ruF":"Если бы ты взяла пешку, ты бы выиграла."},{"ru":"На твоём месте я бы не торопился.","en":"If I were you, I wouldn''t rush.","words":[{"ru":"На","en":"in"},{"ru":"твоём","en":"your"},{"ru":"месте","en":"place"},{"ru":"я","en":"I"},{"ru":"бы","en":"would"},{"ru":"не","en":"not"},{"ru":"торопился.","f":"торопилась.","en":"hurry"}],"ruF":"На твоём месте я бы не торопилась."},{"ru":"Что бы ты сделал?","en":"What would you do?","words":[{"ru":"Что","en":"what"},{"ru":"бы","en":"would"},{"ru":"ты","en":"you"},{"ru":"сделал?","f":"сделала?","en":"do"}],"ruF":"Что бы ты сделала?"},{"ru":"Если хочешь, приходи.","en":"Come over if you want.","words":[{"ru":"Если","en":"if"},{"ru":"хочешь,","en":"you want"},{"ru":"приходи.","en":"come"}]}]},{"type":"grammar","title":"Real and unreal","paragraphs":["**Real:** если + future → future. Если пойдёт дождь, мы останемся дома.","**Unreal:** если **бы** + past → **бы** + past. The same form covers \"if I had\" and \"if I had had\": если бы я знал, я бы сказал = \"if I knew, I''d tell\" or \"if I''d known, I''d have told\".","**На твоём месте** = \"in your place / if I were you\"."],"examples":[{"ru":"Если бы я знал, я бы позвонил.","en":"If I''d known, I would have called."},{"ru":"Я бы на твоём месте отдохнул.","en":"If I were you, I''d get some rest."}]}],"drills":[{"q":"Если ___ у меня было время, я бы поехал.","answer":"бы","options":["бы","был","будет","будь"],"en":"If I had time, I''d go.","why":{"будет":"Будет is \"will be\" — a real future condition. This one is imaginary (я бы поехал), so: если бы.","был":"Был is \"was\". An imaginary condition needs бы.","будь":"Будь is the command \"be!\". An imaginary condition needs бы."}},{"q":"Если будет дождь, мы ___ дома.","answer":"останемся","options":["оставались","останемся","остаёмся","остались"],"en":"If it rains, we''ll stay home.","why":{"остались":"Остались is past. A real future condition (если будет) needs the future: останемся.","остаёмся":"Остаёмся is present. The result of a future condition is future: останемся.","оставались":"Оставались is past. The result here is future: останемся."}},{"q":"На твоём ___ я бы не торопился.","answer":"месте","options":["месте","место","места","местом"],"en":"If I were you, I wouldn''t rush.","why":{"место":"The fixed phrase is на твоём месте (\"in your place\"), with the prepositional.","места":"Места is the genitive. The phrase is на твоём месте.","местом":"Местом is the instrumental. The phrase is на твоём месте."}},{"q":"Если бы ты взял пешку, ты бы ___.","answer":"выиграл","options":["выиграть","выиграешь","выигрываешь","выиграл"],"en":"If you''d taken the pawn, you''d have won.","why":{"выиграешь":"Выиграешь is future. After бы, use the past form: ты бы выиграл.","выигрываешь":"Выигрываешь is present. After бы, use the past form: выиграл.","выиграть":"Выиграть is the infinitive. After бы, use the past form: выиграл."}}]}'::jsonb, 7, 2),
  ('b1-11', 'B1', 'grammar', 11, 'Verbs of motion', 'Глаголы движения', 'Choose between идти and ходить, ехать and ездить — and use prefixes to say exactly where.', '{"intro":"Russian distinguishes one trip in one direction (идти, ехать) from repeated or round trips (ходить, ездить). Prefixes add the direction: in, out, across, up to.","sections":[{"type":"lines","kind":"phrases","title":"Coming and going","lines":[{"ru":"Я иду в магазин.","en":"I''m on my way to the store.","words":[{"ru":"Я","en":"I"},{"ru":"иду","en":"am walking"},{"ru":"в","en":"to"},{"ru":"магазин.","en":"the store"}]},{"ru":"Я часто хожу в этот клуб.","en":"I often go to this club.","words":[{"ru":"Я","en":"I"},{"ru":"часто","en":"often"},{"ru":"хожу","en":"go"},{"ru":"в","en":"to"},{"ru":"этот","en":"this"},{"ru":"клуб.","en":"club"}]},{"ru":"Мы едем на дачу.","en":"We''re driving to the dacha.","words":[{"ru":"Мы","en":"we"},{"ru":"едем","en":"are driving"},{"ru":"на","en":"to"},{"ru":"дачу.","en":"the dacha"}]},{"ru":"Каждое лето мы ездим на море.","en":"Every summer we go to the seaside.","words":[{"ru":"Каждое","en":"every"},{"ru":"лето","en":"summer"},{"ru":"мы","en":"we"},{"ru":"ездим","en":"go"},{"ru":"на","en":"to"},{"ru":"море.","en":"the sea"}]},{"ru":"Он вышел из дома.","en":"He left the house.","words":[{"ru":"Он","en":"he"},{"ru":"вышел","en":"went out"},{"ru":"из","en":"of"},{"ru":"дома.","en":"the house"}]},{"ru":"Она пришла домой поздно.","en":"She came home late.","words":[{"ru":"Она","en":"she"},{"ru":"пришла","en":"came"},{"ru":"домой","en":"home"},{"ru":"поздно.","en":"late"}]},{"ru":"Заходи в гости!","en":"Come over sometime!","words":[{"ru":"Заходи","en":"drop in"},{"ru":"в","en":"as"},{"ru":"гости!","en":"a guest"}]},{"ru":"Конь перешёл на другой фланг.","en":"The knight switched to the other flank.","words":[{"ru":"Конь","en":"the knight"},{"ru":"перешёл","en":"went across"},{"ru":"на","en":"to"},{"ru":"другой","en":"the other"},{"ru":"фланг.","en":"flank"}]},{"ru":"Мы подъезжаем к Москве.","en":"We''re approaching Moscow.","words":[{"ru":"Мы","en":"we"},{"ru":"подъезжаем","en":"are approaching"},{"ru":"к","en":"to"},{"ru":"Москве.","en":"Moscow"}]}]},{"type":"grammar","title":"One way or many","paragraphs":["**Идти / ехать** — one direction, right now or on a specific trip. **Ходить / ездить** — habitual, repeated or round trips.","Prefixes (with the one-way verb for perfective forms): **в-** in (войти), **вы-** out (выйти), **при-** arrive (прийти), **у-** leave (уйти), **пере-** across (перейти), **под-** approach (подойти), **за-** drop by (зайти)."],"examples":[{"ru":"Завтра я иду в театр.","en":"Tomorrow I''m going to the theater."},{"ru":"Я хожу в театр каждый месяц.","en":"I go to the theater every month."}]}],"drills":[{"q":"Сейчас я ___ в магазин.","answer":"иду","options":["ездить","ходил","хожу","иду"],"en":"I''m walking to the store right now.","why":{"хожу":"Хожу is for repeated trips (I go regularly). Right now, in one direction: иду.","ходил":"Ходил is past. Сейчас (now) needs иду.","ездить":"Ездить is an infinitive, and means going by vehicle. On foot, right now: иду."}},{"q":"Каждое лето мы ___ на море.","answer":"ездим","options":["поедем","ехали","едем","ездим"],"en":"Every summer we go to the seaside.","why":{"едем":"Едем is one trip under way (\"we''re on our way\"). Every summer is a habit: ездим.","поедем":"Поедем is one future trip. A repeated habit: ездим.","ехали":"Ехали is past, one trip. A habit in the present: ездим."}},{"q":"Она ___ домой поздно. (arrived)","answer":"пришла","options":["пришла","перешла","ушла","вышла"],"en":"She came home late.","why":{"ушла":"У- means leaving (\"she left\"). Arriving is при-: пришла.","вышла":"Вы- means going out. Arriving is при-: пришла.","перешла":"Пере- means crossing over. Arriving is при-: пришла."}},{"q":"Он ___ из дома в восемь. (went out)","answer":"вышел","options":["подошёл","пришёл","вошёл","вышел"],"en":"He left the house at eight.","why":{"вошёл":"Во- means going in. Going out of somewhere is вы-: вышел.","пришёл":"При- means arriving. Going out is вы-: вышел.","подошёл":"Под- means coming up to someone. Going out is вы-: вышел."}}]}'::jsonb, 9, 11),
  ('b1-12', 'B1', 'chess_talk', 12, 'Analysing the game', 'Анализ партии', 'Go through a game together: spot mistakes, missed chances and the turning point.', '{"intro":"Post-game analysis is a big part of Russian chess culture. You''ll learn to point out a mistake tactfully and explain what would have happened.","sections":[{"type":"lines","kind":"dialogue","title":"Going over the game","lines":[{"ru":"Я заметила, что ты оставил ферзя без защиты.","en":"I noticed that you left your queen undefended.","words":[{"ru":"Я","en":"I"},{"ru":"заметила,","en":"noticed"},{"ru":"что","en":"that"},{"ru":"ты","en":"you"},{"ru":"оставил","en":"left"},{"ru":"ферзя","en":"the queen"},{"ru":"без","en":"without"},{"ru":"защиты.","en":"protection"}],"speaker":"Анна"},{"ru":"Да, это была грубая ошибка.","en":"Yes, that was a blunder.","words":[{"ru":"Да,","en":"yes"},{"ru":"это","en":"it"},{"ru":"была","en":"was"},{"ru":"грубая","en":"gross"},{"ru":"ошибка.","en":"mistake"}],"speaker":"Максим"},{"ru":"Если бы ты сыграл слоном на e3, позиция была бы равной.","en":"If you''d played your bishop to e3, the position would have been equal.","words":[{"ru":"Если","en":"if"},{"ru":"бы","en":"—"},{"ru":"ты","en":"you"},{"ru":"сыграл","en":"played"},{"ru":"слоном","en":"the bishop"},{"ru":"на","en":"to"},{"ru":"e3,","en":"e3"},{"ru":"позиция","en":"the position"},{"ru":"была","en":"was"},{"ru":"бы","en":"would"},{"ru":"равной.","en":"equal"}],"speaker":"Анна"},{"ru":"Я слишком торопился.","en":"I was rushing too much.","words":[{"ru":"Я","en":"I"},{"ru":"слишком","en":"too"},{"ru":"торопился.","en":"was rushing"}],"speaker":"Максим"},{"ru":"В дебюте ты играл хорошо.","en":"You played well in the opening.","words":[{"ru":"В","en":"in"},{"ru":"дебюте","en":"the opening"},{"ru":"ты","en":"you"},{"ru":"играл","en":"played"},{"ru":"хорошо.","en":"well"}],"speaker":"Анна"},{"ru":"А где я упустил преимущество?","en":"So where did I let the advantage slip?","words":[{"ru":"А","en":"and"},{"ru":"где","en":"where"},{"ru":"я","en":"I"},{"ru":"упустил","en":"let slip"},{"ru":"преимущество?","en":"the advantage"}],"speaker":"Максим"},{"ru":"На двадцатом ходу.","en":"On move twenty.","words":[{"ru":"На","en":"on"},{"ru":"двадцатом","en":"the twentieth"},{"ru":"ходу.","en":"move"}],"speaker":"Анна"}]},{"type":"lines","kind":"phrases","title":"Analysis phrases","lines":[{"ru":"Давай разберём эту партию.","en":"Let''s go through this game.","words":[{"ru":"Давай","en":"let''s"},{"ru":"разберём","en":"go through"},{"ru":"эту","en":"this"},{"ru":"партию.","en":"game"}]},{"ru":"Здесь был лучший ход.","en":"There was a better move here.","words":[{"ru":"Здесь","en":"here"},{"ru":"был","en":"was"},{"ru":"лучший","en":"a better"},{"ru":"ход.","en":"move"}]},{"ru":"Это решающий момент.","en":"This is the turning point.","words":[{"ru":"Это","en":"this"},{"ru":"решающий","en":"the decisive"},{"ru":"момент.","en":"moment"}]},{"ru":"Я заметил, что твой слон не участвует в игре.","en":"I noticed your bishop isn''t involved in the game.","words":[{"ru":"Я","en":"I"},{"ru":"заметил,","f":"заметила,","en":"noticed"},{"ru":"что","en":"that"},{"ru":"твой","en":"your"},{"ru":"слон","en":"bishop"},{"ru":"не","en":"not"},{"ru":"участвует","en":"takes part"},{"ru":"в","en":"in"},{"ru":"игре.","en":"the game"}],"ruF":"Я заметила, что твой слон не участвует в игре."}]},{"type":"grammar","title":"Reporting what you noticed","paragraphs":["**Заметить, что…** / **видеть, что…** introduce a clause; keep the comma before **что**.","**Без** + genitive: без защиты (\"undefended\"), без плана, без шансов.","\"On move twenty\": **на** + prepositional ordinal + **ходу**: на пятом ходу, на двадцатом ходу."],"examples":[{"ru":"Я заметил, что у тебя слабая пешка.","en":"I noticed you have a weak pawn."},{"ru":"На десятом ходу ты ошибся.","en":"You made a mistake on move ten."}]}],"drills":[{"q":"Ты оставил ферзя без ___.","answer":"защиты","options":["защита","защиты","защиту","защитой"],"en":"You left your queen undefended.","why":{"защита":"Без takes the genitive: без защиты.","защиту":"Защиту is the accusative. Без needs защиты.","защитой":"Защитой is the instrumental. Без needs защиты."}},{"q":"Это была грубая ___.","answer":"ошибка","options":["ошибка","ошибкой","ошибки","ошибку"],"en":"That was a blunder.","why":{"ошибку":"Ошибку is the accusative (an object). Here ошибка is the subject: грубая ошибка.","ошибки":"Ошибки is the genitive or plural. With грубая: ошибка.","ошибкой":"Ошибкой would need грубой too (это было грубой ошибкой). With грубая: ошибка."}},{"q":"Где я упустил ___?","answer":"преимущество","options":["преимуществе","преимущество","преимущества","преимуществом"],"en":"Where did I let the advantage slip?","why":{"преимущества":"Преимущества is the genitive or plural. Упустить takes the accusative: преимущество.","преимуществом":"Преимуществом is the instrumental. The object of упустить is преимущество.","преимуществе":"Преимуществе is the prepositional. The object of упустить is преимущество."}},{"q":"Давай ___ эту партию.","answer":"разберём","options":["разобрали","разберём","разбираем","разобрать"],"en":"Let''s go through this game.","why":{"разбираем":"Разбираем is present. \"Let''s…\" is давай + the мы future: давай разберём.","разобрали":"Разобрали is past. \"Let''s…\" is давай разберём.","разобрать":"Давай doesn''t take this infinitive. Use the мы form: давай разберём."}}]}'::jsonb, 11, 13),
  ('b1-13', 'B1', 'chess_vocab', 13, 'Strategy', 'Стратегия', 'Describe a position: who''s better, which pawns are weak and what the plan is.', '{"intro":"Russian chess literature is famous, and its strategic vocabulary is everyday language for club players.","sections":[{"type":"lines","kind":"phrases","title":"Evaluating a position","lines":[{"ru":"У белых есть преимущество.","en":"White has the advantage.","words":[{"ru":"У","en":"by"},{"ru":"белых","en":"White"},{"ru":"есть","en":"there is"},{"ru":"преимущество.","en":"an advantage"}]},{"ru":"Чёрные контролируют центр.","en":"Black controls the center.","words":[{"ru":"Чёрные","en":"Black"},{"ru":"контролируют","en":"control"},{"ru":"центр.","en":"the center"}]},{"ru":"Это слабая пешка.","en":"That''s a weak pawn.","words":[{"ru":"Это","en":"this"},{"ru":"слабая","en":"weak"},{"ru":"пешка.","en":"pawn"}]},{"ru":"У тебя лишняя пешка.","en":"You''re a pawn up.","words":[{"ru":"У","en":"by"},{"ru":"тебя","en":"you"},{"ru":"лишняя","en":"extra"},{"ru":"пешка.","en":"pawn"}]},{"ru":"Я перехватил инициативу.","en":"I''ve seized the initiative.","words":[{"ru":"Я","en":"I"},{"ru":"перехватил","f":"перехватила","en":"seized"},{"ru":"инициативу.","en":"the initiative"}],"ruF":"Я перехватила инициативу."},{"ru":"Король в безопасности.","en":"The king is safe.","words":[{"ru":"Король","en":"the king"},{"ru":"в","en":"in"},{"ru":"безопасности.","en":"safety"}]},{"ru":"Нужно развивать фигуры.","en":"You need to develop your pieces.","words":[{"ru":"Нужно","en":"(you) need"},{"ru":"развивать","en":"to develop"},{"ru":"фигуры.","en":"the pieces"}]},{"ru":"Это открытая линия.","en":"That''s an open file.","words":[{"ru":"Это","en":"this"},{"ru":"открытая","en":"open"},{"ru":"линия.","en":"file"}]},{"ru":"Конь на краю доски — плохой конь.","en":"A knight on the rim is dim.","words":[{"ru":"Конь","en":"a knight"},{"ru":"на","en":"on"},{"ru":"краю","en":"the edge"},{"ru":"доски","en":"of the board"},{"ru":"—","en":"(is)"},{"ru":"плохой","en":"a bad"},{"ru":"конь.","en":"knight"}],"note":"A classic proverb: a knight on the edge of the board is a bad knight."},{"ru":"Позиция примерно равная.","en":"The position is roughly equal.","words":[{"ru":"Позиция","en":"the position"},{"ru":"примерно","en":"roughly"},{"ru":"равная.","en":"equal"}]}]},{"type":"grammar","title":"The two sides","paragraphs":["The sides are plural nouns: **белые** (White), **чёрные** (Black). \"White has…\" = **у белых** есть…; \"Black has…\" = **у чёрных**.","Adjectives agree with chess nouns: слаб**ая** пешка, сильн**ый** слон, открыт**ая** линия, лишн**ее** качество."],"examples":[{"ru":"У чёрных слабый король.","en":"Black''s king is weak."},{"ru":"Белые атакуют на ферзевом фланге.","en":"White is attacking on the queenside."}]}],"drills":[{"q":"У ___ есть преимущество. (White)","answer":"белых","options":["белые","белыми","белых","белым"],"en":"White has the advantage.","why":{"белые":"У takes the genitive: у белых.","белым":"Белым is the dative. У needs белых.","белыми":"Белыми is the instrumental (играть белыми). У needs белых."}},{"q":"Это ___ пешка.","answer":"слабая","options":["слабые","слабое","слабая","слабый"],"en":"That''s a weak pawn.","why":{"слабый":"Слабый is masculine. Пешка is feminine: слабая.","слабое":"Слабое is neuter. Пешка is feminine: слабая.","слабые":"Слабые is plural. One пешка: слабая."}},{"q":"Я перехватил ___.","answer":"инициативу","options":["инициатива","инициативой","инициативы","инициативу"],"en":"I''ve seized the initiative.","why":{"инициатива":"Перехватить takes the accusative: инициативу.","инициативы":"Инициативы is the genitive. The object is инициативу.","инициативой":"Инициативой is the instrumental. The object is инициативу."}},{"q":"Король в ___.","answer":"безопасности","options":["безопасный","безопасности","безопасно","безопасность"],"en":"The king is safe.","why":{"безопасность":"В for location takes the prepositional: в безопасности.","безопасный":"Безопасный is the adjective \"safe\". \"In safety\" is в безопасности.","безопасно":"Безопасно is the adverb \"safely\". \"The king is safe\" is король в безопасности."}}]}'::jsonb, 10, 12),
  ('b1-14', 'B1', 'family', 14, 'Family and relationships', 'Семья и отношения', 'Describe the people close to you and how you get along.', '{"intro":"«Мы с братом» means \"my brother and I\" — literally \"we with brother\". It''s one of the most natural constructions in Russian.","sections":[{"type":"lines","kind":"phrases","title":"People close to me","lines":[{"ru":"Мы с братом очень близки.","en":"My brother and I are very close.","words":[{"ru":"Мы","en":"we"},{"ru":"с","en":"with"},{"ru":"братом","en":"brother"},{"ru":"очень","en":"very"},{"ru":"близки.","en":"close"}]},{"ru":"Мои родители живут в другом городе.","en":"My parents live in another city.","words":[{"ru":"Мои","en":"my"},{"ru":"родители","en":"parents"},{"ru":"живут","en":"live"},{"ru":"в","en":"in"},{"ru":"другом","en":"another"},{"ru":"городе.","en":"city"}]},{"ru":"Мы видимся редко.","en":"We rarely see each other.","words":[{"ru":"Мы","en":"we"},{"ru":"видимся","en":"see each other"},{"ru":"редко.","en":"rarely"}]},{"ru":"Я звоню маме каждый день.","en":"I call my mom every day.","words":[{"ru":"Я","en":"I"},{"ru":"звоню","en":"call"},{"ru":"маме","en":"mom"},{"ru":"каждый","en":"every"},{"ru":"день.","en":"day"}]},{"ru":"У моей сестры двое детей.","en":"My sister has two children.","words":[{"ru":"У","en":"by"},{"ru":"моей","en":"my"},{"ru":"сестры","en":"sister"},{"ru":"двое","en":"two"},{"ru":"детей.","en":"children"}]},{"ru":"Я похож на отца.","en":"I look like my father.","words":[{"ru":"Я","en":"I"},{"ru":"похож","f":"похожа","en":"look like"},{"ru":"на","en":"—"},{"ru":"отца.","en":"my father"}],"ruF":"Я похожа на отца."},{"ru":"Мы часто спорим, но любим друг друга.","en":"We argue a lot, but we love each other.","words":[{"ru":"Мы","en":"we"},{"ru":"часто","en":"often"},{"ru":"спорим,","en":"argue"},{"ru":"но","en":"but"},{"ru":"любим","en":"love"},{"ru":"друг","en":"each"},{"ru":"друга.","en":"other"}]},{"ru":"Бабушка всегда нас поддерживает.","en":"Grandma always supports us.","words":[{"ru":"Бабушка","en":"grandma"},{"ru":"всегда","en":"always"},{"ru":"нас","en":"us"},{"ru":"поддерживает.","en":"supports"}]},{"ru":"Я вырос в маленьком городе.","en":"I grew up in a small town.","words":[{"ru":"Я","en":"I"},{"ru":"вырос","f":"выросла","en":"grew up"},{"ru":"в","en":"in"},{"ru":"маленьком","en":"a small"},{"ru":"городе.","en":"town"}],"ruF":"Я выросла в маленьком городе."},{"ru":"Мы собираемся всей семьёй на Новый год.","en":"The whole family gets together for New Year.","words":[{"ru":"Мы","en":"we"},{"ru":"собираемся","en":"gather"},{"ru":"всей","en":"as the whole"},{"ru":"семьёй","en":"family"},{"ru":"на","en":"for"},{"ru":"Новый","en":"New"},{"ru":"год.","en":"Year"}]}]},{"type":"grammar","title":"Мы с…, друг друга","paragraphs":["**Мы с** + instrumental = \"X and I\": мы с мамой, мы с другом, мы с женой.","**Друг друга** = \"each other\" — the second word takes the case the verb needs: любим друг друга, помогаем друг другу.","**Двое, трое** count people and children: двое детей, трое друзей."],"examples":[{"ru":"Мы с подругой учимся вместе.","en":"My friend and I study together."},{"ru":"Они часто звонят друг другу.","en":"They often call each other."}]}],"drills":[{"q":"Мы с ___ очень близки. (брат)","answer":"братом","options":["братом","брата","брат","брату"],"en":"My brother and I are very close.","why":{"брат":"\"Мы с X\" (\"X and I\") takes the instrumental: мы с братом.","брата":"Брата is the genitive or accusative. With с: братом.","брату":"Брату is the dative. With с: братом."}},{"q":"Мы любим друг ___.","answer":"друга","options":["другом","другу","друг","друга"],"en":"We love each other.","why":{"другу":"Другу is the dative, for verbs that take \"to\" (помогаем друг другу). Любить takes the accusative: друг друга.","другом":"Другом is the instrumental (друг с другом — with each other). Любить takes друг друга.","друг":"The second part always changes case. \"Each other\" as an object is друг друга."}},{"q":"Я похож на ___.","answer":"отца","options":["отцу","отец","отцом","отца"],"en":"I look like my father.","why":{"отец":"Похож на takes the accusative. Отец is a person, so it''s отца.","отцом":"Отцом is the instrumental. Похож на needs отца.","отцу":"Отцу is the dative. Похож на needs отца."}},{"q":"У сестры ___ детей.","answer":"двое","options":["двое","два","двух","две"],"en":"My sister has two children.","why":{"два":"Дети is counted with collective numbers: двое детей.","две":"Две is the feminine \"two\" (две сестры). For children: двое.","двух":"Двух is the genitive (у двух детей). Counting children: двое."}}]}'::jsonb, 10, 11),
  ('b2-01', 'B2', 'emotions', 1, 'It didn''t turn out as planned', 'Всё сложилось иначе', 'React to surprises and setbacks with natural, nuanced phrasing.', '{"intro":"At B2 you express not just what happened but how you feel about it — surprise, relief, regret — with idiomatic Russian.","sections":[{"type":"lines","kind":"phrases","title":"When things change","lines":[{"ru":"Если честно, я не ожидал, что всё сложится именно так.","en":"Honestly, I didn''t expect everything to turn out this way.","words":[{"ru":"Если","en":"if"},{"ru":"честно,","en":"honestly"},{"ru":"я","en":"I"},{"ru":"не","en":"not"},{"ru":"ожидал,","f":"ожидала,","en":"expected"},{"ru":"что","en":"that"},{"ru":"всё","en":"everything"},{"ru":"сложится","en":"would turn out"},{"ru":"именно","en":"exactly"},{"ru":"так.","en":"this way"}],"ruF":"Если честно, я не ожидала, что всё сложится именно так."},{"ru":"Всё пошло не по плану.","en":"Nothing went according to plan.","words":[{"ru":"Всё","en":"everything"},{"ru":"пошло","en":"went"},{"ru":"не","en":"not"},{"ru":"по","en":"according to"},{"ru":"плану.","en":"plan"}]},{"ru":"Я до сих пор не могу прийти в себя.","en":"I still can''t get over it.","words":[{"ru":"Я","en":"I"},{"ru":"до","en":"—"},{"ru":"сих","en":"—"},{"ru":"пор","en":"until now"},{"ru":"не","en":"not"},{"ru":"могу","en":"can"},{"ru":"прийти","en":"come"},{"ru":"в","en":"to"},{"ru":"себя.","en":"myself"}]},{"ru":"Кто бы мог подумать!","en":"Who would have thought!","words":[{"ru":"Кто","en":"who"},{"ru":"бы","en":"—"},{"ru":"мог","en":"could"},{"ru":"подумать!","en":"have thought"}]},{"ru":"Это стало для меня полной неожиданностью.","en":"It came as a complete surprise to me.","words":[{"ru":"Это","en":"it"},{"ru":"стало","en":"became"},{"ru":"для","en":"for"},{"ru":"меня","en":"me"},{"ru":"полной","en":"a complete"},{"ru":"неожиданностью.","en":"surprise"}]},{"ru":"Как бы то ни было, мы справились.","en":"Be that as it may, we managed.","words":[{"ru":"Как","en":"as"},{"ru":"бы","en":"—"},{"ru":"то","en":"it"},{"ru":"ни","en":"—"},{"ru":"было,","en":"may be"},{"ru":"мы","en":"we"},{"ru":"справились.","en":"coped"}]},{"ru":"Хорошо, что всё обошлось.","en":"Thank goodness it all worked out.","words":[{"ru":"Хорошо,","en":"it''s good"},{"ru":"что","en":"that"},{"ru":"всё","en":"everything"},{"ru":"обошлось.","en":"turned out fine"}]},{"ru":"Я не жалею о том, что случилось.","en":"I don''t regret what happened.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"жалею","en":"regret"},{"ru":"о","en":"about"},{"ru":"том,","en":"it"},{"ru":"что","en":"that"},{"ru":"случилось.","en":"happened"}]},{"ru":"Нет худа без добра.","en":"Every cloud has a silver lining.","words":[{"ru":"Нет","en":"there''s no"},{"ru":"худа","en":"bad"},{"ru":"без","en":"without"},{"ru":"добра.","en":"good"}],"note":"A proverb: literally \"there''s no bad without some good\"."}]},{"type":"grammar","title":"О том, что… and set phrases","paragraphs":["When a verb needs a preposition and is followed by a whole clause, Russian inserts **то**: жалеть **о том, что**…, думать **о том, что**…, речь идёт **о том, что**….","Fixed expressions to learn whole: **до сих пор** (still, until now), **прийти в себя** (to recover), **как бы то ни было** (be that as it may)."],"examples":[{"ru":"Я думаю о том, что ты сказал.","en":"I''m thinking about what you said."},{"ru":"Он до сих пор не ответил.","en":"He still hasn''t replied."}]}],"drills":[{"q":"Я не ожидал, что всё ___ именно так.","answer":"сложится","options":["сложится","сложилось","сложить","складывается"],"en":"I didn''t expect everything to turn out this way.","why":{"сложилось":"Сложилось is past. When reporting an expectation, Russian keeps the future of the original thought: всё сложится.","складывается":"Складывается is present (\"is turning out\"). The expectation was about what would happen: сложится.","сложить":"Сложить means \"to fold, to put together\" and needs an object. \"To turn out\" is the -ся verb: сложится."}},{"q":"Я не жалею о ___, что случилось.","answer":"том","options":["то","тем","том","тому"],"en":"I don''t regret what happened.","why":{"то":"О (\"about\") takes the prepositional: о том, что…","тем":"Тем is the instrumental. О needs том.","тому":"Тому is the dative. О needs том."}},{"q":"Я до сих ___ не могу прийти в себя.","answer":"пор","options":["поры","пор","пора","порой"],"en":"I still can''t get over it.","why":{"пора":"The fixed phrase is до сих пор (\"still, until now\"). Пора means \"it''s time\".","порой":"Порой means \"at times\". The fixed phrase is до сих пор.","поры":"The fixed phrase is до сих пор, with пор."}},{"q":"Это стало для меня полной ___.","answer":"неожиданностью","options":["неожиданность","неожиданностью","неожиданный","неожиданности"],"en":"It came as a complete surprise.","why":{"неожиданность":"Стать (\"to become\") takes the instrumental: стало неожиданностью (see полной).","неожиданности":"Неожиданности is the genitive or dative. After стать: неожиданностью.","неожиданный":"Неожиданный is an adjective. The sentence needs the noun in the instrumental: неожиданностью."}}]}'::jsonb, 9, 9),
  ('b2-02', 'B2', 'opinions', 2, 'Finding a balance', 'Найти баланс', 'Reflect on priorities and life choices in long, connected sentences.', '{"intro":"This lesson builds the kind of sentence you''d use in a real heart-to-heart: several ideas linked smoothly together.","sections":[{"type":"lines","kind":"phrases","title":"Priorities","lines":[{"ru":"Я стараюсь найти баланс между работой, личной жизнью и собственными интересами.","en":"I''m trying to find a balance between work, my personal life and my own interests.","words":[{"ru":"Я","en":"I"},{"ru":"стараюсь","en":"try"},{"ru":"найти","en":"to find"},{"ru":"баланс","en":"a balance"},{"ru":"между","en":"between"},{"ru":"работой,","en":"work"},{"ru":"личной","en":"personal"},{"ru":"жизнью","en":"life"},{"ru":"и","en":"and"},{"ru":"собственными","en":"my own"},{"ru":"интересами.","en":"interests"}]},{"ru":"Мне кажется, иногда важно просто остановиться и подумать о том, чего ты действительно хочешь.","en":"I think sometimes it''s important to just stop and think about what you really want.","words":[{"ru":"Мне","en":"to me"},{"ru":"кажется,","en":"it seems"},{"ru":"иногда","en":"sometimes"},{"ru":"важно","en":"it''s important"},{"ru":"просто","en":"just"},{"ru":"остановиться","en":"to stop"},{"ru":"и","en":"and"},{"ru":"подумать","en":"think"},{"ru":"о","en":"about"},{"ru":"том,","en":"that"},{"ru":"чего","en":"what"},{"ru":"ты","en":"you"},{"ru":"действительно","en":"really"},{"ru":"хочешь.","en":"want"}],"note":"Abstract \"what you want\" takes the genitive: чего ты хочешь."},{"ru":"Работа занимает у меня почти всё время.","en":"Work takes up almost all of my time.","words":[{"ru":"Работа","en":"work"},{"ru":"занимает","en":"takes up"},{"ru":"у","en":"by"},{"ru":"меня","en":"me"},{"ru":"почти","en":"almost"},{"ru":"всё","en":"all"},{"ru":"время.","en":"the time"}]},{"ru":"Я научился говорить «нет».","en":"I''ve learned to say \"no\".","words":[{"ru":"Я","en":"I"},{"ru":"научился","f":"научилась","en":"learned"},{"ru":"говорить","en":"to say"},{"ru":"«нет».","en":"no"}],"ruF":"Я научилась говорить «нет»."},{"ru":"Важно не только работать, но и отдыхать.","en":"It''s important not just to work but to rest as well.","words":[{"ru":"Важно","en":"it''s important"},{"ru":"не","en":"not"},{"ru":"только","en":"only"},{"ru":"работать,","en":"to work"},{"ru":"но","en":"but"},{"ru":"и","en":"also"},{"ru":"отдыхать.","en":"to rest"}]},{"ru":"Чем больше я отдыхаю, тем лучше работаю.","en":"The more I rest, the better I work.","words":[{"ru":"Чем","en":"the"},{"ru":"больше","en":"more"},{"ru":"я","en":"I"},{"ru":"отдыхаю,","en":"rest"},{"ru":"тем","en":"the"},{"ru":"лучше","en":"better"},{"ru":"работаю.","en":"I work"}]},{"ru":"Я стал больше времени проводить с семьёй.","en":"I''ve started spending more time with my family.","words":[{"ru":"Я","en":"I"},{"ru":"стал","f":"стала","en":"began"},{"ru":"больше","en":"more"},{"ru":"времени","en":"time"},{"ru":"проводить","en":"to spend"},{"ru":"с","en":"with"},{"ru":"семьёй.","en":"family"}],"ruF":"Я стала больше времени проводить с семьёй."},{"ru":"Здоровье дороже денег.","en":"Health matters more than money.","words":[{"ru":"Здоровье","en":"health"},{"ru":"дороже","en":"is dearer"},{"ru":"денег.","en":"than money"}]}]},{"type":"grammar","title":"Чем…, тем…; comparatives","paragraphs":["**Чем** + comparative, **тем** + comparative = \"the more…, the more…\": чем раньше, тем лучше.","A comparative can take the genitive instead of **чем**: дороже денег = дороже, чем деньги.","**Стать** + infinitive = \"to start doing (regularly)\": я стал больше читать."],"examples":[{"ru":"Чем больше практики, тем увереннее речь.","en":"The more practice, the more confident your speech."},{"ru":"Время дороже денег.","en":"Time is more precious than money."}]}],"drills":[{"q":"___ больше я отдыхаю, тем лучше работаю.","answer":"Чем","options":["Тем","Что","Чем","Как"],"en":"The more I rest, the better I work.","why":{"Тем":"Тем goes in the second half. \"The more…, the better…\" is Чем больше…, тем лучше.","Что":"The pattern is Чем…, тем… Что doesn''t fit.","Как":"The pattern is Чем…, тем… Как doesn''t fit."}},{"q":"Подумай о том, ___ ты действительно хочешь.","answer":"чего","options":["чем","что","чему","чего"],"en":"Think about what you really want.","why":{"что":"Что is common in speech, but хотеть with something abstract traditionally takes the genitive: чего ты хочешь.","чем":"Чем is the instrumental. Хотеть takes чего.","чему":"Чему is the dative. Хотеть takes чего."}},{"q":"Я стараюсь найти баланс между работой и личной ___.","answer":"жизнью","options":["жизнях","жизни","жизнью","жизнь"],"en":"I''m trying to balance work and personal life.","why":{"жизнь":"Между takes the instrumental: между работой и жизнью.","жизни":"Жизни is the genitive or dative. Между needs жизнью.","жизнях":"Жизнях is the prepositional plural. Между needs жизнью."}},{"q":"Здоровье дороже ___.","answer":"денег","options":["деньги","денег","деньгами","деньгам"],"en":"Health matters more than money.","why":{"деньги":"A comparative without чем takes the genitive: дороже денег.","деньгами":"Деньгами is the instrumental. After дороже: денег.","деньгам":"Деньгам is the dative. After дороже: денег."}}]}'::jsonb, 8, 9),
  ('b2-03', 'B2', 'problems', 3, 'Not jumping to conclusions', 'Без поспешных выводов', 'Stay measured in a tense situation: gather facts, consider both sides, reserve judgement.', '{"intro":"You''ll meet the \"genitive of negation\" — after a negated verb, the object often switches to the genitive: не делать поспешных выводов.","sections":[{"type":"lines","kind":"phrases","title":"Weighing a situation","lines":[{"ru":"Не хочу делать поспешных выводов, пока не узнаю всей ситуации.","en":"I don''t want to jump to conclusions before I know the whole situation.","words":[{"ru":"Не","en":"not"},{"ru":"хочу","en":"want"},{"ru":"делать","en":"to make"},{"ru":"поспешных","en":"hasty"},{"ru":"выводов,","en":"conclusions"},{"ru":"пока","en":"until"},{"ru":"не","en":"—"},{"ru":"узнаю","en":"learn"},{"ru":"всей","en":"the whole"},{"ru":"ситуации.","en":"situation"}],"note":"пока не + perfective = \"until\": пока не узнаю."},{"ru":"Давай сначала выясним, что произошло.","en":"Let''s first find out what happened.","words":[{"ru":"Давай","en":"let''s"},{"ru":"сначала","en":"first"},{"ru":"выясним,","en":"find out"},{"ru":"что","en":"what"},{"ru":"произошло.","en":"happened"}]},{"ru":"Не всё так однозначно.","en":"It''s not all that clear-cut.","words":[{"ru":"Не","en":"not"},{"ru":"всё","en":"everything"},{"ru":"так","en":"so"},{"ru":"однозначно.","en":"clear-cut"}]},{"ru":"Я бы не стал спешить с выводами.","en":"I wouldn''t rush to conclusions.","words":[{"ru":"Я","en":"I"},{"ru":"бы","en":"would"},{"ru":"не","en":"not"},{"ru":"стал","f":"стала","en":"—"},{"ru":"спешить","en":"rush"},{"ru":"с","en":"with"},{"ru":"выводами.","en":"conclusions"}],"ruF":"Я бы не стала спешить с выводами."},{"ru":"У каждой истории есть две стороны.","en":"There are two sides to every story.","words":[{"ru":"У","en":"by"},{"ru":"каждой","en":"every"},{"ru":"истории","en":"story"},{"ru":"есть","en":"there are"},{"ru":"две","en":"two"},{"ru":"стороны.","en":"sides"}]},{"ru":"Судя по всему, это недоразумение.","en":"By all accounts, it''s a misunderstanding.","words":[{"ru":"Судя","en":"judging"},{"ru":"по","en":"by"},{"ru":"всему,","en":"everything"},{"ru":"это","en":"it''s"},{"ru":"недоразумение.","en":"a misunderstanding"}]},{"ru":"Вполне возможно, что он прав.","en":"It''s quite possible that he''s right.","words":[{"ru":"Вполне","en":"quite"},{"ru":"возможно,","en":"possible"},{"ru":"что","en":"that"},{"ru":"он","en":"he"},{"ru":"прав.","en":"is right"}]},{"ru":"Я предпочитаю не вмешиваться.","en":"I''d rather not get involved.","words":[{"ru":"Я","en":"I"},{"ru":"предпочитаю","en":"prefer"},{"ru":"не","en":"not"},{"ru":"вмешиваться.","en":"to interfere"}]},{"ru":"Поживём — увидим.","en":"Time will tell.","words":[{"ru":"Поживём","en":"we''ll live"},{"ru":"—","en":""},{"ru":"увидим.","en":"we''ll see"}],"note":"Literally \"we''ll live — we''ll see\"."}]},{"type":"grammar","title":"Genitive of negation; пока не","paragraphs":["After a negated verb, a direct object that is abstract or indefinite usually goes into the genitive: не делать **выводов**, не имеет **смысла**, не вижу **разницы**.","**Пока не** + perfective verb = \"until\": подожди, пока я не вернусь.","**Я бы не стал** + infinitive = a polite \"I wouldn''t…\"."],"examples":[{"ru":"Это не имеет никакого значения.","en":"It makes no difference at all."},{"ru":"Я подожду, пока ты не закончишь.","en":"I''ll wait until you finish."}]}],"drills":[{"q":"Не хочу делать поспешных ___.","answer":"выводов","options":["выводы","вывод","выводами","выводов"],"en":"I don''t want to jump to conclusions.","why":{"выводы":"With a negated verb, the object often goes into the genitive: поспешных выводов (see поспешных).","вывод":"Вывод is singular. Поспешных is genitive plural, so: выводов.","выводами":"Выводами is the instrumental. To match поспешных: выводов."}},{"q":"Давай сначала ___, что произошло.","answer":"выясним","options":["выясняем","выяснять","выяснили","выясним"],"en":"Let''s first find out what happened.","why":{"выясняем":"Выясняем is present. \"Let''s…\" is давай + the мы future: давай выясним.","выяснили":"Выяснили is past. \"Let''s find out\" is давай выясним.","выяснять":"Давай выяснять means \"let''s keep looking into it\". For one clear result: давай выясним."}},{"q":"Судя по ___, это недоразумение.","answer":"всему","options":["всем","всё","всему","всего"],"en":"By all accounts, it''s a misunderstanding.","why":{"всё":"The fixed phrase is судя по всему, with по + dative.","всем":"Всем is the dative plural or instrumental. The fixed phrase is судя по всему.","всего":"Всего is the genitive. The fixed phrase is судя по всему."}},{"q":"Я бы не ___ спешить.","answer":"стал","options":["стану","стал","становлюсь","стать"],"en":"I wouldn''t rush.","why":{"стану":"Стану is future. After бы, use the past form: я бы не стал.","стать":"Стать is the infinitive. After бы, use the past form: стал.","становлюсь":"Становлюсь is present (\"I become\"). After бы, use the past form: стал."}}]}'::jsonb, 9, 10),
  ('b2-04', 'B2', 'work', 4, 'Business communication', 'Деловое общение', 'Make requests, apologise and decline in polished, professional Russian.', '{"intro":"Formal Russian has fixed polite formulas. Compare «Пришли отчёт» with «Не могли бы вы прислать отчёт?» — same request, very different tone.","sections":[{"type":"lines","kind":"phrases","title":"Professional formulas","lines":[{"ru":"Не могли бы вы прислать мне отчёт?","en":"Could you send me the report?","words":[{"ru":"Не","en":"not"},{"ru":"могли","en":"could"},{"ru":"бы","en":"—"},{"ru":"вы","en":"you"},{"ru":"прислать","en":"send"},{"ru":"мне","en":"me"},{"ru":"отчёт?","en":"the report"}],"tag":"formal"},{"ru":"Я хотел бы обсудить условия договора.","en":"I''d like to discuss the terms of the contract.","words":[{"ru":"Я","en":"I"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"обсудить","en":"to discuss"},{"ru":"условия","en":"the terms"},{"ru":"договора.","en":"of the contract"}],"ruF":"Я хотела бы обсудить условия договора.","tag":"formal"},{"ru":"Прошу прощения за задержку.","en":"I apologise for the delay.","words":[{"ru":"Прошу","en":"I ask"},{"ru":"прощения","en":"forgiveness"},{"ru":"за","en":"for"},{"ru":"задержку.","en":"the delay"}],"tag":"formal"},{"ru":"Позвольте представить моего коллегу.","en":"Allow me to introduce my colleague.","words":[{"ru":"Позвольте","en":"allow me"},{"ru":"представить","en":"to introduce"},{"ru":"моего","en":"my"},{"ru":"коллегу.","en":"colleague"}],"tag":"formal"},{"ru":"Буду признателен за ответ.","en":"I''d appreciate a reply.","words":[{"ru":"Буду","en":"I''ll be"},{"ru":"признателен","f":"признательна","en":"grateful"},{"ru":"за","en":"for"},{"ru":"ответ.","en":"a reply"}],"ruF":"Буду признательна за ответ.","tag":"formal"},{"ru":"К сожалению, мы вынуждены отказаться.","en":"Unfortunately, we have to decline.","words":[{"ru":"К","en":"to"},{"ru":"сожалению,","en":"regret"},{"ru":"мы","en":"we"},{"ru":"вынуждены","en":"are forced"},{"ru":"отказаться.","en":"to decline"}],"tag":"formal"},{"ru":"Давайте перенесём встречу на четверг.","en":"Let''s move the meeting to Thursday.","words":[{"ru":"Давайте","en":"let''s"},{"ru":"перенесём","en":"move"},{"ru":"встречу","en":"the meeting"},{"ru":"на","en":"to"},{"ru":"четверг.","en":"Thursday"}],"tag":"formal"},{"ru":"Это выходит за рамки моих полномочий.","en":"That''s beyond my authority.","words":[{"ru":"Это","en":"it"},{"ru":"выходит","en":"goes"},{"ru":"за","en":"beyond"},{"ru":"рамки","en":"the bounds"},{"ru":"моих","en":"of my"},{"ru":"полномочий.","en":"authority"}],"tag":"formal"},{"ru":"В связи с этим предлагаю следующее.","en":"In light of this, I propose the following.","words":[{"ru":"В","en":"in"},{"ru":"связи","en":"connection"},{"ru":"с","en":"with"},{"ru":"этим","en":"this"},{"ru":"предлагаю","en":"I propose"},{"ru":"следующее.","en":"the following"}],"tag":"formal"}]},{"type":"grammar","title":"Softening a request","paragraphs":["Russian softens requests with the conditional and negation: **Не могли бы вы…?** (\"Couldn''t you…?\") is more polite than **Можете…?**","Other formulas: **Я хотел бы / хотела бы…**, **Позвольте…**, **Буду признателен / признательна…**, **К сожалению,…**."],"examples":[{"ru":"Пришли отчёт. → Не могли бы вы прислать отчёт?","en":"Send the report. → Could you send the report?"},{"ru":"Перезвони мне. → Будьте добры, перезвоните мне.","en":"Call me back. → Would you kindly call me back?"}]}],"drills":[{"q":"Не ___ бы вы прислать мне отчёт?","answer":"могли","options":["можете","могут","мог","могли"],"en":"Could you send me the report?","why":{"можете":"Можете is present (\"can you\"). With бы, use the past form: могли бы.","мог":"Мог is singular. Вы takes the plural: могли.","могут":"Могут is \"they can\". With вы and бы: могли."}},{"q":"Прошу прощения за ___.","answer":"задержку","options":["задержкой","задержку","задержка","задержки"],"en":"I apologise for the delay.","why":{"задержка":"За (\"for\") takes the accusative: за задержку.","задержки":"Задержки is the genitive. За needs задержку.","задержкой":"Задержкой is the instrumental. За (\"for\") needs задержку."}},{"q":"К ___, мы вынуждены отказаться.","answer":"сожалению","options":["сожалением","сожаления","сожаление","сожалению"],"en":"Unfortunately, we have to decline.","why":{"сожаление":"К takes the dative: к сожалению.","сожаления":"Сожаления is the genitive. К needs сожалению.","сожалением":"С сожалением means \"with regret\". \"Unfortunately\" is к сожалению."}},{"q":"Давайте перенесём встречу на ___.","answer":"четверг","options":["четверге","четвергом","четверг","четверга"],"en":"Let''s move the meeting to Thursday.","why":{"четверга":"Четверга is the genitive (до четверга). Перенести на takes the accusative: на четверг.","четвергом":"Четвергом is the instrumental. Moving it to Thursday: на четверг.","четверге":"Четверге is the prepositional (о четверге). Moving it to Thursday: на четверг."}}]}'::jsonb, 9, 15),
  ('b2-05', 'B2', 'smalltalk', 5, 'Real spoken Russian', 'Живая разговорная речь', 'Understand Russian as it''s actually spoken — fast, clipped and full of particles.', '{"intro":"Native speakers swallow sounds and use expressions you won''t find in textbooks. Learn to recognise them; use them with friends, never in formal settings.","sections":[{"type":"lines","kind":"phrases","title":"Overheard in Moscow","lines":[{"ru":"Ну ты даёшь!","en":"Wow, you''re something else!","words":[{"ru":"Ну","en":"well"},{"ru":"ты","en":"you"},{"ru":"даёшь!","en":"give"}],"tag":"spoken"},{"ru":"Ничего себе!","en":"Wow! / No way!","words":[{"ru":"Ничего","en":"nothing"},{"ru":"себе!","en":"to oneself"}],"tag":"spoken"},{"ru":"Да ладно?","en":"Really? / You''re kidding!","words":[{"ru":"Да","en":"yes"},{"ru":"ладно?","en":"okay"}],"tag":"spoken"},{"ru":"Слушай, а давай завтра?","en":"Listen, how about tomorrow?","words":[{"ru":"Слушай,","en":"listen"},{"ru":"а","en":"and"},{"ru":"давай","en":"let''s"},{"ru":"завтра?","en":"tomorrow"}],"tag":"spoken"},{"ru":"Щас приду.","en":"Be right there.","words":[{"ru":"Щас","en":"now"},{"ru":"приду.","en":"I''ll come"}],"tag":"spoken","note":"Щас is how сейчас sounds in fast speech. You''ll hear it constantly; write сейчас."},{"ru":"Чё ты говоришь?","en":"What are you saying?","words":[{"ru":"Чё","en":"what"},{"ru":"ты","en":"you"},{"ru":"говоришь?","en":"are saying"}],"tag":"spoken","note":"Чё is a very casual spoken form of что. Understand it; don''t use it at work."},{"ru":"Короче, всё нормально.","en":"Long story short, everything''s fine.","words":[{"ru":"Короче,","en":"in short"},{"ru":"всё","en":"everything"},{"ru":"нормально.","en":"is fine"}],"tag":"spoken"},{"ru":"Без проблем!","en":"No problem!","words":[{"ru":"Без","en":"without"},{"ru":"проблем!","en":"problems"}],"tag":"spoken"},{"ru":"Да нет, наверное.","en":"Probably not.","words":[{"ru":"Да","en":"yes"},{"ru":"нет,","en":"no"},{"ru":"наверное.","en":"probably"}],"tag":"spoken","note":"In «да нет» the last word wins: it means \"no\". «Нет, да» means \"yes\"."},{"ru":"Как бы тебе сказать…","en":"How should I put it…","words":[{"ru":"Как","en":"how"},{"ru":"бы","en":"—"},{"ru":"тебе","en":"to you"},{"ru":"сказать…","en":"say"}],"tag":"spoken"},{"ru":"Это вообще не моё.","en":"That''s really not my thing.","words":[{"ru":"Это","en":"it"},{"ru":"вообще","en":"totally"},{"ru":"не","en":"not"},{"ru":"моё.","en":"mine"}],"tag":"spoken"}]},{"type":"grammar","title":"How words shrink","paragraphs":["In fast speech: сейчас → [щас], что → [што] or [чё], тысяча → [тыща], здравствуйте → [здрасьте], только → [токо], говорит → [грит], человек → [чек].","Particles add attitude: **же** (emphasis: Я же говорил!), **ведь** (after all: Ведь ты знаешь), **вообще** (at all / totally)."],"examples":[{"ru":"Я же тебе говорил!","en":"I told you so!"},{"ru":"Ведь мы договорились!","en":"But we agreed!"}]}],"drills":[{"q":"Ну ты ___! (Wow, you''re something!)","answer":"даёшь","options":["даю","дал","давать","даёшь"],"en":"Wow, you''re something else!","why":{"даю":"Даю is the я form. The idiom with ты is Ну ты даёшь!","дал":"Дал is past. The idiom is in the present: Ну ты даёшь!","давать":"Давать is the infinitive. The idiom is Ну ты даёшь!"}},{"q":"Ничего ___!","answer":"себе","options":["себе","себя","собой","сам"],"en":"Wow!","why":{"себя":"The fixed exclamation is Ничего себе! (with the dative).","собой":"Собой is the instrumental. The exclamation is Ничего себе!","сам":"Сам means \"oneself\" (for emphasis). The exclamation is Ничего себе!"}},{"q":"Я ___ тебе говорил!","answer":"же","options":["же","бы","ведь","ли"],"en":"I told you so!","why":{"ведь":"Ведь also adds emphasis, but it goes earlier (я ведь тебе говорил). The set phrase here is я же тебе говорил.","бы":"Бы makes \"would\" (\"I would have told you\"). For \"I told you so!\", use же.","ли":"Ли turns a sentence into a yes/no question. For emphasis, use же."}},{"q":"Да нет, ___.","answer":"наверное","options":["обязательно","конечно","точно","наверное"],"en":"Probably not.","why":{"конечно":"Конечно is \"of course\" — too certain. \"Probably not\" is да нет, наверное.","точно":"Точно is \"definitely, exactly\". \"Probably not\" is да нет, наверное.","обязательно":"Обязательно is \"definitely, without fail\". \"Probably not\" is да нет, наверное."}}]}'::jsonb, 11, 9),
  ('b2-06', 'B2', 'health', 6, 'Health and lifestyle', 'Здоровье и образ жизни', 'Discuss lifestyle, prescriptions, allergies and looking after yourself.', '{"intro":"Medical Russian is full of impersonal constructions: «мне выписали лекарство» — \"they prescribed me medicine\".","sections":[{"type":"lines","kind":"phrases","title":"Taking care of yourself","lines":[{"ru":"Я стараюсь вести здоровый образ жизни.","en":"I try to lead a healthy lifestyle.","words":[{"ru":"Я","en":"I"},{"ru":"стараюсь","en":"try"},{"ru":"вести","en":"to lead"},{"ru":"здоровый","en":"a healthy"},{"ru":"образ","en":"way"},{"ru":"жизни.","en":"of life"}]},{"ru":"Врач посоветовал мне меньше нервничать.","en":"The doctor advised me to stress less.","words":[{"ru":"Врач","en":"the doctor"},{"ru":"посоветовал","en":"advised"},{"ru":"мне","en":"me"},{"ru":"меньше","en":"less"},{"ru":"нервничать.","en":"to stress"}]},{"ru":"У меня аллергия на орехи.","en":"I''m allergic to nuts.","words":[{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"аллергия","en":"an allergy"},{"ru":"на","en":"to"},{"ru":"орехи.","en":"nuts"}]},{"ru":"Мне выписали антибиотики.","en":"I was prescribed antibiotics.","words":[{"ru":"Мне","en":"to me"},{"ru":"выписали","en":"(they) prescribed"},{"ru":"антибиотики.","en":"antibiotics"}]},{"ru":"Я бросил курить три года назад.","en":"I quit smoking three years ago.","words":[{"ru":"Я","en":"I"},{"ru":"бросил","f":"бросила","en":"quit"},{"ru":"курить","en":"smoking"},{"ru":"три","en":"three"},{"ru":"года","en":"years"},{"ru":"назад.","en":"ago"}],"ruF":"Я бросила курить три года назад."},{"ru":"Недосып сказывается на всём.","en":"Lack of sleep affects everything.","words":[{"ru":"Недосып","en":"lack of sleep"},{"ru":"сказывается","en":"tells"},{"ru":"на","en":"on"},{"ru":"всём.","en":"everything"}]},{"ru":"Мне нужно пройти обследование.","en":"I need to get a checkup.","words":[{"ru":"Мне","en":"to me"},{"ru":"нужно","en":"need"},{"ru":"пройти","en":"to undergo"},{"ru":"обследование.","en":"a checkup"}]},{"ru":"Береги себя!","en":"Take care of yourself!","words":[{"ru":"Береги","en":"look after"},{"ru":"себя!","en":"yourself"}]},{"ru":"Главное — не перегружать себя.","en":"The main thing is not to overload yourself.","words":[{"ru":"Главное","en":"the main thing"},{"ru":"—","en":""},{"ru":"не","en":"not"},{"ru":"перегружать","en":"overload"},{"ru":"себя.","en":"yourself"}]}]},{"type":"grammar","title":"Useful patterns","paragraphs":["**Аллергия на** + accusative: на орехи, на кошек. **Бросить** + imperfective infinitive = \"to quit doing\": бросить курить.","**… назад** = \"ago\": три года назад. **Сказываться на** + prepositional = \"to affect\"."],"examples":[{"ru":"Стресс сказывается на здоровье.","en":"Stress affects your health."},{"ru":"Я бросила пить кофе месяц назад.","en":"I quit coffee a month ago."}]}],"drills":[{"q":"У меня аллергия ___ орехи.","answer":"на","options":["на","от","к","с"],"en":"I''m allergic to nuts.","why":{"от":"Аллергия takes на + accusative: аллергия на орехи.","к":"Аллергия takes на, not к: аллергия на орехи.","с":"С means \"with\". Аллергия takes на: аллергия на орехи."}},{"q":"Я бросил ___ три года назад.","answer":"курить","options":["курю","курил","покурить","курить"],"en":"I quit smoking three years ago.","why":{"курю":"Бросить (\"to quit\") takes an infinitive: бросил курить.","курил":"Курил is past. After бросил, use the infinitive: курить.","покурить":"Покурить is \"to have a smoke\" (once). Quitting the habit is бросить курить."}},{"q":"Мне ___ антибиотики.","answer":"выписали","options":["выписал","выписали","выписать","выписывают"],"en":"I was prescribed antibiotics.","why":{"выписал":"Выписал is \"he prescribed\" and needs a subject. With no subject (\"they prescribed\", meaning \"I was prescribed\"): выписали.","выписать":"Выписать is the infinitive. \"I was prescribed\" is мне выписали.","выписывают":"Выписывают is present (\"they prescribe\"). It already happened: выписали."}},{"q":"Береги ___!","answer":"себя","options":["собой","себе","сам","себя"],"en":"Take care of yourself!","why":{"себе":"Себе is the dative. Беречь takes the accusative: береги себя.","собой":"Собой is the instrumental. Беречь needs себя.","сам":"Сам is the emphatic \"yourself\". As the object: береги себя."}}]}'::jsonb, 9, 13),
  ('b2-07', 'B2', 'travel', 7, 'When travel goes wrong', 'Когда всё идёт не так', 'Handle delays, lost luggage and complaints — and tell the story afterwards.', '{"intro":"Things go wrong on every trip. Here''s the Russian to solve problems calmly and to describe the adventure later.","sections":[{"type":"lines","kind":"phrases","title":"Travel trouble","lines":[{"ru":"Мой рейс задержали на три часа.","en":"My flight was delayed by three hours.","words":[{"ru":"Мой","en":"my"},{"ru":"рейс","en":"flight"},{"ru":"задержали","en":"(they) delayed"},{"ru":"на","en":"by"},{"ru":"три","en":"three"},{"ru":"часа.","en":"hours"}]},{"ru":"Мой багаж потерялся.","en":"My luggage got lost.","words":[{"ru":"Мой","en":"my"},{"ru":"багаж","en":"luggage"},{"ru":"потерялся.","en":"got lost"}]},{"ru":"Я пропустил стыковочный рейс.","en":"I missed my connecting flight.","words":[{"ru":"Я","en":"I"},{"ru":"пропустил","f":"пропустила","en":"missed"},{"ru":"стыковочный","en":"connecting"},{"ru":"рейс.","en":"flight"}],"ruF":"Я пропустила стыковочный рейс."},{"ru":"Куда мне обратиться?","en":"Who should I speak to about this?","words":[{"ru":"Куда","en":"where"},{"ru":"мне","en":"to me"},{"ru":"обратиться?","en":"to turn"}]},{"ru":"Мне положена компенсация?","en":"Am I entitled to compensation?","words":[{"ru":"Мне","en":"to me"},{"ru":"положена","en":"is due"},{"ru":"компенсация?","en":"compensation"}]},{"ru":"Гостиница оказалась совсем не такой, как на фотографиях.","en":"The hotel was nothing like the photos.","words":[{"ru":"Гостиница","en":"the hotel"},{"ru":"оказалась","en":"turned out"},{"ru":"совсем","en":"quite"},{"ru":"не","en":"not"},{"ru":"такой,","en":"such"},{"ru":"как","en":"as"},{"ru":"на","en":"in"},{"ru":"фотографиях.","en":"the photos"}]},{"ru":"Я хотел бы подать жалобу.","en":"I''d like to make a complaint.","words":[{"ru":"Я","en":"I"},{"ru":"хотел","f":"хотела","en":"wanted"},{"ru":"бы","en":"would"},{"ru":"подать","en":"to file"},{"ru":"жалобу.","en":"a complaint"}],"ruF":"Я хотела бы подать жалобу."},{"ru":"В итоге всё закончилось благополучно.","en":"In the end, everything turned out fine.","words":[{"ru":"В","en":"in"},{"ru":"итоге","en":"the end"},{"ru":"всё","en":"everything"},{"ru":"закончилось","en":"ended"},{"ru":"благополучно.","en":"well"}]},{"ru":"Зато мы увидели то, чего нет в путеводителях.","en":"But we saw things you won''t find in any guidebook.","words":[{"ru":"Зато","en":"but then"},{"ru":"мы","en":"we"},{"ru":"увидели","en":"saw"},{"ru":"то,","en":"what"},{"ru":"чего","en":"—"},{"ru":"нет","en":"isn''t"},{"ru":"в","en":"in"},{"ru":"путеводителях.","en":"guidebooks"}]}]},{"type":"grammar","title":"Turning out and being owed","paragraphs":["**Оказаться** + instrumental = \"to turn out to be\": гостиница оказалась маленькой.","**Положен / положена / положено** + dative = \"is due / entitled to\": мне положена компенсация.","**Зато** = \"but on the other hand (a compensating plus)\"."],"examples":[{"ru":"Экзамен оказался лёгким.","en":"The exam turned out to be easy."},{"ru":"Дорого, зато удобно.","en":"It''s expensive, but convenient."}]}],"drills":[{"q":"Мой рейс ___ на три часа.","answer":"задержали","options":["задержали","задержал","задерживают","задержать"],"en":"My flight was delayed by three hours.","why":{"задержал":"Задержал is \"he delayed\" and needs a subject. With no subject (\"they delayed\"): задержали.","задержать":"Задержать is the infinitive. \"Was delayed\" is задержали.","задерживают":"Задерживают is present (\"they are delaying\"). It already happened: задержали."}},{"q":"Куда мне ___?","answer":"обратиться","options":["обратился","обратиться","обращение","обращаюсь"],"en":"Who should I speak to?","why":{"обращаюсь":"Обращаюсь is the я form. Мне + infinitive asks \"where should I…\": куда мне обратиться?","обратился":"Обратился is past. Мне + infinitive asks \"where should I…\": обратиться.","обращение":"Обращение is the noun \"an appeal\". The question needs the verb: обратиться."}},{"q":"Гостиница ___ совсем не такой.","answer":"оказалась","options":["оказаться","оказался","оказалась","окажется"],"en":"The hotel turned out to be nothing like that.","why":{"оказался":"Оказался is masculine. Гостиница is feminine: оказалась.","оказаться":"Оказаться is the infinitive. Гостиница needs the feminine past: оказалась.","окажется":"Окажется is future (\"will turn out\"). It already did: оказалась."}},{"q":"Дорого, ___ удобно.","answer":"зато","options":["зато","поэтому","потому","хотя"],"en":"Expensive, but convenient.","why":{"потому":"Потому means \"because\" (потому что). \"But on the other hand\" is зато.","поэтому":"Поэтому means \"therefore\". \"But on the plus side\" is зато.","хотя":"Хотя means \"although\", which flips the sense. \"Expensive, but convenient\" is дорого, зато удобно."}}]}'::jsonb, 9, 15),
  ('b2-08', 'B2', 'grammar', 8, 'Verbal adverbs', 'Деепричастия', 'Combine two actions in one sentence with -я and -в forms, like a commentator.', '{"intro":"Деепричастия (\"developing…\", \"having taken…\") make your Russian compact and elegant. Chess annotations use them constantly.","sections":[{"type":"lines","kind":"phrases","title":"Two actions at once","lines":[{"ru":"Развивая фигуры, я готовлюсь к рокировке.","en":"While developing my pieces, I''m preparing to castle.","words":[{"ru":"Развивая","en":"developing"},{"ru":"фигуры,","en":"the pieces"},{"ru":"я","en":"I"},{"ru":"готовлюсь","en":"prepare"},{"ru":"к","en":"for"},{"ru":"рокировке.","en":"castling"}]},{"ru":"Взяв пешку, он открыл линию.","en":"Having taken the pawn, he opened the file.","words":[{"ru":"Взяв","en":"having taken"},{"ru":"пешку,","en":"the pawn"},{"ru":"он","en":"he"},{"ru":"открыл","en":"opened"},{"ru":"линию.","en":"the file"}]},{"ru":"Подумав, я решил отказаться.","en":"After thinking it over, I decided to decline.","words":[{"ru":"Подумав,","en":"having thought"},{"ru":"я","en":"I"},{"ru":"решил","f":"решила","en":"decided"},{"ru":"отказаться.","en":"to decline"}],"ruF":"Подумав, я решила отказаться."},{"ru":"Читая книгу, я заснул.","en":"I fell asleep while reading the book.","words":[{"ru":"Читая","en":"reading"},{"ru":"книгу,","en":"the book"},{"ru":"я","en":"I"},{"ru":"заснул.","f":"заснула.","en":"fell asleep"}],"ruF":"Читая книгу, я заснула."},{"ru":"Не зная правил, трудно играть.","en":"It''s hard to play if you don''t know the rules.","words":[{"ru":"Не","en":"not"},{"ru":"зная","en":"knowing"},{"ru":"правил,","en":"the rules"},{"ru":"трудно","en":"it''s hard"},{"ru":"играть.","en":"to play"}]},{"ru":"Вернувшись домой, она сразу легла спать.","en":"When she got home, she went straight to bed.","words":[{"ru":"Вернувшись","en":"having returned"},{"ru":"домой,","en":"home"},{"ru":"она","en":"she"},{"ru":"сразу","en":"straight away"},{"ru":"легла","en":"went to bed"},{"ru":"спать.","en":"to sleep"}]},{"ru":"Он говорил, улыбаясь.","en":"He spoke with a smile.","words":[{"ru":"Он","en":"he"},{"ru":"говорил,","en":"spoke"},{"ru":"улыбаясь.","en":"smiling"}]},{"ru":"Сделав ход, она нажала на часы.","en":"After making her move, she pressed the clock.","words":[{"ru":"Сделав","en":"having made"},{"ru":"ход,","en":"the move"},{"ru":"она","en":"she"},{"ru":"нажала","en":"pressed"},{"ru":"на","en":"—"},{"ru":"часы.","en":"the clock"}]}]},{"type":"grammar","title":"-я and -в","paragraphs":["**Imperfective** verbal adverbs (-я, -а): делая, читая, улыбаясь — an action happening at the same time.","**Perfective** verbal adverbs (-в, -вшись): сделав, взяв, вернувшись — an action completed before the main one.","The verbal adverb always shares the subject of the main verb. With a negation, the object goes into the genitive: не зная прав**ил**."],"examples":[{"ru":"Слушая музыку, я работаю.","en":"I work while listening to music."},{"ru":"Закончив работу, он пошёл домой.","en":"Having finished work, he went home."}]}],"drills":[{"q":"___ пешку, он открыл линию. (having taken)","answer":"Взяв","options":["Взял","Беря","Взять","Взяв"],"en":"Having taken the pawn, he opened the file.","why":{"Беря":"Беря means \"while taking\" (ongoing). He took the pawn first, then opened the file: Взяв.","Взял":"Взял is a full verb, so the sentence would need и. \"Having taken\" is Взяв.","Взять":"Взять is the infinitive. \"Having taken\" is Взяв."}},{"q":"___ книгу, я заснул. (while reading)","answer":"Читая","options":["Читал","Читать","Читая","Прочитав"],"en":"I fell asleep while reading the book.","why":{"Прочитав":"Прочитав means \"having finished reading\". \"While reading\" is Читая.","Читал":"Читал is a full verb, so the sentence would need и. \"While reading\" is Читая.","Читать":"Читать is the infinitive. \"While reading\" is Читая."}},{"q":"___ домой, она легла спать.","answer":"Вернувшись","options":["Вернувшись","Возвращаясь","Вернулась","Вернуться"],"en":"When she got home, she went to bed.","why":{"Возвращаясь":"Возвращаясь means \"while coming back\". She got home first, then went to bed: Вернувшись.","Вернулась":"Вернулась is a full verb, so the sentence would need и. \"Having come back\" is Вернувшись.","Вернуться":"Вернуться is the infinitive. \"Having come back\" is Вернувшись."}},{"q":"Не зная ___, трудно играть.","answer":"правил","options":["правила","правилами","правил","правилам"],"en":"It''s hard to play without knowing the rules.","why":{"правила":"After a negated verb, Russian prefers the genitive: не зная правил.","правилам":"Правилам is the dative. After не зная: правил.","правилами":"Правилами is the instrumental. After не зная: правил."}}]}'::jsonb, 8, 9),
  ('b2-09', 'B2', 'grammar', 9, 'Participles', 'Причастия', 'Describe things with verb-adjectives: the abandoned queen, the pawn standing on d5.', '{"intro":"Participles let you pack a whole clause into one word. They''re common in writing, news and chess commentary.","sections":[{"type":"lines","kind":"phrases","title":"Participles in action","lines":[{"ru":"Оставленный ферзь погиб.","en":"The abandoned queen was lost.","words":[{"ru":"Оставленный","en":"the abandoned"},{"ru":"ферзь","en":"queen"},{"ru":"погиб.","en":"was lost"}]},{"ru":"Пешка, стоящая на d5, очень сильная.","en":"The pawn standing on d5 is very strong.","words":[{"ru":"Пешка,","en":"the pawn"},{"ru":"стоящая","en":"standing"},{"ru":"на","en":"on"},{"ru":"d5,","en":"d5"},{"ru":"очень","en":"very"},{"ru":"сильная.","en":"strong"}]},{"ru":"Это книга, написанная известным гроссмейстером.","en":"This is a book written by a famous grandmaster.","words":[{"ru":"Это","en":"this is"},{"ru":"книга,","en":"a book"},{"ru":"написанная","en":"written"},{"ru":"известным","en":"by a famous"},{"ru":"гроссмейстером.","en":"grandmaster"}]},{"ru":"Человек, играющий белыми, ходит первым.","en":"The player with White moves first.","words":[{"ru":"Человек,","en":"the person"},{"ru":"играющий","en":"playing"},{"ru":"белыми,","en":"White"},{"ru":"ходит","en":"moves"},{"ru":"первым.","en":"first"}]},{"ru":"Сыгранная партия вошла в историю.","en":"The game went down in history.","words":[{"ru":"Сыгранная","en":"the played"},{"ru":"партия","en":"game"},{"ru":"вошла","en":"went"},{"ru":"в","en":"into"},{"ru":"историю.","en":"history"}]},{"ru":"Защищённый король — спокойный король.","en":"A protected king is a calm king.","words":[{"ru":"Защищённый","en":"a protected"},{"ru":"король","en":"king"},{"ru":"—","en":""},{"ru":"спокойный","en":"(is) a calm"},{"ru":"король.","en":"king"}]},{"ru":"Все приглашённые гости пришли.","en":"All the invited guests came.","words":[{"ru":"Все","en":"all"},{"ru":"приглашённые","en":"the invited"},{"ru":"гости","en":"guests"},{"ru":"пришли.","en":"came"}]},{"ru":"Это решение, принятое вчера.","en":"It''s a decision made yesterday.","words":[{"ru":"Это","en":"this is"},{"ru":"решение,","en":"a decision"},{"ru":"принятое","en":"made"},{"ru":"вчера.","en":"yesterday"}]}]},{"type":"grammar","title":"Four participles","paragraphs":["**Active present** -ущий / -ющий / -ащий / -ящий: играющий (who is playing), стоящий (standing).","**Active past** -вший: игравший (who played). **Passive present** -емый / -имый: уважаемый (respected).","**Passive past** -нный / -тый: написанный, оставленный, открытый, принятый.","They decline like adjectives and replace a **который** clause: пешка, которая стоит на d5 = пешка, стоящая на d5."],"examples":[{"ru":"Студент, сдавший экзамен, улыбался.","en":"The student who passed the exam was smiling."},{"ru":"Открытая линия — путь для ладьи.","en":"An open file is a road for the rook."}]}],"drills":[{"q":"Пешка, ___ на d5, очень сильная.","answer":"стоящая","options":["стоящее","стоявший","стоящая","стоящий"],"en":"The pawn standing on d5 is very strong.","why":{"стоящий":"Стоящий is masculine. It must agree with пешка (feminine): стоящая.","стоявший":"Стоявший is past (\"that stood\") and masculine. Now, feminine: стоящая.","стоящее":"Стоящее is neuter. Пешка is feminine: стоящая."}},{"q":"Это книга, ___ гроссмейстером.","answer":"написанная","options":["пишущая","написавшая","написанная","написанный"],"en":"This book was written by a grandmaster.","why":{"написанный":"Написанный is masculine. Книга is feminine: написанная.","написавшая":"Написавшая means \"that wrote\" (active). The book was written: написанная.","пишущая":"Пишущая means \"that is writing\" (active). The book was written: написанная."}},{"q":"Все ___ гости пришли.","answer":"приглашённые","options":["приглашённые","пригласившие","приглашающие","приглашённый"],"en":"All the invited guests came.","why":{"приглашённый":"Приглашённый is singular. Гости is plural: приглашённые.","приглашающие":"Приглашающие means \"who are inviting\". The guests were invited: приглашённые.","пригласившие":"Пригласившие means \"who invited\". The guests were invited: приглашённые."}},{"q":"___ ферзь погиб. (abandoned)","answer":"Оставленный","options":["Оставлен","Оставивший","Оставленный","Оставляющий"],"en":"The abandoned queen was lost.","why":{"Оставивший":"Оставивший means \"that left (something)\". The queen was left: Оставленный.","Оставляющий":"Оставляющий means \"that is leaving\". The queen was left: Оставленный.","Оставлен":"Оставлен is a short form (\"is left\"), used after the noun, not before it. Before a noun: Оставленный."}}]}'::jsonb, 8, 11),
  ('b2-10', 'B2', 'grammar', 10, 'Linking ideas', 'Сложные союзы', 'Connect arguments with since, nevertheless, despite, thanks to, instead of.', '{"intro":"These connectors are the backbone of B2 speech and writing. Each one requires a specific case after it — learn them together.","sections":[{"type":"lines","kind":"phrases","title":"Connected reasoning","lines":[{"ru":"Поскольку я устал, я пойду домой.","en":"Since I''m tired, I''m going home.","words":[{"ru":"Поскольку","en":"since"},{"ru":"я","en":"I"},{"ru":"устал,","f":"устала,","en":"got tired"},{"ru":"я","en":"I"},{"ru":"пойду","en":"will go"},{"ru":"домой.","en":"home"}],"ruF":"Поскольку я устала, я пойду домой."},{"ru":"Тем не менее, партия была интересной.","en":"Nevertheless, the game was interesting.","words":[{"ru":"Тем","en":"—"},{"ru":"не","en":"not"},{"ru":"менее,","en":"less"},{"ru":"партия","en":"the game"},{"ru":"была","en":"was"},{"ru":"интересной.","en":"interesting"}]},{"ru":"Несмотря на дождь, мы пошли гулять.","en":"Despite the rain, we went for a walk.","words":[{"ru":"Несмотря","en":"despite"},{"ru":"на","en":"—"},{"ru":"дождь,","en":"the rain"},{"ru":"мы","en":"we"},{"ru":"пошли","en":"went"},{"ru":"гулять.","en":"for a walk"}]},{"ru":"В то время как белые атаковали, чёрные защищались.","en":"While White was attacking, Black was defending.","words":[{"ru":"В","en":"in"},{"ru":"то","en":"that"},{"ru":"время","en":"time"},{"ru":"как","en":"as"},{"ru":"белые","en":"White"},{"ru":"атаковали,","en":"attacked"},{"ru":"чёрные","en":"Black"},{"ru":"защищались.","en":"defended"}]},{"ru":"Именно поэтому я не согласен.","en":"That''s exactly why I disagree.","words":[{"ru":"Именно","en":"precisely"},{"ru":"поэтому","en":"therefore"},{"ru":"я","en":"I"},{"ru":"не","en":"not"},{"ru":"согласен.","f":"согласна.","en":"agree"}],"ruF":"Именно поэтому я не согласна."},{"ru":"Благодаря тренеру я стал играть лучше.","en":"Thanks to my coach, I''ve started playing better.","words":[{"ru":"Благодаря","en":"thanks to"},{"ru":"тренеру","en":"my coach"},{"ru":"я","en":"I"},{"ru":"стал","f":"стала","en":"began"},{"ru":"играть","en":"to play"},{"ru":"лучше.","en":"better"}],"ruF":"Благодаря тренеру я стала играть лучше."},{"ru":"Вместо того чтобы жаловаться, давай действовать.","en":"Instead of complaining, let''s do something.","words":[{"ru":"Вместо","en":"instead"},{"ru":"того","en":"of that"},{"ru":"чтобы","en":"to"},{"ru":"жаловаться,","en":"complain"},{"ru":"давай","en":"let''s"},{"ru":"действовать.","en":"act"}]},{"ru":"Хотя он и устал, он продолжил игру.","en":"Even though he was tired, he kept playing.","words":[{"ru":"Хотя","en":"although"},{"ru":"он","en":"he"},{"ru":"и","en":"—"},{"ru":"устал,","en":"was tired"},{"ru":"он","en":"he"},{"ru":"продолжил","en":"continued"},{"ru":"игру.","en":"the game"}]},{"ru":"Чтобы выиграть, нужно терпение.","en":"To win, you need patience.","words":[{"ru":"Чтобы","en":"in order"},{"ru":"выиграть,","en":"to win"},{"ru":"нужно","en":"you need"},{"ru":"терпение.","en":"patience"}]}]},{"type":"grammar","title":"Connectors and their cases","paragraphs":["**Несмотря на** + accusative (despite) · **благодаря** + dative (thanks to) · **вместо** + genitive (instead of) · **из-за** + genitive (because of, negative).","**Поскольку / так как** = \"since, because\". **Тем не менее** = \"nevertheless\". **В то время как** = \"while (contrast)\".","**Чтобы** + infinitive = \"in order to\"; **вместо того чтобы** + infinitive = \"instead of doing\"."],"examples":[{"ru":"Благодаря тебе я понял правила.","en":"Thanks to you, I understood the rules."},{"ru":"Несмотря на усталость, она выиграла.","en":"Despite being tired, she won."}]}],"drills":[{"q":"Несмотря на ___, мы пошли гулять.","answer":"дождь","options":["дождь","дождю","дождём","дождя"],"en":"Despite the rain, we went for a walk.","why":{"дождя":"Несмотря на takes the accusative: несмотря на дождь.","дождём":"Дождём is the instrumental. Несмотря на needs дождь.","дождю":"Дождю is the dative. Несмотря на needs дождь."}},{"q":"Благодаря ___ я стал играть лучше.","answer":"тренеру","options":["тренеру","тренера","тренером","тренер"],"en":"Thanks to my coach, I play better.","why":{"тренер":"Благодаря takes the dative: благодаря тренеру.","тренера":"Тренера is the genitive or accusative. Благодаря needs тренеру.","тренером":"Тренером is the instrumental. Благодаря needs тренеру."}},{"q":"Вместо того ___ жаловаться, давай действовать.","answer":"чтобы","options":["что","как","если","чтобы"],"en":"Instead of complaining, let''s act.","why":{"что":"Before an infinitive, the phrase is вместо того чтобы.","как":"The phrase is вместо того чтобы, before an infinitive.","если":"Если means \"if\". The phrase is вместо того чтобы."}},{"q":"Тем не ___, партия была интересной.","answer":"менее","options":["меньше","менее","мало","более"],"en":"Nevertheless, the game was interesting.","why":{"более":"Тем более means \"all the more\". \"Nevertheless\" is тем не менее.","меньше":"Меньше means \"less\" (an amount). The fixed phrase is тем не менее.","мало":"Мало means \"little, not much\". The fixed phrase is тем не менее."}}]}'::jsonb, 9, 12),
  ('b2-11', 'B2', 'chess_talk', 11, 'Evaluating a position', 'Оценка позиции', 'Discuss a complex position with a coach — material, safety and the right plan.', '{"intro":"Real chess commentary weighs factors against each other: material against activity, attack against defence. This dialogue is how a Russian coach talks.","sections":[{"type":"lines","kind":"dialogue","title":"With the coach","lines":[{"ru":"Несмотря на материальное преимущество, твоя позиция выглядит довольно уязвимой.","en":"Despite your material advantage, your position looks rather vulnerable.","words":[{"ru":"Несмотря","en":"despite"},{"ru":"на","en":"—"},{"ru":"материальное","en":"your material"},{"ru":"преимущество,","en":"advantage"},{"ru":"твоя","en":"your"},{"ru":"позиция","en":"position"},{"ru":"выглядит","en":"looks"},{"ru":"довольно","en":"rather"},{"ru":"уязвимой.","en":"vulnerable"}],"speaker":"Тренер"},{"ru":"Почему? У меня же лишний конь.","en":"Why? I''m a knight up, after all.","words":[{"ru":"Почему?","en":"why"},{"ru":"У","en":"by"},{"ru":"меня","en":"me"},{"ru":"же","en":"after all"},{"ru":"лишний","en":"an extra"},{"ru":"конь.","en":"knight"}],"speaker":"Анна"},{"ru":"Зато у чёрных сильная атака на короля.","en":"But Black has a strong attack on the king.","words":[{"ru":"Зато","en":"but"},{"ru":"у","en":"by"},{"ru":"чёрных","en":"Black"},{"ru":"сильная","en":"a strong"},{"ru":"атака","en":"attack"},{"ru":"на","en":"on"},{"ru":"короля.","en":"the king"}],"speaker":"Тренер"},{"ru":"Твои фигуры разбросаны и не взаимодействуют.","en":"Your pieces are scattered and don''t coordinate.","words":[{"ru":"Твои","en":"your"},{"ru":"фигуры","en":"pieces"},{"ru":"разбросаны","en":"are scattered"},{"ru":"и","en":"and"},{"ru":"не","en":"not"},{"ru":"взаимодействуют.","en":"work together"}],"speaker":"Тренер"},{"ru":"Что бы вы посоветовали?","en":"What would you advise?","words":[{"ru":"Что","en":"what"},{"ru":"бы","en":"would"},{"ru":"вы","en":"you"},{"ru":"посоветовали?","en":"advise"}],"speaker":"Анна"},{"ru":"Я бы предпочёл укрепить позицию короля, поскольку соперник начал создавать непосредственные угрозы.","en":"I''d prefer to shore up the king''s position, since your opponent has started creating immediate threats.","words":[{"ru":"Я","en":"I"},{"ru":"бы","en":"would"},{"ru":"предпочёл","en":"prefer"},{"ru":"укрепить","en":"to strengthen"},{"ru":"позицию","en":"the position"},{"ru":"короля,","en":"of the king"},{"ru":"поскольку","en":"since"},{"ru":"соперник","en":"the opponent"},{"ru":"начал","en":"has begun"},{"ru":"создавать","en":"creating"},{"ru":"непосредственные","en":"immediate"},{"ru":"угрозы.","en":"threats"}],"speaker":"Тренер"},{"ru":"Значит, сначала защита, а потом реализация преимущества?","en":"So defend first, then convert the advantage?","words":[{"ru":"Значит,","en":"so"},{"ru":"сначала","en":"first"},{"ru":"защита,","en":"defence"},{"ru":"а","en":"and"},{"ru":"потом","en":"then"},{"ru":"реализация","en":"converting"},{"ru":"преимущества?","en":"the advantage"}],"speaker":"Анна"},{"ru":"Именно.","en":"Exactly.","words":[{"ru":"Именно.","en":"exactly"}],"speaker":"Тренер"}]},{"type":"grammar","title":"Commentary style","paragraphs":["**Выглядеть** + instrumental: позиция выглядит уязвим**ой**, игра выглядит интересн**ой**.","The particle **же** adds \"after all / but surely\": У меня же лишний конь!","Chess commentary loves nouns: **реализация преимущества** (converting the advantage), **создание угроз**, **укрепление позиции**."],"examples":[{"ru":"Позиция выглядит опасной.","en":"The position looks dangerous."},{"ru":"Главное сейчас — реализация преимущества.","en":"The key now is converting the advantage."}]}],"drills":[{"q":"Твоя позиция выглядит довольно ___.","answer":"уязвимой","options":["уязвимой","уязвимая","уязвимую","уязвимый"],"en":"Your position looks rather vulnerable.","why":{"уязвимая":"Выглядеть takes the instrumental: выглядит уязвимой.","уязвимую":"Уязвимую is the accusative. Выглядеть needs уязвимой.","уязвимый":"Уязвимый is masculine. Позиция is feminine, and выглядеть needs the instrumental: уязвимой."}},{"q":"Несмотря на материальное ___, позиция опасна.","answer":"преимущество","options":["преимущество","преимущества","преимуществом","преимуществу"],"en":"Despite the material advantage, the position is dangerous.","why":{"преимущества":"Несмотря на takes the accusative: на материальное преимущество.","преимуществом":"Преимуществом is the instrumental. Несмотря на needs преимущество.","преимуществу":"Преимуществу is the dative. Несмотря на needs преимущество."}},{"q":"Твои фигуры не ___.","answer":"взаимодействуют","options":["взаимодействовать","взаимодействуют","взаимодействие","взаимодействует"],"en":"Your pieces don''t coordinate.","why":{"взаимодействует":"Взаимодействует is singular. Фигуры is plural: взаимодействуют.","взаимодействие":"Взаимодействие is the noun \"coordination\". The sentence needs the verb: взаимодействуют.","взаимодействовать":"Взаимодействовать is the infinitive. With фигуры: взаимодействуют."}},{"q":"Соперник начал создавать непосредственные ___.","answer":"угрозы","options":["угрозу","угрозы","угроза","угрозой"],"en":"The opponent has started creating immediate threats.","why":{"угроза":"Угроза is singular. Непосредственные is plural: угрозы.","угрозу":"Угрозу is accusative singular. Непосредственные is plural: угрозы.","угрозой":"Угрозой is the instrumental. The object of создавать is угрозы."}}]}'::jsonb, 8, 12),
  ('b2-12', 'B2', 'chess_vocab', 12, 'Tactics and the endgame', 'Тактика и эндшпиль', 'Name forks, pins, sacrifices, zugzwang and the key endgame ideas.', '{"intro":"Many advanced chess terms in Russian are borrowed from German — эндшпиль, цугцванг, миттельшпиль — while tactical ones are pure Russian: вилка (\"fork\"), связка (\"pin\").","sections":[{"type":"lines","kind":"phrases","title":"Tactical vocabulary","lines":[{"ru":"Это классическая вилка.","en":"That''s a classic fork.","words":[{"ru":"Это","en":"that''s"},{"ru":"классическая","en":"a classic"},{"ru":"вилка.","en":"fork"}]},{"ru":"Конь нападает одновременно на короля и ферзя.","en":"The knight attacks the king and queen at the same time.","words":[{"ru":"Конь","en":"the knight"},{"ru":"нападает","en":"attacks"},{"ru":"одновременно","en":"at once"},{"ru":"на","en":"on"},{"ru":"короля","en":"the king"},{"ru":"и","en":"and"},{"ru":"ферзя.","en":"the queen"}]},{"ru":"Слон связал коня.","en":"The bishop has pinned the knight.","words":[{"ru":"Слон","en":"the bishop"},{"ru":"связал","en":"has pinned"},{"ru":"коня.","en":"the knight"}]},{"ru":"Он пожертвовал ладьёй ради атаки.","en":"He sacrificed a rook for the attack.","words":[{"ru":"Он","en":"he"},{"ru":"пожертвовал","en":"sacrificed"},{"ru":"ладьёй","en":"a rook"},{"ru":"ради","en":"for the sake of"},{"ru":"атаки.","en":"the attack"}],"note":"Жертвовать takes the instrumental; in casual chess talk you''ll also hear «пожертвовал ладью»."},{"ru":"Чёрные попали в цугцванг.","en":"Black is in zugzwang.","words":[{"ru":"Чёрные","en":"Black"},{"ru":"попали","en":"have fallen"},{"ru":"в","en":"into"},{"ru":"цугцванг.","en":"zugzwang"}],"note":"Цугцванг: every possible move makes your position worse."},{"ru":"В эндшпиле король становится активной фигурой.","en":"In the endgame the king becomes an active piece.","words":[{"ru":"В","en":"in"},{"ru":"эндшпиле","en":"the endgame"},{"ru":"король","en":"the king"},{"ru":"становится","en":"becomes"},{"ru":"активной","en":"an active"},{"ru":"фигурой.","en":"piece"}]},{"ru":"Проходная пешка решает исход партии.","en":"The passed pawn decides the game.","words":[{"ru":"Проходная","en":"the passed"},{"ru":"пешка","en":"pawn"},{"ru":"решает","en":"decides"},{"ru":"исход","en":"the outcome"},{"ru":"партии.","en":"of the game"}]},{"ru":"Это теоретическая ничья.","en":"It''s a theoretical draw.","words":[{"ru":"Это","en":"it''s"},{"ru":"теоретическая","en":"a theoretical"},{"ru":"ничья.","en":"draw"}]},{"ru":"Он нашёл красивую комбинацию.","en":"He found a beautiful combination.","words":[{"ru":"Он","en":"he"},{"ru":"нашёл","en":"found"},{"ru":"красивую","en":"a beautiful"},{"ru":"комбинацию.","en":"combination"}]},{"ru":"Ладейные эндшпили — самые частые.","en":"Rook endgames are the most common.","words":[{"ru":"Ладейные","en":"rook"},{"ru":"эндшпили","en":"endgames"},{"ru":"—","en":"are"},{"ru":"самые","en":"the most"},{"ru":"частые.","en":"common"}]}]},{"type":"grammar","title":"Borrowed and native terms","paragraphs":["German loanwords: **эндшпиль** (endgame), **миттельшпиль** (middlegame), **цугцванг**, **гроссмейстер**, **цейтнот** (time trouble).","Native tactical words: **вилка** (fork, literally \"table fork\"), **связка** (pin, \"bundle\"), **жертва** (sacrifice), **комбинация**.","**Становиться** + instrumental = \"to become\": король становится активной фигурой."],"examples":[{"ru":"Я попал в цейтнот.","en":"I got into time trouble."},{"ru":"Это была красивая жертва ферзя.","en":"It was a beautiful queen sacrifice."}]}],"drills":[{"q":"Это классическая ___. (fork)","answer":"вилка","options":["вилкой","вилка","вилки","вилку"],"en":"That''s a classic fork.","why":{"вилку":"Вилку is the accusative (an object). After это, the noun is the subject: вилка.","вилки":"Вилки is the genitive or plural. As the subject: вилка.","вилкой":"Вилкой is the instrumental. With классическая: вилка."}},{"q":"Он пожертвовал ___ ради атаки.","answer":"ладьёй","options":["ладьёй","ладья","ладьи","ладью"],"en":"He sacrificed a rook for the attack.","why":{"ладья":"Пожертвовать takes the instrumental: пожертвовал ладьёй.","ладью":"Ладью is the accusative. Пожертвовать needs ладьёй.","ладьи":"Ладьи is the genitive or plural. Пожертвовать needs ладьёй."}},{"q":"Чёрные попали в ___.","answer":"цугцванг","options":["цугцванг","цугцванга","цугцвангом","цугцванге"],"en":"Black is in zugzwang.","why":{"цугцванга":"Цугцванга is the genitive. Getting into something is в + accusative: в цугцванг.","цугцвангом":"Цугцвангом is the instrumental. Getting into it: в цугцванг.","цугцванге":"В цугцванге means being in zugzwang. Falling into it is попасть в цугцванг."}},{"q":"В эндшпиле король становится активной ___.","answer":"фигурой","options":["фигуры","фигура","фигуру","фигурой"],"en":"In the endgame the king becomes an active piece.","why":{"фигура":"Становиться (\"to become\") takes the instrumental: становится фигурой.","фигуру":"Фигуру is the accusative. Становиться needs фигурой.","фигуры":"Фигуры is the genitive or plural. Становиться needs фигурой."}}]}'::jsonb, 10, 15),
  ('b2-13', 'B2', 'chess_talk', 13, 'Review with a coach', 'Разбор с тренером', 'Take honest criticism of your play and plan your improvement — in fluent, complex Russian.', '{"intro":"This is the B2 goal in action: a long, natural sentence that a coach might say after your game. By now you can understand every part of it.","sections":[{"type":"lines","kind":"dialogue","title":"After a tough loss","lines":[{"ru":"Я считаю, что твоя стратегия была слишком агрессивной, и именно поэтому ты потерял преимущество в эндшпиле.","en":"I believe your strategy was too aggressive, and that''s exactly why you lost your advantage in the endgame.","words":[{"ru":"Я","en":"I"},{"ru":"считаю,","en":"believe"},{"ru":"что","en":"that"},{"ru":"твоя","en":"your"},{"ru":"стратегия","en":"strategy"},{"ru":"была","en":"was"},{"ru":"слишком","en":"too"},{"ru":"агрессивной,","en":"aggressive"},{"ru":"и","en":"and"},{"ru":"именно","en":"precisely"},{"ru":"поэтому","en":"that''s why"},{"ru":"ты","en":"you"},{"ru":"потерял","en":"lost"},{"ru":"преимущество","en":"the advantage"},{"ru":"в","en":"in"},{"ru":"эндшпиле.","en":"the endgame"}],"speaker":"Тренер"},{"ru":"Но ведь атака почти удалась!","en":"But the attack almost worked!","words":[{"ru":"Но","en":"but"},{"ru":"ведь","en":"after all"},{"ru":"атака","en":"the attack"},{"ru":"почти","en":"almost"},{"ru":"удалась!","en":"succeeded"}],"speaker":"Максим"},{"ru":"«Почти» не считается.","en":"\"Almost\" doesn''t count.","words":[{"ru":"«Почти»","en":"almost"},{"ru":"не","en":"doesn''t"},{"ru":"считается.","en":"count"}],"speaker":"Тренер"},{"ru":"Ты пожертвовал пешкой, не просчитав последствий.","en":"You sacrificed a pawn without calculating the consequences.","words":[{"ru":"Ты","en":"you"},{"ru":"пожертвовал","en":"sacrificed"},{"ru":"пешкой,","en":"a pawn"},{"ru":"не","en":"not"},{"ru":"просчитав","en":"having calculated"},{"ru":"последствий.","en":"the consequences"}],"speaker":"Тренер"},{"ru":"Согласен, я переоценил свои шансы.","en":"Fair enough, I overestimated my chances.","words":[{"ru":"Согласен,","en":"agreed"},{"ru":"я","en":"I"},{"ru":"переоценил","en":"overestimated"},{"ru":"свои","en":"my"},{"ru":"шансы.","en":"chances"}],"speaker":"Максим"},{"ru":"Тебе стоит поработать над эндшпилем.","en":"You should work on your endgame.","words":[{"ru":"Тебе","en":"for you"},{"ru":"стоит","en":"it''s worth"},{"ru":"поработать","en":"working"},{"ru":"над","en":"on"},{"ru":"эндшпилем.","en":"the endgame"}],"speaker":"Тренер"},{"ru":"С чего мне начать?","en":"Where should I start?","words":[{"ru":"С","en":"with"},{"ru":"чего","en":"what"},{"ru":"мне","en":"for me"},{"ru":"начать?","en":"to start"}],"speaker":"Максим"},{"ru":"С ладейных окончаний.","en":"With rook endings.","words":[{"ru":"С","en":"with"},{"ru":"ладейных","en":"rook"},{"ru":"окончаний.","en":"endings"}],"speaker":"Тренер"}]},{"type":"grammar","title":"Building a long sentence","paragraphs":["Break the coach''s sentence into blocks: **Я считаю,** | **что** твоя стратегия была слишком агрессивной, | **и именно поэтому** ты потерял преимущество | **в эндшпиле**.","Opinion verb + **что**-clause, then a result linked with **и именно поэтому**. **Быть** + instrumental in the past: была агрессивн**ой**.","A negated verbal adverb takes the genitive: не просчитав последстви**й**."],"examples":[{"ru":"Я думаю, что план был хорошим, но именно поэтому соперник его предвидел.","en":"I think the plan was good, but that''s exactly why the opponent saw it coming."},{"ru":"Он ушёл, не сказав ни слова.","en":"He left without saying a word."}]}],"drills":[{"q":"Твоя стратегия была слишком ___.","answer":"агрессивной","options":["агрессивной","агрессивный","агрессивную","агрессивная"],"en":"Your strategy was too aggressive.","why":{"агрессивная":"Агрессивная is heard in speech, but after была the standard form is the instrumental: агрессивной.","агрессивный":"Агрессивный is masculine. Стратегия is feminine: агрессивной.","агрессивную":"Агрессивную is the accusative. After была: агрессивной."}},{"q":"Именно ___ ты потерял преимущество.","answer":"поэтому","options":["почему","что","потому","поэтому"],"en":"That''s exactly why you lost the advantage.","why":{"потому":"Потому needs что (\"because\"). \"That''s why\" is поэтому.","почему":"Почему is \"why?\", a question word. \"That''s why\" is поэтому.","что":"Что is \"that, what\". \"That''s why\" is поэтому."}},{"q":"Ты пожертвовал пешкой, не просчитав ___.","answer":"последствий","options":["последствия","последствиями","последствий","последствиям"],"en":"You sacrificed a pawn without calculating the consequences.","why":{"последствия":"After a negated verb (не просчитав), Russian prefers the genitive: последствий.","последствиям":"Последствиям is the dative. After не просчитав: последствий.","последствиями":"Последствиями is the instrumental. After не просчитав: последствий."}},{"q":"Тебе стоит поработать над ___.","answer":"эндшпилем","options":["эндшпилю","эндшпилем","эндшпиля","эндшпиль"],"en":"You should work on your endgame.","why":{"эндшпиль":"Над takes the instrumental: над эндшпилем.","эндшпиля":"Эндшпиля is the genitive. Над needs эндшпилем.","эндшпилю":"Эндшпилю is the dative. Над needs эндшпилем."}}]}'::jsonb, 8, 10),
  ('b2-14', 'B2', 'opinions', 14, 'A real debate', 'Настоящая дискуссия', 'Debate ideas with idioms and discourse markers that sound genuinely fluent.', '{"intro":"Fluency isn''t just grammar — it''s having the right phrase at the right moment. These are the expressions educated Russians use in a lively discussion.","sections":[{"type":"lines","kind":"phrases","title":"Debating","lines":[{"ru":"Позволь с тобой не согласиться.","en":"Allow me to disagree with you.","words":[{"ru":"Позволь","en":"allow me"},{"ru":"с","en":"with"},{"ru":"тобой","en":"you"},{"ru":"не","en":"not"},{"ru":"согласиться.","en":"to agree"}]},{"ru":"Ты упускаешь из виду одну важную деталь.","en":"You''re overlooking one important detail.","words":[{"ru":"Ты","en":"you"},{"ru":"упускаешь","en":"are letting slip"},{"ru":"из","en":"from"},{"ru":"виду","en":"view"},{"ru":"одну","en":"one"},{"ru":"важную","en":"important"},{"ru":"деталь.","en":"detail"}]},{"ru":"С этим трудно спорить.","en":"That''s hard to argue with.","words":[{"ru":"С","en":"with"},{"ru":"этим","en":"this"},{"ru":"трудно","en":"it''s hard"},{"ru":"спорить.","en":"to argue"}]},{"ru":"Это палка о двух концах.","en":"It cuts both ways.","words":[{"ru":"Это","en":"this is"},{"ru":"палка","en":"a stick"},{"ru":"о","en":"with"},{"ru":"двух","en":"two"},{"ru":"концах.","en":"ends"}],"note":"Literally \"a stick with two ends\"."},{"ru":"Давай посмотрим на это с другой стороны.","en":"Let''s look at it from a different angle.","words":[{"ru":"Давай","en":"let''s"},{"ru":"посмотрим","en":"look"},{"ru":"на","en":"at"},{"ru":"это","en":"it"},{"ru":"с","en":"from"},{"ru":"другой","en":"another"},{"ru":"стороны.","en":"side"}]},{"ru":"Я не отрицаю, что в этом есть смысл.","en":"I don''t deny that it makes some sense.","words":[{"ru":"Я","en":"I"},{"ru":"не","en":"not"},{"ru":"отрицаю,","en":"deny"},{"ru":"что","en":"that"},{"ru":"в","en":"in"},{"ru":"этом","en":"this"},{"ru":"есть","en":"there is"},{"ru":"смысл.","en":"sense"}]},{"ru":"Дело не в деньгах, а в принципе.","en":"It''s not about the money; it''s the principle.","words":[{"ru":"Дело","en":"the point"},{"ru":"не","en":"not"},{"ru":"в","en":"in"},{"ru":"деньгах,","en":"money"},{"ru":"а","en":"but"},{"ru":"в","en":"in"},{"ru":"принципе.","en":"principle"}]},{"ru":"Одно другому не мешает.","en":"The two aren''t mutually exclusive.","words":[{"ru":"Одно","en":"one thing"},{"ru":"другому","en":"the other"},{"ru":"не","en":"not"},{"ru":"мешает.","en":"hinders"}]},{"ru":"В конечном счёте решать тебе.","en":"In the end, it''s your call.","words":[{"ru":"В","en":"in"},{"ru":"конечном","en":"the final"},{"ru":"счёте","en":"reckoning"},{"ru":"решать","en":"to decide"},{"ru":"тебе.","en":"is yours"}]}]},{"type":"grammar","title":"Discourse markers","paragraphs":["**Дело не в… , а в…** = \"it''s not about X, it''s about Y\" (prepositional after в).","**Упускать из виду** = \"to overlook\". **В конечном счёте** = \"ultimately\". **Одно другому не мешает** = \"one doesn''t exclude the other\".","Dative + infinitive expresses whose decision or duty it is: **решать тебе**, **тебе выбирать**."],"examples":[{"ru":"Дело не во времени, а в желании.","en":"It''s not a matter of time, it''s a matter of will."},{"ru":"Выбирать тебе.","en":"It''s your choice."}]}],"drills":[{"q":"Дело не в деньгах, а в ___.","answer":"принципе","options":["принцип","принципе","принципа","принципом"],"en":"It''s not about the money; it''s the principle.","why":{"принцип":"Like в деньгах, this в takes the prepositional: в принципе.","принципа":"Принципа is the genitive. Here в needs принципе.","принципом":"Принципом is the instrumental. Here в needs принципе."}},{"q":"Ты упускаешь из ___ одну деталь.","answer":"виду","options":["вид","виду","вида","видом"],"en":"You''re overlooking one detail.","why":{"вид":"The fixed phrase is упускать из виду (\"to overlook\").","вида":"Из вида is also heard, but the classic idiom is упускать из виду.","видом":"Видом is the instrumental. The idiom is упускать из виду."}},{"q":"Это палка о двух ___.","answer":"концах","options":["концы","концов","концах","концами"],"en":"It cuts both ways.","why":{"концы":"О takes the prepositional: о двух концах.","концов":"Концов is the genitive. О needs концах.","концами":"Концами is the instrumental. О needs концах."}},{"q":"В конечном счёте решать ___.","answer":"тебе","options":["тебя","тобой","ты","тебе"],"en":"In the end, it''s your call.","why":{"ты":"\"It''s yours to decide\" uses the dative: решать тебе.","тебя":"Тебя is the genitive or accusative. \"Up to you\" is решать тебе.","тобой":"Тобой is the instrumental. \"Up to you\" is решать тебе."}}]}'::jsonb, 9, 10)
