insert into public.tests (id, level, title, summary, pass_pct, sort) values
  ('placement', null, 'Placement test', 'Sixteen quick questions from A1 to B2. We''ll start you at the first level you haven''t mastered yet.', 70, 1),
  ('A1', 'A1', 'A1 level test', 'Twelve questions on A1 vocabulary, grammar and listening. Pass with 80% to move up to A2.', 80, 2),
  ('A2', 'A2', 'A2 level test', 'Twelve questions on A2 grammar, everyday situations and chess talk. Pass with 80% to move up to B1.', 80, 3),
  ('B1', 'B1', 'B1 level test', 'Twelve questions on conditionals, motion verbs, opinions and analysis. Pass with 80% to move up to B2.', 80, 4),
  ('B2', 'B2', 'B2 level test', 'Twelve questions on participles, verbal adverbs, connectors and natural speech. Pass with 80% to earn B2.', 80, 5)
insert into public.test_items (id, test_id, sort, level, kind, prompt, ru, options, answer) values
  ('placement-01', 'placement', 1, 'A1', 'vocab', 'What does «спасибо» mean?', null, '["thank you","please","goodbye","sorry"]'::jsonb, 0),
  ('placement-02', 'placement', 2, 'A1', 'listening', 'Listen. What does it mean?', 'Как тебя зовут?', '["What''s your name?","Where are you from?","How old are you?","How are you?"]'::jsonb, 0),
  ('placement-03', 'placement', 3, 'A1', 'grammar', 'Choose the right word: «Это ___ сестра.»', null, '["мои","моё","моя","мой"]'::jsonb, 2),
  ('placement-04', 'placement', 4, 'A1', 'reading', 'What does this mean?', 'Я из Америки.', '["I live in America.","I''m from America.","I love America.","I''m going to America."]'::jsonb, 1),
  ('placement-05', 'placement', 5, 'A2', 'grammar', 'Choose the right word: «Вчера она ___ в магазин.»', null, '["ходил","пойдёт","ходит","ходила"]'::jsonb, 3),
  ('placement-06', 'placement', 6, 'A2', 'listening', 'Listen. What would the speaker like?', 'Я бы хотел кофе без сахара.', '["Tea without sugar","Sugar without coffee","Coffee with sugar","Coffee without sugar"]'::jsonb, 3),
  ('placement-07', 'placement', 7, 'A2', 'grammar', 'Choose the right word: «Я хожу в спортзал три ___ в неделю.»', null, '["разу","раза","разом","раз"]'::jsonb, 1),
  ('placement-08', 'placement', 8, 'A2', 'reading', 'What does this mean?', 'После работы я пойду домой.', '["I work from home.","I went home after work.","I''m walking home from work now.","After work I''ll go home."]'::jsonb, 3),
  ('placement-09', 'placement', 9, 'B1', 'grammar', 'Choose the right word: «Если ___ у меня было время, я бы поехал в Россию.»', null, '["был","будет","буду","бы"]'::jsonb, 3),
  ('placement-10', 'placement', 10, 'B1', 'reading', 'What does this mean?', 'Я не совсем согласен с тобой, но понимаю твою точку зрения.', '["I don''t understand your point of view at all.","I don''t fully agree with you, but I see your point.","I completely agree with your point of view.","I agree with you, but not with them."]'::jsonb, 1),
  ('placement-11', 'placement', 11, 'B1', 'grammar', 'Choose the right word: «Каждое лето мы ___ на море.»', null, '["поедем","ехали","ездим","едем"]'::jsonb, 2),
  ('placement-12', 'placement', 12, 'B1', 'listening', 'Listen. What does it mean?', 'Я заметил, что ты оставил ферзя без защиты.', '["I''m leaving my queen to defend.","I noticed you protected your queen.","I noticed you left your queen undefended.","You noticed that I left my queen."]'::jsonb, 2),
  ('placement-13', 'placement', 13, 'B2', 'grammar', 'Choose the right word: «___ пешку, он открыл линию.»', null, '["Взяв","Взятый","Беря","Взял"]'::jsonb, 0),
  ('placement-14', 'placement', 14, 'B2', 'reading', 'What does this mean?', 'Не хочу делать поспешных выводов, пока не узнаю всей ситуации.', '["I''ll decide quickly once I know a little more.","I don''t want to jump to conclusions until I know the whole situation.","I don''t want to find out about the situation.","I''ve already drawn conclusions about the situation."]'::jsonb, 1),
  ('placement-15', 'placement', 15, 'B2', 'grammar', 'Choose the right word: «Несмотря на ___, мы пошли гулять.»', null, '["дождём","дождя","дождь","дождю"]'::jsonb, 2),
  ('placement-16', 'placement', 16, 'B2', 'listening', 'Listen. What does it mean?', 'Дело не в деньгах, а в принципе.', '["There''s no money in this business.","It''s not about the money; it''s the principle.","The money is the main principle.","It''s about the money, not principles."]'::jsonb, 1),
  ('a1-01', 'A1', 1, 'A1', 'vocab', 'What does «пешка» mean?', null, '["knight","bishop","pawn","rook"]'::jsonb, 2),
  ('a1-02', 'A1', 2, 'A1', 'vocab', 'What does «Очень приятно» mean?', null, '["Very nice weather","Very good","Thank you very much","Nice to meet you"]'::jsonb, 3),
  ('a1-03', 'A1', 3, 'A1', 'grammar', 'Choose the right word: «Мы ___ в шахматы.»', null, '["играешь","играют","играем","играю"]'::jsonb, 2),
  ('a1-04', 'A1', 4, 'A1', 'grammar', 'Choose the right word: «Кофе с ___, пожалуйста.»', null, '["молока","молоко","молоке","молоком"]'::jsonb, 3),
  ('a1-05', 'A1', 5, 'A1', 'grammar', 'Choose the right word: «Мне двадцать ___.»', null, '["года","год","годы","лет"]'::jsonb, 3),
  ('a1-06', 'A1', 6, 'A1', 'listening', 'Listen. What does it mean?', 'Повторите, пожалуйста.', '["Please speak.","Please repeat that.","Please wait.","Please come in."]'::jsonb, 1),
  ('a1-07', 'A1', 7, 'A1', 'listening', 'Listen. What does it mean?', 'Извините, где метро?', '["I''m on the metro.","Excuse me, where''s the metro?","When does the metro open?","Is the metro far?"]'::jsonb, 1),
  ('a1-08', 'A1', 8, 'A1', 'grammar', 'Choose the right word: «Я играю ___ гитаре.»', null, '["на","в","о","с"]'::jsonb, 0),
  ('a1-09', 'A1', 9, 'A1', 'grammar', 'Choose the right word: «Это ___ окно.»', null, '["мой","моё","моя","мои"]'::jsonb, 1),
  ('a1-10', 'A1', 10, 'A1', 'reading', 'What does this mean?', 'У меня есть брат.', '["My brother is here.","I have a brother.","I don''t have a brother.","I am a brother."]'::jsonb, 1),
  ('a1-11', 'A1', 11, 'A1', 'grammar', 'Choose the right word: «Ты играешь ___?» (white)', null, '["белый","белыми","белых","белые"]'::jsonb, 1),
  ('a1-12', 'A1', 12, 'A1', 'listening', 'Listen. What does it mean?', 'Сегодня холодно.', '["It''s hot today.","It was cold yesterday.","It''s raining today.","It''s cold today."]'::jsonb, 3),
  ('a2-01', 'A2', 1, 'A2', 'grammar', 'A woman says: «Вчера я ___ в шахматы.»', null, '["играла","буду играть","играл","играю"]'::jsonb, 0),
  ('a2-02', 'A2', 2, 'A2', 'grammar', 'A man says: «Я бы ___ суп.»', null, '["хотел","хотеть","хотела","хочу"]'::jsonb, 0),
  ('a2-03', 'A2', 3, 'A2', 'grammar', 'Choose the right word: «У нас нет ___.» (хлеб)', null, '["хлеба","хлебу","хлебом","хлеб"]'::jsonb, 0),
  ('a2-04', 'A2', 4, 'A2', 'grammar', 'Choose the right word: «Что ты делаешь в ___?»', null, '["суббота","субботы","субботу","субботой"]'::jsonb, 2),
  ('a2-05', 'A2', 5, 'A2', 'grammar', 'Choose the right word: «Я хочу защитить своего ___.»', null, '["король","королём","короля","королю"]'::jsonb, 2),
  ('a2-06', 'A2', 6, 'A2', 'grammar', 'Choose the right word: «Я увлекаюсь ___.»', null, '["музыка","музыке","музыку","музыкой"]'::jsonb, 3),
  ('a2-07', 'A2', 7, 'A2', 'listening', 'Listen. What does it mean?', 'Мне нужно записаться к врачу.', '["I need to make a doctor''s appointment.","The doctor needs to write to me.","I''m a doctor and I need to write.","I need to call the doctor back."]'::jsonb, 0),
  ('a2-08', 'A2', 8, 'A2', 'listening', 'Listen. What does it mean?', 'Вас плохо слышно.', '["You can''t hear me.","I can''t hear you well.","You speak badly.","You don''t listen well."]'::jsonb, 1),
  ('a2-09', 'A2', 9, 'A2', 'reading', 'What does this mean?', 'Завтра я буду работать.', '["I won''t work tomorrow.","Yesterday I was working.","Tomorrow I''ll be working.","I worked tomorrow."]'::jsonb, 2),
  ('a2-10', 'A2', 10, 'A2', 'reading', 'What does this mean?', 'Слон ходит по диагонали.', '["The king moves one square.","The rook moves along the files.","The knight moves in an L-shape.","The bishop moves diagonally."]'::jsonb, 3),
  ('a2-11', 'A2', 11, 'A2', 'grammar', 'Choose the right word: «В следующем году мы ___ на море.»', null, '["ходили","поехали","ездили","поедем"]'::jsonb, 3),
  ('a2-12', 'A2', 12, 'A2', 'listening', 'Listen. What does it mean?', 'Я опоздал на поезд.', '["I missed my train.","The train is late.","I''ll take the train.","I''m on the train."]'::jsonb, 0),
  ('b1-01', 'B1', 1, 'B1', 'grammar', 'Choose the right word: «Если ___ у меня было время, я бы поехал.»', null, '["бы","был","буду","будет"]'::jsonb, 0),
  ('b1-02', 'B1', 2, 'B1', 'grammar', 'Choose the right word: «Я никогда ___ был в России.»', null, '["нету","ни","нет","не"]'::jsonb, 3),
  ('b1-03', 'B1', 3, 'B1', 'grammar', 'Choose the right word: «Мне не ___ конец фильма.»', null, '["понравились","понравилось","понравилась","понравился"]'::jsonb, 3),
  ('b1-04', 'B1', 4, 'B1', 'grammar', 'Choose the right word: «Я скучаю по ___.»', null, '["тебе","тобой","тебя","ты"]'::jsonb, 0),
  ('b1-05', 'B1', 5, 'B1', 'grammar', 'Choose the right word: «Мы с ___ очень близки.»', null, '["братом","брат","брата","брату"]'::jsonb, 0),
  ('b1-06', 'B1', 6, 'B1', 'grammar', 'Choose the right word: «Каждое лето мы ___ на море.»', null, '["едем","ехать","поедем","ездим"]'::jsonb, 3),
  ('b1-07', 'B1', 7, 'B1', 'reading', 'What does this mean?', 'Это мне не по карману.', '["I can''t afford it.","It doesn''t fit me.","I don''t have my wallet.","It''s not in my pocket."]'::jsonb, 0),
  ('b1-08', 'B1', 8, 'B1', 'reading', 'What does this mean?', 'Давай не будем ссориться.', '["Let''s not be late.","We won''t argue anymore.","Let''s not meet up.","Let''s not argue."]'::jsonb, 3),
  ('b1-09', 'B1', 9, 'B1', 'listening', 'Listen. What does it mean?', 'Честно говоря, я сомневаюсь.', '["Honestly, I agree.","Frankly, I''m surprised.","To be honest, I have my doubts.","Honestly, I''m sure of it."]'::jsonb, 2),
  ('b1-10', 'B1', 10, 'B1', 'grammar', 'Choose the right word: «Я работаю ___.» (as a manager)', null, '["менеджером","менеджер","менеджера","менеджеру"]'::jsonb, 0),
  ('b1-11', 'B1', 11, 'B1', 'listening', 'Listen. What does it mean?', 'У белых есть преимущество.', '["Black has the advantage.","The position is equal.","White has the advantage.","White has a weak pawn."]'::jsonb, 2),
  ('b1-12', 'B1', 12, 'B1', 'listening', 'Listen. What does it mean?', 'Ты меня не так понял.', '["You don''t understand me at all.","I didn''t understand you.","You misunderstood me.","You understood me correctly."]'::jsonb, 2),
  ('b2-01', 'B2', 1, 'B2', 'grammar', 'Choose the right word: «___ домой, она сразу легла спать.»', null, '["Вернуться","Возвращаясь","Вернувшись","Вернулась"]'::jsonb, 2),
  ('b2-02', 'B2', 2, 'B2', 'grammar', 'Choose the right word: «Пешка, ___ на d5, очень сильная.»', null, '["стоявший","стоять","стоящий","стоящая"]'::jsonb, 3),
  ('b2-03', 'B2', 3, 'B2', 'grammar', 'Choose the right word: «Благодаря ___ я стал играть лучше.»', null, '["тренер","тренером","тренеру","тренера"]'::jsonb, 2),
  ('b2-04', 'B2', 4, 'B2', 'grammar', 'Choose the right word: «Не хочу делать поспешных ___.»', null, '["выводами","выводы","выводов","вывод"]'::jsonb, 2),
  ('b2-05', 'B2', 5, 'B2', 'grammar', 'Choose the right word: «Твоя позиция выглядит довольно ___.»', null, '["уязвимая","уязвимую","уязвимой","уязвимый"]'::jsonb, 2),
  ('b2-06', 'B2', 6, 'B2', 'reading', 'What does this mean?', 'Если честно, я не ожидал, что всё сложится именно так.', '["Honestly, I didn''t expect things to turn out like this.","Honestly, this is exactly what I expected.","To be fair, everything was planned.","I hoped things would turn out like this."]'::jsonb, 0),
  ('b2-07', 'B2', 7, 'B2', 'reading', 'What does this mean?', 'Одно другому не мешает.', '["The two aren''t mutually exclusive.","Nobody bothers anyone.","One thing gets in the way of the other.","One is better than the other."]'::jsonb, 0),
  ('b2-08', 'B2', 8, 'B2', 'listening', 'Listen. What does it mean?', 'Я стараюсь найти баланс между работой и личной жизнью.', '["My personal life matters more than work.","I''m trying to balance work and my personal life.","I''m trying to find a job I like.","I''m trying to balance my work budget."]'::jsonb, 1),
  ('b2-09', 'B2', 9, 'B2', 'reading', 'What does this mean?', 'Ну ты даёшь!', '["Wow, you''re something else!","Well, hand it over!","Come on, give it to me.","You give too much."]'::jsonb, 0),
  ('b2-10', 'B2', 10, 'B2', 'grammar', 'Choose the right word: «Несмотря на ___, она выиграла.»', null, '["усталостью","усталый","усталость","усталости"]'::jsonb, 2),
  ('b2-11', 'B2', 11, 'B2', 'listening', 'Listen. What does it mean?', 'Не могли бы вы прислать мне отчёт?', '["Could you write the report?","I can''t send you the report.","Could you send me the report?","You couldn''t send me the report."]'::jsonb, 2),
  ('b2-12', 'B2', 12, 'B2', 'listening', 'Listen. What does it mean?', 'Я считаю, что твоя стратегия была слишком агрессивной.', '["Your aggressive strategy worked well.","I count on an aggressive strategy.","I believe your strategy was too aggressive.","I think your strategy was too cautious."]'::jsonb, 2)
insert into public.conversation_scenarios (id, level, category_id, sort, title, title_ru, description, tutor_role, script) values
  ('a1-cafe', 'A1', 'restaurants', 1, 'At the café', 'В кафе', 'Order a drink, choose milk or no milk, and pay.', 'a friendly barista in a Moscow café', '[{"who":"tutor","ru":"Здравствуйте! Что будете заказывать?","en":"Hello! What would you like to order?"},{"who":"user","hint":"Order a coffee or a tea.","answers":["Кофе, пожалуйста.","Чай, пожалуйста.","Мне кофе, пожалуйста.","Я хочу кофе.","Я хочу чай."]},{"who":"tutor","ru":"С молоком или без молока?","en":"With milk or without?"},{"who":"user","hint":"Say with or without milk.","answers":["Без молока, пожалуйста.","С молоком, пожалуйста.","Без молока.","С молоком."]},{"who":"tutor","ru":"Что-нибудь ещё?","en":"Anything else?"},{"who":"user","hint":"Say no, thanks, and ask how much it costs.","answers":["Нет, спасибо. Сколько это стоит?","Нет, спасибо. Сколько стоит?","Сколько стоит?"]},{"who":"tutor","ru":"Двести рублей. Можно картой.","en":"Two hundred rubles. You can pay by card."},{"who":"user","hint":"Thank them and say goodbye.","answers":["Спасибо! До свидания!","Спасибо, до свидания!","Спасибо!"]},{"who":"tutor","ru":"Хорошего дня!","en":"Have a nice day!"}]'::jsonb),
  ('a1-meet', 'A1', 'meeting', 2, 'Meeting someone new', 'Знакомство', 'Introduce yourself, say where you''re from and what you do.', 'Lena, a friendly student you meet at a chess club', '[{"who":"tutor","ru":"Привет! Меня зовут Лена. А тебя?","en":"Hi! My name is Lena. And yours?"},{"who":"user","hint":"Tell her your name.","answers":["Меня зовут Алекс.","Привет! Меня зовут Алекс.","Я Алекс."]},{"who":"tutor","ru":"Очень приятно! Откуда ты?","en":"Nice to meet you! Where are you from?"},{"who":"user","hint":"Say where you''re from.","answers":["Я из Америки.","Я из Канады.","Я из Англии.","Очень приятно! Я из Америки."]},{"who":"tutor","ru":"Здорово! А что ты делаешь? Работаешь или учишься?","en":"Cool! What do you do? Do you work or study?"},{"who":"user","hint":"Say whether you work or study.","answers":["Я работаю.","Я учусь.","Я работаю программистом.","Я студент."]},{"who":"tutor","ru":"Ты играешь в шахматы?","en":"Do you play chess?"},{"who":"user","hint":"Say yes and suggest playing.","answers":["Да! Давай сыграем!","Да, играю. Давай сыграем!","Да, давай сыграем."]},{"who":"tutor","ru":"Давай! Ты играешь белыми.","en":"Let''s! You''re playing white."}]'::jsonb),
  ('a1-directions', 'A1', 'directions', 3, 'Asking the way', 'Где метро?', 'Ask how to get to the metro and check if it''s far.', 'a passer-by on a Moscow street', '[{"who":"tutor","ru":"Да? Вы что-то ищете?","en":"Yes? Are you looking for something?"},{"who":"user","hint":"Politely ask where the metro is.","answers":["Извините, где метро?","Извините, где здесь метро?","Где метро?"]},{"who":"tutor","ru":"Идите прямо, потом налево.","en":"Go straight, then turn left."},{"who":"user","hint":"Ask if it''s far.","answers":["Это далеко?","Это далеко отсюда?"]},{"who":"tutor","ru":"Нет, это близко. Пять минут пешком.","en":"No, it''s close. Five minutes on foot."},{"who":"user","hint":"Thank them.","answers":["Спасибо большое!","Спасибо!","Большое спасибо!"]},{"who":"tutor","ru":"Пожалуйста!","en":"You''re welcome!"}]'::jsonb),
  ('a1-game', 'A1', 'chess_talk', 4, 'A friendly game', 'Давай сыграем', 'Start a game, choose a colour and react to moves.', 'Misha, a chess club member', '[{"who":"tutor","ru":"Привет! Давай сыграем в шахматы?","en":"Hi! Shall we play chess?"},{"who":"user","hint":"Agree to play.","answers":["Давай!","Да, давай сыграем!","Давай сыграем!"]},{"who":"tutor","ru":"Ты хочешь играть белыми или чёрными?","en":"Do you want to play white or black?"},{"who":"user","hint":"Choose a colour.","answers":["Белыми.","Чёрными.","Я хочу играть белыми.","Я играю чёрными."]},{"who":"tutor","ru":"Хорошо. Твой ход!","en":"Okay. Your move!"},{"who":"user","hint":"Say you''re moving a pawn.","answers":["Я хожу пешкой.","Я двигаю пешку.","Пешка на e4."]},{"who":"tutor","ru":"Хороший ход! Шах!","en":"Good move! Check!"},{"who":"user","hint":"React: say \"oh!\" and that it''s a good move.","answers":["Ой! Хороший ход!","Ой, хороший ход!","Ой!"]},{"who":"tutor","ru":"Спасибо за игру!","en":"Thanks for the game!"}]'::jsonb),
  ('a2-dinner', 'A2', 'restaurants', 1, 'Dinner at a restaurant', 'В ресторане', 'Ask for the menu, order a meal politely and ask for the bill.', 'a waiter in a traditional Russian restaurant', '[{"who":"tutor","ru":"Добрый вечер! Вы готовы заказать?","en":"Good evening! Are you ready to order?"},{"who":"user","hint":"Ask for the menu.","answers":["Можно меню, пожалуйста?","Можно меню?","Дайте, пожалуйста, меню."]},{"who":"tutor","ru":"Конечно, вот меню. Что будете?","en":"Of course, here''s the menu. What will you have?"},{"who":"user","hint":"Politely order soup or borscht.","answers":["Я бы хотел борщ.","Я бы хотела борщ.","Я буду суп.","Я бы хотел суп, пожалуйста."]},{"who":"tutor","ru":"Отличный выбор. Что-нибудь пить?","en":"Great choice. Anything to drink?"},{"who":"user","hint":"Order a drink without sugar.","answers":["Чай без сахара, пожалуйста.","Кофе без сахара, пожалуйста.","Я бы хотел чай без сахара."]},{"who":"tutor","ru":"Как вам еда?","en":"How is the food?"},{"who":"user","hint":"Say you really like it.","answers":["Мне очень нравится.","Очень вкусно!","Мне очень нравится эта еда."]},{"who":"tutor","ru":"Спасибо! Что-нибудь ещё?","en":"Thank you! Anything else?"},{"who":"user","hint":"Ask for the bill.","answers":["Счёт, пожалуйста.","Нет, спасибо. Счёт, пожалуйста."]}]'::jsonb),
  ('a2-plans', 'A2', 'plans', 2, 'Weekend plans', 'Планы на выходные', 'Agree on a plan, a time and a place to meet.', 'Dima, a friend calling about the weekend', '[{"who":"tutor","ru":"Привет! Что ты делаешь в субботу?","en":"Hi! What are you doing on Saturday?"},{"who":"user","hint":"Say you don''t know yet and ask why.","answers":["Пока не знаю. А что?","Ещё не знаю. А что?","Не знаю. А что?"]},{"who":"tutor","ru":"Давай сходим в кино!","en":"Let''s go to the movies!"},{"who":"user","hint":"Accept and ask what time.","answers":["С удовольствием! Во сколько?","Давай! Во сколько?","Хорошо! Во сколько?"]},{"who":"tutor","ru":"В семь вечера. Тебе подходит?","en":"At seven in the evening. Does that work?"},{"who":"user","hint":"Say it works and ask where to meet.","answers":["Да, подходит. Где встретимся?","Подходит. Где встретимся?"]},{"who":"tutor","ru":"У входа в кинотеатр.","en":"At the cinema entrance."},{"who":"user","hint":"Confirm the plan.","answers":["Договорились!","Договорились! До встречи!","Хорошо, до встречи!"]},{"who":"tutor","ru":"До субботы!","en":"See you Saturday!"}]'::jsonb),
  ('a2-doctor', 'A2', 'health', 3, 'At the doctor''s', 'У врача', 'Describe your symptoms and understand the doctor''s advice.', 'a calm, kind doctor at a clinic', '[{"who":"tutor","ru":"Здравствуйте! Что вас беспокоит?","en":"Hello! What seems to be the problem?"},{"who":"user","hint":"Say you have a headache.","answers":["У меня болит голова.","Здравствуйте! У меня болит голова."]},{"who":"tutor","ru":"Как давно?","en":"For how long?"},{"who":"user","hint":"Say since yesterday.","answers":["Со вчерашнего дня.","С вчерашнего дня.","Со вчера."]},{"who":"tutor","ru":"Температура есть?","en":"Do you have a temperature?"},{"who":"user","hint":"Answer yes or no.","answers":["Да, у меня температура.","Нет, температуры нет.","Да, есть.","Нет."]},{"who":"tutor","ru":"Принимайте это лекарство три раза в день.","en":"Take this medicine three times a day."},{"who":"user","hint":"Ask where the nearest pharmacy is.","answers":["Где ближайшая аптека?","Спасибо. Где ближайшая аптека?"]},{"who":"tutor","ru":"Аптека рядом, на первом этаже. Выздоравливайте!","en":"The pharmacy is right here on the ground floor. Get well soon!"}]'::jsonb),
  ('a2-hotel', 'A2', 'hotels', 4, 'Checking in', 'В гостинице', 'Check in, ask about breakfast and report a problem.', 'a receptionist at a St Petersburg hotel', '[{"who":"tutor","ru":"Добрый день! Чем могу помочь?","en":"Good afternoon! How can I help?"},{"who":"user","hint":"Say you have a booking.","answers":["У меня забронирован номер.","Здравствуйте, у меня забронирован номер."]},{"who":"tutor","ru":"Ваша фамилия?","en":"Your last name?"},{"who":"user","hint":"Give your last name.","answers":["Смит.","Моя фамилия Смит.","Джонсон."]},{"who":"tutor","ru":"Да, вижу. На три ночи. Вот ваш ключ.","en":"Yes, I see it. Three nights. Here is your key."},{"who":"user","hint":"Ask if breakfast is included.","answers":["Завтрак включён?","Спасибо. Завтрак включён?"]},{"who":"tutor","ru":"Да, завтрак с семи до десяти.","en":"Yes, breakfast is from seven to ten."},{"who":"user","hint":"Say the air conditioning doesn''t work.","answers":["В номере не работает кондиционер.","Кондиционер не работает."]},{"who":"tutor","ru":"Извините, мы сейчас всё исправим.","en":"Sorry, we''ll fix it right away."}]'::jsonb),
  ('b1-day', 'B1', 'smalltalk', 1, 'How was your day?', 'Как прошёл день?', 'Talk about your day, share an opinion and make a suggestion.', 'Katya, a close friend you meet after work', '[{"who":"tutor","ru":"Привет! Как прошёл твой день?","en":"Hi! How was your day?"},{"who":"user","hint":"Say it was fine but tiring.","answers":["Неплохо, но я очень устал.","Нормально, но я устала.","Неплохо, но очень устала."]},{"who":"tutor","ru":"Понимаю. Что случилось?","en":"I get it. What happened?"},{"who":"user","hint":"Say you had a long meeting at work.","answers":["У меня было длинное совещание.","На работе было длинное совещание."]},{"who":"tutor","ru":"Ой, сочувствую. Слушай, может, сходим куда-нибудь вечером?","en":"Oh, I feel for you. Listen, shall we go out tonight?"},{"who":"user","hint":"Give your opinion: you think it''s a good idea to try something new.","answers":["Я думаю, что нам стоит попробовать что-нибудь новое.","По-моему, это отличная идея!"]},{"who":"tutor","ru":"Отлично! Есть новый грузинский ресторан.","en":"Great! There''s a new Georgian restaurant."},{"who":"user","hint":"Agree and suggest a time.","answers":["Давай! В восемь?","Давай встретимся в восемь.","С удовольствием, давай в восемь."]},{"who":"tutor","ru":"Договорились!","en":"It''s a deal!"}]'::jsonb),
  ('b1-coworker', 'B1', 'work', 2, 'Talking to a coworker', 'Разговор с коллегой', 'Discuss a project deadline and ask for help.', 'Andrey, a colleague at your office', '[{"who":"tutor","ru":"Привет! Как дела с проектом?","en":"Hi! How''s the project going?"},{"who":"user","hint":"Say you need to finish it by Friday.","answers":["Мне нужно закончить его до пятницы.","Нужно закончить проект до пятницы."]},{"who":"tutor","ru":"Успеешь?","en":"Will you make it?"},{"who":"user","hint":"Say you''re not sure and ask for help.","answers":["Не уверен. Можешь мне помочь?","Я не уверена. Ты можешь помочь?","Честно говоря, сомневаюсь. Поможешь?"]},{"who":"tutor","ru":"Конечно. Что нужно сделать?","en":"Of course. What needs doing?"},{"who":"user","hint":"Ask him to check the report.","answers":["Проверь, пожалуйста, отчёт.","Можешь проверить отчёт?"]},{"who":"tutor","ru":"Без проблем. Кстати, ты слышал, что начальник уходит?","en":"No problem. By the way, did you hear the boss is leaving?"},{"who":"user","hint":"React with surprise.","answers":["Да ладно! Не может быть!","Правда? Я не знал!","Ничего себе!"]},{"who":"tutor","ru":"Да, сам удивился.","en":"Yeah, I was surprised too."}]'::jsonb),
  ('b1-disagree', 'B1', 'problems', 3, 'A disagreement', 'Спор с другом', 'Clear up a misunderstanding and make peace.', 'Pasha, a friend who''s upset with you', '[{"who":"tutor","ru":"Ты вчера не пришёл. Я тебя ждал целый час!","en":"You didn''t come yesterday. I waited for you a whole hour!"},{"who":"user","hint":"Apologise and say you didn''t mean to upset him.","answers":["Извини, я не хотел тебя обидеть.","Прости, пожалуйста. Я не хотела тебя обидеть."]},{"who":"tutor","ru":"Мог хотя бы позвонить.","en":"You could at least have called."},{"who":"user","hint":"Say he misunderstood: you meant to meet today.","answers":["Ты меня не так понял. Я имел в виду сегодня.","Ты не так понял, я думал, что мы встречаемся сегодня."]},{"who":"tutor","ru":"Правда? Ну ладно.","en":"Really? Well, okay."},{"who":"user","hint":"Suggest not arguing and meeting tomorrow.","answers":["Давай не будем ссориться. Встретимся завтра?","Давай не будем ссориться. Может, завтра?"]},{"who":"tutor","ru":"Хорошо, проехали.","en":"Fine, let''s drop it."}]'::jsonb),
  ('b1-analysis', 'B1', 'chess_talk', 4, 'Post-game analysis', 'Анализ партии', 'Analyse the game you just played together.', 'Ivan, the opponent you just played', '[{"who":"tutor","ru":"Хорошая партия! Давай разберём?","en":"Good game! Shall we go over it?"},{"who":"user","hint":"Agree and say where you think he made a mistake.","answers":["Давай! Я заметил, что ты оставил ферзя без защиты.","Давай. Мне кажется, ты ошибся на двадцатом ходу."]},{"who":"tutor","ru":"Да, это была грубая ошибка. А что бы ты сделал на моём месте?","en":"Yes, that was a blunder. What would you have done in my place?"},{"who":"user","hint":"Say you would have played the bishop.","answers":["Я бы сыграл слоном.","На твоём месте я бы пошёл слоном.","Я бы защитил ферзя слоном."]},{"who":"tutor","ru":"Интересно. А где ты упустил преимущество?","en":"Interesting. And where did you let your advantage slip?"},{"who":"user","hint":"Say you were rushing.","answers":["Я слишком торопился.","Я слишком торопилась.","Мне кажется, я торопился."]},{"who":"tutor","ru":"Сыграем ещё одну?","en":"Shall we play another?"}]'::jsonb),
  ('b2-negotiation', 'B2', 'work', 1, 'A formal request', 'Деловые переговоры', 'Make formal requests, propose a change and stay polite.', 'Ms Orlova, a manager at a partner company', '[{"who":"tutor","ru":"Добрый день. Чем могу быть полезна?","en":"Good afternoon. How can I help you?"},{"who":"user","hint":"Say you''d like to discuss the contract terms.","answers":["Я хотел бы обсудить условия договора.","Добрый день. Я хотела бы обсудить условия договора."]},{"who":"tutor","ru":"Конечно. Что именно вас не устраивает?","en":"Of course. What exactly doesn''t suit you?"},{"who":"user","hint":"Politely ask whether the deadline could be moved.","answers":["Не могли бы вы перенести срок?","Не могли бы мы перенести срок на месяц?"]},{"who":"tutor","ru":"Боюсь, это выходит за рамки моих полномочий.","en":"I''m afraid that''s beyond my authority."},{"who":"user","hint":"Ask her to pass the request to her manager; say you''d appreciate a reply.","answers":["Не могли бы вы передать просьбу руководству? Буду признателен за ответ.","Тогда не могли бы вы передать это руководству?"]},{"who":"tutor","ru":"Хорошо, я передам и сообщу вам результат.","en":"All right, I''ll pass it on and let you know."}]'::jsonb),
  ('b2-travel', 'B2', 'travel', 2, 'A travel complaint', 'Жалоба в аэропорту', 'Explain a missed connection and lost luggage, and ask about compensation.', 'an airline service desk agent', '[{"who":"tutor","ru":"Слушаю вас.","en":"How can I help?"},{"who":"user","hint":"Explain your flight was delayed and you missed your connection.","answers":["Мой рейс задержали, и я пропустил стыковочный рейс.","Рейс задержали на три часа, и я пропустила стыковку."]},{"who":"tutor","ru":"Понимаю. Мы можем посадить вас на следующий рейс.","en":"I understand. We can put you on the next flight."},{"who":"user","hint":"Say your luggage also got lost and ask who to contact.","answers":["К тому же мой багаж потерялся. Куда мне обратиться?","И ещё мой багаж потерялся. Куда обратиться?"]},{"who":"tutor","ru":"Заполните, пожалуйста, эту форму.","en":"Please fill in this form."},{"who":"user","hint":"Ask whether you''re entitled to compensation.","answers":["Мне положена компенсация?","Скажите, а мне положена компенсация?"]},{"who":"tutor","ru":"Да, при задержке больше трёх часов.","en":"Yes, for delays over three hours."}]'::jsonb),
  ('b2-debate', 'B2', 'opinions', 3, 'A friendly debate', 'Дискуссия', 'Debate whether work or personal life should come first.', 'Oleg, a friend who loves to argue about life', '[{"who":"tutor","ru":"По-моему, в молодости нужно работать, а отдыхать будем потом.","en":"In my view, you work hard while you''re young and rest later."},{"who":"user","hint":"Politely disagree and mention balance.","answers":["Позволь с тобой не согласиться. Важно найти баланс между работой и личной жизнью.","Позволь не согласиться: мне кажется, важен баланс."]},{"who":"tutor","ru":"Но без денег личная жизнь тоже не складывается.","en":"But without money, your personal life doesn''t work out either."},{"who":"user","hint":"Say you don''t deny it but he''s overlooking something.","answers":["Я не отрицаю, но ты упускаешь из виду одну деталь.","С этим трудно спорить, но ты упускаешь из виду здоровье."]},{"who":"tutor","ru":"Какую?","en":"Which one?"},{"who":"user","hint":"Say health is worth more than money.","answers":["Здоровье дороже денег.","Дело не в деньгах, а в здоровье."]},{"who":"tutor","ru":"Ну, одно другому не мешает.","en":"Well, the two aren''t mutually exclusive."}]'::jsonb),
  ('b2-coach', 'B2', 'chess_talk', 4, 'Review with your coach', 'Разбор с тренером', 'Discuss your loss, accept criticism and plan your training.', 'Coach Sergey Petrovich, demanding but fair', '[{"who":"tutor","ru":"Ну что, давай разберём твою партию.","en":"Well then, let''s go over your game."},{"who":"user","hint":"Say honestly that you didn''t expect to lose.","answers":["Если честно, я не ожидал, что проиграю.","Честно говоря, я не ожидала такого результата."]},{"who":"tutor","ru":"Я считаю, что твоя стратегия была слишком агрессивной.","en":"I believe your strategy was too aggressive."},{"who":"user","hint":"Admit you overestimated your chances.","answers":["Согласен, я переоценил свои шансы.","Согласна, я переоценила свои шансы."]},{"who":"tutor","ru":"Именно поэтому ты потерял преимущество в эндшпиле.","en":"That''s exactly why you lost your advantage in the endgame."},{"who":"user","hint":"Ask where you should start working.","answers":["С чего мне начать?","Над чем мне стоит поработать?"]},{"who":"tutor","ru":"С ладейных окончаний. И меньше торопись.","en":"With rook endings. And rush less."}]'::jsonb),
  ('talk-a1-15', 'A1', 'meeting', 5, 'Where do you live?', 'Где ты живёшь?', 'Say where you live, when you moved, who you live with and what''s near your home.', 'Anya, your new neighbour', '[{"who":"tutor","ru":"Где ты живёшь?","en":"Where do you live?"},{"who":"user","hint":"Answer: “I live in Florida. It''s always warm here!”","answers":["Я живу во Флориде. Здесь всегда тепло!"]},{"who":"tutor","ru":"Ты давно во Флориде?","en":"Have you been in Florida long?"},{"who":"user","hint":"Answer: “No, I moved here recently.”","answers":["Нет, я переехал недавно.","Нет, я переехала недавно."]},{"who":"tutor","ru":"Почему ты переехал во Флориду?","en":"Why did you move to Florida?"},{"who":"user","hint":"Answer: “Because there''s work here, and it''s warm.”","answers":["Потому что здесь есть работа и тепло."]},{"who":"tutor","ru":"С кем ты живёшь?","en":"Who do you live with?"},{"who":"user","hint":"Answer: “With a friend. We rent an apartment together.”","answers":["С другом. Мы вместе снимаем квартиру."]},{"who":"tutor","ru":"У вас большая квартира?","en":"Is your apartment big?"},{"who":"user","hint":"Answer: “No, it''s smallish, but comfortable.”","answers":["Нет, небольшая, но удобная."]},{"who":"tutor","ru":"Тебе нравится твой район?","en":"Do you like your neighbourhood?"},{"who":"user","hint":"Answer: “Yes, very much. It''s quiet here, and there''s a park nearby.”","answers":["Да, очень. Здесь тихо, и рядом есть парк."]},{"who":"tutor","ru":"А что ещё есть рядом с домом?","en":"And what else is near your home?"},{"who":"user","hint":"Answer: “A shop, a café and a gym. For example, I walk to the gym.”","answers":["Магазин, кафе и спортзал. Например, в спортзал я хожу пешком."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-16', 'A1', 'work', 6, 'What do you do?', 'Чем ты занимаешься?', 'Talk about your job: what you do, where it is, how you get there and when you''re free.', 'Dima, a friend of a friend at a party', '[{"who":"tutor","ru":"Чем ты занимаешься?","en":"What do you do?"},{"who":"user","hint":"Answer: “I work at a furniture store.”","answers":["Я работаю в мебельном магазине."]},{"who":"tutor","ru":"А что ты там делаешь?","en":"And what do you do there?"},{"who":"user","hint":"Answer: “I work as a salesperson. I help people choose furniture.”","answers":["Я работаю продавцом. Я помогаю людям выбирать мебель."]},{"who":"tutor","ru":"Где находится твой магазин?","en":"Where is your store?"},{"who":"user","hint":"Answer: “In the city centre, not far from my home.”","answers":["В центре города, недалеко от моего дома."]},{"who":"tutor","ru":"Как ты ездишь на работу?","en":"How do you get to work?"},{"who":"user","hint":"Answer: “Usually by car, but sometimes by bus.”","answers":["Обычно на машине, но иногда на автобусе."]},{"who":"tutor","ru":"Во сколько ты начинаешь работать?","en":"What time do you start work?"},{"who":"user","hint":"Answer: “At nine in the morning, so I get up at seven.”","answers":["В девять утра, поэтому я встаю в семь."]},{"who":"tutor","ru":"Ты работаешь по субботам?","en":"Do you work on Saturdays?"},{"who":"user","hint":"Answer: “Yes, on Saturdays we have a lot of customers.”","answers":["Да, по субботам у нас много клиентов."]},{"who":"tutor","ru":"А когда у тебя выходной?","en":"And when''s your day off?"},{"who":"user","hint":"Answer: “Monday and Tuesday. By the way, are you free on Monday?”","answers":["В понедельник и вторник. Кстати, ты свободен в понедельник?"]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-17', 'A1', 'routines', 7, 'From morning to evening', 'С утра до вечера', 'Describe your day in order — first, then, after that — from waking up to going to bed.', 'Lena, a colleague on a coffee break', '[{"who":"tutor","ru":"Во сколько ты обычно просыпаешься?","en":"What time do you usually wake up?"},{"who":"user","hint":"Answer: “I usually wake up at seven in the morning.”","answers":["Обычно я просыпаюсь в семь утра."]},{"who":"tutor","ru":"А что ты делаешь сначала?","en":"And what do you do first?"},{"who":"user","hint":"Answer: “First I have coffee, then I take a shower.”","answers":["Сначала я пью кофе, потом принимаю душ."]},{"who":"tutor","ru":"Что ты обычно ешь на завтрак?","en":"What do you usually eat for breakfast?"},{"who":"user","hint":"Answer: “I usually eat eggs and toast.”","answers":["Обычно я ем яйца и тосты."]},{"who":"tutor","ru":"Ты обедаешь на работе?","en":"Do you have lunch at work?"},{"who":"user","hint":"Answer: “Yes, I bring my lunch with me.”","answers":["Да, я беру обед с собой."]},{"who":"tutor","ru":"Что ты делаешь после работы?","en":"What do you do after work?"},{"who":"user","hint":"Answer: “I usually go to the gym. After that I cook dinner.”","answers":["Обычно я иду в спортзал. После этого я готовлю ужин."]},{"who":"tutor","ru":"Ты поздно ложишься спать?","en":"Do you go to bed late?"},{"who":"user","hint":"Answer: “No, usually at eleven, because I get up early.”","answers":["Нет, обычно в одиннадцать, потому что я рано встаю."]},{"who":"tutor","ru":"Ты сегодня занят?","en":"Are you busy today?"},{"who":"user","hint":"Answer: “No, I have a free evening today.”","answers":["Нет, сегодня у меня свободный вечер."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-18', 'A1', 'cooking', 8, 'Food you love', 'Любимая еда', 'Talk about cooking, your favourite food, Russian dishes and where you shop.', 'Olya, a friend who loves to cook', '[{"who":"tutor","ru":"Ты часто готовишь дома?","en":"Do you often cook at home?"},{"who":"user","hint":"Answer: “Yes, almost every day. I especially love cooking meat and rice.”","answers":["Да, почти каждый день. Особенно я люблю готовить мясо и рис."]},{"who":"tutor","ru":"Какое твоё любимое блюдо?","en":"What''s your favourite dish?"},{"who":"user","hint":"Answer: “I really like pasta with chicken.”","answers":["Мне очень нравится паста с курицей."]},{"who":"tutor","ru":"Ты пробовал русскую кухню?","en":"Have you tried Russian food?"},{"who":"user","hint":"Answer: “Yes, I''ve tried borscht and blini. It was delicious!”","answers":["Да, я пробовал борщ и блины. Было очень вкусно!","Да, я пробовала борщ и блины. Было очень вкусно!"]},{"who":"tutor","ru":"Что ты пьёшь утром, чай или кофе?","en":"What do you drink in the morning, tea or coffee?"},{"who":"user","hint":"Answer: “Coffee, of course! I can''t wake up without coffee.”","answers":["Кофе, конечно! Без кофе я не могу проснуться."]},{"who":"tutor","ru":"Ты любишь сладкое?","en":"Do you like sweets?"},{"who":"user","hint":"Answer: “Not really. But sometimes I have ice cream.”","answers":["Не очень. Но иногда я ем мороженое."]},{"who":"tutor","ru":"Где ты обычно покупаешь продукты?","en":"Where do you usually buy groceries?"},{"who":"user","hint":"Answer: “At the supermarket near my home. They have everything there.”","answers":["В супермаркете рядом с домом. Там есть всё."]},{"who":"tutor","ru":"Хочешь научиться готовить блины?","en":"Do you want to learn to make blini?"},{"who":"user","hint":"Answer: “Yes, I''d love to! Can you teach me?”","answers":["Да, очень! Ты можешь меня научить?"]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-19', 'A1', 'hobbies', 9, 'Getting to know you', 'Давай познакомимся поближе', 'Ask about someone''s day, free time, music, films and travel — and keep the conversation going.', 'Katya, a new friend from the chess club', '[{"who":"tutor","ru":"Как прошёл твой день?","en":"How was your day?"},{"who":"user","hint":"Answer: “Good, but I''m a little tired.”","answers":["Хорошо, но я немного устал.","Хорошо, но я немного устала."]},{"who":"tutor","ru":"Как ты отдыхаешь?","en":"How do you relax?"},{"who":"user","hint":"Answer: “I like walking, doing sport and watching films.”","answers":["Мне нравится гулять, заниматься спортом и смотреть фильмы."]},{"who":"tutor","ru":"Какую музыку ты слушаешь?","en":"What kind of music do you listen to?"},{"who":"user","hint":"Answer: “All kinds. For example, rock and hip-hop.”","answers":["Разную. Например, рок и хип-хоп."]},{"who":"tutor","ru":"Какой твой любимый фильм?","en":"What''s your favourite film?"},{"who":"user","hint":"Answer: “I like science fiction films.”","answers":["Мне нравятся научно-фантастические фильмы."]},{"who":"tutor","ru":"Ты любишь путешествовать?","en":"Do you like travelling?"},{"who":"user","hint":"Answer: “Yes, I love discovering new places.”","answers":["Да, я люблю открывать новые места."]},{"who":"tutor","ru":"Ты давно играешь в шахматы?","en":"Have you been playing chess long?"},{"who":"user","hint":"Answer: “No, I started recently. But I play every day!”","answers":["Нет, я начал недавно. Но я играю каждый день!","Нет, я начала недавно. Но я играю каждый день!"]},{"who":"tutor","ru":"Хочешь сыграть со мной?","en":"Do you want to play with me?"},{"who":"user","hint":"Answer: “Sure! Only I don''t play very well yet.”","answers":["Конечно! Только я ещё плохо играю."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-20', 'A1', 'shopping', 10, 'At a clothes shop', 'В магазине одежды', 'Answer a shop assistant''s questions, try something on, ask for another size and pay.', 'a shop assistant in a clothes shop', '[{"who":"tutor","ru":"Вам помочь?","en":"Can I help you?"},{"who":"user","hint":"Answer: “Yes, thanks. I''m looking for a jacket.”","answers":["Да, спасибо. Я ищу куртку."]},{"who":"tutor","ru":"Какой у вас размер?","en":"What size are you?"},{"who":"user","hint":"Answer: “Forty-eight. Can I look at this one?”","answers":["Сорок восьмой. Можно посмотреть вот эту?"]},{"who":"tutor","ru":"Хотите примерить?","en":"Would you like to try it on?"},{"who":"user","hint":"Answer: “Yes, thanks. Where''s the fitting room?”","answers":["Да, спасибо. Где у вас примерочная?"]},{"who":"tutor","ru":"Ну как? Подходит?","en":"Well? Does it fit?"},{"who":"user","hint":"Answer: “It''s a bit small. Do you have another size?”","answers":["Немного маленькая. У вас есть другой размер?"]},{"who":"tutor","ru":"Вот пятидесятый. Так лучше?","en":"Here''s a fifty. Is that better?"},{"who":"user","hint":"Answer: “Yes, much better! How much is it?”","answers":["Да, намного лучше! Сколько она стоит?"]},{"who":"tutor","ru":"Сто долларов. Как будете платить?","en":"A hundred dollars. How would you like to pay?"},{"who":"user","hint":"Answer: “By card, if that''s OK.”","answers":["Картой, если можно."]},{"who":"tutor","ru":"Пакет нужен?","en":"Do you need a bag?"},{"who":"user","hint":"Answer: “No thanks, I don''t need one. Goodbye!”","answers":["Нет, спасибо, не нужно. До свидания!"]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-21', 'A1', 'essentials', 11, 'Can you help me?', 'Ты можешь мне помочь?', 'Ask for help, ask the way, ask someone to slow down and say thank you.', 'Sasha, a friendly local on the street', '[{"who":"tutor","ru":"Ты что-то ищешь?","en":"Are you looking for something?"},{"who":"user","hint":"Answer: “Yes, I''m looking for a pharmacy. Can you help me?”","answers":["Да, я ищу аптеку. Ты можешь мне помочь?"]},{"who":"tutor","ru":"Конечно! Ты знаешь адрес?","en":"Sure! Do you know the address?"},{"who":"user","hint":"Answer: “No, I don''t. How do I get there?”","answers":["Нет, не знаю. Как мне туда добраться?"]},{"who":"tutor","ru":"Иди прямо, потом направо. Понятно?","en":"Go straight, then turn right. Got it?"},{"who":"user","hint":"Answer: “Not quite. Please speak more slowly.”","answers":["Не совсем. Говори, пожалуйста, медленнее."]},{"who":"tutor","ru":"Прямо, а потом направо. Теперь понятно?","en":"Straight, and then right. Clear now?"},{"who":"user","hint":"Answer: “Yes, I''ve got it now. Is it far?”","answers":["Да, теперь понятно. Это далеко?"]},{"who":"tutor","ru":"Нет, пять минут пешком. Ты не местный?","en":"No, five minutes on foot. You''re not from around here?"},{"who":"user","hint":"Answer: “No, it''s my first time here. I don''t know the city well.”","answers":["Нет, я здесь первый раз. Я плохо знаю город."]},{"who":"tutor","ru":"Но ты хорошо говоришь по-русски! Ты учишь русский?","en":"But you speak Russian well! Are you learning Russian?"},{"who":"user","hint":"Answer: “Thanks! Yes, I am, but for now I speak slowly.”","answers":["Спасибо! Да, учу, но пока говорю медленно."]},{"who":"tutor","ru":"Что ещё тебе нужно?","en":"What else do you need?"},{"who":"user","hint":"Answer: “Nothing else, thanks! You''ve been a big help.”","answers":["Больше ничего, спасибо! Ты мне очень помог."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a1-22', 'A1', 'family', 12, 'The people close to you', 'Мои близкие', 'Talk about where your family lives, brothers and sisters, your parents'' jobs and staying in touch.', 'Misha, a friend from work', '[{"who":"tutor","ru":"Где живёт твоя семья?","en":"Where does your family live?"},{"who":"user","hint":"Answer: “My parents live in another state, far from here.”","answers":["Мои родители живут в другом штате, далеко отсюда."]},{"who":"tutor","ru":"Ты часто их видишь?","en":"Do you see them often?"},{"who":"user","hint":"Answer: “Not very often, so I call them every week.”","answers":["Не очень часто, поэтому я звоню им каждую неделю."]},{"who":"tutor","ru":"У тебя есть братья или сёстры?","en":"Do you have any brothers or sisters?"},{"who":"user","hint":"Answer: “Yes, I have a younger brother.”","answers":["Да, у меня есть младший брат."]},{"who":"tutor","ru":"Сколько ему лет?","en":"How old is he?"},{"who":"user","hint":"Answer: “He''s fifteen. He''s still at school.”","answers":["Ему пятнадцать лет. Он ещё учится в школе."]},{"who":"tutor","ru":"Вы похожи?","en":"Are you alike?"},{"who":"user","hint":"Answer: “A little. For example, we both love sport.”","answers":["Немного. Например, мы оба любим спорт."]},{"who":"tutor","ru":"Чем занимаются твои родители?","en":"What do your parents do?"},{"who":"user","hint":"Answer: “Mum works at a hospital, and Dad is a driver.”","answers":["Мама работает в больнице, а папа — водитель."]},{"who":"tutor","ru":"Ты скучаешь по ним?","en":"Do you miss them?"},{"who":"user","hint":"Answer: “Yes, of course. But we often talk on video.”","answers":["Да, конечно. Но мы часто говорим по видео."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-15', 'A2', 'smalltalk', 5, 'How was your weekend?', 'Как прошли выходные?', 'Tell the story of your weekend in the past tense — what you did, where you went and what you thought of it.', 'Ira, a coworker on Monday morning', '[{"who":"tutor","ru":"Как прошли твои выходные?","en":"How was your weekend?"},{"who":"user","hint":"Answer: “Good, but too short! To be honest, I''d like one more day off.”","answers":["Хорошо, но слишком быстро! Честно говоря, я бы хотел ещё один выходной.","Хорошо, но слишком быстро! Честно говоря, я бы хотела ещё один выходной."]},{"who":"tutor","ru":"А что ты делал на выходных?","en":"So what did you do at the weekend?"},{"who":"user","hint":"Answer: “On Saturday I went to the gym, and in the evening I met up with friends.”","answers":["В субботу я ходил в спортзал, а вечером встретился с друзьями.","В субботу я ходила в спортзал, а вечером встретилась с друзьями."]},{"who":"tutor","ru":"Куда вы ходили с друзьями?","en":"Where did you go with your friends?"},{"who":"user","hint":"Answer: “First we had dinner at a restaurant, and then we went to the cinema.”","answers":["Сначала мы поужинали в ресторане, а потом пошли в кино."]},{"who":"tutor","ru":"Какой фильм вы смотрели?","en":"What film did you see?"},{"who":"user","hint":"Answer: “A new action film. Actually, I didn''t really like it.”","answers":["Новый боевик. На самом деле, мне он не очень понравился."]},{"who":"tutor","ru":"Почему он тебе не понравился?","en":"Why didn''t you like it?"},{"who":"user","hint":"Answer: “Because the plot was boring, although the actors were good.”","answers":["Потому что сюжет был скучный, хотя актёры играли хорошо."]},{"who":"tutor","ru":"А что ты делал в воскресенье?","en":"And what did you do on Sunday?"},{"who":"user","hint":"Answer: “On Sunday I rested at home: I cleaned the apartment, read, and went to bed early.”","answers":["В воскресенье я отдыхал дома: убирал квартиру, читал и рано лёг спать.","В воскресенье я отдыхала дома: убирала квартиру, читала и рано легла спать."]},{"who":"tutor","ru":"Ты хорошо отдохнул?","en":"Did you get a good rest?"},{"who":"user","hint":"Answer: “All in all, yes. I''m ready for a new week!”","answers":["В общем, да. Я готов к новой неделе!","В общем, да. Я готова к новой неделе!"]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-16', 'A2', 'travel', 6, 'Travel stories', 'Путешествия', 'Talk about places you''ve been, your last trip, what you liked and where you dream of going.', 'Maxim, a friend who loves to travel', '[{"who":"tutor","ru":"Ты когда-нибудь был в Европе?","en":"Have you ever been to Europe?"},{"who":"user","hint":"Answer: “Yes, I''ve been to Germany, and I''d like to visit a few more countries.”","answers":["Да, я был в Германии и хотел бы посетить ещё несколько стран.","Да, я была в Германии и хотела бы посетить ещё несколько стран."]},{"who":"tutor","ru":"Когда ты в последний раз путешествовал?","en":"When did you last travel?"},{"who":"user","hint":"Answer: “A few months ago, when I went to another city.”","answers":["Несколько месяцев назад, когда я ездил в другой город.","Несколько месяцев назад, когда я ездила в другой город."]},{"who":"tutor","ru":"В какой город?","en":"Which city?"},{"who":"user","hint":"Answer: “New York. It was my first time there.”","answers":["В Нью-Йорк. Я был там в первый раз.","В Нью-Йорк. Я была там в первый раз."]},{"who":"tutor","ru":"Что тебе больше всего понравилось?","en":"What did you like most?"},{"who":"user","hint":"Answer: “I liked the museums most. Besides that, the food there is really good.”","answers":["Больше всего мне понравились музеи. Кроме того, там очень вкусная еда."]},{"who":"tutor","ru":"Ты любишь путешествовать один?","en":"Do you like travelling alone?"},{"who":"user","hint":"Answer: “Not really. I usually go with friends, because it''s more fun that way. Although sometimes I feel like being on my own.”","answers":["Не очень. Обычно я езжу с друзьями, потому что так веселее. Хотя иногда хочется побыть одному.","Не очень. Обычно я езжу с друзьями, потому что так веселее. Хотя иногда хочется побыть одной."]},{"who":"tutor","ru":"Куда ты хочешь поехать в следующий раз?","en":"Where do you want to go next time?"},{"who":"user","hint":"Answer: “I dream of going to Russia. If it works out, I''ll go in the summer.”","answers":["Я мечтаю поехать в Россию. Если получится, поеду летом."]},{"who":"tutor","ru":"Ты уже готовишься к поездке?","en":"Are you already getting ready for the trip?"},{"who":"user","hint":"Answer: “Yes, I study Russian every day. By the way, that''s one of the reasons I''m learning the language!”","answers":["Да, я учу русский каждый день. Кстати, это одна из причин, почему я учу язык!"]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-17', 'A2', 'friends', 7, 'What''s new?', 'Что нового?', 'Catch up with an old friend: a new job, a first day, yesterday evening and when to meet.', 'Natasha, an old friend you haven''t seen for a while', '[{"who":"tutor","ru":"Что интересного произошло на этой неделе?","en":"What interesting things happened this week?"},{"who":"user","hint":"Answer: “This week I started a new job and met some interesting people.”","answers":["На этой неделе я начал новую работу и познакомился с интересными людьми.","На этой неделе я начала новую работу и познакомилась с интересными людьми."]},{"who":"tutor","ru":"Правда? Где ты теперь работаешь?","en":"Really? Where are you working now?"},{"who":"user","hint":"Answer: “At a car dealership. I sell cars.”","answers":["В автосалоне. Я продаю машины."]},{"who":"tutor","ru":"И как тебе там?","en":"And how do you like it there?"},{"who":"user","hint":"Answer: “I like it so far. On the one hand, there''s a lot that''s new, but on the other hand, my colleagues help a lot.”","answers":["Пока нравится. С одной стороны, много нового, а с другой стороны, коллеги очень помогают."]},{"who":"tutor","ru":"Тебе было трудно в первый день?","en":"Was it hard on your first day?"},{"who":"user","hint":"Answer: “Yes, a little. At first I didn''t understand anything, but after that it got easier.”","answers":["Да, немного. Сначала я ничего не понимал, но после этого стало легче.","Да, немного. Сначала я ничего не понимала, но после этого стало легче."]},{"who":"tutor","ru":"Что ты делал вчера после работы?","en":"What did you do yesterday after work?"},{"who":"user","hint":"Answer: “First I had dinner, then went for a short walk and watched a film.”","answers":["Сначала я поужинал, потом немного погулял и посмотрел фильм.","Сначала я поужинала, потом немного погуляла и посмотрела фильм."]},{"who":"tutor","ru":"Ты устаёшь после работы?","en":"Do you get tired after work?"},{"who":"user","hint":"Answer: “Sometimes, but I try to go for a walk every day, because it helps me unwind.”","answers":["Иногда, но я стараюсь каждый день гулять, потому что это помогает отдохнуть."]},{"who":"tutor","ru":"Когда мы увидимся?","en":"When shall we meet up?"},{"who":"user","hint":"Answer: “Let''s do Saturday! If you''re free, we can have lunch together.”","answers":["Давай в субботу! Если ты свободна, можем вместе пообедать."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-18', 'A2', 'opinions', 8, 'What do you think?', 'Что ты думаешь?', 'Give your opinion, explain why, compare big cities and small towns, and talk about what matters to you.', 'Oleg, a friend who loves a good discussion', '[{"who":"tutor","ru":"Я хочу открыть шахматный клуб. Что ты думаешь об этом?","en":"I want to open a chess club. What do you think about it?"},{"who":"user","hint":"Answer: “I think it''s a good idea, but I''d like to think it all over first.”","answers":["Мне кажется, это хорошая идея, но я хотел бы сначала всё обдумать.","Мне кажется, это хорошая идея, но я хотела бы сначала всё обдумать."]},{"who":"tutor","ru":"Почему ты сомневаешься?","en":"Why are you unsure?"},{"who":"user","hint":"Answer: “Because it''s expensive. But on the other hand, it could be useful in the future.”","answers":["Потому что это дорого. Но с другой стороны, это может быть полезно в будущем."]},{"who":"tutor","ru":"А ты предпочитаешь жить в большом городе или в маленьком?","en":"And do you prefer living in a big city or a small one?"},{"who":"user","hint":"Answer: “I prefer a big city, because there are more opportunities.”","answers":["Я предпочитаю большой город, потому что там больше возможностей."]},{"who":"tutor","ru":"А что тебе не нравится в больших городах?","en":"And what don''t you like about big cities?"},{"who":"user","hint":"Answer: “To be honest, there are too many cars and too much noise.”","answers":["Честно говоря, там слишком много машин и шума."]},{"who":"tutor","ru":"Слушай, а что для тебя важнее всего в отношениях?","en":"Listen, what matters most to you in a relationship?"},{"who":"user","hint":"Answer: “For me, trust, respect and being able to talk to each other are important.”","answers":["Для меня важны доверие, уважение и умение разговаривать друг с другом."]},{"who":"tutor","ru":"А в дружбе?","en":"And in friendship?"},{"who":"user","hint":"Answer: “The same in friendship. Besides that, a friend should be there when things are hard.”","answers":["В дружбе то же самое. Кроме того, друг должен быть рядом, когда трудно."]},{"who":"tutor","ru":"Что бы ты изменил в своей жизни?","en":"What would you change in your life?"},{"who":"user","hint":"Answer: “I''d like to travel more and keep growing as a person.”","answers":["Я бы хотел больше путешествовать и постоянно развиваться.","Я бы хотела больше путешествовать и постоянно развиваться."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-19', 'A2', 'plans', 9, 'Plans and dreams', 'Планы и мечты', 'Talk about your plans for the weekend, the year and the next five years — and what you''ll do if things change.', 'Vika, a friend over coffee', '[{"who":"tutor","ru":"Какие у тебя планы на выходные?","en":"What are your plans for the weekend?"},{"who":"user","hint":"Answer: “I''m going to finish a few things, and then I want to rest.”","answers":["Я собираюсь закончить несколько дел, а потом хочу отдохнуть."]},{"who":"tutor","ru":"Какие дела?","en":"What things?"},{"who":"user","hint":"Answer: “For example, I need to do the laundry and buy groceries.”","answers":["Например, мне нужно постирать вещи и купить продукты."]},{"who":"tutor","ru":"А что ты будешь делать, если пойдёт дождь?","en":"And what will you do if it rains?"},{"who":"user","hint":"Answer: “Most likely I''ll stay home and watch a film.”","answers":["Скорее всего, останусь дома и посмотрю фильм."]},{"who":"tutor","ru":"Ты планируешь куда-нибудь поехать в этом году?","en":"Are you planning to go anywhere this year?"},{"who":"user","hint":"Answer: “Yes, I''d like to take a trip to Europe. If I have the money, of course.”","answers":["Да, я хотел бы съездить в Европу. Если будут деньги, конечно.","Да, я хотела бы съездить в Европу. Если будут деньги, конечно."]},{"who":"tutor","ru":"Чем ты хочешь заниматься через пять лет?","en":"What do you want to be doing in five years?"},{"who":"user","hint":"Answer: “I want to have a stable job, travel and start a family.”","answers":["Я хочу иметь стабильную работу, путешествовать и создать семью."]},{"who":"tutor","ru":"Как ты думаешь, это реально?","en":"Do you think that''s realistic?"},{"who":"user","hint":"Answer: “I think so, although I''ll have to work a lot.”","answers":["Думаю, да, хотя придётся много работать."]},{"who":"tutor","ru":"Ты уже решил, чем займёшься завтра?","en":"Have you decided what you''ll do tomorrow?"},{"who":"user","hint":"Answer: “Not yet, I''m still thinking. And you?”","answers":["Пока нет, я ещё думаю. А ты?"]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-20', 'A2', 'problems', 10, 'Let''s talk it through', 'Давай поговорим', 'Apologise, explain what you meant, talk about solving problems and feelings — and make up.', 'Liza, a close friend', '[{"who":"tutor","ru":"Почему ты не ответил на моё сообщение?","en":"Why didn''t you answer my message?"},{"who":"user","hint":"Answer: “Sorry, I was busy at work and couldn''t reply.”","answers":["Извини, я был занят на работе и не мог ответить.","Извини, я была занята на работе и не могла ответить."]},{"who":"tutor","ru":"Ладно. Ты можешь объяснить, что ты имеешь в виду?","en":"Okay. Can you explain what you mean?"},{"who":"user","hint":"Answer: “Of course. I just wanted to say that we need to talk everything through.”","answers":["Конечно. Я просто хотел сказать, что нам нужно всё обсудить.","Конечно. Я просто хотела сказать, что нам нужно всё обсудить."]},{"who":"tutor","ru":"Как ты обычно решаешь проблемы?","en":"How do you usually solve problems?"},{"who":"user","hint":"Answer: “First I try to understand the situation, and then I look for a solution.”","answers":["Сначала я стараюсь понять ситуацию, а потом ищу решение."]},{"who":"tutor","ru":"А если ты злишься?","en":"And if you''re angry?"},{"who":"user","hint":"Answer: “If I''m angry, I need a little time. After that I calmly explain everything.”","answers":["Если я злюсь, мне нужно немного времени. После этого я спокойно всё объясняю."]},{"who":"tutor","ru":"Что тебя больше всего раздражает?","en":"What annoys you most?"},{"who":"user","hint":"Answer: “I don''t like it when people don''t say directly how they feel.”","answers":["Мне не нравится, когда люди не говорят прямо о своих чувствах."]},{"who":"tutor","ru":"Ты легко знакомишься с новыми людьми?","en":"Do you find it easy to meet new people?"},{"who":"user","hint":"Answer: “Sometimes, but at first I can be a little shy.”","answers":["Иногда да, но сначала я могу немного стесняться."]},{"who":"tutor","ru":"Ну что, мир?","en":"So, are we okay?"},{"who":"user","hint":"Answer: “Of course we are! All in all, I''m glad we talked.”","answers":["Конечно, мир! В общем, я рад, что мы поговорили.","Конечно, мир! В общем, я рада, что мы поговорили."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-21', 'A2', 'work', 11, 'Talking about work', 'Разговор о работе', 'Say what you like about your job, what''s hard, how many hours you work and whether you''d start your own business.', 'Yulia, a friend who''s curious about your job', '[{"who":"tutor","ru":"Тебе нравится твоя работа?","en":"Do you like your job?"},{"who":"user","hint":"Answer: “Yes, I like talking to people, but sometimes the work can be hard.”","answers":["Да, мне нравится общаться с людьми, но иногда работа бывает сложной."]},{"who":"tutor","ru":"Что самое сложное в твоей работе?","en":"What''s the hardest thing about your job?"},{"who":"user","hint":"Answer: “Sometimes it''s hard to understand exactly what the customer needs.”","answers":["Иногда трудно понять, что именно нужно клиенту."]},{"who":"tutor","ru":"А что тебе больше всего нравится?","en":"And what do you like most?"},{"who":"user","hint":"Answer: “I like helping people choose a car.”","answers":["Мне нравится помогать людям выбирать машину."]},{"who":"tutor","ru":"Сколько часов в неделю ты работаешь?","en":"How many hours a week do you work?"},{"who":"user","hint":"Answer: “About forty, but sometimes more if there are a lot of customers.”","answers":["Около сорока, но иногда больше, если много клиентов."]},{"who":"tutor","ru":"Ты хотел бы открыть собственный бизнес?","en":"Would you like to start your own business?"},{"who":"user","hint":"Answer: “Yes, I''m interested in working for myself and building my own project.”","answers":["Да, мне интересно работать на себя и развивать собственный проект."]},{"who":"tutor","ru":"Какой бизнес ты хотел бы открыть?","en":"What kind of business would you like to start?"},{"who":"user","hint":"Answer: “Maybe my own store. On the one hand, it''s a risk, but on the other hand — freedom.”","answers":["Может быть, свой магазин. С одной стороны, это риск, а с другой стороны — свобода."]},{"who":"tutor","ru":"Что тебе нужно для этого?","en":"What do you need for that?"},{"who":"user","hint":"Answer: “First, money, and second, experience. So for now I''m saving up and learning.”","answers":["Во-первых, деньги, а во-вторых, опыт. Поэтому пока я коплю и учусь."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb),
  ('talk-a2-22', 'A2', 'money', 12, 'Talking about money', 'Поговорим о деньгах', 'Talk about what you spend on, saving, your last purchase, shopping online and lending money.', 'Pasha, your roommate', '[{"who":"tutor","ru":"На что ты обычно тратишь деньги?","en":"What do you usually spend your money on?"},{"who":"user","hint":"Answer: “Mostly on housing, food, the car and everyday expenses.”","answers":["В основном на жильё, еду, машину и повседневные расходы."]},{"who":"tutor","ru":"Ты предпочитаешь экономить или тратить деньги?","en":"Do you prefer saving money or spending it?"},{"who":"user","hint":"Answer: “I try to save sensibly, but sometimes I treat myself to something nice.”","answers":["Я стараюсь разумно экономить, но иногда позволяю себе что-нибудь приятное."]},{"who":"tutor","ru":"Что ты купил себе в последний раз?","en":"What''s the last thing you bought for yourself?"},{"who":"user","hint":"Answer: “New headphones. To be honest, they were a bit pricey, but they''re really good.”","answers":["Новые наушники. Честно говоря, они были дороговаты, но очень хорошие."]},{"who":"tutor","ru":"Ты копишь на что-нибудь?","en":"Are you saving up for anything?"},{"who":"user","hint":"Answer: “Yes, I''m saving up for a trip. Besides that, I want to buy a new car.”","answers":["Да, я коплю на путешествие. Кроме того, я хочу купить новую машину."]},{"who":"tutor","ru":"Ты часто покупаешь что-то онлайн?","en":"Do you often buy things online?"},{"who":"user","hint":"Answer: “Yes, quite often, because it''s convenient. But I buy clothes in a store, because I want to try them on.”","answers":["Да, довольно часто, потому что это удобно. Но одежду я покупаю в магазине, потому что хочу её примерить."]},{"who":"tutor","ru":"Ты даёшь деньги в долг друзьям?","en":"Do you lend money to friends?"},{"who":"user","hint":"Answer: “Sometimes, if it''s a good friend. But not very large amounts.”","answers":["Иногда даю, если это хороший друг. Но не очень большие суммы."]},{"who":"tutor","ru":"Как ты думаешь, деньги приносят счастье?","en":"Do you think money brings happiness?"},{"who":"user","hint":"Answer: “Actually, not exactly. Money gives you freedom, but happiness is the people around you.”","answers":["На самом деле, не совсем. Деньги дают свободу, но счастье — это люди рядом."]},{"who":"tutor","ru":"Спасибо, было интересно поговорить!","en":"Thanks, it was nice talking!"}]'::jsonb)
insert into public.pron_milestones (id, level, sort, title, summary, focus, items, pass_count) values
  ('a1-vowels', 'A1', 1, 'The ten vowels', 'Russian has five vowel sounds written with ten letters. The "soft" letters я, ё, ю, е add a y-sound at the start of a word and soften the consonant before them.', array['а','о','у','э','ы','я','ё','ю','е','и']::text[], '[{"ru":"да","en":"yes","tip":"Open, clear «а», like \"ah\"."},{"ru":"нет","en":"no","tip":"The е softens the н: put the middle of your tongue up toward the roof of your mouth."},{"ru":"мама","en":"mom","tip":"Both syllables are clear «а»; stress the first."},{"ru":"суп","en":"soup","tip":"«у» is rounded and tight, like \"oo\" in \"food\"."},{"ru":"это","en":"this","tip":"«э» at the start of a word is like \"e\" in \"met\"."},{"ru":"мы","en":"we","tip":"«ы» has no English twin: say \"ee\" while pulling your tongue back."},{"ru":"ёлка","en":"fir tree","tip":"«ё» = \"yo\", and it is always stressed."},{"ru":"юг","en":"south","tip":"«ю» = \"yu\", like \"you\"."},{"ru":"яблоко","en":"apple","tip":"«я» = \"ya\"; only the first syllable is stressed."}]'::jsonb, 6),
  ('a1-hard-soft', 'A1', 2, 'Hard and soft consonants', 'Almost every Russian consonant has a hard and a soft version. The soft sign ь and the vowels я, ё, ю, е, и make the consonant before them soft.', array['ь','palatalization']::text[], '[{"ru":"брат","en":"brother","tip":"Hard т at the end: tongue tip behind the teeth."},{"ru":"брать","en":"to take","tip":"Soft ть: press the middle of your tongue up, as if about to say \"y\"."},{"ru":"мат","en":"checkmate","tip":"Hard т."},{"ru":"мать","en":"mother","tip":"Soft ть — the only difference from мат."},{"ru":"конь","en":"knight","tip":"Soft нь at the end."},{"ru":"день","en":"day","tip":"Soft д and soft нь."},{"ru":"угол","en":"corner","tip":"Hard л: the back of the tongue is raised (a \"dark\" l)."},{"ru":"уголь","en":"coal","tip":"Soft ль: like the \"l\" in \"million\"."}]'::jsonb, 5),
  ('a1-hissing', 'A1', 3, 'Ж, Ш, Щ, Ц, Ч', 'Ж, ш and ц are always hard; ч and щ are always soft. These five sounds are the heart of a Russian accent.', array['ж','ш','щ','ц','ч']::text[], '[{"ru":"шах","en":"check","tip":"«ш» is a hard, deep \"sh\" with the tongue pulled back."},{"ru":"жена","en":"wife","tip":"«ж» is a hard, buzzing \"zh\" — like \"s\" in \"pleasure\", but deeper."},{"ru":"шахматы","en":"chess","tip":"Hard «ш»; stress the first syllable."},{"ru":"щи","en":"cabbage soup","tip":"«щ» is a long, soft \"shsh\", like \"fresh sheet\" said quickly."},{"ru":"ещё","en":"more, still","tip":"Soft, long «щ» followed by stressed «ё»."},{"ru":"цена","en":"price","tip":"«ц» = \"ts\", always hard."},{"ru":"чай","en":"tea","tip":"«ч» = soft \"ch\", lighter than in English."},{"ru":"часы","en":"clock","tip":"Soft «ч», then the «ы» sound in the stressed syllable."}]'::jsonb, 5),
  ('a1-phrases', 'A1', 4, 'Your first phrases', 'Say whole greetings smoothly, with one strong stressed syllable in each word.', array['rhythm','stress']::text[], '[{"ru":"Привет!","en":"Hi!","tip":"Stress the second syllable: при-ВЕТ."},{"ru":"Спасибо!","en":"Thank you!","tip":"спа-СИ-бо; the о at the end is reduced and short."},{"ru":"Как дела?","en":"How are you?","tip":"The stress falls on the last syllable: де-ЛА."},{"ru":"Здравствуйте!","en":"Hello!","tip":"The first в is silent: [ЗДРА-стуй-те]."},{"ru":"Очень приятно.","en":"Nice to meet you.","tip":"О-чень при-ЯТ-но."},{"ru":"Меня зовут Анна.","en":"My name is Anna.","tip":"ме-НЯ зо-ВУТ — two stresses, no pause."}]'::jsonb, 5),
  ('a2-stress', 'A2', 1, 'Stress and vowel reduction', 'Only the stressed vowel is pronounced fully. Unstressed «о» sounds like «а», and unstressed «е» and «я» sound close to «и».', array['о → а','е/я → и']::text[], '[{"ru":"молоко","en":"milk","tip":"Stress the last syllable; the first two о sound like «а»: [ма-ла-КО]."},{"ru":"хорошо","en":"well","tip":"[ха-ра-ШО]."},{"ru":"голова","en":"head","tip":"[га-ла-ВА]."},{"ru":"окно","en":"window","tip":"[ак-НО]."},{"ru":"сегодня","en":"today","tip":"The г is pronounced «в»: [си-ВОД-ня]."},{"ru":"теперь","en":"now","tip":"The first е sounds like «и»: [ти-ПЕРЬ]."},{"ru":"язык","en":"language","tip":"The я sounds like «и»: [и-ЗЫК]."}]'::jsonb, 5),
  ('a2-clusters', 'A2', 2, 'Consonant clusters', 'Russian piles up consonants. Glide through them without adding extra vowels.', array['в','з','с clusters','silent letters']::text[], '[{"ru":"вторник","en":"Tuesday","tip":"«вт» together — don''t insert a vowel."},{"ru":"вчера","en":"yesterday","tip":"«в» before «ч» sounds like «ф»: [фчи-РА]."},{"ru":"всегда","en":"always","tip":"«вс» sounds like [фс]: [фсиг-ДА]."},{"ru":"встреча","en":"meeting","tip":"«вст» — three consonants in one breath."},{"ru":"здравствуйте","en":"hello (formal)","tip":"«здр» then the cluster «вств» — the first в is silent."},{"ru":"взять","en":"to take","tip":"«вз» — start with a voiced buzz."},{"ru":"страшно","en":"scary","tip":"«стр» — keep the р rolled."}]'::jsonb, 5),
  ('a2-sentences', 'A2', 3, 'Everyday sentences', 'Join words together with one main stressed word in each phrase.', array['sentence stress']::text[], '[{"ru":"Сколько это стоит?","en":"How much does it cost?","tip":"Main stress on СКОЛЬ-ко; the voice falls at the end."},{"ru":"Я хочу пить.","en":"I''m thirsty.","tip":"Link «хочу пить» without a pause."},{"ru":"Где здесь метро?","en":"Where''s the metro here?","tip":"Stress мет-РО at the end."},{"ru":"Повторите, пожалуйста.","en":"Please repeat that.","tip":"по-жа-луй-ста is often said quickly as [па-ЖАЛ-ста]."},{"ru":"Я бы хотел кофе без сахара.","en":"I''d like coffee without sugar.","tip":"«без сахара» runs together: [биз-СА-ха-ра]."},{"ru":"Мне очень нравится эта еда.","en":"I really like this food.","tip":"Stress НРА-вит-ся."}]'::jsonb, 5),
  ('b1-softness', 'B1', 1, 'Softness in connected speech', 'In longer sentences, keep soft consonants soft even when you speak faster.', array['soft consonants','ть','нь','ль']::text[], '[{"ru":"Мне нужно отдохнуть.","en":"I need to rest.","tip":"Soft «ть» at the very end — don''t drop it."},{"ru":"Я тебя люблю.","en":"I love you.","tip":"Soft т in тебя, soft л in люблю."},{"ru":"Сегодня очень тепло.","en":"It''s very warm today.","tip":"Soft «ч» and soft «т» in тепло."},{"ru":"Учитель объяснил правило.","en":"The teacher explained the rule.","tip":"The ъ in объяснил separates: [аб-йис-НИЛ]."},{"ru":"Конь на краю доски.","en":"A knight on the edge of the board.","tip":"Soft нь, then soft «ю»."}]'::jsonb, 4),
  ('b1-devoicing', 'B1', 2, 'Final devoicing and assimilation', 'Voiced consonants become voiceless at the end of a word and before voiceless consonants.', array['б→п','д→т','г→к','в→ф','з→с','ж→ш']::text[], '[{"ru":"хлеб","en":"bread","tip":"Final б sounds like п: [хлеп]."},{"ru":"друг","en":"friend","tip":"Final г sounds like к: [друк]."},{"ru":"снег","en":"snow","tip":"Final г sounds like к: [снек]."},{"ru":"город","en":"city","tip":"[го-рат]: final т, unstressed о → а."},{"ru":"лёгкий","en":"light, easy","tip":"«гк» sounds like «хк»: [ЛЁХ-кий]."},{"ru":"сказка","en":"fairy tale","tip":"«зк» sounds like «ск»: [СКАС-ка]."},{"ru":"Это мой последний ход.","en":"This is my last move.","tip":"ход ends in [т]: [хот]."}]'::jsonb, 4),
  ('b1-rhythm', 'B1', 3, 'Rhythm in long sentences', 'Split long sentences into meaningful groups with a small pause between them.', array['rhythm','phrasing']::text[], '[{"ru":"Я давно хотел с тобой поговорить.","en":"I''ve wanted to talk to you for a long time.","tip":"Two groups: «Я давно хотел» | «с тобой поговорить»."},{"ru":"Как прошёл твой день?","en":"How was your day?","tip":"The question rises on the stressed «день»."},{"ru":"Я думаю, что нам стоит попробовать что-нибудь новое.","en":"I think we should try something new.","tip":"Pause after «думаю»; что is pronounced [што]."},{"ru":"Я не совсем согласен с тобой, но понимаю твою точку зрения.","en":"I don''t fully agree with you, but I understand your point of view.","tip":"Lift your voice slightly before «но»."}]'::jsonb, 3),
  ('b2-intonation', 'B2', 1, 'Intonation', 'Russian yes/no questions have no word order change — only a sharp rise on the key word. Exclamations fall strongly.', array['questions','exclamations']::text[], '[{"ru":"Ты играешь?","en":"Are you playing?","tip":"Sharp rise on иг-РА-ешь, then fall."},{"ru":"Ты играешь.","en":"You''re playing.","tip":"Same words, falling tone: a statement."},{"ru":"Да ладно?","en":"Really?","tip":"Surprised rise on ЛАД-но."},{"ru":"Ничего себе!","en":"Wow!","tip":"Strong fall on се-БЕ."},{"ru":"Кто бы мог подумать!","en":"Who would have thought!","tip":"Emphasis on КТО, then a gentle fall."}]'::jsonb, 4),
  ('b2-natural', 'B2', 2, 'Natural conversational speed', 'Say complex B2 sentences at a natural pace, with reductions native speakers use.', array['connected speech','reductions']::text[], '[{"ru":"Если честно, я не ожидал, что всё сложится именно так.","en":"Honestly, I didn''t expect everything to turn out like this.","tip":"«честно» is [ЧЕС-на]: the т is silent."},{"ru":"Не хочу делать поспешных выводов, пока не узнаю всей ситуации.","en":"I don''t want to jump to conclusions until I know the whole situation.","tip":"Keep «поспешных выводов» as one rhythmic group."},{"ru":"Несмотря на материальное преимущество, твоя позиция выглядит довольно уязвимой.","en":"Despite the material advantage, your position looks rather vulnerable.","tip":"Pause after «преимущество»."},{"ru":"Я считаю, что твоя стратегия была слишком агрессивной.","en":"I believe your strategy was too aggressive.","tip":"«считаю» starts with [щ]: [щи-ТА-ю]."}]'::jsonb, 3),
  ('b2-tongue', 'B2', 3, 'Tongue twisters', 'Classic Russian скороговорки. Start slowly, then speed up.', array['ш/с','р/л','к/г']::text[], '[{"ru":"Шла Саша по шоссе и сосала сушку.","en":"Sasha walked along the highway sucking on a sushka.","tip":"Keep «ш» deep and «с» sharp."},{"ru":"Карл у Клары украл кораллы.","en":"Karl stole corals from Klara.","tip":"Roll every р; keep л hard."},{"ru":"Ехал Грека через реку.","en":"Greka was crossing a river.","tip":"Soft р in «реку», hard г."}]'::jsonb, 2)
